const e="cfexpress",a="2.0.0",l="CFexpress 4.0 Type A TOUGH＆次世代BiCS FLASH",s="CFexpress 4.0 Type A TOUGH & BiCS10 NAND Anatomy",n=130,t=JSON.parse('[{"id":"cfe-top-metal-armor","order":1,"swatchColor":"#272d38","groupKey":"最強の金属鎧_C01_切手サイズなのに_重さ15キロで曲げても折","assembledPos":[0,1.4,2.48],"explodeOffset":[0,0,68],"integratedExplodeOffset":[0,0,68],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C01. 高剛性アルミ／ステンレス上面放熱アーマーシェル（TOUGH耐曲げ150N・耐落下7.5m）","subtitle":"High-Rigidity Brushed Metal Top Armor & Thermal Dissipation Shell (150N Bend / 7.5m Drop)","category":"最強の金属鎧 C01 — 切手サイズなのに「重さ15キロで曲げても折れず、ビル3階から落としても壊れない」放熱アーマー","plainAnalogy":"昔のプラスチック製SDカードはうっかり踏んだりカバンで挟むとパキッと割れて、大切な思い出の写真が全部消えてしまいましたよね。CFexpress TOUGHカードの上面には、強靭な金属アーマープレートが貼り付けられていて、落下や踏みつけから中のチップを守ると同時に、アツアツの熱を外へ逃がす放熱板も兼ねているんです！","summary":"ソニーCEA-GシリーズTOUGH仕様に代表される、上面を覆う高剛性金属アーマー＆放熱シェル。CFexpress規格の約5〜10倍に当たる耐曲げ強度（最大150 N）と7.5 m落下耐性を実現しつつ、カメラ側ヒートシンク（B90）へ熱を受け渡す放熱インターフェースを担います。","opticsAndPhysics":["PCIe Gen4で毎秒1,800〜3,750 MBもの超高速データを書き込むと、小さなカード内部で数ワットの熱が発生します。金属上面シェルは内部の純銅スプレッダー（C25）と熱結合し、熱をカメラのカードスロット放熱機構へ効率よく逃がします。","高降伏点ステンレス／陽極酸化アルミ薄板と一体成型樹脂（C03）の複合サンドイッチ構造により、ポケット内での曲げ荷重やロケ中の踏みつけから内部の8層基板のクラックを徹底防御します。","表面のレーザーマーキング・耐摩耗コートは、数千回のスロット出し入れでも擦れにくく静電気を逃がすアース経路も兼ねます。"],"formula":{"expression":"耐曲げ荷重 ≥ 150 N（約 15 kgf：規格比約10倍） ／ 耐落下 7.5 m ／ 面内放熱パス直結","description":"超薄型カードに強靭な機械的装甲と高速放熱プレートの2大機能を同時融合"},"nextGenInnovation":"CFexpress 4.0（2025〜2026）ではPCIe Gen4発熱対策として、シェル全体へマイクロエンボス放熱面や高放射率ブラックアノダイズ処理を施す進化が加速。","specs":[{"label":"カード実寸","value":"Type A: 20.0×28.0×2.8 mm（3D表示は2倍拡大解剖）"},{"label":"耐曲げ・耐落下","value":"耐曲げ 150 N ／ 落下耐性 7.5 m（TOUGH基準）"},{"label":"熱的役割","value":"カメラ側放熱ブリッジ（B90）への主要伝熱面"},{"label":"動作温度範囲","value":"-12 ℃ 〜 +72 ℃（過酷フィールド保証）"}],"diagramType":"cfe_top_metal_armor"},{"id":"cfe-bottom-metal-shell","order":2,"swatchColor":"#94a3b8","groupKey":"裏面放熱_信頼の証_C02_裏側からも熱を逃がし_動画の_最低保","assembledPos":[0,1.6,-2.48],"explodeOffset":[0,0,-62],"integratedExplodeOffset":[0,0,-62],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C02. 下面金属放熱バックプレート＆精密レーザー刻印シリアル／VPG800認証マーク","subtitle":"Bottom Metal Thermal Backplate & Laser-Etched Serial / VPG400-800 Certification Plate","category":"裏面放熱＆信頼の証 C02 — 裏側からも熱を逃がし、動画の「最低保証スピード（VPG）」を刻む底面プレート","plainAnalogy":"カードの裏側にも頑丈な金属プレートが貼られていて、表面と裏面で中の半導体チップをサンドイッチのように挟んで冷やします！さらに裏面には消えないレーザーで「VPG400 / VPG800（1秒間に必ず400〜800MB以上ずっと書き続けられるよ！というプロ映画の合格証）」とシリアル番号が彫られているんです。","summary":"上面シェルと対になってカード全体をサンドイッチ補強・両面放熱する下面金属バックプレート。裏面にはCompactFlash Association（CFA）公式のVPG400／VPG800認証ロゴ・個別シリアルコード・製造トレーサビリティ情報をレーザー刻印しています。","opticsAndPhysics":["8K RAW動画の長時間連続記録では、片面放熱だけではコントローラ温度が70℃を超えて速度低下（サーマルスロットリング）を招くため、下面金属プレート経由でもスロット下側へ熱を逃がす両面放熱設計が採用されます。","外周の精密ロールヘミング／インサート接着により、カードスロットのバネ機構と擦れてもめくれないフラットな段差ゼロ構造に仕上げられています。","インク印刷ではなく金属面へのファイバーレーザー刻印のため、汗や溶剤・摩擦でシリアル番号や保証IDが消えることがありません。"],"formula":{"expression":"両面サンドイッチ放熱：R_th_dual ≈ 0.55 × R_th_single  （長回し8Kでもスロットリングを大幅に遅延）","description":"表裏両面の金属プレートで熱を分散放出し、VPG400/VPG800の連続書込み保証を長時間キープ"},"nextGenInnovation":"2025〜2026年のCFexpress 4.0カードではVPG800（最低保証800 MB/s）・VPG1600（1,600 MB/s）認証が本格登場し、12K RAW映画収録へ対応。","specs":[{"label":"裏面構造","value":"高熱伝導ステンレス／アルミ放熱バックプレート"},{"label":"刻印工法","value":"耐摩耗ファイバーレーザー直接刻印"},{"label":"動画保証規格","value":"CFA公式 VPG400 / VPG800（連続書込保証）"},{"label":"機械剛性","value":"上面シェルと協働する箱型モノコック補強"}],"diagramType":"cfe_bottom_metal_shell"},{"id":"cfe-monolithic-resin","order":3,"swatchColor":"#1e2128","groupKey":"継ぎ目ゼロの無敵構造_C03_2枚のフタを貼るのではなく_まるご","assembledPos":[0,0,0],"explodeOffset":[-64,0,12],"integratedExplodeOffset":[-64,0,12],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C03. ソニーTOUGH独自「一体成型（モノリシック）高強度樹脂フレーム」","subtitle":"Sony TOUGH Monolithic One-Piece Molded High-Rigidity Composite Resin Frame","category":"継ぎ目ゼロの無敵構造 C03 — 2枚のフタを貼るのではなく、まるごと樹脂で固めて「絶対にパカッと割れない」独自構造","plainAnalogy":"普通のメモリーカードはモナカのように上下2枚のプラスチックを貼り合わせているので、落とすと継ぎ目からパカッと口を開けて壊れてしまいます。ソニーのTOUGHカードは発想をひっくり返し、中身の基板ごと高強度樹脂で「継ぎ目ゼロの一体成型（モノリシック）」にしてしまったんです！だから水もホコリも入らずビクともしません。","summary":"ソニーTOUGHシリーズの最大の革新である、基板・チップ群の周囲を継ぎ目のない一体型高硬度・高熱伝導複合樹脂で隙間なく封入成型する「モノリシック（一体成型）フレーム構造」です。","opticsAndPhysics":["従来の2分割超音波溶着ケースに必ず存在した「内部の空気のすき間」と「合わせ目の弱点」を完全に排除し、カード全体を1つのソリッドな塊（モノコック）へ昇華させています。","樹脂自体にガラス繊維や熱伝導フィラーを配合することで、曲げ剛性を約10倍に引き上げつつ、チップの発熱を外側金属シェルへ伝える熱橋渡し役もこなします。","破損原因の定番だった「物理ライトプロテクトスイッチ」や「華奢なプラスチックリブ」を完全廃止したプロ仕様のタフネス設計です。"],"formula":{"expression":"中空2分割ケース → 継ぎ目ゼロ一体成型モノリシック構造（破壊耐性・防水性・耐衝撃性が桁違い！）","description":"内部の空洞とケースの合わせ目をなくすことで、踏みつけ・落下・水没に圧倒的に強いプロ品質を実現"},"nextGenInnovation":"高熱伝導樹脂と金属シェルの複合インサート成型により、「壊れないTOUGH」と「熱だれしない高速4.0」を両立。","specs":[{"label":"成型技術","value":"ソニーTOUGH独自 継ぎ目レス一体成型（モノリシック）"},{"label":"樹脂特性","value":"ガラス繊維・熱伝導フィラー配合高強度複合材"},{"label":"構造優位性","value":"ケース割れ・内部空洞結露・ピンリブ折損ゼロ"},{"label":"耐久実績","value":"CFexpress規格比 最大 5〜10 倍の曲げ/落下耐性"}],"diagramType":"cfe_monolithic_resin"},{"id":"cfe-ip57-seal-perimeter","order":4,"swatchColor":"#06b6d4","groupKey":"水没・砂嵐ガード_C04_川に落としても泥水がついても_拭き取れ","assembledPos":[0,0,0],"explodeOffset":[64,0,22],"integratedExplodeOffset":[64,0,22],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C04. IP57防塵・防水（水深1m・30分）シームレス封止ガスケット＆防湿コート","subtitle":"IP57 Dust/Water-Proof Seamless Perimeter Seal & Internal Hydrophobic Conformal Coating","category":"水没・砂嵐ガード C04 — 川に落としても泥水がついても、拭き取れば写真がぜんぶ無事で残る防水バリア","plainAnalogy":"雨の日の屋外ロケや川辺の撮影で、うっかりメモリーカードを水たまりや砂の上に落としてしまったら真っ青になりますよね！IP57等級の防水・防塵シールと内部基板の撥水コーティングがあれば、水深1メートルに30分沈んでも中身に水が1滴も入らず、乾かせば大切なデータをそのまま読み出せるんです！","summary":"IEC規格「IP57」（防塵5級：有害な粉塵侵入防止／防水7級：水深1 m・30分浸漬耐性）を実現する、外周密着シールリングおよび内部基板・ハンダ接合部への超撥水ナノ・コンフォーマルコーティング層です。","opticsAndPhysics":["金属シェルと一体成型樹脂の境界を全周シームレスに密封封止し、砂漠の細かい砂塵や豪雨・水没時の浸水を内部電子回路へ一切到達させません。","さらにコネクタ端子裏の基板境界にも疎水性コンフォーマル防湿バリアを施すことで、万一濡れた手で挿抜しても塩分や水分による腐食（マイグレーション短絡）を防止します。","湿度の高いジャングルから氷点下の雪山へ急移動した際に起きる内部結露トラブルも、中空空間の排除と防湿コートの組み合わせで完全にシャットアウトします。"],"formula":{"expression":"保護等級 IP57（防塵 5 級 ＋ 水深 1.0 m × 30 分浸漬耐水 7 級）＋ 内部防湿コート","description":"砂嵐・豪雨・うっかり水没という撮影現場の最悪アクシデントから、かけがえのない記録データを守り抜く"},"nextGenInnovation":"最新世代では防水防塵IP57に加え、耐X線（空港保安検査）・耐磁気・耐静電気・耐紫外線（UV）の「6重環境プロテクト」を標準装備。","specs":[{"label":"防塵・防水等級","value":"IP57 準拠（水深 1 m・30 分耐水＋完全防塵）"},{"label":"外周封止","value":"シームレス防水エラストマー＆樹脂密着境界"},{"label":"基板保護膜","value":"超撥水・耐塩害ナノコンフォーマルコート"},{"label":"耐環境保護","value":"防水・防塵・耐X線・耐静電・耐温度衝撃"}],"diagramType":"cfe_ip57_seal_perimeter"},{"id":"cfe-21pin-gold-fingers","order":5,"swatchColor":"#eab308","groupKey":"超高速の黄金接点_C05_パソコンの最新グラフィックボードと同じ","assembledPos":[0,-24.6,0],"explodeOffset":[0,-56,16],"integratedExplodeOffset":[0,-56,16],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C05. 21ピン硬質金メッキ・PCIe高速エッジコネクタ端子（1万回抜き差し耐久）","subtitle":"21-Pin Hard-Gold (30 μin) PCIe Gen4 Edge Connector Fingers (10,000+ Mating Cycles)","category":"超高速の黄金接点 C05 — パソコンの最新グラフィックボードと同じ「PCIe信号」を通す21本のピカピカ金端子","plainAnalogy":"CFexpressカードがSDカードより何倍も速い秘密は、この先端に並んだ金色の端子！なんと中身はパソコンの中で超高速SSDやグラフィックボードを繋ぐ「PCI Express（PCIe）」そのものなんです。21本の端子（電源・アース・高速データ線・時計線）に硬い金メッキを施し、1万回抜き差ししてもピッカピカのまま超高速通信します！","summary":"CFexpress Type A規格（21ピン構成：PCIe高速差動TX/RXレーン、100 MHz REFCLK差動クロック、PERST#/CLKREQ#制御、3.3V電源、および高速信号の両脇を挟む多数のGNDリターンピン）を備えた、30 µin（約0.76 µm）硬質金メッキ・エッジコネクタ端子群です。","opticsAndPhysics":["PCIe Gen4（16 GT/s）という超高周波信号が乱れなく通過できるよう、高速差動ペア（TX+/TX-, RX+/RX-）の両隣を必ずグラウンド（GND）ピンで挟み込む「G-S-S-G（Ground-Signal-Signal-Ground）」配置で電磁クロストークを徹底排除しています。","電源ピンとGNDピンを信号ピンよりわずかに長く（先行接触・スタッガード長）設計することで、カードの活線挿抜時にまずアースが確実に繋がり、静電気破壊やデータ破損を防ぎます。","ニッケル下地＋コバルト硬化金メッキ（30 µin）により、毎日何十回もカードリーダーとカメラを行き来するプロ現場で10,000回以上の挿抜に耐えます。"],"formula":{"expression":"PCIe Gen4 (16 GT/s) G-S-S-G 差動配列：Type A (1レーン最大 2,000 MB/s) / Type B (2レーン最大 4,000 MB/s)","description":"信号線の両脇をアースで守るプロ高周波配列と硬質金メッキで、毎秒数ギガバイトの超高速データ流を安定接続"},"nextGenInnovation":"CFexpress 4.0では物理ピン形状と後方互換性を100%保ったまま、信号速度をPCIe Gen3（8 GT/s）からGen4（16 GT/s）へ一気に倍増！","specs":[{"label":"端子ピン構成","value":"CFexpress Type A: 21ピン（G-S-S-G高周波配列）"},{"label":"表面メッキ","value":"ニッケル下地＋30 μin コバルト硬質金メッキ"},{"label":"通信インターフェース","value":"PCIe Gen4.0 / NVMe 2.0（後方互換あり）"},{"label":"挿抜耐久回数","value":"10,000 回以上の着脱サイクル保証"}],"diagramType":"cfe_21pin_gold_fingers"},{"id":"cfe-connector-shroud","order":6,"swatchColor":"#334155","groupKey":"ピン折れ防止ガード_C06_絶対に裏表を間違えず_ソニー独自の_","assembledPos":[0,-24.8,0],"explodeOffset":[0,-76,-14],"integratedExplodeOffset":[0,-76,-14],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C06. 誤挿入防止キー溝＆耐衝撃コネクタ保護リブ（Type A専用ガイドノッチ）","subtitle":"Polarized Anti-Reverse Keying Notch & Recessed Impact-Resistant Terminal Shroud","category":"ピン折れ防止ガード C06 — 絶対に裏表を間違えず、ソニー独自の「SD＋CFexpress兼用スロット」へスッと導く専用枠","plainAnalogy":"ソニーα7 IVやα1 IIのすごいところは、1つのカードスロットに「SDカード」も「CFexpress Type A」も両方挿せること！それを可能にするのが、先端の特殊な切り欠き（キー溝）と端子を奥に引っ込めて守る保護枠（シュラウド）。裏表を間違えて無理やり押し込んでピンを曲げる事故を防いでくれます！","summary":"CFexpress Type A独自の20×28 mmコンパクト形状へ統合された、逆挿入・表裏誤挿入を物理的に阻止する左右非対称キー溝と、繊細な21ピン端子列を外部の衝撃・指脂接触から守るリセスド保護シュラウドです。","opticsAndPhysics":["SDカード（24×32 mm）より一回り小さいType A（20×28 mm）の側面ガイドレールと先端キー溝により、ソニーのデュアルフォーマット兼用スロット内でCFexpressとSDを機械的に自動判別・正確ガイドします。","SDカードと違って露出した金端子に指が直接触れにくい段差シュラウド構造を採用し、指先の皮脂汚れや静電気放電（ESD）による接触不良を大幅に減らします。","プッシュ・プッシュ式イジェクト機構のハートカム爪が噛み合う側面ロッキングノッチを高耐摩耗樹脂で成形しています。"],"formula":{"expression":"Type A (20×28×2.8 mm) ＜ SD (24×32×2.1 mm)  →  デュアル兼用スロットへ完全共存設計！","description":"SDカードよりコンパクトな専用キー形状と端子保護シュラウドで、誤挿入ゼロと兼用スロット互換を実現"},"nextGenInnovation":"TOUGH設計では割れやすい細いプラスチック仕切りリブを排除し、高剛性一体枠でコネクタ口元を保護する折損レス構造を採用。","specs":[{"label":"互換スロット","value":"CFexpress Type A / SD UHS-II デュアル兼用対応"},{"label":"誤挿入防止","value":"非対称ガイドレール＆先端ポカヨケキー溝"},{"label":"端子保護","value":"指脂・静電気接触を防ぐ段差保護シュラウド"},{"label":"ロック機構","value":"高耐摩耗イジェクトカム用サイドノッチ"}],"diagramType":"cfe_connector_shroud"},{"id":"cfe-hdi-8layer-pcb","order":7,"swatchColor":"#0f3c30","groupKey":"極薄8階建てハイウェイ基板_C07_厚さわずか0_5ミリの中に8","assembledPos":[0,0.5,0],"explodeOffset":[0,0,0],"integratedExplodeOffset":[0,0,0],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C07. 超薄型8層高密度ビルドアップ（HDI）プリント基板（PCIe Gen4等長配線）","subtitle":"Ultra-Thin 0.5 mm 8-Layer HDI Micro-Via PCB (85 Ω / 100 Ω PCIe Gen4 Differential Routing)","category":"極薄8階建てハイウェイ基板 C07 — 厚さわずか0.5ミリの中に8層もの超高速道路を重ねた極小マザーボード","plainAnalogy":"CFexpressカードの中身は、じつは「切手サイズの超高性能パソコン用SSD」そのもの！厚さたった0.5ミリ（名刺2枚分！）の極薄基板の中に、なんと8階建てもの立体配線（8層HDI基板）が張り巡らされていて、16 GHz級の超高速信号が1ミリも遅れずゴールするよう、線の長さを蛇行させてピッタリ揃えてあるんです！","summary":"厚さわずか約0.45〜0.60 mmの極薄ガラスエポキシ低損失（Low-Dk / Low-Df）基材へ、レーザーマイクロビアで8層を立体積層したHDI（高密度相互接続）プリント基板。PCIe Gen4差動レーンと多チャネル3D NAND高速バスを厳密なインピーダンス制御で配線します。","opticsAndPhysics":["PCIe Gen4（16 GT/s）の高速データ線（＋線と−線のペア）は、わずかな長さのズレ（スキュー）でも波形が崩れて通信エラーになるため、基板上でミクロン単位の「等長蛇行（サーペンタイン）配線」と 85 Ω 差動インピーダンス整合を施しています。","信号層の上下を必ずベタの銅グラウンド層で挟むストリップライン構造により、高周波信号の反射損失と外部への電磁ノイズ放射（EMI）を最小化します。","熱伝導の悪い樹脂基板を貫通する多数の銅サーマルビア（熱ぬき穴）をコントローラ直下へ配置し、基板の裏面シェルへも効率よく放熱します。"],"formula":{"expression":"8層極薄HDI（総厚 ≈ 0.5 mm） ／ 差動インピーダンス Z_diff = 85 Ω ±5% ／ 等長誤差 < 0.1 mm","description":"名刺2枚分の極薄8層基板へ低損失PCIe Gen4高速配線と放熱ビアを高密度集積した超小型SSDの土台"},"nextGenInnovation":"低誘電正接（Low-Df）メガトロン系高周波基材の採用により、CFexpress 4.0（PCIe Gen4）の極限高速信号でもクリアな波形（アイ開口）を維持。","specs":[{"label":"層数・基板厚","value":"8層 ビルドアップHDI（総厚約 0.50 mm）"},{"label":"配線技術","value":"レーザーマイクロビア＋85Ω差動等長蛇行配線"},{"label":"基材特性","value":"高周波低損失（Low-Dk / Low-Df）ガラスエポキシ"},{"label":"放熱工夫","value":"コントローラ直下 貫通銅サーマルビア格子"}],"diagramType":"cfe_hdi_8layer_pcb"},{"id":"cfe-pcie4-controller-soc","order":8,"swatchColor":"#2563eb","groupKey":"カードの超高速頭脳_C08_毎秒1_800_3_750MBの巨大","assembledPos":[-6.2,-9,0.65],"explodeOffset":[-42,-26,26],"integratedExplodeOffset":[-42,-26,26],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C08. 次世代7nm/12nm PCIe Gen4・NVMe 2.0メインコントローラSoC（毎秒1,800〜3,750 MB頭脳）","subtitle":"Next-Gen 7nm/12nm PCIe Gen4 & NVMe 2.0 Main SSD Controller SoC (1,800–3,750 MB/s)","category":"カードの超高速頭脳 C08 — 毎秒1,800〜3,750MBの巨大8K映像を0.001秒の詰まりもなく捌く「超小型SSD頭脳チップ」","plainAnalogy":"カメラが1秒間に30枚もの超高画素RAW写真や8K RAW動画を連射すると、とてつもない量のデータがカードへ流れ込みます！その交通整理を一手に引き受けるのが、先端の7nm〜12nm半導体プロセスで作られたこのメインコントローラSoC。省エネ・低発熱なのに、映画1本分のデータを数秒で書き込む天才指揮官です！","summary":"CFexpress 4.0（PCIe Gen4 / NVMe 2.0規格：Type A最大1,800 MB/s・Type B最大3,750 MB/s）の中枢を担う、先端7nm／12nm FinFETプロセス製造の低消費電力NVMeメインコントローラSoC（Phison PS5027-E27T / Silicon Motion SM2324 / ソニーカスタムコントローラ世代）です。","opticsAndPhysics":["従来のCFexpress 2.0（PCIe Gen3：約800〜1,700 MB/s）から2025〜2026年のCFexpress 4.0（PCIe Gen4）へ進化したことで、データ帯域が一気に2倍へ跳ね上がり、撮影後のパソコン取り込み（オフロード）時間が半分以下へ劇的に短縮されました。","狭いカメラのカードスロット内で発熱を抑え続けるため、微細7nm/12nmプロセスと「SmartIdle（待機時超省電力休止）」などの自律省電力制御を内蔵し、消費電力を約2〜3 W以下へ抑え込んでいます。","NVMe 2.0プロトコルの超低レイテンシ並列キュー処理により、カメラの連写バッファを瞬時に空にして「無限連写」を支えます。"],"formula":{"expression":"CFexpress 4.0：Type A (Gen4×1) 最大 1,800 MB/s ／ Type B (Gen4×2) 最大 3,750 MB/s","description":"先端微細プロセスによる省電力・低発熱化とPCIe Gen4倍速帯域を両立し、8K/12K RAW撮影と爆速PC転送を実現"},"nextGenInnovation":"2025〜2026年の最新CFexpress 4.0コントローラは3,200〜3,600 MT/sの最新3D NANDインターフェースとVPG800/VPG1600定速制御をハードウェア実装。","specs":[{"label":"対応規格","value":"CFexpress 4.0 / PCIe Gen4 / NVMe 2.0"},{"label":"製造プロセス","value":"先端 7 nm / 12 nm 低電力FinFETプロセス"},{"label":"最大転送速度","value":"Type A: 1,800 MB/s ／ Type B: 3,750 MB/s"},{"label":"省電力技術","value":"PCIe L1.2省電力・SmartIdle低発熱休止制御"}],"diagramType":"cfe_pcie4_controller_soc"},{"id":"cfe-arm-dualcore-engine","order":9,"swatchColor":"#7c3aed","groupKey":"長寿命の整理整頓マン_C09_メモリの一部だけ使いすぎて壊れない","assembledPos":[-6.2,-9,1.3],"explodeOffset":[-62,-16,42],"integratedExplodeOffset":[-62,-16,42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C09. コントローラ内蔵マルチコアARM CPU＆FTL（ウェアレベリング・長寿命管理頭脳）","subtitle":"Embedded Multi-Core ARM Cortex-R CPU & FTL (Flash Translation Layer) Wear-Leveling Engine","category":"長寿命の整理整頓マン C09 — メモリの一部だけ使いすぎて壊れないよう、全エリアへ均等に書き分ける賢い図書館司書","plainAnalogy":"メモリーカードのフラッシュメモリには「同じ場所ばかり何度も書き直すとそこだけ先に疲れて壊れる」という弱点があります。そこでコントローラの中に住む超小型ARMコンピューターが「図書館の司書（FTL）」のように働き、全部のページを均等にまんべんなく使って（ウェアレベリング）カード寿命を何倍も長持ちさせています！","summary":"コントローラSoC（C08）内部へ集積されたリアルタイム・マルチコアARM Cortex-Rプロセッサと、論理アドレスを物理NANDブロックへ最適配置するFTL（Flash Translation Layer：ウェアレベリング・ガベージコレクション・TRIM管理）エンジンです。","opticsAndPhysics":["NANDフラッシュは「上書き」ができず必ず「ブロック単位で消去してから書き込む」必要があるため、FTLが空きブロックを先読み整理（ガベージコレクション）することで、動画収録中の突発的な書き込み落ち込み（コマ落ち）を防ぎます。","動的・静的ウェアレベリングにより、全NANDブロックの書き換え回数（P/Eサイクル）を均等化し、1TBカードで数百〜数千TBもの総書込量（TBW）を実現します。","さらに空き時間に裏側でデータをリフレッシュ整理する「データ保持リフレッシュ」により、数年保管した大切な写真の電荷抜けを防ぎます。"],"formula":{"expression":"ウェアレベリング平準化：max(PE_i) − min(PE_i) ≈ 0  →  総書込耐久(TBW)を最大化＆コマ落ちゼロ","description":"全メモリ領域を均等にローテーション活用し、不要データの裏整理を自動化することで長寿命と定速書込みを保証"},"nextGenInnovation":"撮影用動画ストリームを認識してリアルタイム帯域を優先確保する「VPG専用QoS（PerformaShape等）スケジューラ」を搭載。","specs":[{"label":"内蔵CPU","value":"リアルタイム Multi-Core ARM Cortex-R プロセッサ"},{"label":"主要機能①","value":"FTL（論理⇔物理アドレス高速マッピング変換）"},{"label":"主要機能②","value":"動的・静的ウェアレベリング＆自動ゴミ掃除"},{"label":"動画保護","value":"VPG400/800 連続定速書込みリアルタイム制御"}],"diagramType":"cfe_arm_dualcore_engine"},{"id":"cfe-ldpc-ecc-engine","order":10,"swatchColor":"#10b981","groupKey":"データ自動修復ドクター_C10_宇宙線や劣化で_0と1が化けてし","assembledPos":[-6.2,-11.8,1.3],"explodeOffset":[-62,-40,42],"integratedExplodeOffset":[-62,-40,42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C10. ハードウェア4K LDPC誤り訂正（ECC）＆エンドツーエンドデータ保護回路","subtitle":"Hardware 4K LDPC (Low-Density Parity-Check) Soft-Decoding ECC & End-to-End CRC Guard","category":"データ自動修復ドクター C10 — 宇宙線や劣化で「0と1が化けてしまった写真」を数学の力で瞬時に元通り直す守護神","plainAnalogy":"超微細なフラッシュメモリに何兆個もの「0と1」を詰め込むと、ごくまれに熱や時間経過で「1だったはずが0に化ける」エラーが起きます。そこでカード内部の専用ドクター「4K LDPC誤り訂正回路」が、数独パズルを解くような高度な数学計算でエラー箇所を瞬時に見つけ出し、写真が1ピクセルも壊れる前に自動で元通り修復してくれるんです！","summary":"コントローラ内部へ専用ハードウェア実装された、次世代4KB単位・低密度パリティ検査符号（LDPC：Low-Density Parity-Check）ハード／ソフトデコード誤り訂正エンジンと、カード入口からNANDまで全経路を監視するエンドツーエンドデータ保護回路です。","opticsAndPhysics":["3D TLC NANDは1つのセルに3ビット（8段階の微小電圧）を記憶するため、書き換えが進むと電圧の境目が曖昧になります。従来のBCH符号より圧倒的に強力な「4K LDPC符号」を使うことで、4KB当たり数百ビットもの誤りをリアルタイムで無傷修復できます。","通常の読み取り（ハードデコード）で直せないほどの劣化セルに対しても、しきい値電圧を少しずつ変えて確率計算する「ソフトデコード＋リード・リトライ」と、RAID類似のダイ間パリティ保護が何重にもデータを救出します。","さらにPCIe入口→SRAM/DRAM→NANDの全データパスにCRCチェックを付加（End-to-End Protection）し、静かなデータ化け（サイレント破損）を徹底排除します。"],"formula":{"expression":"UBER（訂正不能ビット誤り率）< 10⁻¹⁶  （4K LDPC 軟判定復号＋End-to-End CRC保護）","description":"天文学的な確率レベルまでデータ化けを抑え込み、プロの1発勝負の商業写真・映画データを鉄壁保護"},"nextGenInnovation":"第5世代LDPC＋AI適応しきい値予測により、高温環境や数千回書き換え後の3D NANDでも新車同様のデータ保持信頼性を維持。","specs":[{"label":"誤り訂正方式","value":"ハードウェア 4KB LDPC（硬判定＋軟判定復号）"},{"label":"訂正不能エラー率","value":"UBER < 10⁻¹⁶（エンタープライズSSD級信頼性）"},{"label":"全経路保護","value":"End-to-End Data Path Protection（CRC検証）"},{"label":"データ救済","value":"自動リード・リトライ＆ダイ間パリティ復元"}],"diagramType":"cfe_ldpc_ecc_engine"},{"id":"cfe-aes256-crypto-core","order":11,"swatchColor":"#f59e0b","groupKey":"データの金庫ロック_C11_速度を1ミリも落とさずデータを暗号化","assembledPos":[-10.2,-10.8,1.3],"explodeOffset":[-82,-28,32],"integratedExplodeOffset":[-82,-28,32],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C11. ハードウェアAES-256暗号化＆セキュアブート・ファームウェア改ざん防止エンジン","subtitle":"Hardware AES-256 XTS Inline Encryption & Cryptographic Secure-Boot Firmware Guard","category":"データの金庫ロック C11 — 速度を1ミリも落とさずデータを暗号化し、不正改造ファームウェアの乗っ取りも防ぐ","plainAnalogy":"映画の公開前映像や報道写真が入ったカードを万一落としたり、怪しいウイルスに書き換えられたら大問題ですよね。この暗号エンジンは、データを通過させながら一瞬で世界最強クラスの「AES-256金庫ロック」をかけ、さらに起動時にはカードのプログラム（ファームウェア）が正規の本物か電子署名チェックまで行います！","summary":"コントローラ内蔵の専用ハードウェアAES-256（XTSモード）インライン暗号化エンジンと、RSA/ECDSAデジタル署名でカード自身のファームウェア改ざんを防ぐセキュアブート保護コアです。","opticsAndPhysics":["ソフトウェアではなく専用ハードウェア回路がデータ転送パイプラインの途中で自動暗号化・復号を行うため、最大1,800〜3,750 MB/sの転送速度を1%も落とさずにAES-256セキュリティを適用できます。","TCG Opal / サニタイズ消去（Crypto Erase）に対応し、内部の暗号鍵を1ミリ秒で破棄するだけでカード全容量のデータを復元不可能なレベルで瞬時に完全消去できます。","電源投入ごとに内蔵ROMの公開鍵でファームウェア署名を検証（セキュアブート）し、悪意ある改ざんやファームウェア破損による誤動作を未然に防ぎます。"],"formula":{"expression":"AES-256 インライン暗号（鍵空間 2²⁵⁶ ≈ 1.1×10⁷⁷ 通り）＋ RSA/ECDSA セキュアブート検証","description":"フルスピードを保ったまま軍事級暗号化・瞬時完全消去・ファームウェア改ざん防御をハードウェア実行"},"nextGenInnovation":"カメラ側のC2PAコンテンツ真贋署名（B101）と連携し、撮影からカード記録・納品まで一貫した改ざんゼロの信頼チェーンを構築。","specs":[{"label":"暗号化規格","value":"ハードウェア AES-256（速度劣化ゼロ インライン処理）"},{"label":"起動検証","value":"デジタル署名セキュアブート（改ざん完全防御）"},{"label":"瞬時消去","value":"Crypto Erase（暗号鍵破棄による一瞬安全消去）"},{"label":"対応用途","value":"映画制作機密保護・報道セキュリティ・企業監査"}],"diagramType":"cfe_aes256_crypto_core"},{"id":"cfe-3d-nand-pkg-primary","order":12,"swatchColor":"#0ea5e9","groupKey":"写真と動画の大倉庫_C12_爪先サイズの黒いチップの中に_300","assembledPos":[0,12.6,0.7],"explodeOffset":[-34,38,28],"integratedExplodeOffset":[-34,38,28],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C12. 高密度3D TLC NANDフラッシュ・メインパッケージ（232〜300+層・16ダイ積層BGA）","subtitle":"High-Density 232–300+ Layer 3D TLC NAND Flash Primary BGA Package (Up to 16 Stacked Dies)","category":"写真と動画の大倉庫 C12 — 爪先サイズの黒いチップの中に「300階建ての極小マンション」を16枚重ねた大容量メモリ","plainAnalogy":"昔は1ギガバイトでも大変だったのに、今では小指の爪ほどの黒いチップ1個に「1〜2テラバイト（写真何万枚・8K動画何時間分！）」が入ります。その秘密は「3D NAND」！平屋ではなく縦に232〜300階建て以上の超高層メモリを積み上げ、しかも薄いシリコンチップを1つのパッケージの中に階段状に8〜16枚も重ねているんです！","summary":"Kioxia BiCS8 / Micron 232層 / Samsung V-NAND世代に代表される、232〜300+層もの垂直メモリ層を持つ極薄3D TLC NANDシリコンダイを最大16枚、極細ワイヤーまたはハイブリッド接合で1つのBGAパッケージへ超高密度封入したメイン記憶チップです。","opticsAndPhysics":["「TLC（Triple-Level Cell）」は1つの極小記憶セルに溜める電子の量を8段階（000〜111の3ビット）に精密識別することで、小型カードに1TB〜4TBもの超大容量を実現しています。","最新世代ではCMOS周辺制御回路ウェハーと3Dメモリアレイウェハーを別々に最適化製造してから貼り合わせる「CBA（CMOS directly Bonded to Array）」技術により、最大3,200〜3,600 MT/sという驚異的なI/O速度と省電力化を同時達成しています。","電源を切っても電子を絶縁膜の中に10年近く閉じ込めておける「不揮発性メモリ」だからこそ、電池を抜いたカメラからカードを取り出しても思い出が消えません。"],"formula":{"expression":"記憶容量 ＝ 3 bit/cell (TLC) × 232〜300+ 積層 × 最大 16 ダイ積層  →  1パッケージで最大 2 TB！","description":"300階建て3D構造と16枚チップ立体積層の掛け算により、切手サイズのカードへプロ用テラバイト倉庫を実現"},"nextGenInnovation":"2025〜2026年登場のLexar / Sony 2TB Type A・4TB Type Bカードでは、BiCS8等の300層級3D TLCと超高速Toggle 5.0インターフェースが主役に。","specs":[{"label":"メモリ種別","value":"232〜300+ 層 3D TLC NANDフラッシュ（3 bit/cell）"},{"label":"ダイ積層数","value":"極薄ウェハー研磨 8〜16 ダイ立体積層BGA"},{"label":"NAND I/O速度","value":"最大 2,400〜3,600 MT/s（Toggle / ONFI高速IF）"},{"label":"代表容量帯","value":"240GB / 480GB / 960GB / 1.92TB / 4TB"}],"diagramType":"cfe_3d_nand_pkg_primary"},{"id":"cfe-3d-nand-pkg-secondary","order":13,"swatchColor":"#0284c7","groupKey":"スピード倍増の相棒チップ_C13_レジを2列・4列に増やして同時","assembledPos":[0,12.6,-0.7],"explodeOffset":[34,38,-28],"integratedExplodeOffset":[34,38,-28],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C13. 並列インターリーブ用セカンド3D NANDパッケージ（同時並列書込みで倍速化！）","subtitle":"Secondary 3D NAND Flash Package for Multi-Channel Interleaved Parallel Writing","category":"スピード倍増の相棒チップ C13 — レジを2列・4列に増やして同時進行でデータを流し込み、書き込み速度を一気に倍増","plainAnalogy":"スーパーのレジが1台だけだとお客さんが大行列しますが、レジを4台・8台同時に開ければあっという間に捌けますよね！大容量のCFexpressカードに複数のNANDパッケージ（や複数ダイ）を並べるのは、容量を増やすだけでなく「同時に並列書き込み（インターリーブ）」をして1秒間に何千MBもの爆速記録を実現するためなんです！","summary":"メインNANDパッケージ（C12）と対をなしてコントローラのマルチチャネル・インターリーブバスへ接続されるセカンド3D NANDフラッシュパッケージ。複数チップ・複数プレーンへの並列ストライピング書込みで実効速度を倍増させます。","opticsAndPhysics":["NANDフラッシュ単体（1ダイ）の書き込み速度には物理的な限界（プログラム時間 t_PROG ≈ 数百マイクロ秒）がありますが、複数パッケージの複数プレーンへ順番にずらして同時投入（チャネル並列＋ダイ・インターリーブ）することで待ち時間を完全に隠蔽します。","だからこそ「128GBの小容量モデルより、512GB〜2TBの大容量CFexpressカードの方が連続書込み速度が圧倒的に速い」という現象が起きるのです！（例：Sandisk 4.0では128GBが900 MB/sに対し2TBは3,100 MB/s！）","さらに複数チップへ熱源を物理分散させることで、1箇所への極端な温度集中を抑える放熱メリットも生まれます。"],"formula":{"expression":"BW_write ≈ N_channels × N_interleave × BW_single_die  （並列度が増えるほど連続書込みが爆速化！）","description":"複数NANDパッケージと複数プレーンの同時並列稼働により、1枚の8K RAWフレームを瞬時に分散記録"},"nextGenInnovation":"4プレーン／6プレーン同時アクセス対応の最新3D NANDと組み合わせ、限られたType A面積でもVPG400〜VPG800の超高速持続書込みを実現。","specs":[{"label":"動作方式","value":"マルチチャネル並列＆マルチダイ・インターリーブ"},{"label":"高速化原理","value":"複数プレーン同時ストライピングで待ち時間隠蔽"},{"label":"副次効果","value":"書き込み発熱の面内分散＆長寿命化"},{"label":"特徴","value":"大容量モデルほど並列度が増し持続速度が向上"}],"diagramType":"cfe_3d_nand_pkg_secondary"},{"id":"cfe-pslc-write-cache","order":14,"swatchColor":"#f97316","groupKey":"爆速ターボ書込み帯_C14_3ビット入る部屋を贅沢に_1ビット専","assembledPos":[0,7.6,1.45],"explodeOffset":[44,24,36],"integratedExplodeOffset":[44,24,36],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C14. ダイナミック／ネイティブpSLC高速キャッシュ領域（VPG400/VPG800途切れない保証）","subtitle":"Dynamic & Native pSLC (Pseudo-SLC 1-bit/cell) High-Speed Write Zone (VPG400/800)","category":"爆速ターボ書込み帯 C14 — 3ビット入る部屋を贅沢に「1ビット専用」で使うことで、8K動画が1フレームも止まらない","plainAnalogy":"1つのロッカーに荷物を3つキツキツに詰める（TLC）と時間がかかりますが、急いでいるときは「1ロッカーに1個だけポンと入れる（pSLCモード）」にすれば3倍以上速く入れられますよね！プロのCFexpressカードはこの超高速「pSLCターボエリア」を活用して、8K RAWや秒間120コマ連写を息切れゼロで受け止め続けるんです！","summary":"3D TLC NANDの一部または全領域を、1セル当たり1ビット（2値：0か1）だけで駆動する「pSLC（疑似SLC：Pseudo-SLC）」モードとして運用する超高速キャッシュ＆定速記録領域。CFA公式のVPG400（400 MB/s保証）／VPG800（800 MB/s保証）を支える核心技術です。","opticsAndPhysics":["TLC（8段階の精密電圧制御）に比べ、pSLC（2段階の単純判定）は書き込みプログラム時間が約1/4〜1/5と桁違いに短く、書き換え寿命も数万回クラスへ約10倍向上し、さらに発熱も大幅に下がります。","ソニーTOUGHシリーズやプロ用VPG800カードでは、高速なpSLCバッファでカメラの爆速バーストを無遅延で受け止めつつ、裏側で効率よくTLC領域へ折り畳み転送（または全容量ネイティブpSLC運用）することで、カード残量が少なくなっても極端な速度落ちを起こさないよう緻密チューニングされています。","VPG400／VPG800認定は「カード全体を通して1秒たりとも最低保証速度を下回らない」という厳格なプロ動画試験に合格した証です。"],"formula":{"expression":"TLC (3 bit / 8値) → pSLC運用 (1 bit / 2値)：書込速度 約 3〜5× 高速化 ＋ 書換寿命 約 10× 向上！","description":"1セル1ビットの贅沢高速運用で書き込み遅延と発熱を劇減させ、VPG400/800のコマ落ちゼロ収録を死守"},"nextGenInnovation":"2025〜2026年は全容量をpSLC化した超耐久・超低温シネマカードや、1,600 MB/s持続のVPG1600モデルが12K RAW撮影現場で普及。","specs":[{"label":"記録方式","value":"pSLC（Pseudo-SLC：1 bit/cell 高速・高耐久駆動）"},{"label":"動画保証基準","value":"VPG400 (≥400 MB/s) / VPG800 (≥800 MB/s)"},{"label":"寿命向上効果","value":"通常TLC比 約 5〜10 倍の書き換え耐久性"},{"label":"熱メリット","value":"ベリファイ回数激減による書き込み発熱低下"}],"diagramType":"cfe_pslc_write_cache"},{"id":"cfe-3d-nand-vertical-pillar","order":15,"swatchColor":"#a855f7","groupKey":"ミクロの超高層マンション_C15_髪の毛の1_1000の極細の柱","assembledPos":[0,15.8,1.38],"explodeOffset":[-24,62,54],"integratedExplodeOffset":[-24,62,54],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C15. 3D NAND超高層「チャージトラップ（CTF）垂直メモリ柱」拡大構造","subtitle":"3D NAND Vertical Charge-Trap Flash (CTF) Memory Channel Pillar & 232+ Wordline Stack","category":"ミクロの超高層マンション C15 — 髪の毛の1/1000の極細の柱に232階以上の「電子の部屋」が並ぶナノ建築の奇跡","plainAnalogy":"黒い記憶チップの中を電子顕微鏡で超拡大すると、なんと「232〜300階建ての超高層タワーマンション」が何億本も森のように建ち並んでいます！1本の極細の柱（メモリホール）の各階に小さな絶縁体のポケット（チャージトラップ）があり、そこに電子を閉じ込める数で「写真のデータ」を何年も記憶しているんです！","summary":"3D TLC NANDシリコンダイの内部構造を可視化した、垂直エッチング貫通メモリチャンネル柱（直径約80 nm）、232〜300+層のタングステン制御ゲート（ワードライン）積層、および窒化シリコン・チャージトラップ（CTF）電子捕獲層のナノ記憶セル拡大解剖モデルです。","opticsAndPhysics":["書き込み時は制御ゲート（ワードライン）へ約20Vのパルス電圧を印加し、量子力学的な「ファウラー・ノルドハイム（FN）トンネル効果」で電子を薄い酸化膜の壁をすり抜けさせて窒化シリコンのトラップ層へ閉じ込めます。","従来の浮遊ゲート（導体）と違い、絶縁体の窒化シリコン（チャージトラップ）を使うことで、膜に1箇所ミクロの傷ができても全部の電子が逃げ出さず、圧倒的なデータ保持信頼性を得られます。","縦に何百層も貫く高アスペクト比（幅1に対し深さ100以上！）の微細穴を原子レベルで真っ直ぐ掘る「クライオ（極低温）エッチング」が現代半導体最高峰の技術です。"],"formula":{"expression":"FNトンネル注入：V_prog ≈ 20 V → 電子が酸化膜壁を量子トンネル通過し窒化膜トラップへ10年保存！","description":"量子トンネル効果で各階の絶縁ポケットへ電子を出し入れする、人類最高密度の3次元ナノ記憶アーキテクチャ"},"nextGenInnovation":"2025〜2026年には300層超・400層世代へ突入し、1平方ミリメートルあたり20ギガビット超という驚異的な記録密度へ到達。","specs":[{"label":"記憶原理","value":"CTF（Charge-Trap Flash：窒化シリコン電子捕獲）"},{"label":"垂直積層数","value":"232〜300+ 階（超高アスペクト比エッチング柱）"},{"label":"書込み現象","value":"量子力学的 FN（ファウラー・ノルドハイム）トンネル効果"},{"label":"記憶保持","value":"無電源で長期データ保持（不揮発性メモリ）"}],"diagramType":"cfe_3d_nand_vertical_pillar"},{"id":"cfe-lpddr4-dram-cache","order":16,"swatchColor":"#6366f1","groupKey":"超高速インデックス帳_C16_2TBの巨大な倉庫の_どこに何があ","assembledPos":[9.4,-8.5,0.85],"explodeOffset":[56,-24,24],"integratedExplodeOffset":[56,-24,24],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C16. 超高速LPDDR4 DRAMキャッシュメモリIC（巨大アドレス目次を瞬時参照）","subtitle":"Low-Power LPDDR4/LPDDR4X DRAM Cache IC (Instant FTL Mapping Table & Burst Accelerator)","category":"超高速インデックス帳 C16 — 2TBの巨大な倉庫の「どこに何があるか」を0.000001秒で引き出す専用メモ帳チップ","plainAnalogy":"図書館の本が何百万冊もあると、毎回本棚を探し回っていたら日が暮れてしまいますよね。そこで受付のすぐ横に「超高速の目次ノート（LPDDR4 DRAMキャッシュ）」を置いておけば、カメラから「ここに保存して！」と来た瞬間に0.000001秒で空き場所がわかり、連写バッファを一瞬で空っぽにできるんです！","summary":"プロ向けハイエンドCFexpressカードへ搭載される、大容量FTL（論理⇔物理アドレス変換）マッピングテーブルを丸ごと常駐させるための低電圧・超高速LPDDR4／LPDDR4X DRAMキャッシュメモリIC（またはオンチップ大容量SRAMバッファ）です。","opticsAndPhysics":["1TBのカードには約2億5,000万個もの4KBページが存在するため、その住所録（FTLテーブル）だけで約1 GB近くの容量になります。これをNANDから毎回読むと遅くなりますが、DRAMキャッシュへ常駐させるとランダムアクセスと連続連写時のレスポンスが劇的に向上します。","1.1V駆動のLPDDR4低消費電力規格を使うことで、カード内部の発熱とカメラのバッテリー消費を抑えながら毎秒数ギガバイトの目次参照をこなします。","一方で最新世代の省電力DRAMレス（HMB/大容量オンチップSRAM）設計との使い分けにより、用途に応じた最適な熱・速度バランスを実現しています。"],"formula":{"expression":"FTL目次サイズ ≈ カード容量の 0.1%（1 TB → 約 1 GB） ／ DRAMアクセス遅延 ≈ 15 ns（NANDの約1,000倍速！）","description":"住所録を高速DRAMへ常駐させることで、2TB級の大容量カードでも連写・サムネイル一覧表示を爆速レスポンス化"},"nextGenInnovation":"最新世代ではオンパッケージ大容量SRAMとLPDDR4X超低電力スリープを組み合わせ、8K連続書込み時の定速安定性と低発熱を両立。","specs":[{"label":"メモリ種別","value":"超低電圧 LPDDR4 / LPDDR4X（1.1 V 駆動）"},{"label":"主な役割","value":"FTL論理・物理マッピング表の高速キャッシュ"},{"label":"速度メリット","value":"NAND参照比 約 1,000 倍の超低遅延アドレス解決"},{"label":"撮影効果","value":"連写後バッファ解放＆大量写真再生スクロール高速化"}],"diagramType":"cfe_lpddr4_dram_cache"},{"id":"cfe-pmic-buck-regulator","order":17,"swatchColor":"#ef4444","groupKey":"カード内部の変電所_C17_カメラから届く3_3Vの電気を各チッ","assembledPos":[9.6,-9.2,-0.85],"explodeOffset":[56,-22,-26],"integratedExplodeOffset":[56,-22,-26],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C17. カード内蔵マルチチャネルPMIC電源管理IC（3.3V→0.9V/1.2V/1.8V精密降圧）","subtitle":"On-Card Multi-Channel Synchronous Buck PMIC (3.3V Host Rail to 0.9V/1.2V/1.8V/2.5V)","category":"カード内部の変電所 C17 — カメラから届く3.3Vの電気を各チップ好みの電圧へ無駄なく変換する超小型電源係","plainAnalogy":"カメラのスロットから届く電気は「3.3ボルト」の1種類だけ。でもカードの中の7nm頭脳チップは「0.85ボルト」、DRAMは「1.1ボルト」、3D NANDは「1.8ボルト＆2.5ボルト」とみんな欲しい電圧がバラバラ！そこで極小の「多出力変電所（PMIC）」が変換効率92%超でそれぞれの電圧をピッタリ配り分けています！","summary":"PCIeコネクタから供給される単一3.3V電源を、メインコントローラコア用（0.85V）、LPDDR4用（1.1V）、NAND I/O用（1.2V/1.8V）、およびNANDコア用（2.5V）の複数レイルへ高効率同期整流降圧（バック変換）するカード内蔵PMICチップです。","opticsAndPhysics":["発熱が最大の敵となる切手サイズのカード内では、単純なドロッパー（LDO）だと電力の半分以上が熱になってしまいます。数MHzの超高周波スイッチング同期整流PMICにより変換効率90〜95%を達成し、カード自身の無駄な発熱を徹底削減します。","電源投入時の立ち上がり順序（パワーシーケンス）をマイクロ秒単位で精密制御し、活線挿抜やカメラ起動時の突入電流（インラッシュ）による誤動作を防ぎます。","撮影待ちのアイドル時にはコントローラと連動して使わない電圧レイルを瞬時に休止（L1.2低電力ステート：数十mW）させ、カメラの電池持ちとカード冷却を両立します。"],"formula":{"expression":"3.3 V ホスト給電 → 多出力高効率PMIC (η ≈ 93%) → [0.85V SoC / 1.1V DRAM / 1.8V & 2.5V NAND]","description":"超高効率マルチチャネル変電所が変換ロス発熱を最小化し、省電力待機と8Kフルパワー給電を瞬時切替"},"nextGenInnovation":"動的な負荷に応じて電圧をミリボルト刻みで自動調整するAVS（適応電圧スケーリング）により、CFexpress 4.0の消費電力を2.0世代以下に抑制。","specs":[{"label":"入力電源","value":"PCIe スロット供給 DC 3.3 V（±5%）"},{"label":"出力レイル","value":"0.85V / 1.1V / 1.2V / 1.8V / 2.5V 多系統同時生成"},{"label":"変換効率","value":"最大 92〜95%（高周波同期整流バック変換）"},{"label":"省電力機能","value":"PCIe L1.2 アイドル時 < 50 mW 超省エネ待機"}],"diagramType":"cfe_pmic_buck_regulator"},{"id":"cfe-power-inductors-mlcc","order":18,"swatchColor":"#d97706","groupKey":"極小の電気ダム群_C18_厚さ0_8ミリの超薄コイルと砂粒サイズ","assembledPos":[0,0,0],"explodeOffset":[54,4,-36],"integratedExplodeOffset":[54,4,-36],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C18. 極薄シールドパワーインダクタ＆高密度0201積層セラミックコンデンサ（MLCC）群","subtitle":"Ultra-Low-Profile Metal-Alloy Shielded Power Inductors & 0201/01005 MLCC Decoupling Bank","category":"極小の電気ダム群 C18 — 厚さ0.8ミリの超薄コイルと砂粒サイズのコンデンサ群が電気の波をピタッと静める","plainAnalogy":"カード全体の厚さはたった2.8ミリしかないので、普通の背の高い部品は1個も入りません！そこで厚さ0.8ミリ以下の超ペラペラな「磁気シールド付きコイル（インダクタ）」と、くしゃみで飛んでいくほど小さい砂粒サイズ（0.6×0.3 mm）のコンデンサを何十個もびっしり並べて、電気のノイズや電圧ブレを綺麗に抑え込んでいます！","summary":"カード内蔵PMIC（C17）のスイッチング出力を滑らかな直流へ平滑化する高さ0.6〜0.8 mmの超薄型メタルアロイ・シールドインダクタと、コントローラ・NANDの直近へびっしり配置された0201／01005サイズの積層セラミックコンデンサ（MLCC）デカップリング群です。","opticsAndPhysics":["金属磁性粉一体成型シールドインダクタを採用することで、数MHzのスイッチング磁束が隣のPCIe Gen4高速配線へ飛び火する磁気干渉（クロストーク）を封じ込めます。","3D NANDは書き込みパルス発生の瞬間にナノ秒オーダーの急激な電流スパイクを吸い込むため、極小0201（0.6×0.3 mm）MLCCをパッケージ直近へ数十個並列配置して超低ESL（等価直列インダクタンス）で瞬時に電気を補給します。","この高密度マイクロ受動部品群の配置品質が、高温環境での書き込み安定性とEMI静粛性を影で支えています。"],"formula":{"expression":"高さ h ≤ 0.8 mm シールドコイル ＋ 0201 MLCC (0.6×0.3 mm) 並列群 → 電源リップル < 20 mV_pp","description":"2.8mmの極薄カード内へ収まる超低背コイルと砂粒コンデンサ群が、爆速動作時の電源ノイズを徹底鎮静"},"nextGenInnovation":"超微細01005サイズ（0.4×0.2 mm）MLCCと一体成型インダクタの採用により、限られたType A基板面積でも大容量NANDの実装スペースを最大化。","specs":[{"label":"パワーコイル","value":"高さ 0.6〜0.8 mm メタル一体シールドインダクタ"},{"label":"コンデンサ寸法","value":"0201 (0.6×0.3 mm) / 01005 超微細MLCC群"},{"label":"電源安定度","value":"ピーク書込み時リップル < 20 mV_pp 抑制"},{"label":"ノイズ対策","value":"磁気シールド構造でPCIe高速線への干渉ゼロ"}],"diagramType":"cfe_power_inductors_mlcc"},{"id":"cfe-plp-hold-caps","order":19,"swatchColor":"#eab308","groupKey":"突然の停電レスキュー_C19_録画中にうっかり電池が切れても_最","assembledPos":[-10.2,-10.5,-0.9],"explodeOffset":[-56,-24,-30],"integratedExplodeOffset":[-56,-24,-30],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C19. 電源瞬断保護（PLP）タンタル／ポリマー大容量ホールドコンデンサ","subtitle":"Power-Loss Protection (PLP) Low-Profile Tantalum/Polymer Hold-Up Capacitor Bank","category":"突然の停電レスキュー C19 — 録画中にうっかり電池が切れても「最後の0.01秒」だけ粘ってファイル破損を防ぐ予備タンク","plainAnalogy":"大事な動画の録画中にカメラの電池が切れたり、間違えてカードを抜きそうになったらゾッとしますよね。この平べったい「ホールドコンデンサ」はカード内部の極小非常用バッテリー！電源が切れた瞬間の「たった数ミリ秒」だけ電気を粘って供給し、書きかけの目次データ（FTL）を急いで安全な場所へ保存してファイル全滅を防ぎます！","summary":"不意のバッテリー切れ・接触瞬断・強制シャットダウン時に数ミリ秒の非常電力をカード内部へ供給し、DRAM/SRAMキャッシュ内の書きかけメタデータ（FTL目次）を3D NANDへ安全フラッシュ完了させるための、超薄型導電性高分子タンタル・ホールドコンデンサ（PLP）バンクです。","opticsAndPhysics":["メモリーカードで最も恐ろしい「カード全体が認識不能（フォーマット要求）」トラブルの多くは、写真本体ではなく住所録（FTLテーブル）を書き換えている最中に電源が途絶えることで起きます。","PMICの電圧低下監視回路が3.3Vの急落（約2.9V以下）を検知した瞬間、ホールドコンデンサに蓄えたエネルギー（E = ½CV²）を使ってコントローラが緊急フラッシュを実行し、論理整合性を100%守ります。","薄型ポリマー・タンタルコンデンサは高温（70℃超）でも容量低下が少なく、液漏れリスクもゼロの高い長期信頼性を備えています。"],"formula":{"expression":"E_hold = ½ C (V_nom² − V_min²)  →  瞬断後 数 ms の非常給電でFTL目次を安全退避！","description":"不意の電池切れでも書きかけの住所録を安全に閉じ切り、「カード全体が読めなくなる悲劇」を未然に防止"},"nextGenInnovation":"ファームウェア側の原子書込み（アトミック・メタデータ更新）とハードウェアPLPの二重防御により、プロシネマ現場の突発停電耐性を極限まで強化。","specs":[{"label":"コンデンサ種別","value":"超薄型 導電性高分子タンタル／ポリマーキャパシタ"},{"label":"保護機能","value":"PLP（Power-Loss Protection：瞬断データ保護）"},{"label":"退避対象","value":"書きかけのFTLマッピング目次＆キャッシュデータ"},{"label":"防止トラブル","value":"電池切れ時のカード認識不能・ファイルシステム破損"}],"diagramType":"cfe_plp_hold_caps"},{"id":"cfe-pcie-ac-coupling","order":20,"swatchColor":"#14b8a6","groupKey":"超高速データの関門_C20_毎秒160億回の超高速信号を通しなが","assembledPos":[-2,-18.5,0.72],"explodeOffset":[-34,-52,34],"integratedExplodeOffset":[-34,-52,34],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C20. PCIe Gen4高速差動レーン用ACカップリングコンデンサ＆インピーダンス整合配線","subtitle":"PCIe Gen4 16 GT/s Differential Lane AC-Coupling 0201 Capacitors & Anti-Pad Routing","category":"超高速データの関門 C20 — 毎秒160億回の超高速信号を通しながら、直流の電圧ズレだけを綺麗にカットする透明フィルター","plainAnalogy":"カメラ本体とCFexpressカードは別の会社が作っているので、電気の基準（直流電圧）が微妙に違うことがあります。そこでPCIe高速データ線のすぐ入り口に「ACカップリングコンデンサ」という小さなフィルターを直列に挟み、直流のズレだけをシャットアウトして毎秒160億回の高速データ波だけをピシッと通しているんです！","summary":"PCIe Gen4規格（16 GT/s）の送信差動ペア（TX+/TX-）へ直列挿入された、極小0201サイズ・0.22 µF（220 nF）ACカップリングコンデンサ群と、パッド直下の内層グラウンドを精密くり抜き（アンチパッド加工）した超低反射高速差動配線構造です。","opticsAndPhysics":["PCIe Base Specification 4.0では、送信側（TX）へ176〜265 nF（標準220 nF）のACカップリングコンデンサを挿入し、カメラ側とカード側の直流コモンモード電圧を完全に切り離すことが厳格に定められています。","16 GT/s（ナイキスト周波数 8 GHz！）の世界ではコンデンサのハンダパッドのわずかな寄生容量すら信号反射の原因になるため、基板内層の真下の銅箔を最適サイズで抜く「アンチパッド最適化」と45°/曲線ベンド配線で85 Ωインピーダンスを寸分違わず維持します。","これにより、ケーブルやコネクタを通過しても受信側の信号波形（アイダイアグラム）がクッキリ大きく開き、ビットエラーゼロの爆速転送が成り立ちます。"],"formula":{"expression":"C_AC = 220 nF (PCIe Gen4標準) ／ Z_diff = 85 Ω（アンチパッド整合・反射損失 S11 < -15 dB @ 8 GHz）","description":"毎秒160億ビットの超高周波波だけを無反射で通す精密カップリングとマイクロ波級の基板配線設計"},"nextGenInnovation":"CFexpress 4.0（PCIe Gen4）への移行にあたり、最も緻密な高周波シミュレーション（3D電磁界解析）が注ぎ込まれた高速信号の要。","specs":[{"label":"コンデンサ容量","value":"220 nF（0.22 μF）0201 低インダクタンスMLCC"},{"label":"対応信号速度","value":"PCIe Gen4.0 16 GT/s（ナイキスト 8 GHz）"},{"label":"基板高周波技術","value":"パッド直下アンチパッドくり抜き＆85Ω等長配線"},{"label":"主な役割","value":"ホスト⇔カード間のDC分離＆超低反射高速伝送"}],"diagramType":"cfe_pcie_ac_coupling"},{"id":"cfe-esd-tvs-diode-array","order":21,"swatchColor":"#e11d48","groupKey":"静電気の避雷針_C21_冬のパチッ_という1万5千ボルトの静電気","assembledPos":[0,-20.8,-0.75],"explodeOffset":[34,-52,-34],"integratedExplodeOffset":[34,-52,-34],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C21. 極低容量TVS静電気保護ダイオードアレイ（±15 kV静電気から21ピンを死守）","subtitle":"Ultra-Low-Capacitance (0.2 pF) TVS ESD Protection Diode Array (±15 kV Air Discharge Guard)","category":"静電気の避雷針 C21 — 冬のパチッ！という1万5千ボルトの静電気を10億分の1秒で地面へ逃がす超小型避雷針","plainAnalogy":"冬にセーターを着てカメラからカードを抜き差しすると、指先から「パチッ！」と静電気（なんと1万ボルト超！）が飛ぶことがあります。そのまま7nmの繊細な頭脳チップへ入ったら一瞬で即死！そこで21ピン端子のすぐ後ろに「極小の避雷針（TVSダイオード）」を並べ、静電気の雷だけを10億分の1秒でアースへ逃がしているんです！","summary":"21ピン高速エッジコネクタの直後へ並列配置された、接合容量わずか0.15〜0.25 pFの超低容量TVS（過渡電圧抑制）静電気保護ダイオードアレイ。IEC 61000-4-2（気中±15 kV／接触±8 kV）の静電気放電パルスをナノ秒未満でクランプ逃がしします。","opticsAndPhysics":["通常の保護ダイオードは寄生容量が大きすぎてPCIe Gen4（16 GT/s）の高速波形をなまらせてしまいますが、専用シリコン・アバランシェTVSアレイは容量わずか約0.2 pFという透明さ（信号へ一切影響ゼロ）を実現しています。","通常時は完全に電気を通さない「見えない壁」として待機し、端子に高圧静電気パルスが飛び込んだ瞬間だけサブナノ秒で導通して雷電流をGNDシェルへバイパスします。","ソニーTOUGHカードが謳う「耐静電気（ESD）プロテクト」を物理的に支える最前線の守護チップです。"],"formula":{"expression":"C_j ≈ 0.20 pF（PCIe Gen4無減衰） ／ 応答時間 < 0.5 ns ／ IEC 61000-4-2 ±15 kV クランプ保護","description":"高速通信を一切邪魔しない極小容量のまま、冬場の強烈な静電気ショックから7nmコントローラを完全防衛"},"nextGenInnovation":"フロースルー（貫通型）パッケージ配置により、差動配線に余計な枝分かれ（スタブ）を作らずに全レーンへ直列通過保護を実装。","specs":[{"label":"静電気耐圧","value":"IEC 61000-4-2 気中 ±15 kV / 接触 ±8 kV"},{"label":"寄生容量","value":"約 0.20 pF（PCIe Gen4 16 GT/s 完全透過）"},{"label":"クランプ応答","value":"< 0.5 ns（雷パルス到達前に瞬時アース逃がし）"},{"label":"配置位置","value":"21ピン金メッキ端子直後の最前線フロースルー配置"}],"diagramType":"cfe_esd_tvs_diode_array"},{"id":"cfe-xtal-clock-gen","order":22,"swatchColor":"#facc15","groupKey":"超高速リズムメーカー_C22_毎秒何十億回ものデータ受け渡しを1","assembledPos":[8.5,-17.5,0.75],"explodeOffset":[46,-46,30],"integratedExplodeOffset":[46,-46,30],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C22. 超小型水晶振動子＆PCIe 100 MHzリファレンスクロックPLLバッファ","subtitle":"Ultra-Miniature 1612 Crystal Oscillator & PCIe Gen4 100 MHz REFCLK Differential PLL Buffer","category":"超高速リズムメーカー C22 — 毎秒何十億回ものデータ受け渡しを1ピコ秒の狂いもなく刻む超小型クォーツ時計","plainAnalogy":"1秒間に何十億ビットもの「0と1」をカメラとカードでキャッチボールするとき、お互いのリズムが10億分の1秒でもズレたら文字化けしてしまいます！この米粒より小さい水晶振動子（クォーツ）と専用PLL回路が、超正確な基準リズムを刻んで高速PCIe通信と3D NAND書込みの足並みをピッタリ揃えています！","summary":"1.6×1.2 mmサイズの超小型水晶振動子（26 MHz／40 MHzローカル基準クロック）と、カメラ側ホストから供給される100 MHz差動PCIeリファレンスクロック（REFCLK+/−）を低ジッター整形・逓倍する内部PLLクロック回路です。","opticsAndPhysics":["PCIe Gen4（16 GT/s）では、1ビットの時間幅がわずか 62.5 ピコ秒（1兆分の62.5秒！）しかないため、クロックの揺らぎ（RMS位相ジッター）を 0.5 ピコ秒未満へ抑える超低ノイズPLLと電源フィルタが必須です。","また、カード内部のARM CPUやNAND高速Toggleバス（最大3,600 MT/s）の自律動作・ガベージコレクション用に、ホストクロック休止時（L1.2省電力時）でも動く独立ローカル水晶振動子を備えています。","スペクトラム拡散クロック（SSC：-0.5%ダウン拡散）に対応し、100 MHz高調波ノイズがカメラのWi-Fi・マイクへ乗るのを防ぎます。"],"formula":{"expression":"T_bit(Gen4) = 1 / 16 GHz = 62.5 ps  （クロック揺らぎ σ_j < 0.5 ps RMS の超精密同期！）","description":"1兆分の62.5秒という極細ビット窓へ正確にデータを送り込む、超低ジッター水晶＆PCIeクロック同期網"},"nextGenInnovation":"ホスト側リファレンスクロック不要で自律同期できるSRIS（Separate Refclk Independent SSC）対応により、幅広いカメラ＆USB4カードリーダーと高互換接続。","specs":[{"label":"水晶サイズ","value":"超小型 1612 パッケージ（1.6 × 1.2 mm）"},{"label":"ホスト基準時計","value":"PCIe 差動 100 MHz REFCLK（SSC低EMI対応）"},{"label":"許容ジッター","value":"< 0.5 ps RMS（PCIe Gen4 厳格規格クリア）"},{"label":"役割","value":"PCIe SerDes・ARM CPU・3D NAND高速同期基準"}],"diagramType":"cfe_xtal_clock_gen"},{"id":"cfe-spi-nor-firmware","order":23,"swatchColor":"#8b5cf6","groupKey":"起動プログラムの金庫_C23_カードの電源が入った0_01秒後に","assembledPos":[-11.2,0.2,-0.82],"explodeOffset":[-60,8,-32],"integratedExplodeOffset":[-60,8,-32],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C23. 専用シリアルNORフラッシュメモリ（NVMeファームウェア＆工場不良ブロック地図ROM）","subtitle":"Dedicated SPI NOR Flash Memory (NVMe Boot Firmware & Factory Bad-Block Table ROM)","category":"起動プログラムの金庫 C23 — カードの電源が入った0.01秒後に最初に読み込む「取扱説明書と工場地図のチップ」","plainAnalogy":"パソコンの電源を入れるとまず「起動プログラム（BIOS）」が動きますよね。CFexpressカードの中にも、大容量の写真倉庫（NAND）とは別に、絶対にデータが消えにくい堅牢な「専用NORフラッシュ」が入っています！ここにはカードの頭脳を動かすプログラム（ファームウェア）と「工場で見つけた使えない部屋の地図」が大切に保存されています。","summary":"コントローラSoCのブートシーケンス時に最優先で読み出される、高信頼シリアルSPI NORフラッシュメモリ（またはデュアル冗長ブートROM領域）。NVMe 2.0ファームウェア、VPG制御パラメータ、および工場選別不良ブロック表（Bad-Block Map）を格納します。","opticsAndPhysics":["大容量なNANDフラッシュは構造上わずかな不良ブロックやビット誤りが避けられませんが、NORフラッシュは1バイト単位のランダム高速読出しと20年超の極めて高いデータ保持信頼性を誇ります。","カメラの電源を入れてから数十ミリ秒でカードが撮影可能（Ready）になる爆速起動は、このNORフラッシュからの高速ファームウェア展開のおかげです。","OWC Innergizeやメーカー公式ツールによるユーザー自身での「カード・ファームウェアアップデート」でも、旧版を残した二重バンク更新で安全に最新カメラ互換性へ進化させられます。"],"formula":{"expression":"電源ON → SPI NOR読出し(数 ms) → セキュアブート署名検証 → NVMe 2.0 Ready（即座に撮影開始！）","description":"高信頼ブートメモリと工場不良マップにより、爆速起動と新カメラ対応ファームウェア更新を安全に実現"},"nextGenInnovation":"A/Bデュアルバンク冗長ファームウェア領域により、アップデート中に万一PCのUSBが抜けてもカードが文鎮化せず旧版へ自動復旧。","specs":[{"label":"メモリ種別","value":"高信頼シリアル SPI NOR フラッシュ（16〜64 Mbit）"},{"label":"格納データ","value":"NVMe 2.0 ファームウェア・VPG制御・不良ブロック地図"},{"label":"データ保持","value":"20 年以上（超長期不揮発性・二重バンク冗長）"},{"label":"メリット","value":"電源ONからの爆速レディ起動＆現場ファーム更新対応"}],"diagramType":"cfe_spi_nor_firmware"},{"id":"cfe-thermal-sensor-diode","order":24,"swatchColor":"#f43f5e","groupKey":"賢い熱セーフティ_C24_熱くなりすぎても急に録画を止めず_ギリ","assembledPos":[-0.2,-2,0.75],"explodeOffset":[-42,4,42],"integratedExplodeOffset":[-42,4,42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C24. 高精度デジタル温度センサー＆インテリジェント・サーマルスロットリング制御","subtitle":"Precision Digital Thermal Diode & Smooth NVMe Adaptive Thermal Throttling Control","category":"賢い熱セーフティ C24 — 熱くなりすぎても急に録画を止めず、ギリギリ安全な速度へ滑らかに調整して守り抜く温度番人","plainAnalogy":"炎天下で8K動画をずっと撮り続けるとカードは70℃近くまで熱くなります。そのまま限界を超えるとチップが壊れて録画がプツッと強制終了！そこで内蔵の温度センサーが0.5℃刻みで熱を見張り、アツアツになる少し手前から賢くペース配分（サーマルスロットリング）をして、壊れず止まらず最後まで撮り切れるよう守っているんです！","summary":"コントローラダイ内部および基板ホットスポットへ配置された精度±1℃のデジタル温度センサー（バンドギャップ熱ダイオード＋ADC）と、NVMe HCTM（Host-Controlled Thermal Management）対応の多段階サーマルスロットリング制御機構です。","opticsAndPhysics":["従来の急激なスロットリング（いきなり速度が1/10へ落ちる）では動画のコマ落ちが発生するため、最新のCFexpress 4.0カードは温度に応じてクロック・待機挿入を滑らかに多段階制御し、VPG400/VPG800最低保証速度を死守しつつ発熱を均衡させます。","NVMe SMARTログを通じて現在のカード温度（Composite Temperature）をカメラ本体やPCユーティリティへ常時報告し、カメラ側の冷却ファン（B88）や過熱警告アイコンとも協調動作します。","極限温度（約85℃超のクリティカル限界）へ達した際はデータ保持エラーを防ぐため安全保護シャットダウンを実行します。"],"formula":{"expression":"T < 68 ℃: 100%全開 → 68〜78 ℃: VPG維持スムーズ制御 → > 85 ℃: データ保護リミット作動","description":"温度を±1℃で常時監視し、VPG動画保証を落とさない滑らかな熱制御で長時間8K収録の安定性を死守"},"nextGenInnovation":"Sandisk SmartIdleやSony高効率ファームウェアのように、書込みの合間のミリ秒単位の隙間で瞬時に低電力休止へ落とし発熱自体を作らない設計へ進化。","specs":[{"label":"計測精度","value":"±1.0 ℃（分解能 0.25〜0.5 ℃ デジタル出力）"},{"label":"熱制御規格","value":"NVMe 2.0 HCTM（適応型多段階サーマル管理）"},{"label":"動作保証上限","value":"カード表面動作保証 -12 ℃ 〜 +72 ℃"},{"label":"動画保護","value":"熱制御中もVPG最低保証書込み速度を極力死守"}],"diagramType":"cfe_thermal_sensor_diode"},{"id":"cfe-copper-heat-spreader","order":25,"swatchColor":"#ea580c","groupKey":"超高速の熱ぬき銅板_C25_コントローラ1点に集中した熱をカード","assembledPos":[0,2.2,1.78],"explodeOffset":[0,0,44],"integratedExplodeOffset":[0,0,44],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C25. ソニー独自・高熱伝導「純銅ヒートスプレッダー＆熱拡散プレート」","subtitle":"Proprietary High-Conductivity Pure Copper Internal Heat Spreader & Thermal Diffusion Plate","category":"超高速の熱ぬき銅板 C25 — コントローラ1点に集中した熱をカード全面へ一気に広げて冷やす、ソニーTOUGHの隠し玉","plainAnalogy":"カードの中で一番アツくなるのは「頭脳チップ（コントローラ）」たった1箇所！ほっておくとそこだけ火傷しそうに熱くなって速度が落ちてしまいます。そこでチップの真上に熱の伝わりやすさ抜群の「純銅ヒートスプレッダー板」を敷き詰め、1点の熱をカード全面へ一気に広げて金属外装から効率よく外へ逃がしているんです！","summary":"ソニーCEA-Gシリーズ等のハイエンドCFexpressカード内部に組み込まれる、熱伝導率約 398 W/m·K の高純度無酸素銅（C1020系）極薄ヒートスプレッダープレート。コントローラSoCの局所ホットスポットをカード全面へ高速水平拡散します。","opticsAndPhysics":["プラスチック樹脂の熱伝導率（約0.2 W/m·K）に比べ、純銅は約2,000倍もの圧倒的な熱伝導能力（398 W/m·K）を持ちます。","コントローラ直上で発生した約2〜3 Wの局所集中熱を、厚さ0.15〜0.25 mmの純銅プレートが数秒以内にカード全面積（20×28 mm）へ均一拡散させ、表面の金属アーマー（C01）とカメラ側の放熱ブリッジ（B90）へ最大限の面積で引き渡します。","これにより、小さなType Aサイズでありながら8K／4K 120pの長時間連続記録でも安定してフルスピードを維持できます。"],"formula":{"expression":"k_Cu ≈ 398 W/(m·K)（一般樹脂の約 2,000 倍！） → 局所ホットスポット温度を約 12〜18 ℃ 低減！","description":"コントローラ1点集中の熱を純銅プレートでカード全面へ素早く拡散し、長回し8K撮影の熱だれを劇的に抑制"},"nextGenInnovation":"CFexpress 4.0世代では銅スプレッダー＋グラフェンシート＋高熱伝導モールド樹脂の「3層ハイブリッド放熱構造」が最新トレンド。","specs":[{"label":"材質・熱伝導","value":"無酸素純銅プレート（k ≈ 398 W/m·K）"},{"label":"板厚","value":"極薄 0.15〜0.25 mm（段差レス精密成形）"},{"label":"冷却効果","value":"コントローラピーク温度 約 -12〜18 ℃ 低下"},{"label":"熱パス","value":"SoC → TIMパッド → 純銅板 → 金属殻 → カメラ放熱器"}],"diagramType":"cfe_copper_heat_spreader"},{"id":"cfe-graphene-tim-pad","order":26,"swatchColor":"#ec4899","groupKey":"隙間ゼロの熱橋渡し_C26_チップと金属殻のわずかな空気の隙間を","assembledPos":[0,0,1.38],"explodeOffset":[0,0,-42],"integratedExplodeOffset":[0,0,-42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C26. 超薄型シリコーン熱伝導パッド（TIM）＆高配向グラファイト放熱シート","subtitle":"Ultra-Thin Soft Silicone Thermal Interface Pad (TIM) & High-Orientation Graphene Heat Sheet","category":"隙間ゼロの熱橋渡し C26 — チップと金属殻のわずかな空気の隙間を「ぷにぷに熱伝導シート」で埋めて熱を逃がす","plainAnalogy":"実は「空気」は熱をほとんど通さない最強の断熱材なんです！チップと金属のフタの間に髪の毛1本でも空気の隙間があると熱が逃げられません。そこで柔らかい「熱伝導シリコーンパッド（TIM）」と、銅より3倍も横へ熱を広げる「グラファイトシート」をピッタリ挟んで、空気ゼロで一気に熱を運び出します！","summary":"コントローラ・3D NANDパッケージ表面の微細な高さバラつきを吸収して空気層を排除する極薄シリコーン系サーマルインターフェースパッド（TIM：k ≈ 6〜10 W/m·K）と、面内熱伝導率 1,200〜1,500 W/m·K の高配向グラファイト／グラフェン放熱シートの複合層です。","opticsAndPhysics":["コントローラ（厚さ約0.5 mm）と16ダイ積層NAND（厚さ約0.9 mm）ではパッケージの高さが異なるため、弾力性のある軟質TIMパッドが段差をぴったり吸収して全チップを均一に熱接触させます。","同時に柔らかいTIMパッドは、カード落下時の衝撃が金属アーマーからシリコンチップへ直接伝わるのを和らげる機械的ショックアブソーバーとしても機能します。","外装直下のグラファイトシートは「指で触ったときに1箇所だけ熱く感じない」均一放熱を実現します。"],"formula":{"expression":"空気層 (k = 0.026) → 軟質TIM (k ≈ 8 W/m·K) ＋ グラファイト面内 (k_xy ≈ 1,400 W/m·K) で熱抵抗激減！","description":"断熱材である微細な空気隙間を完全排除し、チップ段差吸収・耐衝撃・高速面内放熱の3役を同時達成"},"nextGenInnovation":"極薄ナノグラフェン複合TIMシートの進化により、0.2 mm未満の超薄ギャップでも高熱伝導と衝撃吸収を両立。","specs":[{"label":"密着緩衝層","value":"極薄軟質シリコーンTIMパッド（k ≈ 6〜10 W/m·K）"},{"label":"面内拡散層","value":"高配向グラファイト／グラフェンシート（k ≈ 1,400）"},{"label":"副次効果","value":"チップ高さ段差吸収＆落下衝撃クッション緩衝"},{"label":"配置箇所","value":"SoC・NAND上面〜銅ヒートスプレッダー／外装間"}],"diagramType":"cfe_graphene_tim_pad"},{"id":"cfe-emi-shield-frame","order":27,"swatchColor":"#cbd5e1","groupKey":"電波ノイズの遮音壁_C27_毎秒160億回の爆速通信が出す電磁ノ","assembledPos":[-6.2,-9,1],"explodeOffset":[-74,-46,14],"integratedExplodeOffset":[-74,-46,14],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C27. 超薄型パーマロイ／洋白EMI電磁シールド枠（PCIe 4.0高周波ノイズ完全遮断）","subtitle":"Ultra-Thin Nickel-Silver / Permalloy EMI Shielding Collar & Chassis Ground Clips","category":"電波ノイズの遮音壁 C27 — 毎秒160億回の爆速通信が出す電磁ノイズが、カメラのWi-Fiやマイクへ漏れるのを防ぐ金属幕","plainAnalogy":"毎秒160億回も電気のスイッチを切り替えているCFexpressカードは、対策しないと小さな「電波ノイズ発生器」になってしまい、すぐ横にあるカメラのWi-Fiやマイクの音声にジーッという雑音を入れてしまいます！そこで基板の周りを極薄の金属シールド枠で囲んでアースへ繋ぎ、ノイズを中に閉じ込めているんです！","summary":"コントローラSoCおよびPCIe Gen4高速インターフェース周辺を囲み、カード外装金属シェルおよびエッジコネクタのGNDピンへ低インピーダンス接地する超薄型洋白（ニッケルシルバー）／パーマロイEMI電磁シールド枠です。","opticsAndPhysics":["PCIe Gen4（基本周波数 8 GHz）や3D NAND高速バスの高調波は、カメラの2.4 GHz / 5 GHz / 6 GHz Wi-Fiアンテナ（B95）やGNSSアンテナ（B107）、さらには音声マイクアンプへ飛び込んで受信感度低下や録音ノイズを起こす恐れがあります。","ファラデーケージ原理により高速回路を金属シールドで取り囲み、複数のスプリング接点でGND層と外装シェルを等電位結合することで、放射ノイズを -25〜-35 dB 以上強力に減衰させます。","逆に外部からの強い無線電波やX線検査・磁界ノイズがカード内部の誤動作を引き起こすのも同時に防ぐ双方向シールドです。"],"formula":{"expression":"SE_EMI = 20 log₁₀(E_in / E_out) ≥ 30 dB  （高周波EMI漏洩を1/30以下へ閉じ込め！）","description":"超高速PCIe 4.0信号の電磁ノイズを金属ファラデーケージへ封じ込め、カメラの無線・音声品質をクリーンに保つ"},"nextGenInnovation":"パッケージ表面へ直接金属薄膜をスパッタ形成する「コンフォーマル・パッケージEMIシールド」技術により、厚み増加ほぼゼロで最高級シールドを実現。","specs":[{"label":"シールド材質","value":"極薄洋白（Cu-Ni-Zn）またはスパッタ金属EMI膜"},{"label":"ノイズ減衰量","value":"30 dB 以上（1〜10 GHz 広帯域シールド）"},{"label":"保護対象","value":"カメラ内Wi-Fi 6E・GNSS・音声マイク・センサー"},{"label":"接地構造","value":"基板GND層＆外装シェル低インピーダンス直結"}],"diagramType":"cfe_emi_shield_frame"},{"id":"cfe-bga-underfill-epoxy","order":28,"swatchColor":"#9333ea","groupKey":"極小ハンダの鉄壁補強_C28_チップの裏に並ぶ何百粒もの極小ハン","assembledPos":[0,0,0.54],"explodeOffset":[-56,36,-18],"integratedExplodeOffset":[-56,36,-18],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C28. BGAはんだボール保護アンダーフィル樹脂（7.5m落下でも極小ハンダが割れない補強材）","subtitle":"Capillary Epoxy BGA Solder-Ball Underfill Reinforcement (7.5m Drop & 150N Bend Guard)","category":"極小ハンダの鉄壁補強 C28 — チップの裏に並ぶ何百粒もの極小ハンダを特殊樹脂で固め、落下や曲げでも絶対に断線させない","plainAnalogy":"コントローラや記憶チップは、裏側にびっしり並んだ「直径0.2ミリの小さなハンダの粒（BGAボール）」で基板にくっついています。そのままカードを曲げたり落としたりすると、ハンダの粒がポキッと割れてカードが突然死！そこでチップと基板の極小の隙間に「強いエポキシ樹脂（アンダーフィル）」を毛細管現象で流し込んでガッチリ補強しているんです！","summary":"コントローラSoC（C08）および3D NANDパッケージ（C12/C13）の底面に並ぶ数百個の微細BGAはんだボールの隙間を、毛細管現象で完全充填・硬化補強する低熱膨張シリカ配合エポキシ・アンダーフィル樹脂層です。","opticsAndPhysics":["カードを落とした際の衝撃波（数千G）やポケット内での曲げ応力（最大150 N）が加わると、硬いシリコンチップと柔軟な基板の境界にある極小BGAはんだボールへせん断応力が集中し、クラック破断の原因になります。","アンダーフィル樹脂がチップ下面全体と基板を強固に面接着して応力を10分の1以下へ分散することで、7.5 m落下や150 N曲げ試験でも導通断線ゼロを達成します。","さらに-12℃〜+72℃の激しい温度変化（ヒートサイクル）によるはんだ疲労クラックも劇的に抑制し、カードの長期寿命を支えます。"],"formula":{"expression":"はんだボール応力集中 → アンダーフィル面分散（耐落下衝撃サイクル約 10×・耐ヒートサイクル約 5×向上）","description":"極小BGAはんだ接合の弱点をエポキシ充填で完全克服し、TOUGH規格の7.5m落下と150N耐曲げを内部から支える"},"nextGenInnovation":"一体成型モノリシック樹脂（C03）と低応力ナノシリカ・アンダーフィルの二重補強が、プロ現場で「絶対にデータが死なない」信頼性を築いています。","specs":[{"label":"補強箇所","value":"SoC・3D NAND・DRAM 底面 BGAはんだボール全域"},{"label":"充填工法","value":"精密キャピラリー（毛細管）アンダーフィル注入"},{"label":"材料特性","value":"低熱膨張シリカフィラー配合・高強度エポキシ"},{"label":"耐久効果","value":"7.5 m落下・150 N曲げ・温度衝撃でのハンダ割れゼロ"}],"diagramType":"cfe_bga_underfill_epoxy"},{"id":"cfe-smart-health-monitor","order":29,"swatchColor":"#22c55e","groupKey":"カードの健康診断システム_C29_そろそろ書き換え寿命が近づいて","assembledPos":[9.8,0.5,0.8],"explodeOffset":[60,14,42],"integratedExplodeOffset":[60,14,42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C29. S.M.A.R.T.寿命診断＆「Media Scan Utility」不良セクタ予防監視ロジック","subtitle":"NVMe S.M.A.R.T. Health Telemetry & Sony Media Scan Utility Predictive Wear Monitor","category":"カードの健康診断システム C29 — 「そろそろ書き換え寿命が近づいていますよ！」と壊れる前に教えてくれる予防医学機能","plainAnalogy":"メモリーカードが大事な結婚式や旅行の途中で急に壊れたら取り返しがつきませんよね。最新のCFexpressカードはNVMeの健康診断機能「S.M.A.R.T.」を内蔵！ソニーの「Media Scan Utility」やOWC Innergizeへ繋ぐと、「残り寿命92%・エラー0件・最高温度58℃」と健康診断書を出してくれて、壊れる前に安全に買い替え時を教えてくれるんです！","summary":"NVMe 2.0標準のS.M.A.R.T.（自己監視・分析・報告技術）テレメトリカウンタと、ソニー独自「Media Scan Utility」等と連携してフラッシュの書き換え上限接近や予備ブロック残量を事前警告する予防診断ロジックです。","opticsAndPhysics":["カード内部のファームウェアが、総書き込みデータ量（TBW）、平均／最大消去回数（P/Eサイクル）、予備（スペア）ブロック残量率、LDPC訂正エラー発生頻度、および最高到達温度履歴を不揮発ログへ常時記録します。","パソコンのカードリーダー（Sony MRW-G3等）へ挿すだけで自動的にフラッシュメモリの健康状態をスキャン診断し、寿命限界（残り予備ブロック低下）に近づくと買い替えアラートを通知します。","さらに消去済みブロックを綺麗に整えて新品時の爆速速度へ戻す「サニタイズ／リフレッシュ機能」もサポートします。"],"formula":{"expression":"残存寿命(%) = 100 × (1 − Avg_PE / Max_PE_spec)  ＋ スペアブロック残量＆温度履歴を常時診断","description":"突然死ゼロを目指し、フラッシュの消耗度合いとエラー予兆を数値で見える化するプロの予防メンテナンス機能"},"nextGenInnovation":"2025〜2026年はPCだけでなく、最新カメラ本体のメニュー画面上でも直接CFexpressカードの残存寿命や温度状態を確認できる次世代連携へ進化中。","specs":[{"label":"診断プロトコル","value":"NVMe 2.0 S.M.A.R.T. / Health Log ページ"},{"label":"対応ツール例","value":"Sony Media Scan Utility / OWC Innergize 等"},{"label":"監視項目","value":"残存寿命%・総書込TBW・予備ブロック・最高温度"},{"label":"現場メリット","value":"本番撮影中のカード突然死を未然に防止"}],"diagramType":"cfe_smart_health_monitor"},{"id":"cfe-grip-pull-tab-rib","order":30,"swatchColor":"#38bdf8","groupKey":"取り出しやすさ_6重保護ラベル_C30_濡れた指や寒い手でもツル","assembledPos":[0,0,0],"explodeOffset":[22,48,34],"integratedExplodeOffset":[22,48,34],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C30. 人間工学ノンスリップ引出しリブ＆耐X線・耐UV・耐静電プロテクトラベル層","subtitle":"Ergonomic Non-Slip Eject Pull-Tab Rib & Multi-Layer Anti-UV / Anti-Static Protective Label","category":"取り出しやすさ＆6重保護ラベル C30 — 濡れた指や寒い手でもツルッと落とさず引き出せる段差リブと表面保護膜","plainAnalogy":"カメラのカードスロットから切手サイズの小さなCFexpressカードを取り出すとき、指先が滑ってポロッと地面に落としそうになりますよね。カードの後ろ端には指の腹がピタッと引っかかる「小さな段差リブ（グリップ）」が彫ってあり、表面ラベルも紫外線・空港X線・静電気から中身を守る多層プロテクト仕上げになっているんです！","summary":"CFexpressカード後端の人間工学ノンスリップ引出しグリップリブと、耐紫外線（UV）・帯電防止・耐薬品オーバーコートを施した多層プロテクト識別ラベル層（容量・速度・書き込みメモ欄付き）です。","opticsAndPhysics":["スロットからバネで数ミリ飛び出したカード後端を親指と人差し指で確実につまみ出せるよう、高さ0.35 mmの精細な階段状ノンスリップリブを後端エッジへ成形しています。","表面ラベルには静電気を溜めにくい帯電防止コートと耐UVラミネートを施し、真夏の炎天下のロケや空港の手荷物X線検査（ISO 7816-1準拠耐X線）を繰り返してもデータ・外観とも劣化しません。","ラベル余白には油性ペンで「Aカメ・DAY1」などロケ管理番号を書き込めるマット仕上げエリアを備え、プロの大量カード運用を支えます。"],"formula":{"expression":"6重環境耐性：耐X線(ISO7816-1) / 耐UV / 耐静電 / 耐衝撃 / 耐曲げ150N / IP57防水防塵","description":"現場で「落としにくく扱いやすい」人間工学グリップと、世界ロケの過酷環境に耐える多層表面プロテクト仕上げ"},"nextGenInnovation":"視認性の高い高コントラスト容量表記とカラーコーディング（Sony TOUGHの黒×白×金など）により、暗い撮影バッグの中でも瞬時に大容量カードを識別可能。","specs":[{"label":"グリップ構造","value":"カード後端 ノンスリップ引出し段差リブ"},{"label":"耐X線・耐UV","value":"国際空港X線検査適合（ISO 7816-1）・耐UV加工"},{"label":"帯電対策","value":"静電気蓄積を防ぐ帯電防止トップラミネート"},{"label":"現場工夫","value":"ロケ番号メモ可能マット欄＆高視認性容量表示"}],"diagramType":"cfe_grip_pull_tab_rib"},{"id":"cfe-edge-bevel-chamfer","order":31,"swatchColor":"#ca8a04","groupKey":"先端のスロープ加工_C31_カメラの繊細な金属バネを傷めずスルッ","assembledPos":[0,-27.2,0],"explodeOffset":[-32,-64,14],"integratedExplodeOffset":[-32,-64,14],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C31. 20°〜30° エッジコネクタ先端面取り（1万回挿抜スムーズガイド）","subtitle":"CNC 20°–30° Gold-Finger Leading-Edge PCB Bevel Chamfer","category":"先端のスロープ加工 C31 — カメラの繊細な金属バネを傷めずスルッと滑り込ませる「滑り台」","plainAnalogy":"カードをカメラのスロットへ押し込むとき、カードの先端が四角く角張っていたら、カメラ側の細い金属バネにゴンッと引っかかって曲げてしまいますよね。そこで先端のフチを20〜30度のなだらかな滑り台（面取り）に削って、1万回抜き差ししてもバネが優しく乗り上がるようにしているんです！","summary":"21ピン硬質金メッキ端子（C05）の先端エッジに施された精密CNC面取り（20°〜30°ベベル加工）。カメラ側スロットのコンタクトスプリングを無理なく押し広げ、銅箔のめくれ（ピーリング）とピン折れを防止します。","opticsAndPhysics":["ガラスエポキシ基板（FR-4 / 低誘電材）の角を斜めに研磨することで、挿入力のピーク値を約40%低減し、スムーズなクリック挿入感を実現します。","面取りのすぐ後ろから金メッキ接点が始まる「セットバック距離」を精密管理し、挿入の衝撃で金箔の端がめくれ上がる事故を防ぎます。","断面には微細なバリ取り（デバリング）と防湿シーリングを施し、ガラス繊維の微粉がスロット内へ落ちるのを防いでいます。"],"formula":{"expression":"面取り角 θ = 20°〜30° ／ 挿抜耐久 > 10,000 サイクル（金箔めくれ 0）","description":"カメラ側の精密ピンを守りながら、高速連写の現場での素早いカード交換を支える微細加工"},"nextGenInnovation":"PCIe Gen4（16 GT/s）では先端の余分な銅箔スタブを極限まで削り落とすことで、コネクタ境界での高周波インピーダンス乱れも抑えています。","specs":[{"label":"面取り角度","value":"20°〜30° 精密CNCダイヤモンド研磨"},{"label":"金箔セットバック","value":"先端から 0.25〜0.35 mm（剥がれ防止）"},{"label":"挿抜寿命","value":"10,000回以上（CFA機械仕様準拠）"},{"label":"防塵加工","value":"ガラス繊維バリ除去＆エッジ平滑仕上げ"}],"diagramType":"cfe_edge_bevel_chamfer"},{"id":"cfe-staggered-hotplug-pins","order":32,"swatchColor":"#eab308","groupKey":"時間差タッチの工夫_C32_アース_電源_信号_装着完了の順につ","assembledPos":[0,-24.8,0.56],"explodeOffset":[34,-64,20],"integratedExplodeOffset":[34,-64,20],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C32. 先行接触GND・電源＆遅延接触INS#カード検知スタガーピン構造","subtitle":"CFA Staggered Hot-Plug Finger Geometry (First-Make GND/+3V3 & Last-Make INS#)","category":"時間差タッチの工夫 C32 — アース→電源→信号→装着完了の順につなぐ「安全な握手の順番」","plainAnalogy":"21本の金色の指をよく見ると、じつは長さがわずかに段違い（スタガー）になっています！カードを挿した瞬間、まず長いアースと電源の指が先に触れて電気を落ち着かせ、奥まで完全に入った最後に一番短い「入ったよ！ピン（INS#）」が触れてから高速データ通信を始める安全な仕組みなんです。","summary":"CompactFlash Association（CFA）規格で定められた段差長（スタガー）エッジ端子構造。GND（Pin 1/15/18/21）と+3.3 V（Pin 10）が先行接触（First-Make / Last-Break）し、カード検知ピン`INS#`（Pin 12）が最後に導通します。","opticsAndPhysics":["最初にGNDピンが接触してカメラとカードの電位差（静電気）を瞬時にゼロへ揃え、続いて+3.3 V電源、次にPCIe高速差動信号線（PET/PER/REFCLK）がつながります。","一番短い`INS#`ピン（カード内部でGND直結、ホスト側で100〜200 kΩプルアップ）がローになった瞬間に初めてカメラが「装着完了」と認識し、PCIeリセット（PERST#）を解除します。","逆にカードを抜きかけた瞬間は`INS#`が真っ先に切れるため、電源や信号が物理的に離れる前にカメラへ緊急停止を知らせることができます。"],"formula":{"expression":"接触順序：GND → +3.3 V → PCIe信号 → INS#（遅延検知・引き抜き時は逆順）","description":"活線挿抜（ホットプラグ）時の電気火花・ラッチアップ・データ破損を防ぐ物理シーケンス"},"nextGenInnovation":"CFexpress 4.0（PCIe Gen4）でもCFexpress 2.0と完全なピン長・ピン配列互換を維持し、旧カメラでも安全に動作する後方互換性を実現。","specs":[{"label":"先行ピン","value":"GND（Pin 1,15,18,21）＆ +3V3（Pin 10）"},{"label":"遅延検知ピン","value":"INS#（Pin 12・Active Low・カード内GND接続）"},{"label":"安全効果","value":"静電気先逃がし＋活線抜去の先行検知"},{"label":"準拠規格","value":"CFA CFexpress Type A 2.0 / 4.0 共通配列"}],"diagramType":"cfe_staggered_hotplug_pins"},{"id":"cfe-side-guide-rails-notch","order":33,"swatchColor":"#ea580c","groupKey":"カチッと固定の溝_C33_裏表を絶対間違えず_押すと_カチッ_と","assembledPos":[0,0,0],"explodeOffset":[-92,0,26],"integratedExplodeOffset":[-92,0,26],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C33. 非対称サイドガイドレール＆プッシュロック固定ノッチ溝","subtitle":"Asymmetric Side Alignment Rails & Push-Push Camera Slot Retention Detent Notch","category":"カチッと固定の溝 C33 — 裏表を絶対間違えず、押すと「カチッ」と止まる側面のくぼみ","plainAnalogy":"CFexpress Type Aカードをカメラに入れるとき、指でグッと押すと「カチッ」と止まり、もう一度押すと「ポンッ」と出てきますよね。その秘密がカード側面の細いレールと小さな「くぼみ（ノッチ）」！裏返しに挿そうとするとレールが止めてくれて、正しい向きならくぼみにバネ爪がピタッと掛かるんです。","summary":"CFexpress Type A規格（20.0 × 28.0 × 2.8 mm）の両側面に精密成形された左右非対称のガイドレールと、カメラ側プッシュ・プッシュ機構のロック爪が係合するサイドリテンションノッチ溝です。","opticsAndPhysics":["片側サイドに段差レールを設けることで、暗い現場で裏表を逆にして押し込んでもコネクタ端子へ届く前に物理的にブロックします。","ソニーαシリーズのデュアルスロット（SDカード／CFexpress Type A両用スロット）内で、わずかにサイズの異なる両カードを正確に中心位置決めする基準面にもなります。","振動や落下衝撃を受けてもカードがスロットから浮き上がらないよう、サイドノッチにカメラ側ロックピンが一定の保持力で係合します。"],"formula":{"expression":"Type A 外形 20.0 × 28.0 × 2.8 mm（公差 ±0.10 mm）＋ サイドノッチ保持 > 10 N","description":"SD/CFexpress Type A 兼用ハイブリッドスロットでも確実に位置決め・固定する精密側壁"},"nextGenInnovation":"ソニーTOUGHなどの一体成形カードでは、割れやすい別パーツのレールを廃止し高強度樹脂モノコックと一体化することで折損事故を激減。","specs":[{"label":"ガイド構造","value":"左右非対称ポカヨケ・サイドガイドレール"},{"label":"固定ノッチ","value":"プッシュ・プッシュ式イジェクト爪用凹部"},{"label":"対応スロット","value":"CFexpress Type A 専用 / SD兼用デュアルスロット"},{"label":"寸法公差","value":"幅 20.0 ± 0.1 mm ／ 厚さ 2.8 ± 0.1 mm"}],"diagramType":"cfe_side_guide_rails_notch"},{"id":"cfe-armor-laser-welds","order":34,"swatchColor":"#94a3b8","groupKey":"鉄壁の縫い目_C34_上下の金属板を点レーザーでガッチリ縫い合わ","assembledPos":[0,1.4,0],"explodeOffset":[92,0,-24],"integratedExplodeOffset":[92,0,-24],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C34. 上下メタルアーマー微細レーザー溶接＆剛性クリンプシーム","subtitle":"Perimeter Micro-Laser Spot Welds & Mechanical Interlock Crimp Tabs","category":"鉄壁の縫い目 C34 — 上下の金属板を点レーザーでガッチリ縫い合わせ、曲げや落下に負けない箱に","plainAnalogy":"2枚の薄い金属板も、フチ同士がバラバラだとペラペラ曲がってしまいます。上下の金属アーマーの周りを精密なレーザー光線で何十か所も「ジジッ」と溶接し爪で噛み合わせることで、15キロの力で曲げても7.5メートルから落としても壊れない、頑丈なミニ金庫の箱に生まれ変わるんです！","summary":"上面メタルアーマー（C01）と下面ベースシェル（C02）の接合縁に施されたパルスファイバーレーザー微細スポット溶接と、折り返しインターロック爪（クリンプシーム）構造です。","opticsAndPhysics":["上下の金属シェルを箱型閉断面（ボックスビーム構造）として剛結することで、単純な2枚重ねに比べて曲げ剛性とねじり剛性が飛躍的に向上します。","ソニーCEA-G TOUGH規格では曲げ強度150 N（約15 kgf、規格比10倍）、落下耐性7.5 m（規格比5倍）という圧倒的な機械強度をこの接合構造と一体樹脂が支えます。","溶接熱が内部の3D NANDや防水シール（C04）へ伝わらないよう、ミリ秒単位の極短パルスレーザーで接合点のみを局所溶融させます。"],"formula":{"expression":"曲げ耐力 150 N（規格比 10×） ／ 落下耐性 7.5 m（閉断面ボックス剛性）","description":"薄さわずか2.8 mmの極薄カードに、踏まれても折れにくい圧倒的な構造強度を付与"},"nextGenInnovation":"2025〜2026年のプロ用カード（Angelbird / Sony TOUGH / ProGrade Iridium）では、金属シェル全面をヒートシンク兼用にする連続レーザー接合が拡大。","specs":[{"label":"接合工法","value":"パルスファイバーレーザー微細スポット溶接＋爪カシメ"},{"label":"曲げ強度","value":"最大 150 N（CFexpress標準規格の約10倍）"},{"label":"耐落下衝撃","value":"最大 7.5 m（コンクリート面落下試験）"},{"label":"構造効果","value":"基板の反り防止によるBGAハンダクラック抑止"}],"diagramType":"cfe_armor_laser_welds"},{"id":"cfe-emi-ground-spring-clips","order":35,"swatchColor":"#d97706","groupKey":"電波を逃がすアース橋_C35_金属の殻と基板のアースをつなぎ_超","assembledPos":[0,1,0.9],"explodeOffset":[-86,-18,-32],"integratedExplodeOffset":[-86,-18,-32],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C35. シェル導通EMIグラウンドスプリングクリップ＆導電ガスケット","subtitle":"Beryllium-Copper PCB-to-Shell EMI Grounding Clips & Conductive Gasket","category":"電波を逃がすアース橋 C35 — 金属の殻と基板のアースをつなぎ、超高速ノイズを閉じ込める","plainAnalogy":"CFexpress 4.0の中では1秒間に160億回もの超高速な電気信号が飛び交っているので、放っておくとカメラのWi-Fiやマイクに「ジーッ」とノイズが漏れてしまいます。基板のアースと外側の金属カバーをこの小さなバネクリップで直接つなぐことで、金属ケース全体が完璧な電波バリアになるんです！","summary":"8層HDI基板（C07）外周のグラウンドパッドと上下メタルアーマー（C01/C02）を低インピーダンスで直結するベリリウム銅製ミニスプリングクリップと導電性Ni-Cuファブリックガスケットです。","opticsAndPhysics":["金属外装が電気的に宙に浮いている（フローティング状態）と逆にアンテナ化してノイズを放射してしまいます。複数点のアースクリップでGNDへ落とすことで真のファラデーケージが完成します。","PCIe Gen4（基本波8 GHz・高調波16〜24 GHz）の放射EMIを20 dB以上減衰させ、カメラ内蔵のWi-Fi 6E／Bluetooth／GNSSアンテナ感度低下を防ぎます。","外部からカード表面へ静電気が飛んだ際も、内部チップを通さず金属シェル→アースクリップ→GNDピンへと安全に逃がすESDバイパス経路になります。"],"formula":{"expression":"シェル接地インピーダンス Z_gnd < 50 mΩ ／ 放射EMI低減 > 20 dB（〜16 GHz）","description":"金属外装を完全なシールド筐体として機能させ、カメラ無線・音声へのノイズ干渉を遮断"},"nextGenInnovation":"CFexpress 4.0世代では8 GHz帯の波長（約37 mm）がカード長（28 mm）に近づくため、外周4〜6点の多点グラウンド接続による共振防止が不可欠。","specs":[{"label":"クリップ材質","value":"金メッキ・ベリリウム銅マイクロ板バネ"},{"label":"補助シール","value":"Ni-Cuメッキ導電ファブリックガスケット"},{"label":"接地点数","value":"基板外周 4〜6点 低インピーダンス多点接地"},{"label":"シールド帯域","value":"100 MHz 〜 16 GHz（PCIe Gen4高調波対応）"}],"diagramType":"cfe_emi_ground_spring_clips"},{"id":"cfe-micro-vapor-fin-plate","order":36,"swatchColor":"#ea580c","groupKey":"熱の高速道路_C36_8K_RAW録画で燃えるように熱いチップの","assembledPos":[0,2.2,2.02],"explodeOffset":[46,20,26],"integratedExplodeOffset":[46,20,26],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C36. 次世代超薄型マイクロ放熱フィン＆ヒートスプレッダ熱拡散層","subtitle":"CFexpress 4.0 Sustained-Write Micro-Grooved Thermal Fin / Vapor-Spreader Layer","category":"熱の高速道路 C36 — 8K RAW録画で燃えるように熱いチップの熱をカード全面へ一気に逃がす","plainAnalogy":"CFexpress 4.0は1秒間に約2GBもの動画データを休みなく書き込むので、小さなコントローラチップが小さなカイロみたいにアツアツになります。放っておくと熱暴走を避けるため速度が落ちてしまいますが、この微細な溝（フィン）付きの金属熱拡散板が熱をカード全体へサッと散らして冷やし続けるんです！","summary":"CFexpress 4.0（VPG800・連続書込1,600〜1,900 MB/s）の3〜5 Wピーク発熱を処理するため、上面アーマー内面に統合された極薄マイクログルーブ熱拡散／次世代超薄型ベイパーヒートプレート層です。","opticsAndPhysics":["コントローラSoC（C08）のわずか数mm四方に集中する高密度な熱流束（ヒートフラックス）を、面内熱伝導率の高い構造で20×28 mmの全面へ瞬時に拡散します。","熱をカード全体へ均等に広げることで、カメラ側スロットの金属ガイドレールやサーマルシートへの放熱面積を最大化し、サーマルスロットリング（速度低下）発動を大幅に遅らせます。","2025〜2026年のフラッグシップカード（Sony CEA-G 4.0 / Nextorage NX-A2PRO / ProGrade Iridium等）では、7 nm低電力コントローラとこの熱拡散構造の併用で8K X-OCNやRAWの長時間連続収録を実現しています。"],"formula":{"expression":"連続放熱許容 P_th ≈ 3.5〜4.8 W ／ チップ〜外装温度差 ΔT 約 35% 低減","description":"小さなType AカードでVPG800（最低800 MB/s保証）の長時間連続録画を支える熱設計"},"nextGenInnovation":"2026年以降の次世代Type A/Bカードでは厚さ0.25 mm級の極薄銅メッシュ・マイクロベイパーチャンバー（二相冷却板）の内蔵研究が進展。","specs":[{"label":"構造仕様","value":"極薄 0.25〜0.30 mm マイクロ溝熱拡散プレート"},{"label":"対応発熱量","value":"3.5 〜 5.0 W（PCIe Gen4連続8K録画負荷）"},{"label":"熱結合経路","value":"SoC → グラフェンTIM → 熱拡散層 → メタル外装"},{"label":"持続性能","value":"VPG400 / VPG800 サーマルスロットリング抑制"}],"diagramType":"cfe_micro_vapor_fin_plate"},{"id":"cfe-vpg800-laser-serial","order":37,"swatchColor":"#facc15","groupKey":"赤外線放熱_プロ保証刻印_C37_実は_黒いツヤ消し_は熱を外へ","assembledPos":[0,0,-2.68],"explodeOffset":[28,-26,-74],"integratedExplodeOffset":[28,-26,-74],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C37. 高放射率マット黒放熱塗装＆レーザー刻印VPG800／シリアル銘板","subtitle":"High-Emissivity Thermal Radiation Back Coating & Permanent Laser VPG800 / Serial Mark","category":"赤外線放熱＆プロ保証刻印 C37 — 実は「黒いツヤ消し」は熱を外へ逃がしやすくする科学のワザ！","plainAnalogy":"カードの裏面がツヤ消しの黒っぽい塗装になっているのには、見た目のカッコよさ以上の秘密があります！ツヤ消しの黒い金属はピカピカの銀色より「赤外線」として熱を何倍も遠くへ逃がせる（熱放射率が高い）んです。さらに絶対に消えないレーザーでVPG800の保証マークと番号も刻まれています。","summary":"カード裏面メタルシェルに施された高赤外線放射率（ε ≈ 0.85〜0.92）のセラミック系マットブラック放熱コーティングと、永久レーザー刻印されたVPG400/VPG800動画性能保証ロゴ・個別シリアル番号です。","opticsAndPhysics":["ステファン・ボルツマンの法則（Q = εσAT⁴）により、裸のステンレス（放射率ε≈0.15）に比べ、マット黒放射コート（ε≈0.90）は狭いカードスロット内での赤外線放射放熱を約5〜6倍に高めます。","VPG800（Video Performance Guarantee 800）ロゴは、カード全域で最低800 MB/sの連続書き込みを1フレームも落とさず維持できる厳格なCFA公式認証を取得した証です。","裏面の個別シリアルコードと製造バッチ番号はレーザー刻印されており、データ復旧サービスや保証交換時の個体識別に使われます。"],"formula":{"expression":"赤外線熱放射 P_rad = ε · σ · A · (T⁴ − T₀⁴) ／ 放射率 ε ≈ 0.15 → 0.90（約6倍）","description":"ファンレス密閉スロット内でも赤外線放射でカード温度を下げる表面熱工学＋VPG800認証刻印"},"nextGenInnovation":"2025〜2026年のCFexpress 4.0 Type A（Nextorage NX-A2PRO / ProGrade Iridium / Angelbird AV PRO v4等）でVPG800認証取得カードが一気に普及。","specs":[{"label":"表面処理","value":"高熱放射セラミック系マットブラック塗装（ε≈0.90）"},{"label":"認証マーク","value":"CFA VPG400 / VPG800（最低保証 400〜800 MB/s）"},{"label":"刻印方式","value":"耐摩耗レーザーマーキング（シリアル＆QR追跡）"},{"label":"副次効果","value":"指紋汚れ防止＋耐擦傷＋赤外線放熱促進"}],"diagramType":"cfe_vpg800_laser_serial"},{"id":"cfe-diff-85ohm-serpentine","order":38,"swatchColor":"#f59e0b","groupKey":"電気のゴール同時到着レース_C38_クネクネ道を作って2本の信号","assembledPos":[-4,-16.8,0.52],"explodeOffset":[-56,-68,36],"integratedExplodeOffset":[-56,-68,36],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C38. PCIe Gen4 85Ω整合差動ペア＆蛇行等長配線（サーペンタイン）","subtitle":"PCIe Gen4 16 GT/s 85-Ohm Controlled-Impedance Differential Pairs & Length-Matched Serpentines","category":"電気のゴール同時到着レース C38 — クネクネ道を作って2本の信号が1兆分の1秒もズレずにゴール！","plainAnalogy":"基板をよく見ると、2本組の銅の線がわざとクネクネ蛇行（サーペンタイン）している場所があります。カーブでは内側のレーンのほうが距離が短くて早く着いてしまうので、内側の線に小さなクネクネ遠回りを作って、1秒間に160億回走るプラスとマイナスの信号がピッタリ同時にゴールできるように揃えているんです！","summary":"21ピン端子からコントローラSoC（C08）までを接続する、特性インピーダンス85 Ω±5%厳密管理のPCIe Gen4差動伝送ペア（PETp0/n0・PERp0/n0・REFCLK±）とピコ秒精度の蛇行等長配線です。","opticsAndPhysics":["PCIe Gen4（16 GT/s）では1ビットの幅がわずか62.5ピコ秒（光がたった1.8 cmしか進まない時間！）しかないため、ペア間の配線長差を0.125 mm（5 mil）以内に抑える必要があります。","プラス線とマイナス線を逆位相で並走させる差動伝送により、外部ノイズを互いに打ち消し合い、85 Ω整合で信号の跳ね返り（反射）を防止します。","ガラス繊維の織り目のスキマで伝搬速度が変わる「ファイバーウィーブ効果」を避けるため、配線をわずかに斜め（ジグザグ約10°）に走らせる最新基板設計も使われます。"],"formula":{"expression":"Z_diff = 85 Ω ± 5% ／ ペア内配線長誤差 ΔL < 0.125 mm（Δt < 0.8 ps）","description":"16 GT/s超高速PCIe Gen4のアイパターンをくっきり開かせるミクロン精度の高周波銅配線"},"nextGenInnovation":"CFexpress 4.0（16 GT/s）から将来のPCIe Gen5（32 GT/s）世代では、低粗度HVLP銅箔とスプレッドガラス基板による表皮効果損失低減が鍵。","specs":[{"label":"特性インピーダンス","value":"差動 85 Ω ± 5%（PCIe Gen3/4標準）"},{"label":"等長マッチング","value":"ペア内スキュー < 0.125 mm（サーペンタイン補正）"},{"label":"信号速度","value":"16 GT/s（Type A x1 ＝ 理論約 2 GB/s）"},{"label":"銅箔仕様","value":"超平滑 HVLP 銅箔（高周波表皮損失を抑制）"}],"diagramType":"cfe_diff_85ohm_serpentine"},{"id":"cfe-backdrilled-microvias","order":39,"swatchColor":"#d97706","groupKey":"基板の垂直エレベーター_C39_8階建て基板のフロア間を最短で結","assembledPos":[-2,-4.5,0],"explodeOffset":[-30,-20,-56],"integratedExplodeOffset":[-30,-20,-56],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C39. レーザー極細マイクロビア＆バックドリル高速貫通ビア","subtitle":"Stacked Laser Blind Micro-Vias (<75 μm) & Stub-Free Back-Drilled PCIe Vias","category":"基板の垂直エレベーター C39 — 8階建て基板のフロア間を最短で結び、信号の「行き止まり」を削り取る","plainAnalogy":"8層基板（C07）は8階建てのビルのようなもので、電気信号が上の階と下の階を行き来するには「ビア」という銅の縦穴エレベーターを使います。超高速なPCIe 4.0では、使わない階まで穴が突き抜けていると「行き止まりの袋小路」で電波が反響してしまうので、レーザーで必要な階だけ掘ったり余分な先を削り取るんです！","summary":"8層0.5 mm極薄HDI基板の内部で層間接続を担う直径50〜75 μmのレーザーブラインドマイクロビアと、高周波信号反射の原因となる余剰ビアスタブを除去するバックドリル／任意層（Any-Layer）ビア構造です。","opticsAndPhysics":["BGAパッケージ（0.35〜0.4 mmボールピッチ）の真下に直接銅充填ビアを配置する「Via-in-Pad（VIPPO）」構造により、極小Type A基板上にコントローラ・DRAM・NANDを高密度実装できます。","貫通ビアに余分な銅筒（スタブ）が残ると特定周波数で共振ノッチが生じ、16 GT/s信号の波形が潰れてしまいます。必要な層間のみをつなぐマイクロビア／バックドリルでスタブ長をほぼゼロにします。","コントローラやPMIC直下には数十本のサーマルビア（熱エレベーター）を密に並べて、チップの熱を基板裏面の銅プレーンへ素早く逃がしています。"],"formula":{"expression":"ビア径 φ50〜75 μm（UVレーザー穿孔） ／ 残存スタブ長 < 0.10 mm（反射抑止）","description":"極薄0.5 mm基板の8層立体配線と、16 GT/s超高速信号の無反射伝送を両立する微細縦穴"},"nextGenInnovation":"2025〜2026年の2 TB〜4 TB級超大容量Type Aカードでは全層レーザー接続のAny-Layer HDI基板と銅めっき充填ビアが標準化。","specs":[{"label":"ビア加工法","value":"UVレーザーブラインドマイクロビア＋銅フィルVIPPO"},{"label":"最小穴径","value":"50 〜 75 μm（髪の毛と同等の極細縦配線）"},{"label":"高周波対策","value":"スタブレス構造＋周囲GNDステッチビア囲い"},{"label":"放熱機能","value":"コントローラ直下サーマルビアアレイで裏面排熱"}],"diagramType":"cfe_backdrilled_microvias"},{"id":"cfe-efuse-hotplug-switch","order":40,"swatchColor":"#0284c7","groupKey":"電気のソフトドアマン_C40_カードを挿した瞬間の_電気のドッと","assembledPos":[4.5,-19.8,0.72],"explodeOffset":[54,-68,18],"integratedExplodeOffset":[54,-68,18],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C40. eFuse電子ヒューズ＆突入電流ソフトスタート・ロードスイッチIC","subtitle":"Integrated 3.3 V eFuse Electronic Protection & Slew-Rate Soft-Start Load Switch","category":"電気のソフトドアマン C40 — カードを挿した瞬間の「電気のドッと流れ込み」を優しく抑えて守る","plainAnalogy":"カードをカメラに挿した瞬間、カード内部の空っぽなコンデンサへ一気に大電流が「ドバッ！」と流れ込むと、カメラ本体の電源が一瞬ガクッと落ちてフリーズすることがあります。この電子ヒューズ（eFuse）は水道蛇口をゆっくり開けるように電気を流し、異常な高電圧やショートが起きたら100万分の1秒で止めるんです！","summary":"Pin 10（+3.3 V）入力のすぐ後ろに配置されたスマート電子ヒューズ（eFuse）＆突入電流制御ロードスイッチIC。ソフトスタート、過電圧クランプ（OVP）、過電流遮断（OCP）、逆流防止を1チップで担います。","opticsAndPhysics":["カード挿入直後に電源立ち上がりスルーレートを約0.5〜2 msかけて滑らかに上昇させ、PLPコンデンサ（C19）等への突入電流（インラッシュ）を抑えてカメラ本体の電圧ドロップを防ぎます。","粗悪なカードリーダーから誤って5 V過電圧が印加された場合でも、約3.8 Vで即座に入力を遮断（OVP）して貴重な撮影データが入ったNANDとSoCを焼損から守ります。","物理ヒューズと違って一度切れても壊れず、異常が取り除かれれば自動復帰するスマート保護機能を備えます。"],"formula":{"expression":"突入電流制限 I_inrush < 1.5 A ／ OVP高速遮断 t_off < 2 μs（V_ov ≈ 3.8 V）","description":"カメラ電源の瞬断トラブルと、故障リーダーによるカード焼損を未然に防ぐ入力守護神"},"nextGenInnovation":"2025〜2026年世代ではPLP停電保護時にカード側コンデンサの電荷がカメラ側へ逆流するのを瞬時に防ぐ「真逆流遮断（True Reverse Current Blocking）」機能が必須。","specs":[{"label":"定格入力","value":"+3.3 V ± 5%（オン抵抗 R_on ≈ 25 mΩ）"},{"label":"ソフトスタート","value":"出力立ち上がり制御による突入電流抑制"},{"label":"保護機能","value":"OVP過電圧・OCP過電流・サーマル・逆流遮断"},{"label":"パッケージ","value":"極小 WLCSP / DFN-6（1.5 × 1.5 mm）"}],"diagramType":"cfe_efuse_hotplug_switch"},{"id":"cfe-ferrite-cm-choke","order":41,"swatchColor":"#475569","groupKey":"電源の防音カーテン_C41_デジタル回路の激しい雑音が繊細な高速","assembledPos":[6.5,-13.8,-0.78],"explodeOffset":[80,-42,-26],"integratedExplodeOffset":[80,-42,-26],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C41. 電源系統別フェライトビーズ＆高周波ノイズ遮断フィルタ群","subtitle":"Power-Domain Isolating Ferrite Beads & High-Frequency Analog PHY Noise Filters","category":"電源の防音カーテン C41 — デジタル回路の激しい雑音が繊細な高速通信へ漏れないよう仕切る","plainAnalogy":"カードの中では「NANDに書き込む力仕事（1.8V/3.3V）」「頭脳チップの計算（0.8V）」「カメラと超高速通信する繊細な耳（1.2V）」が同じ電気を分け合っています。力仕事の振動が繊細な耳に響かないよう、電気の通りの途中に「フェライト」という特殊な磁性体の防音カーテンを挟んで静かにしているんです。","summary":"PMIC（C17）から各ブロックへ分岐する電源レール間に挿入された0402/0201多層チップフェライトビーズ群。デジタル負荷のスイッチングリップルを遮断し、PCIe Gen4アナログPHYとPLLクロック（C22）へ超クリーンな電源を供給します。","opticsAndPhysics":["フェライトビーズは直流（DC）に対しては数十mΩの低い抵抗で電気をロスなく通す一方、100 MHz〜数GHzの高周波ノイズに対しては数百Ωの高い抵抗成分に変わり、雑音を熱へ変えて消し去ります。","PCIe Gen4の16 GT/s送受信回路（SerDes PHY）や100 MHz PLLの電源にノイズが乗るとジッター（時間ブレ）が増えて通信エラーになるため、専用のフェライト＋コンデンサπ型フィルタで徹底的に浄化します。","NANDの瞬間的な同時書き込み（ページプログラム）時の電源揺れがコントローラ側へ逆流するのを防ぐアイソレーションの役割も果たします。"],"formula":{"expression":"DC抵抗 R_DC < 0.05 Ω ／ 高周波インピーダンス Z ≈ 220–600 Ω @ 100 MHz〜1 GHz","description":"直流パワーはロスなく通し、GHz帯のデジタル電源ノイズだけを吸収する電源分離フィルタ"},"nextGenInnovation":"CFexpress 4.0世代ではPCIe 4.0の8 GHz帯までインピーダンスが落ちにくいGHz特化型ニッケル亜鉛フェライトビーズが採用されています。","specs":[{"label":"素子種別","value":"多層チップフェライトビーズ（0402 / 0201サイズ）"},{"label":"分離電源域","value":"PCIe PHY 1.2 V・PLL 1.8 V・NAND VCCQ 1.2/1.8 V"},{"label":"フィルタ構成","value":"フェライト＋極小MLCCによるπ型ローパスフィルタ"},{"label":"効果指標","value":"ジッター低減＆電源クロストーク > 30 dB 抑制"}],"diagramType":"cfe_ferrite_cm_choke"},{"id":"cfe-pcie-sideband-logic","order":42,"swatchColor":"#16a34a","groupKey":"省エネお昼寝スイッチ_C42_撮影していないスキマ時間に0_00","assembledPos":[-10.8,-19.6,0.72],"explodeOffset":[-78,-62,16],"integratedExplodeOffset":[-78,-62,16],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C42. PERST#リセット／CLKREQ#省電力（L1.2）サイドバンド制御回路","subtitle":"PCIe Sideband Signal Conditioning (PERST# Reset, CLKREQ# L1.2 Substate & Pull-Ups)","category":"省エネお昼寝スイッチ C42 — 撮影していないスキマ時間に0.005Wへ眠らせカメラの電池を長持ち！","plainAnalogy":"CFexpressカードはパソコンの超高速SSDと同じ中身なので、ずっと全力運転しているとカメラのバッテリーをあっという間に食べてしまいます。そこでカメラと合図し合う専用ピン（CLKREQ#）を使い、シャッターを押していない一瞬の合間にカードを「深いお昼寝（L1.2省電力）」へ切り替えて電池を守っているんです！","summary":"CFA 21ピン端子の制御信号ピン`PERST#`（Pin 9：リセット）および`CLKREQ#`（Pin 11：クロック要求／L1.2省電力制御）のプルアップ／プルダウン抵抗・レベルシフト・ノイズフィルタ回路群です。","opticsAndPhysics":["撮影待機中、コントローラが`CLKREQ#`を解放すると、カメラは100 MHz基準クロック（REFCLK）まで完全に停止する「PCIe L1.2サブステート」へ移行し、カード消費電力を数Wからわずか約5 mW以下（約1/500！）へ削減します。","シャッター半押しや録画ボタンを押した瞬間、わずか数十マイクロ秒で`CLKREQ#`を再アサートして16 GT/sフルスピードへ瞬時復帰します。","`PERST#`信号は電源安定後にコントローラとNANDをクリーンに起動・再初期化するハードウエアリセット線で、誤動作防止のシュミットトリガ／RCフィルタを通ります。"],"formula":{"expression":"アクティブ約 2.5–4.0 W ↔ L1.2スリープ約 5 mW（待機電力 99.8% 削減！）","description":"カメラのバッテリー撮影枚数を犠牲にせず、PCIe Gen4の爆速転送を両立する省電力通信制御"},"nextGenInnovation":"CFexpress 4.0コントローラ（7 nm / 6 nm級）はNVMe APST（自律電源状態遷移）とL1.2サブステートを細かく連携させ、発熱も劇的に低減。","specs":[{"label":"制御ピン","value":"PERST#（Pin 9）・CLKREQ#（Pin 11）・REFCLK±（Pin 13/14）"},{"label":"省電力規格","value":"PCIe ASPM L1.1 / L1.2 サブステート＋NVMe APST"},{"label":"復帰時間","value":"数十 μs（シャッタータイムラグへの影響ゼロ）"},{"label":"待機電力","value":"約 3〜10 mW（撮影待機時の発熱と電池消費を抑制）"}],"diagramType":"cfe_pcie_sideband_logic"},{"id":"cfe-plp-cap-health-mcu","order":43,"swatchColor":"#eab308","groupKey":"非常用バッテリーの点検係_C43_いざという時本当にデータが救え","assembledPos":[-10.2,-5.2,-0.82],"explodeOffset":[-82,-2,-42],"integratedExplodeOffset":[-82,-2,-42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C43. PLP停電保護コンデンサ健全性監視回路＆放電自己診断部","subtitle":"Power-Loss-Protection (PLP) Tantalum Capacitor Capacitance Self-Test & Monitor","category":"非常用バッテリーの点検係 C43 — いざという時本当にデータが救えるか、毎回電源ONでテスト！","plainAnalogy":"撮影中にうっかり電池が切れても動画を壊さず保存してくれる非常用コンデンサ（C19）ですが、何年も使うと少しずつ体力が弱ることがあります。そこで2025〜2026年のプロ用カードは、カメラの電源を入れるたびにこの点検係が非常用コンデンサの元気さを自動テストして、弱っていたら早めに教えてくれるんです！","summary":"停電保護用タンタルコンデンサバンク（C19）の静電容量とESR（内部抵抗）を起動時および運用中に定期テストするPLPキャパシタ健全性監視回路（放電チェック抵抗＋電圧傾き測定ADC）です。","opticsAndPhysics":["起動時に一瞬だけコンデンサへの充電を止め、既知の微弱テスト負荷抵抗へ放電させた際の電圧降下速度（dV/dt = I/C）から残存静電容量を正確に算出します。","もし経年劣化や高温で静電容量が規定値を下回り、DRAMキャッシュ（C16）のフラッシュに必要なエネルギー（E = ½CV²）を満たせなくなると、S.M.A.R.T.警告を発行します。","同時にコントローラはライトキャッシュポリシーを安全な直書きモードへ自動切替し、データ破損リスクを未然に回避します。"],"formula":{"expression":"蓄積エネルギー E = ½ · C · (V_charge² − V_min²) ／ 実測容量 C = I_test / (dV/dt)","description":"非常用PLPコンデンサの寿命を毎回自動検査し、プロ現場の「いざという時のデータ消失」を防止"},"nextGenInnovation":"2026年の産業用・シネマ用NVMe / CFexpress（ATP / Exascend等）で採用が広がるPLPキャパシタヘルスモニタリング機能。","specs":[{"label":"診断方式","value":"起動時＆定期放電スロープ測定（C / ESR同時判定）"},{"label":"対象部品","value":"PLP停電保護タンタルコンデンサバンク（C19）"},{"label":"安全動作","value":"劣化検知時にS.M.A.R.T.通知＆安全書込モード移行"},{"label":"信頼性効果","value":"突然の電池切れ・カード誤抜去時のファイル破損防止"}],"diagramType":"cfe_plp_cap_health_mcu"},{"id":"cfe-jtag-uart-test-pads","order":44,"swatchColor":"#f59e0b","groupKey":"工場専用の秘密の診察口_C44_出荷前の厳しい検査や緊急データ復","assembledPos":[15.2,2.5,-0.56],"explodeOffset":[86,22,-36],"integratedExplodeOffset":[86,22,-36],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C44. 工場診断・ファーム書込用JTAG / UART / ROMリカバリテストパッド","subtitle":"Factory Debug JTAG / UART Serial Telemetry & Emergency ROM-Mode Test Pads","category":"工場専用の秘密の診察口 C44 — 出荷前の厳しい検査や緊急データ復旧のときだけ使う隠し端子","plainAnalogy":"外装の金属ケースを開けると、基板の隅っこに小さな金色の丸い点（テストパッド）が並んでいます。これは病院の聴診器を当てる場所のような「工場とデータ復旧の専門家専用の秘密の診察口」！ここで初期プログラムを書き込んだり、NANDの全ブロックに不良がないか検査してから出荷しているんです。","summary":"基板端に配置されたENIG金メッキのマイクロテストパッド群（UARTシリアルログ、JTAGデバッグ、ROMモード強制ショート用ジャンパパッド）。工場のNAND全数スクリーニングとファームウエア書き込みに使用されます。","opticsAndPhysics":["工場のRDT（Reliability Demonstration Test）工程で、カード全領域へ高温下でテストパターンを繰り返し書き込み、不良ブロック（バッドブロック）を自動登録して出荷します。","ファームウエア破損などでPCIe認識不能になった際、ROMモードパッドを短絡して起動することでコントローラを直接診断・修復できるエンジニアリング導線になっています。","量産出荷時はセキュアブート（C11）と連動してJTAG外部読み出しを無効化（ヒューズロック）し、ユーザーのデータが不正ダンプされないよう保護します。"],"formula":{"expression":"工場全数 RDT 検査（NAND全ブロック品質選別）＋ 出荷後 JTAG ロック保護","description":"1ビットの初期不良も逃さない工場検査と、出荷後の強固なセキュリティを両立する診断接点"},"nextGenInnovation":"データ復旧ラボ（Sony File Rescue / プロ向け物理復旧）でも、障害発生時のコントローラ状態解析にこの内部診断アーキテクチャが重要な役割を果たします。","specs":[{"label":"テスト系統","value":"UARTログ・JTAG/SWD・ROMブートピン・電源測定"},{"label":"パッド寸法","value":"φ0.5 〜 0.8 mm 金メッキマイクロパッド"},{"label":"工場用途","value":"初期FW書込・全ブロックRDT選別・LDPC最適値学習"},{"label":"セキュリティ","value":"製品出荷時にデバッグアクセスを暗号ロック"}],"diagramType":"cfe_jtag_uart_test_pads"},{"id":"cfe-optical-fiducials","order":45,"swatchColor":"#fbbf24","groupKey":"ロボットの的あて目印_C45_砂粒サイズの部品を100分の1ミリ","assembledPos":[0,0,0.54],"explodeOffset":[84,-18,40],"integratedExplodeOffset":[84,-18,40],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C45. SMT自動実装ロボット用・光学アライメント基準マーク（フィデューシャル）","subtitle":"Bare-Copper Gold-Flashed SMT Pick-and-Place Optical Fiducial Targets","category":"ロボットの的あて目印 C45 — 砂粒サイズの部品を100分の1ミリ精度で置くための「金の二重丸」","plainAnalogy":"カード基板の対角のすみっこに、小さな「金色の二重丸（的）」がぽつんと印刷されています。じつはこれ、工場の超高速ロボットがカメラで見て「基板がコンマ何ミリずれて置かれたか」を一瞬で見抜き、砂粒より小さい0201コンデンサやBGAチップをピタッと寸分違わず載せるための基準マークなんです！","summary":"基板対角の2〜3か所およびファインピッチBGAチップ近傍に配置された直径1.0 mmのソルダーレジスト抜き金メッキ円形ターゲット（グローバル／ローカル・フィデューシャルマーク）。","opticsAndPhysics":["基板は製造時の熱でミクロン単位にわずかに伸縮するため、チップマウンタのマシンビジョンカメラが対角のフィデューシャル中心を認識してX・Y・回転θと伸縮率をリアルタイム補正します。","ハンダペースト印刷機（ステンシルアライメント）と3D SPI/AOI自動外観検査機も同じ基準マークを参照し、0.35 mmピッチのBGAボールのハンダブリッジ不良をゼロに近づけます。","周囲を幅1 mmのクリアランス（レジスト無し銅抜きリング）で囲うことで、照明反射コントラストを最大化してカメラ誤認識を防いでいます。"],"formula":{"expression":"実装位置決め精度 ±15 μm（3σ） ／ ターゲット径 φ1.0 mm ＋ クリアランス φ2.0 mm","description":"極小Type A基板上へ百数十個の微細部品を超高歩留まりで自動実装するマシンビジョン基準点"},"nextGenInnovation":"2025〜2026年のAI光学検査（AOI）＋X線3D検査ラインでは、フィデューシャル座標と紐づけた全ハンダ接合部のデジタルツイン品質管理を実施。","specs":[{"label":"形状仕様","value":"φ1.0 mm 円形銅箔（ENIG金メッキ）＋クリアランス環"},{"label":"配置位置","value":"基板対角グローバル×3 ＋ コントローラ近傍ローカル×2"},{"label":"ロボット精度","value":"±15 μm 位置・回転・熱伸縮リアルタイム補正"},{"label":"対応工程","value":"クリームハンダ印刷・高速チップ実装・3D AOI検査"}],"diagramType":"cfe_optical_fiducials"},{"id":"cfe-conformal-nano-coat","order":46,"swatchColor":"#06b6d4","groupKey":"目に見えない超撥水バリア_C46_万一湿気が入り込んでも水滴をコ","assembledPos":[0,1.5,0.65],"explodeOffset":[-76,36,8],"integratedExplodeOffset":[-76,36,8],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C46. 基板全体プラズマ撥水ナノコーティング（耐塩害・耐結露保護膜）","subtitle":"Sub-500 nm Plasma-Deposited Fluoropolymer Hydrophobic Nano-Coating","category":"目に見えない超撥水バリア C46 — 万一湿気が入り込んでも水滴をコロッと弾きサビさせない魔法の膜","plainAnalogy":"カードの外側にはIP57防水シール（C04）がありますが、嵐の海辺や真冬の雪山ではわずかな湿気が入り込むこともあります。そこで基板とチップのすみずみまで、ハスの葉みたいに水をコロコロ弾く「厚さ髪の毛の200分の1の透明な撥水膜」をプラズマで焼き付けて、サビとショートを二重に防いでいるんです！","summary":"実装済みPCBと全電子部品の表面を厚さ100〜500 nmの極薄フッ素系撥水ポリマーで覆うプラズマCVDナノコーティング被膜。結露や潮風によるイオンマイグレーション（腐食ショート）を徹底抑止します。","opticsAndPhysics":["真空チャンバー内でプラズマ重合により気相成膜するため、BGAチップ下の狭いスキマや0201コンデンサ側面までピンホールなしで回り込みます。","水接触角が110°以上の超撥水性を持ちながら、厚さが0.5 μm未満と極薄なのでコントローラやNANDの放熱をまったく妨げません。","21ピン金メッキ端子だけはマスキングして通電性を100%保ちつつ、内部回路全域に耐湿・耐塩水噴霧プロテクションを与えます。"],"formula":{"expression":"ナノ被膜厚 t ≈ 200〜500 nm ／ 撥水接触角 θ > 110°（熱抵抗増加 ≈ 0）","description":"防水シールのさらに内側で結露・潮風・腐食から大切な撮影データを守る最終防湿バリア"},"nextGenInnovation":"2025〜2026年のプロ用タフカードでは、外装IP57密閉＋内部プラズマ撥水コート＋BGAアンダーフィルの「3重環境耐性」が最高峰スペック。","specs":[{"label":"成膜工法","value":"真空プラズマ気相重合（PECVD）フッ素系ナノ膜"},{"label":"膜厚仕様","value":"100 〜 500 nm（放熱阻害ゼロ・超軽量）"},{"label":"撥水性能","value":"水接触角 110°以上（結露水滴の膜化を防止）"},{"label":"防御対象","value":"海辺塩害・熱帯高湿・急激温度差の結露ショート"}],"diagramType":"cfe_conformal_nano_coat"},{"id":"cfe-solder-mask-silkscreen","order":47,"swatchColor":"#15803d","groupKey":"高速信号の舗装道路_C47_普通の基板だとGHz信号が途中で消え","assembledPos":[0,1.2,-0.52],"explodeOffset":[0,-34,-66],"integratedExplodeOffset":[0,-34,-66],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C47. 低誘電率（Low-Dk）ソルダーレジスト＆全面銅リファレンスGND層","subtitle":"Ultra-Low-Loss Dielectric Prepreg, Solder Mask & Continuous Solid Copper GND Plane","category":"高速信号の舗装道路 C47 — 普通の基板だとGHz信号が途中で消えてしまうので特別な低損失材を採用","plainAnalogy":"F1カーが砂利道では走れないように、PCIe Gen4（毎秒160億回）の超高速信号も普通の安い基板の上では途中でエネルギーを吸い取られて弱ってしまいます。そこで電波を吸いにくい特別な低誘電率（Low-Dk）素材と、真下に敷き詰めた一枚板の銅アース（GND層）でツルツルの専用サーキットを作っているんです！","summary":"8層HDI基板（C07）のPCIe Gen4信号層を挟み込む低誘電正接（Low-Df）絶縁プリプレグ／ソルダーレジスト、および信号帰還電流の最短経路となる切れ目のない全面銅リファレンスGNDプレーンです。","opticsAndPhysics":["GHz帯の誘電体損失（α_d ∝ f · √Dk · Df）を最小化するため、一般FR-4（Df≈0.020）より遥かに低損失なMegtron系／低誘電ガラスクロス材（Df < 0.006）を採用します。","高速差動配線の直下層に一切のスリット（切れ目）がない一枚板の銅GNDプレーンを敷くことで、帰還電流が最小ループで戻り、インピーダンス85 Ωの均一性と低EMIを両立します。","ソルダーレジストの厚みを±5 μmで均一管理し、表面マイクロストリップ配線の誘電率バラつきによる信号反射を防いでいます。"],"formula":{"expression":"誘電損失 α_d ∝ f · √Dk · Df（Low-Df < 0.006 ＋ 連続銅GND基準面）","description":"16 GT/sの高周波信号減衰とクロストークを抑え、エラーゼロの超高速転送を支える基板材料工学"},"nextGenInnovation":"2025〜2026年のCFexpress 4.0（将来5.0見据え）では、低損失材と超低粗度銅箔の組み合わせが高速安定性の隠れた決め手です。","specs":[{"label":"絶縁基材","value":"低誘電率（Dk≈3.4）・低誘電正接（Df<0.006）高速材"},{"label":"基準プレーン","value":"切れ目なし全面1 oz銅リファレンスGND層（2〜3層）"},{"label":"レジスト管理","value":"低誘電ソルダーレジスト厚 ±5 μm 高精度塗布"},{"label":"電気効果","value":"16 GT/s挿入損失低減＆隣接レーンクロストーク遮断"}],"diagramType":"cfe_solder_mask_silkscreen"},{"id":"cfe-flipchip-c4-bumps","order":48,"swatchColor":"#b45309","groupKey":"チップをひっくり返して直結_C48_細い糸の代わりに数百個の極小","assembledPos":[-6.2,-9,0.88],"explodeOffset":[-96,-38,22],"integratedExplodeOffset":[-96,-38,22],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C48. コントローラSoCフリップチップC4ハンダバンプ＆銅ピラー接続アレイ","subtitle":"7 nm/12 nm Controller Silicon Die Flip-Chip C4 Solder & C2 Copper-Pillar Micro-Bumps","category":"チップをひっくり返して直結！C48 — 細い糸の代わりに数百個の極小ハンダ粒で最短直結する爆速実装","plainAnalogy":"昔のチップは周りから細い金の糸（ワイヤー）を伸ばしてつないでいましたが、糸が長いと毎秒160億回の信号が詰まってしまいます。そこでコントローラのシリコン頭脳を「うつぶせ（フリップチップ）」にひっくり返し、お腹に並べた数百個の極小銅柱・ハンダ粒（C4バンプ）で基板へ最短直結しているんです！","summary":"7 nm / 12 nm PCIe Gen4コントローラSoC（C08）のパッケージ内部で、シリコンダイの能動面を下向きにしてパッケージ基板へ直接接合するフリップチップC4ハンダバンプ／C2銅ピラー（マイクロバンプ）格子です。","opticsAndPhysics":["従来のワイヤーボンディング（接続長1〜3 mm）に比べ、フリップチップのC4/C2バンプは接続長がわずか30〜80 μm（約1/30！）で寄生インダクタンスが極小になるため、PCIe Gen4（16 GT/s）や3,600 MT/s NANDバスが安定動作します。","シリコンチップの中央部にも電源・GNDバンプを直接配置できる（エリアアレイ接続）ため、数Aの瞬時電力も電圧ドロップ（IRドロップ）なく均等に供給できます。","チップの背中（シリコン裏面）が上を向く構造なので、すぐ上のグラフェンTIM（C26）や銅ヒートスプレッダー（C25）へ熱をダイレクトに逃がせる放熱上の大メリットもあります。"],"formula":{"expression":"バンプ高さ ≈ 40〜70 μm ／ 寄生インダクタンス L < 0.05 nH（ワイヤー比 1/20以下）","description":"超高速PCIe Gen4信号品質と裏面ダイレクト放熱を同時に叶える先端チップ接続技術"},"nextGenInnovation":"最新の6 nm / 7 nm NVMeコントローラ（SM2504XT / Phison次世代等）ではピッチ40 μm級のC2銅ピラー＋SnAgキャップ微細バンプが主流。","specs":[{"label":"実装方式","value":"フリップチップ（FC-CSP / FC-BGA）フェースダウン接合"},{"label":"バンプ構造","value":"C4 SnAgハンダバンプ / C2 銅ピラーマイクロバンプ"},{"label":"接続ピッチ","value":"約 50 〜 90 μm（数百ピン高密度エリアアレイ）"},{"label":"放熱利点","value":"シリコンダイ裏面を上向き露出させ上面熱拡散板へ直結"}],"diagramType":"cfe_flipchip_c4_bumps"},{"id":"cfe-abf-package-substrate","order":49,"swatchColor":"#0f766e","groupKey":"ミクロとマクロの変換インターチェンジ_C49_50_mの超極細配","assembledPos":[-6.2,-9,0.66],"explodeOffset":[-94,-14,48],"integratedExplodeOffset":[-94,-14,48],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C49. 多層ABF / BTパッケージ基板＆RDL極細再配線層","subtitle":"High-Density Multi-Layer ABF / BT Package Substrate & Redistribution Layer (RDL)","category":"ミクロとマクロの変換インターチェンジ C49 — 50μmの超極細配線から0.4mmの基板端子へ広げる翻訳板","plainAnalogy":"コントローラのシリコンチップの端子は髪の毛より狭い0.05ミリ間隔で並んでいますが、カードの8層基板のハンダ粒は0.4ミリ間隔です。そのままでは細かすぎてつなげないので、パッケージの中に「ABF（味の素ビルドアップフィルム）」という日本のスゴイ材料のミニ多層基板を挟んで、配線をきれいに扇状に広げているんです！","summary":"コントローラSoC（C08）パッケージの土台となる極薄4〜6層ABF／BT樹脂ビルドアップ基板と、マイクロバンプ間隔（~50 μm）をBGAハンダボール間隔（0.4 mm）へ変換するRDL（再配線層）です。","opticsAndPhysics":["日本の味の素ファインテクノが生み出した絶縁フィルム（ABF）上へレーザー加工とセミアディティブ銅めっきで線幅／線間10 μm級の超微細配線を多層形成します。","薄型CFexpressカード（全厚2.8 mm）へ収めるため、パッケージ基板自体の厚さはわずか100〜150 μm（コピー用紙1.5枚分！）まで極薄化されています。","内部に専用の電源プレーンとGNDシールド層を持ち、ダイ直下のインピーダンス整合と同時スイッチングノイズ（SSN）の吸収を行います。"],"formula":{"expression":"線幅/線間 L/S ≈ 10/10 μm（ピッチ 50 μm → 400 μm へ 8倍ファンアウト展開）","description":"先端7 nmシリコンとカード側HDI基板を繋ぐ、超高密度・極薄半導体パッケージインターポーザ"},"nextGenInnovation":"2025〜2026年の超小型CFexpress Type A向けパッケージでは、薄型コアレス基板やファンアウト・ウェハレベルパッケージ（FOWLP）でさらなる薄型・低損失化が進行。","specs":[{"label":"基板材料","value":"ABF（Ajinomoto Build-up Film） / 高剛性BTレジン"},{"label":"配線微細度","value":"最小線幅 8〜12 μm（レーザーマイクロビア積層）"},{"label":"基板厚さ","value":"約 0.12 〜 0.18 mm（超薄型FC-CSPパッケージ）"},{"label":"役割機能","value":"C4バンプ→BGAボール配線変換＋電源デカップリング"}],"diagramType":"cfe_abf_package_substrate"},{"id":"cfe-nand-staggered-16die","order":50,"swatchColor":"#0284c7","groupKey":"1ミリの中に16階建てのシリコン階段_C50_髪の毛の半分の薄さ","assembledPos":[0,12.6,1.05],"explodeOffset":[-76,56,36],"integratedExplodeOffset":[-76,56,36],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C50. 16段階段状オフセット積層NANDダイ（16DP）＆ダミースペーサー","subtitle":"16-Die Vertically Staggered 3D NAND Silicon Stack (30 μm Ultra-Thin Dies) & Dummy Spacer","category":"1ミリの中に16階建てのシリコン階段！C50 — 髪の毛の半分の薄さに削った記憶チップを16枚重ねる神業","plainAnalogy":"切手より小さい黒いNANDチップ（C12）の中に、どうして1テラバイト〜2テラバイトもの動画が入るのでしょう？なんとシリコンの板を「髪の毛の半分以下（0.03ミリ）」までペラペラに削り、トランプを少しずつズラして階段状に16枚も積み重ねているんです！端っこをズラすことで全部の層へ金の糸をつなげるんですよ。","summary":"1 TB〜2 TB級の超高密度3D NAND BGAパッケージ（C12/C13）の内部で、厚さ約25〜35 μmまで裏面研削（バックグラインド）した最大16枚のNANDシリコンダイを階段状（スタッガード）に積層した16DP構造です。","opticsAndPhysics":["1枚のダイ（512 Gb〜1 Tb容量）をそのまま真上に重ねると下段の電極パッドが隠れてしまうため、各段を0.3〜0.5 mmずつズラす「階段オフセット積層」またはジグザグ積層を採用します。","16枚もの極薄シリコンが熱で反り返る（ウォーページ）のを防ぎ、ワイヤーを張る空間を確保するため、途中に配線のない「ダミーシリコンスペーサー」を挟んで機械バランスを整えます。","チップイネーブル（CE）ピンで16枚のダイを独立制御し、コントローラが複数ダイへ同時並列書き込み（ダイ・インターリーブ）を行うことで1,700〜1,900 MB/sの爆速を実現します。"],"formula":{"expression":"16ダイ × 1 Tb/ダイ ＝ 2 TB/パッケージ（単ダイ厚 ≈ 30 μm・総高 < 0.85 mm！）","description":"切手大の極薄Type Aカードへ1〜2 TBの大容量と並列超高速転送を詰め込む3D積層パッケージ技術"},"nextGenInnovation":"2025〜2026年のBiCS8世代では2 Tbダイや16〜32ダイ積層（32DP）により、極小Type Aカードでも2 TB〜4 TB時代へ突入しています。","specs":[{"label":"積層段数","value":"8DP / 16DP（最大16枚の超薄シリコンダイ階段積層）"},{"label":"単ダイ厚さ","value":"約 25 〜 35 μm（人間の髪の毛 約70 μm の半分以下）"},{"label":"反り対策","value":"ダミーシリコンスペーサー挿入＋低応力積層制御"},{"label":"並列動作","value":"マルチCE並列インターリーブで連続1,700+ MB/s達成"}],"diagramType":"cfe_nand_staggered_16die"},{"id":"cfe-nand-daf-gold-wires","order":51,"swatchColor":"#f59e0b","groupKey":"16段をつなぐ極細の金の橋_C51_0_01ミリの特殊テープで貼","assembledPos":[0,12.6,0.85],"explodeOffset":[-96,36,16],"integratedExplodeOffset":[-96,36,16],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C51. ダイアタッチフィルム（DAF）接着層＆多段アーチ極細ボンディングワイヤー","subtitle":"10 μm Thermal Die-Attach Film (DAF / FOW) & Multi-Tier Low-Loop Au/Cu Bond Wires","category":"16段をつなぐ極細の金の橋 C51 — 0.01ミリの特殊テープで貼り合わせ、何百本もの極細ワイヤーで配線","plainAnalogy":"ペラペラに削った16枚のNANDチップ同士を普通の液体のりで貼ると、はみ出して電極を汚してしまいます。そこで厚さわずか0.01ミリの両面テープ「DAF」でピタッと貼り、階段のように並んだ16枚の端っこから基板へ、クモの糸より細い金や銅のワイヤーを何百本もアーチ状に渡しているんです！","summary":"階段積層された各NANDダイ間に挟まる厚さ5〜10 μmの固体接着シート「DAF（Die Attach Film / ワイヤー埋込型FOW）」と、多段ダイの電極パッドをパッケージ基板へ結ぶ直径15〜20 μmの低ループ多段ボンディングワイヤー群です。","opticsAndPhysics":["従来の液状ペーストと違い、固体フィルムのDAFはウエハの裏面へ事前に貼って一緒にダイシング（切断）するため、接着厚みが完全に均一で電極パッドへのはみ出し（ブリード）が起きません。","下段ワイヤーの真上に次のダイを載せる際は、熱で軟化してワイヤーを優しく包み込む「FOW（Film Over Wire）」フィルムを使い、ワイヤー同士の接触ショートを防ぎます。","超低ループ・チェーンボンディング技術により、16段もの高層スタックでありながら最上段ワイヤーの天井高を極限まで低く抑え、薄さ0.85 mmのBGAへ収めています。"],"formula":{"expression":"DAFフィルム厚 5〜10 μm ／ ワイヤー径 φ15〜20 μm（多段ロー・ループ配線）","description":"16枚もの極薄シリコンダイを破損させず電気的・機械的に高密度結線する半導体後工程の結晶"},"nextGenInnovation":"高速Toggle 5.0 / ONFI 5.1（3,600 MT/s）対応ではワイヤーのインダクタンス低減と、次世代TSV（シリコン貫通電極）によるワイヤーレス積層も研究が進んでいます。","specs":[{"label":"接着シート","value":"DAF / FOW（厚さ 5〜10 μm 高熱伝導絶縁フィルム）"},{"label":"ワイヤー材質","value":"φ15〜20 μm 高純度金（Au）またはPdコート銅（PCC）"},{"label":"配線技術","value":"多段チェーンボンディング＆スタンドオフステッチ（SOS）"},{"label":"耐振保護","value":"EMC樹脂モールド封止でワイヤー揺れを完全固定"}],"diagramType":"cfe_nand_daf_gold_wires"},{"id":"cfe-nand-emc-mold-balls","order":52,"swatchColor":"#64748b","groupKey":"チップを守る黒い鎧と数百個のハンダの足_C52_中の極細ワイヤー","assembledPos":[0,12.6,0.58],"explodeOffset":[0,68,-42],"integratedExplodeOffset":[0,68,-42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C52. 高熱伝導エポキシモールド樹脂（EMC）＆SAC305鉛フリーBGAハンダボール","subtitle":"Silica-Filled Epoxy Molding Compound (EMC) & SAC305 Lead-Free BGA Solder Ball Grid","category":"チップを守る黒い鎧と数百個のハンダの足 C52 — 中の極細ワイヤーを固めて守り、基板と繋ぐ銀色の粒","plainAnalogy":"メモリカードを開けると見える黒い四角いチップの表面は、じつはシリカの微粒子を85%以上も混ぜた超頑丈な黒い樹脂（EMC）で中の繊細なチップと金の糸を丸ごと固めた「保護カプセル」なんです！そして裏側には、基板とつながる何百個もの小さな銀色のハンダの粒（BGAボール）が碁盤の目のように並んでいます。","summary":"NAND積層ダイとボンディングワイヤーを外部衝撃・湿気から封止する高シリカ充填エポキシモールド樹脂（EMC）、およびパッケージ底面に格子配列された鉛フリーSAC305（Sn-3.0Ag-0.5Cu）BGAハンダボール群です。","opticsAndPhysics":["EMC樹脂には球状シリカフィラーを85〜90 wt%高充填し、熱膨張係数（CTE）をシリコンや基板へ近づけることで、-40 ℃〜+85 ℃の激しい温度サイクルでも内部ワイヤーが断線するのを防ぎます。","トランスファー成形時の樹脂流れで極細ワイヤーが流されない（ワイヤースイープ防止）よう、低粘度かつ高熱伝導な最新モールドコンパウンドが使われます。","底面のSAC305鉛フリーBGAハンダボール（直径約0.20〜0.25 mm・132/152ボール等）はリフロー炉の自己整列（セルフアライメント）効果で基板パッドへ一斉接合され、周囲をアンダーフィル（C28）で補強します。"],"formula":{"expression":"EMC シリカ充填率 ≈ 88 wt%（低CTE） ／ BGA 132〜152ボール（SAC305 融点 217 °C）","description":"繊細な16層シリコンを7.5 m落下や真夏の車内高温から守り抜く堅牢封止と高密度面実装"},"nextGenInnovation":"2025〜2026年の高発熱CFexpress 4.0では、アルミナ／窒化ホウ素フィラー配合の超高熱伝導EMC樹脂でNANDパッケージからの放熱効率も向上。","specs":[{"label":"封止樹脂","value":"低応力・高シリカ充填エポキシモールド樹脂（EMC）"},{"label":"ハンダ合金","value":"SAC305 鉛フリー（Sn96.5 / Ag3.0 / Cu0.5・RoHS適合）"},{"label":"BGA格子","value":"132 / 152 / 252 ボール（ピッチ 0.4〜0.5 mm）"},{"label":"信頼性試験","value":"温度衝撃 -40〜+85 °C 1,000サイクル＋落下耐性"}],"diagramType":"cfe_nand_emc_mold_balls"},{"id":"cfe-hmb-sram-controller-buf","order":53,"swatchColor":"#8b5cf6","groupKey":"超速の一時メモ帳_C53_1ミリ秒も待たせずにデータを受け止め_","assembledPos":[-3.5,-6.5,1.32],"explodeOffset":[-46,-10,64],"integratedExplodeOffset":[-46,-10,64],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C53. コントローラ内蔵高速SRAMバッファ＆HMB（Host Memory Buffer）DMAエンジン","subtitle":"On-Die High-Speed SRAM Write-Coalescing Buffer & NVMe HMB DMA Engine","category":"超速の一時メモ帳 C53 — 1ミリ秒も待たせずにデータを受け止め、DRAMなし設計でも爆速をキープ！","plainAnalogy":"CFexpress Type Aは切手サイズで超狭いので、外付けのDRAMチップ（C16）を載せず省電力にする「DRAMレス型（Phison E27T / SM2269XT系）」も大活躍しています！その秘密が頭脳チップ内蔵の超高速メモ帳（SRAM）と、カメラ側のメモリを少し間借りする「HMB」という賢い仕組みなんです。","summary":"コントローラSoCのシリコン内部に統合された低遅延SRAMキャッシュ（FTLホットマッピング＆ライト結合バッファ）と、NVMe仕様のHMB（Host Memory Buffer）でホスト側RAMをPCIe DMA活用する高速メモリエンジンです。","opticsAndPhysics":["外付けDRAMを省略した小型・低消費電力CFexpress 4.0カードでも、内蔵SRAMへ頻繁に使うアドレス変換表（L2Pテーブル）と書き込み結合バッファを保持して連写バーストを受け止めます。","さらにPCカードリーダーやHMB対応ホストへ接続時は、PCIe Gen4経由でホスト側DRAMの数十MBを直接借りる（HMB）ことで、ランダムアクセス性能をDRAM搭載機に迫る水準へ引き上げます。","専用ハードウエアDMAエンジンがCPU（C09）を介さずPCIe⇔SRAM⇔LDPC⇔NAND間でデータをゼロコピー直送し、電力1 Wあたりの転送速度（MB/s/W）を最大化します。"],"formula":{"expression":"オンダイSRAMアクセス遅延 < 2 ns ＋ NVMe HMB DMA（消費電力最大 30% 低減）","description":"省電力・低発熱が命の小型Type Aカードで爆速連写と長時間8K録画を両立するメモリアーキテクチャ"},"nextGenInnovation":"2025〜2026年のCFexpress 4.0主力コントローラ（Phison PS5027-E27T / PS5029-E29T、Silicon Motion SM2269XT / SM2504XT）が採用する最先端低発熱設計。","specs":[{"label":"内蔵メモリ","value":"コントローラ直内蔵 マルチバンク高速SRAMバッファ"},{"label":"拡張機能","value":"NVMe 2.0 HMB（Host Memory Buffer）DMA対応"},{"label":"代表採用IC","value":"Phison E27T / E29T・SMI SM2269XT / SM2504XT系"},{"label":"熱的利点","value":"外付けDRAM省電力化によりType Aのサーマル余裕拡大"}],"diagramType":"cfe_hmb_sram_controller_buf"},{"id":"cfe-cba-cu-hybrid-bond","order":54,"swatchColor":"#d97706","groupKey":"別_に作って合体させる2025_2026最大の革新_C54_記憶","assembledPos":[0,14.5,1.24],"explodeOffset":[-52,74,58],"integratedExplodeOffset":[-52,74,58],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C54. 次世代CBAウェハ直接接合＆Cu-Cuハイブリッドボンディング（BiCS8–10技術）","subtitle":"2025–2026 CMOS Directly Bonded to Array (CBA) Wafer-to-Wafer Cu-Cu Hybrid Bonding","category":"別々に作って合体させる2025–2026最大の革新！C54 — 記憶層と高速回路を最強の工場で作り銅で直接合体","plainAnalogy":"従来の3D NANDは「管理人室（制御回路）」の上に「200階建てマンション（記憶セル）」を同じ工場で高温焼き上げしていたので、管理人室が熱で痛んでスピードが出ませんでした。2025〜2026年主役の「CBA技術（BiCS8等）」は、マンションと管理人室を別々の最強工場で作ってから、数百万個の極小の銅パッドでピタッと直接合体させる革命なんです！","summary":"キオクシア／サンディスク「BiCS FLASH 第8〜10世代（BiCS8–10）」等で2025〜2026年に本格量産されているCBA（CMOS directly Bonded to Array）構造。メモリセルウェハと高速CMOSウェハを別工程で最適製造し、数百万点のミクロン級Cu-Cu銅ハイブリッド接合で直接貼り合わせます。","opticsAndPhysics":["セル形成時の超高温熱処理からCMOSトランジスタを切り離せるため、低電圧・超高速な先端CMOSロジックを使え、NANDのI/O速度を3,600 MT/s超へ引き上げつつ書き込み電力効率を約70%も改善しました。","2枚の300 mmシリコンウェハ表面を原子レベルに平坦化（CMP）し、酸化膜同士の分子結合＋銅パッド同士の直接拡散接合（Cu-Cu Hybrid Bonding）で隙間なく一体化します。","2026年10月にはメモリセル配列同士もCuハイブリッド接合で多段化する「MSA-CBA（1,000層超への道）」まで発表され、将来の超高容量CFexpressカードへの展開が始まっています。"],"formula":{"expression":"BiCS8 CBA：ビット密度 2.3× ／ 書込電力効率 +70% ／ I/O速度 3,600+ MT/s","description":"「積む」から「別々に作って銅で直接貼る」へ進化した、2025–2026年3D NAND最大のブレイクスルー"},"nextGenInnovation":"2026年度末にはキオクシア出荷の約80%がCBA採用のBiCS8以降へ移行するとされ、最新CFexpress 4.0カードの低発熱・大容量化を直撃しています。","specs":[{"label":"技術名称","value":"CBA（CMOS directly Bonded to Array）ウェハ直接接合"},{"label":"接合界面","value":"数百万点 Cu-Cu 銅ハイブリッドボンディング（サブμm精度）"},{"label":"性能飛躍","value":"I/O速度 3,600+ MT/s・書込効率約70%向上・小型化"},{"label":"次世代発展","value":"BiCS9 / BiCS10 / MSA-CBA（1,000層超ロードマップ）"}],"diagramType":"cfe_cba_cu_hybrid_bond"},{"id":"cfe-crossed-bitline-cbl","order":55,"swatchColor":"#0ea5e9","groupKey":"マンションの真下に管理人室を収納_C55_回路を記憶セルの真下へ","assembledPos":[0,11.2,1.22],"explodeOffset":[56,58,42],"integratedExplodeOffset":[56,58,42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C55. クロスビットライン（CBL）＆CMOS直下周辺回路（CuA）フロア","subtitle":"Crossed Bit Line (CBL) Routing & Underneath CMOS Peripheral Circuit Layer (CuA / CBA)","category":"マンションの真下に管理人室を収納 C55 — 回路を記憶セルの真下へしまい込み、チップ面積をムダなく活用！","plainAnalogy":"昔のフラッシュメモリは記憶セルの「横」に管理人室（読み書き回路）を並べていたので土地がもったいなかったんです。現代の3D NANDは管理人室をマンションの「1階・地下（真下）」へすっぽり収納（CuA / CBA）し、さらに2025〜2026年の最新「クロスビットライン（CBL）」配線で信号の渋滞まで解消しているんです！","summary":"メモリセルアレイの直下（あるいはCBA接合面の下側）にページバッファ・デコーダ・センスアンプを集約したCuA／CBA周辺回路フロアと、キオクシアBiCS8で導入された新配線構造「CBL（Crossed Bit Line）」です。","opticsAndPhysics":["周辺CMOS回路をセルアレイの直下へ立体配置することで、シリコンチップ全体の面積効率（アレイ占有率）を約60%から85〜90%近くまで大幅に向上させます。","2025年発表のCBL（Crossed Bit Line）アーキテクチャは、ビット線とセンスアンプの接続トポロジを立体交差最適化することで配線の寄生容量を削り、読み出し速度と消費電力を同時改善します。","1つのダイ内部を4〜6プレーン（独立した記憶ブロック群）に分割し、直下の周辺回路が並列同時アクセスすることで高スループットを生み出します。"],"formula":{"expression":"アレイ面積効率 ~60% → ~88% ＋ CBL立体交差配線によるビット線容量＆電力削減","description":"切手サイズに数TBを収め、1秒間に数ギガバイトを並列読み書きする最新チップ平面設計"},"nextGenInnovation":"2025〜2026年のBiCS8 / BiCS10（ISSCC発表）でCBL＋CBAの組み合わせにより4-plane / 6-plane超並列動作が実用化。","specs":[{"label":"立体配置","value":"CuA（CMOS under Array）/ CBA 周辺回路直下構造"},{"label":"最新配線","value":"CBL（Crossed Bit Line）低容量立体交差ビット線"},{"label":"内蔵ブロック","value":"行／列デコーダ・ページバッファ・センスアンプ・制御ロジック"},{"label":"並列構成","value":"4〜6独立プレーン並列読み書き（高速連写に直結）"}],"diagramType":"cfe_crossed_bitline_cbl"},{"id":"cfe-ono-charge-trap-stack","order":56,"swatchColor":"#a855f7","groupKey":"電子を閉じ込めるナノの金庫壁_C56_電源を切っても10年データ","assembledPos":[5.5,15.8,1.15],"explodeOffset":[34,72,52],"integratedExplodeOffset":[34,72,52],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C56. 原子レベルONO絶縁積層（トンネル酸化膜／Si₃N₄捕獲層／アルミナ遮断膜）","subtitle":"Nanometer ONO Charge-Trap Film Stack (Tunnel SiO₂ / Si₃N₄ Charge Trap / Al₂O₃ Blocking)","category":"電子を閉じ込めるナノの金庫壁 C56 — 電源を切っても10年データが消えない秘密の「3重サンドイッチ膜」","plainAnalogy":"カメラからカードを抜いて机に1年置いても、なぜ写真データが消えないのでしょう？それは1つ1つの記憶セルの中にある、わずか数ナノメートルの「3重の魔法の壁（ONO膜）」のおかげ！書き込みの時だけ電子がトンネルをくぐって真ん中の「窒化シリコン捕獲室」へ入り、電源を切ると両側の絶縁壁が電子をガッチリ閉じ込めて逃がさないんです！","summary":"3D NANDの垂直メモリストリング（C15）の壁面に原子層堆積（ALD）で形成された、トンネル酸化膜（SiO₂）・電荷捕獲層（Si₃N₄）・ブロック絶縁膜（SiO₂＋高誘電Al₂O₃）の3層ナノ構造（CTF：Charge Trap Flash）です。","opticsAndPhysics":["書込時に約20 Vの強い電界をかけると、中央のポリシリコンチャネルから電子が量子力学的な「ファウラー・ノルドハイム（FN）トンネリング」で薄いトンネル酸化膜（約4〜6 nm）をすり抜け、Si₃N₄層内の欠陥トラップへ捕獲されます。","外側のブロック酸化膜＋高誘電アルミナ（Al₂O₃）層は電子がゲート電極へ逃げ出す（バックトンネリング）のを阻止し、無電源でも数年間データを保持します。","昔の2Dフローティングゲート（導体）と違い絶縁体のSi₃N₄へ電子を離散的に捕獲するため、膜に小さな欠陥ができても電子が一気に全部漏れず、300層超の微細化でも高信頼性を保てます。"],"formula":{"expression":"ONO構造：SiO₂（~5 nm）｜ Si₃N₄捕獲層（~6 nm）｜ Al₂O₃/SiO₂遮断層（~10 nm）","description":"量子トンネル効果で電子を出し入れし、無電源で写真・動画を長期保存する不揮発メモリの核心"},"nextGenInnovation":"2025〜2026年の次世代研究では高誘電（High-k）ハフニア／強誘電体膜による低電圧書込や、300〜400層超でも均一成膜できる極精密ALDプロセスが進展。","specs":[{"label":"トンネル層","value":"極薄 SiO₂ / 酸窒化膜（約 4〜6 nm・量子トンネル通路）"},{"label":"電荷捕獲層","value":"窒化シリコン Si₃N₄（約 5〜7 nm・電子を長期トラップ）"},{"label":"ブロック層","value":"SiO₂ ＋ アルミナ Al₂O₃ 高誘電遮断膜（リーク阻止）"},{"label":"成膜技術","value":"原子1層ずつ積む ALD（原子層堆積）超精密プロセス"}],"diagramType":"cfe_ono_charge_trap_stack"},{"id":"cfe-wordline-staircase","order":57,"swatchColor":"#64748b","groupKey":"300階建てマンションの外階段_C57_積み上げた300層それぞ","assembledPos":[-7.5,15.8,1.15],"explodeOffset":[-86,66,-6],"integratedExplodeOffset":[-86,66,-6],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C57. タングステン／モリブデン・ワード線階段（ステアケース）連絡構造","subtitle":"232–300+ Layer Tungsten / Molybdenum Wordline Staircase Contact Array","category":"300階建てマンションの外階段！C57 — 積み上げた300層それぞれのフロアへ電気をつなぐピラミッド構造","plainAnalogy":"3D NANDは232〜300階もの記憶フロアを真上に積み上げていますが、全部のフロアをバラバラに呼び出すにはどうやって電線をつなぐのでしょう？なんとチップの端っこを「マヤ文明のピラミッドみたいな巨大な階段（ステアケース）」状に削り、1階から300階まで各段の上から金属の柱をズラッと垂直に降ろして配線しているんです！","summary":"232〜300層以上の水平ゲート電極（ワード線：タングステンW、最新世代ではさらに低抵抗なモリブデンMo）の各層へ独立して電圧を印加するため、アレイ端部を階段状にエッチング加工し垂直コンタクト柱を接続したステアケース連絡部です。","opticsAndPhysics":["ワード線は記憶セルのゲート電極（スイッチの開閉つまみ）として機能し、書込時は選択した1層だけに20 V、他の299層には約8〜10 Vのパス電圧を精密に印加します。","200層を超えると階段の面積だけでチップが大きくなりすぎるため、1段のテラスを4方向・多段階に折り返す「3Dマルチステップ階段」で面積を劇的に圧縮しています。","2025〜2026年の300層超世代では、従来のタングステン（W）＋TiNバリア膜から、バリアレスで電気抵抗が約半分になる新金属「モリブデン（Mo）」ワード線への大転換が進んでいます。"],"formula":{"expression":"積層ワード線 N = 218〜321層 ／ 新世代 Mo 金属化によりワード線RC遅延 最大 40% 低減","description":"数百階建ての3D記憶層を1層ずつ独立制御する、半導体微細加工の芸術品「ナノ階段構造」"},"nextGenInnovation":"2025〜2026年にKioxia / Micron / SK hynix / Samsung各社が300層超世代でモリブデン（Mo）ワード線導入を加速し、さらなる高速化を実現。","specs":[{"label":"電極金属","value":"タングステン（W/TiN）→ 次世代低抵抗モリブデン（Mo）"},{"label":"階段構造","value":"232〜300+段 立体マルチステップ・ステアケース"},{"label":"接続方法","value":"各段テラスへの垂直高アスペクト比コンタクト柱"},{"label":"役割機能","value":"行デコーダから全300層のゲート電圧を個別駆動"}],"diagramType":"cfe_wordline_staircase"},{"id":"cfe-nand-charge-pump","order":58,"swatchColor":"#ef4444","groupKey":"チップの中の昇圧ポンプ_C58_3_3Vの電源から瞬間的に20V","assembledPos":[8.5,12.6,1.15],"explodeOffset":[84,52,16],"integratedExplodeOffset":[84,52,16],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C58. オンダイ高電圧チャージポンプ（20V書込／消去パルス昇圧回路）","subtitle":"On-Die Multi-Stage Dickson High-Voltage Charge Pump (18–22 V ISPP Pulse Generator)","category":"チップの中の昇圧ポンプ C58 — 3.3Vの電源から瞬間的に20Vを生み出し電子を記憶室へ押し込む！","plainAnalogy":"カメラからカードへ届く電気はたった3.3ボルトですが、記憶セルの絶縁壁（C56）へ電子をギュッと押し込んだり消したりするには約20ボルトもの高い電圧が必要です！そこでNANDチップの中にコンデンサとスイッチを何段も並べた「電気のバケツリレー昇圧ポンプ」が内蔵されていて、3.3Vを20Vまで一気に持ち上げているんです！","summary":"3D NANDシリコンダイの周辺回路に内蔵された多段ディクソン（Dickson）型チャージポンプ昇圧回路。外部の1.8 V / 3.3 V電源から、書き込み・消去に必要な18〜22 Vの高電圧パルスを精密生成します。","opticsAndPhysics":["TLC（1セルに3ビット＝8段階の電荷量）を正確に書き込むため、いきなり20 Vをかけるのではなく「ISPP（段階的昇圧パルス書込）」で14 V→14.3 V→14.6 V…と少しずつ電圧を上げながら毎回目標電圧を確認します。","データを書き換える前のブロック消去時には、基板チャネル側へ約20 Vの逆電界パルスをかけてSi₃N₄捕獲層から電子を一斉に引き抜き、全ビットを「1」へリセットします。","高電圧はワード線の配線容量を充放電する大電流を伴うため、CBA世代（C54）では高耐圧MOSFETと省電力ポンプ制御で書き込み消費電力を大幅削減しています。"],"formula":{"expression":"入力 3.3 V → 昇圧 V_pgm ≈ 18〜22 V（ISPPステップ ΔV ≈ 0.2〜0.5 V 精密制御）","description":"外部電源3.3 Vだけで量子トンネル書き込み・消去を実行するNANDチップ内蔵の高電圧発生器"},"nextGenInnovation":"2025〜2026年の高速3D NANDでは、複数プレーン独立チャージポンプと高速放電リカバリ回路で1秒間1,800 MB超の連続書き込みを支えます。","specs":[{"label":"昇圧方式","value":"オンダイ多段ディクソン・スイッチトキャパシタ昇圧"},{"label":"生成電圧","value":"書込 V_pgm ≈ 18〜22 V ／ パス V_pass ≈ 8〜10 V"},{"label":"書込制御","value":"ISPP（Incremental Step Pulse Programming）微細段階パルス"},{"label":"安全分離","value":"高耐圧トランジスタによる低電圧ロジック保護"}],"diagramType":"cfe_nand_charge_pump"},{"id":"cfe-sense-amp-page-buf","order":59,"swatchColor":"#3b82f6","groupKey":"ナノ電流を聞き分ける超精密な耳_C59_たった1つの記憶セルから","assembledPos":[4.5,9.2,1.15],"explodeOffset":[84,34,48],"integratedExplodeOffset":[84,34,48],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C59. 高速ページバッファ＆マルチレベルセンスアンプ（TLC 8段階電圧判定器）","subtitle":"16 KB On-Die Page Buffer Latches & 8-Level TLC Threshold-Voltage Sense Amplifiers","category":"ナノ電流を聞き分ける超精密な耳 C59 — たった1つの記憶セルから「8段階の微妙な電圧差」を読み取る！","plainAnalogy":"現代のTLC 3D NANDは、1つの極小セルの中に電子の量を「空っぽ〜満タンまで8段階（000〜111の3ビット分）」に分けて覚えています！読み出すときは、ビット線を流れるごくわずかなナノアンペアの電流を何万個もの「超精密な耳（センスアンプ）」が一斉に聞き分けて、16キロバイト分の0と1を一瞬で取り出しているんです！","summary":"各ビット線（数万本並列）の直下に配置された超高感度センスアンプアレイと16 KBページバッファSRAMラッチ。1セルあたり8つのしきい値電圧（Vth）分布をマイクロ秒で判別し、ソフト判定情報も出力します。","opticsAndPhysics":["TLCセルでは8つの電圧状態（ER, P1〜P7）の間隔がわずか0.3〜0.5 Vほどしかなく、経年変化や温度で電子が少し漏れると境界が曖昧になります。","通常の「ハード読み出し」でエラーが多い場合、センスアンプは基準電圧をわずかにズラして何度も測る「ソフトセンス（LLR対数尤度比）」を出力し、LDPC誤り訂正エンジン（C10）へ渡して完璧に復元します。","1ページ（16 KB＋ECC冗長部）分のデータを丸ごと並列ラッチしてキャッシュパイプライン動作させるため、次のページを読みながら前のページを3,600 MT/sでコントローラへ転送できます。"],"formula":{"expression":"1セル＝2³＝8電圧レベル（TLC 3 bit/cell） ／ 16 KB並列一括センス tR ≈ 30〜45 μs","description":"極微弱なセル電流から8段階のデジタルビットと信頼度情報を並列抽出するNANDの聴覚器官"},"nextGenInnovation":"BiCS8 CBL/CBA世代ではセンスアンプを直下ウェハの最新CMOSで作れるため、読み出しレイテンシ（tR）とページキャッシュ転送速度が劇的に向上。","specs":[{"label":"判定階調","value":"TLC 8レベル（3 bit/cell）・pSLC時 2レベル高速判定"},{"label":"並列幅","value":"16 KB＋ECCパリティ（約14万ビット一括並列センス）"},{"label":"ECC連携","value":"ハード判定＋多段階ソフト判定（LDPC LLR生成）"},{"label":"読み出し時間","value":"tR 約 30〜45 μs（キャッシュリードで連続高スループット）"}],"diagramType":"cfe_sense_amp_page_buf"},{"id":"cfe-read-reclaim-scrub","order":60,"swatchColor":"#10b981","groupKey":"データの見回り修復パトロール_C60_読みすぎや時間経過で薄れか","assembledPos":[-7.5,8.8,1.15],"explodeOffset":[72,68,-22],"integratedExplodeOffset":[72,68,-22],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C60. リードディスターブ対策（Early-Move / Read-Reclaim＆自動巡回データ修復）","subtitle":"Proactive Early-Move, Read-Reclaim & Background Charge-Drift Data Scrubber Engine","category":"データの見回り修復パトロール C60 — 読みすぎや時間経過で薄れかけた記録を、消える前に新しい部屋へお引越し！","plainAnalogy":"フラッシュメモリは同じ場所を何万回も読み出したり、夏場の暑い車内に置いたりすると、閉じ込めた電子が少しずつ薄れてしまう弱点（リードディスターブ／データ保持劣化）があります。そこで2025〜2026年のプロ用カードは、エラーが増え始める前に「お引越しパトロール」が自動で新しい部屋へ書き直してデータを永遠に守るんです！","summary":"2025〜2026年のプロ用シネマCFexpress・産業用NVMe（ATP / Sony / ProGrade Refresh Pro等）に搭載される、リードディスターブ検知（Read-Reclaim）・早期退避（Early-Move）・バックグラウンド巡回リフレッシュ機構です。","opticsAndPhysics":["あるブロックのデータを何度も再生・プレビューすると、隣のセルにかかる読み出しパス電圧の影響で徐々に電子が紛れ込みます（リードディスターブ）。読出回数がしきい値に達すると自動で別ブロックへ移し替えて清浄化します（Read-Reclaim）。","LDPC誤り訂正エンジン（C10）が訂正ビット数の微増を検知した瞬間、エラーが訂正不能になるずっと手前で「Early-Move（予防的再配置）」を発動し、新鮮な強い電荷で書き直します。","撮影の合間のアイドル時間やPCでのリフレッシュ実行時に全領域の電荷保持状態（Data Retention）を巡回診断し、8K収録ファイルの長期信頼性を保証します。"],"formula":{"expression":"訂正ビット数 N_err > 予防しきい値 N_early → 自動フレッシュブロック再書込（BER < 10⁻¹⁷維持）","description":"電子の自然流出や読み込みストレスによるデータ消失を「壊れる前に自動修復」するプロ仕様の守護機能"},"nextGenInnovation":"2026年最新ファームウエアでは温度履歴（高温放置ほど電子漏れが速いアレニウス則）も加味して巡回リフレッシュ間隔をAI的に最適化。","specs":[{"label":"予防機構","value":"Early-Move（エラー予兆検知時の自動ブロック退避）"},{"label":"読出保護","value":"Read-Reclaim（リードディスターブ蓄積ブロック自動更新）"},{"label":"長期保持","value":"バックグラウンド巡回スクラビング＆温度補償リフレッシュ"},{"label":"データ信頼性","value":"訂正不能エラー率 UBER < 10⁻¹⁷（シネマ収録基準）"}],"diagramType":"cfe_read_reclaim_scrub"},{"id":"cfe-pcie-gen4-serdes-phy","order":61,"swatchColor":"#2563eb","groupKey":"毎秒160億回の波をくっきり蘇らせる耳と口_C61_なまった超高","assembledPos":[-6.2,-13.6,1.32],"explodeOffset":[-42,-56,56],"integratedExplodeOffset":[-42,-56,56],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C61. 16 GT/s PCIe Gen4 ×1 アナログSerDes PHY ＆ CTLE/DFE波形イコライザ","subtitle":"16 GT/s PCIe Gen4 ×1 Analog SerDes Transceiver PHY & CTLE/DFE Equalizer Front-End","category":"毎秒160億回の波をくっきり蘇らせる耳と口 C61 — なまった超高速信号をオンダイコイルで整形するアナログ最前線","plainAnalogy":"CFexpress 4.0では1秒間に160億回もの速さで0と1の電気の波が飛び交いますが、たった数センチ基板を走っただけで波の形は丸く潰れてしまいます。そこでコントローラ入口に極小の渦巻き銅コイル（ピーキングインダクタ）とCTLE/DFE波形復元回路を置き、潰れた波を一瞬でピンと蘇らせて読み誤りゼロを保ちます！","summary":"PCIe Gen4（16 GT/s NRZ）通信の物理層を担うコントローラ内蔵アナログSerDes PHYブロック。オンダイ・スパイラルピーキングインダクタ、100 Ω精密終端抵抗、連続時間線形等化器（CTLE）、判定帰還等化器（DFE）を集積しています。","opticsAndPhysics":["8 GHzナイキスト周波数における基板・コネクタの表皮効果損失（Insertion Loss）を、送信側プリエンファシスと受信側CTLE/DFEの適応イコライゼーションで自動補償します。","クロック・データ・リカバリ（CDR）PLLがデータ波形自体からピコ秒単位の最適サンプリング位相を常時追尾し、8K RAW連続記録中のビット誤り率（BER < 10⁻¹²）を保証します。"],"formula":{"expression":"16 GT/s × 128b/130b符号化 ≈ 1.969 GB/s（単一PCIe Gen4レーン理論帯域・BER < 10⁻¹²）","description":"たった1レーン（TX/RX各1対）で毎秒約2ギガバイトを通すため、極限のアナログ波形整形技術が動く"},"nextGenInnovation":"CFexpress 4.0 Type A（最大1,800 MB/s）から将来のPCIe Gen5 PAM4世代へと進化する際の中核となる超高周波アナログフロントエンド技術です。","specs":[{"label":"物理層速度","value":"PCIe Gen4 ×1（16.0 GT/s・128b/130bエンコーディング）"},{"label":"波形等化回路","value":"TX 3-Tap FFE ＋ RX 適応型 CTLE / マルチタップ DFE"},{"label":"高周波素子","value":"オンダイ極小スパイラル銅ピーキングインダクタ ＋ 100 Ω精密終端"},{"label":"クロック復元","value":"低ジッタCDR（Clock & Data Recovery）位相追尾ループ"}],"diagramType":"cfe_pcie_gen4_serdes_phy"},{"id":"cfe-nand-toggle5-phy-bus","order":62,"swatchColor":"#0ea5e9","groupKey":"頭脳と記憶チップを結ぶ8車線ハイウェイ_C62_コントローラとB","assembledPos":[-1,2.2,0.56],"explodeOffset":[24,34,54],"integratedExplodeOffset":[24,34,54],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C62. ONFI / Toggle 5.0 3,200 MT/s DDR 8チャネルNANDバス ＆ DQSストローブ配線","subtitle":"ONFI / Toggle 5.0 3200 MT/s DDR 8-Channel NAND Interface Bus & Differential DQS Strobe Bridge","category":"頭脳と記憶チップを結ぶ8車線ハイウェイ C62 — コントローラとBiCS8 NANDを毎秒32億回で並列往復する超高速配線網","plainAnalogy":"カメラからの映像をコントローラが受け取ったあと、記憶チップ（3D NAND）へ書き込む道路が狭いと渋滞してしまいます。このToggle 5.0バスはコントローラと表裏のNANDチップを最大8車線並列で結び、データ（DQ）と一緒に正確な合図（差動DQSストローブ）を毎秒32億回送り出して8K動画を詰まらせません！","summary":"PCIe Gen4コントローラ（U1）と表裏のKIOXIA BiCS8 3D NANDパッケージ（U2/U3）間を並列接続する、Toggle DDR 5.0（最大3,200〜3,600 MT/s）対応インピーダンス制御マルチチャネルバスおよび差動DQSストローブ配線群。","opticsAndPhysics":["データ線（DQ0〜7）と基準クロック（DQS_t / DQS_c 差動対）の配線長を±0.1 mm以内で厳密等長化（スキュー制御）し、1.2 V低振幅VCCQインターフェースで高速・低消費電力転送を実現します。","オンダイ終端（ODT）とZ_Qキャリブレーションにより、16ダイ積層（16DP）の大きな入力容量でも波形反射を抑え、VPG800持続書込のボトルネックを解消します。"],"formula":{"expression":"チャネル帯域 = 3,200 MT/s × 8 bit = 3.2 GB/s/ch（並列インターリーブで書込1,700 MB/s持続）","description":"コントローラから表裏の16層NANDダイへ同時並列にデータを流し込み、圧倒的な書込速度を生む"},"nextGenInnovation":"BiCS8 CBA世代の高速I/O（3.2〜3.6 Gb/s）と組み合わせることで、Type A極小カードでもプロ用シネマRAWの持続書込を余裕でこなします。","specs":[{"label":"インターフェース","value":"Toggle DDR 5.0 / ONFI 5.1（1.2 V 低消費電力高速I/O）"},{"label":"転送レート","value":"最大 3,200 〜 3,600 MT/s（差動DQSストローブ同期）"},{"label":"並列構成","value":"表裏インターリーブ多チャネル並列アクセス（16DP対応）"},{"label":"信号整合","value":"等長配線 ＋ オンダイ終端（ODT）＆ ZQ自動インピーダンス校正"}],"diagramType":"cfe_nand_toggle5_phy_bus"},{"id":"cfe-thermal-via-copper-slug","order":63,"swatchColor":"#ea580c","groupKey":"基板を貫く純銅の放熱エレベーター_C63_7nmコントローラの熱","assembledPos":[-6.2,-9,0],"explodeOffset":[-62,-16,-54],"integratedExplodeOffset":[-62,-16,-54],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C63. コントローラ直下 銅充填サーマルビア群 ＆ 基板埋込純銅サーマルコイン","subtitle":"Under-Controller Stacked Copper Thermal Via Array & Embedded Solid-Copper PCB Thermal Coin Slug","category":"基板を貫く純銅の放熱エレベーター C63 — 7nmコントローラの熱を基板の裏側まで一気に貫通させて両面放熱！","plainAnalogy":"8層基板の材料（ガラスエポキシ）はプラスチックと同じで熱を通しにくい性質があります。そのためコントローラの真下にそのままでは熱が裏のステンレス放熱板へ届きません！そこでコントローラ真下の基板を純銅の塊（サーマルコイン）と25本の銅ビアでぶち抜き、表の銅板と裏の金属板の「両面同時放熱」を実現しています！","summary":"NVMe Gen4コントローラ（C08）のサーマルグラウンドパッド直下に埋め込まれた高熱伝導純銅サーマルコイン（Copper Coin）および5×5銅めっき充填サーマルビア（VIPPO）貫通アレイ。","opticsAndPhysics":["FR-4樹脂基板の厚み方向熱伝導率はわずか約 0.3 W/m·K ですが、純銅サーマルコイン＋銅充填ビア（約 380 W/m·K）を貫通させることで、垂直方向の熱抵抗を100分の1以下へ激減させます。","コントローラの発熱を表面の純銅スプレッダ（C25）だけでなく裏面ステンレスバックプレート（C02）へも50:50で均等分配し、8K連続録画時のサーマルスロットリング発動を大幅に遅らせます。"],"formula":{"expression":"k_Cu (380 W/m·K) / k_FR4 (0.3 W/m·K) > 1,200倍（表裏デュアル放熱ルート開通！）","description":"コントローラ直下を純銅の柱で貫通させることで、カードの表面と裏面の両方から効率よく熱を逃がす"},"nextGenInnovation":"極小体積のCFexpress Type AでGen4 1,800 MB/sの発熱を捌き切るための、プロシネマカード専用の高密度熱設計構造です。","specs":[{"label":"構造部材","value":"基板埋込型無酸素銅サーマルコイン ＋ 銅充填VIPPOビア（5×5）"},{"label":"熱伝導率","value":"約 380 W/m·K（FR-4基板単体比 約1,200倍の垂直熱輸送）"},{"label":"放熱経路","value":"コントローラ直下 → 表銅板（C25）＆ 裏SUS放熱板（C02）両面分配"},{"label":"効果","value":"VPG800 / 8K連続収録時の温度上昇と速度低下を抑制"}],"diagramType":"cfe_thermal_via_copper_slug"},{"id":"cfe-slot-contact-wiper-interface","order":64,"swatchColor":"#eab308","groupKey":"カードを受け止めるカメラ側の精密ソケット_C64_21本の金バネ","assembledPos":[0,-29.2,0],"explodeOffset":[0,-88,26],"integratedExplodeOffset":[0,-88,26],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C64. カメラ側 CFexpress Type A コンボスロット 21ピン金ばね接点 ＆ プッシュ式ロック機構","subtitle":"Camera-Side CFexpress Type A Combo-Slot 21-Pin Gold Spring Wiper Block & Push-Push Eject Latch","category":"カードを受け止めるカメラ側の精密ソケット C64 — 21本の金バネとカチッと留まるハートカム機構で1万回挿抜に対応！","plainAnalogy":"カードをカメラに押し込んだとき「カチッ」と心地よくロックされ、もう一度押すとスッと飛び出す仕組みの正体がこれ！カメラ側のコンボスロット内部には、カードの21枚の金端子を優しく挟み込む金めっきバネ接点と、ボールペンのノックと同じ「ハートカム＋ステンレスラッチ爪」が仕込まれているんです！","summary":"Sony α7 IV / α1 / FX3等に採用されるSD・CFexpress Type Aデュアル対応コンボスロットのカード側結合インターフェース。21本の金めっきりん青銅ばねワイパー接点と、側面ノッチ（C33）を係止するステンレス製プッシュ・プッシュ式イジェクト機構です。","opticsAndPhysics":["カードを挿入すると、まず長いGND/+3.3Vピン（C32）が金ばねワイパーに接触して静電気を逃がし、最後に凹んだINS#検出ピンが触れた瞬間にカメラ側電源投入シーケンスが開始します。","右側面デテント溝（C33）に噛み合うステンレス製イジェクト爪と戻しコイルばねは、10,000回以上の抜き差しサイクルに耐える高信頼設計です。"],"formula":{"expression":"挿抜耐久 ≥ 10,000回 ／ 接触ワイプ荷重 ≈ 0.4 N/pin × 21ピン（低挿抜力＋耐衝撃ロック）","description":"カメラ側の21本金バネとハートカムラッチが、高速データ通信と確実な抜け止めを両立する"},"nextGenInnovation":"1つのスロットでSDカードとCFexpress Type Aの両方を自動判別・物理保持できるソニーα独自の革新的なハイブリッド・コンボスロット機構です。","specs":[{"label":"接点構造","value":"21ピン 金めっきりん青銅スプリングワイパー接点アレイ"},{"label":"ロック機構","value":"ステンレス製ハートカム プッシュ・プッシュ着脱ラッチ ＋ 戻しばね"},{"label":"互換方式","value":"Sony α独自 CFexpress Type A / SD UHS-II 兼用コンボスロット"},{"label":"機械寿命","value":"10,000回以上の着脱サイクル保証"}],"diagramType":"cfe_slot_contact_wiper_interface"},{"id":"cfe-pcie-refclk-diff-term","order":65,"swatchColor":"#facc15","groupKey":"カメラとカードの鼓動をピタリ合わせる基準線_C65_100_MH","assembledPos":[6.4,-20.2,0.62],"explodeOffset":[66,-66,36],"integratedExplodeOffset":[66,-66,36],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C65. 100 MHz HCSL PCIe基準クロック差動線路 ＆ 50 Ω精密終端抵抗ネットワーク","subtitle":"100 MHz HCSL PCIe Reference Clock Differential Pair & 50-Ohm Precision Termination Network","category":"カメラとカードの鼓動をピタリ合わせる基準線 C65 — 100 MHzの極低ジッタ基準クロックを反射ゼロで受け取る終端回路","plainAnalogy":"カメラ（BIONZ XR）とCFexpressカードが毎秒160億回もの超高速データ転送を息ピッタリで行うには、共通の「100 MHzメトロノーム信号（REFCLK）」が欠かせません。この専用差動ペア線と0.1%精度の49.9 Ω終端抵抗が、信号の跳ね返り（反射）を完全に吸収し、クロックの揺らぎをピコ秒未満に保ちます！","summary":"エッジコネクタ（ピン16/17）からPCIe Gen4コントローラのPLLクロック入力へ供給される100 MHz HCSL差動リファレンスクロック（REFCLK+ / REFCLK−）の等長伝送線路、49.9 Ω精密終端抵抗対、およびAC結合コンデンサ群。","opticsAndPhysics":["PCIe Gen4（16 GT/s）仕様では100 MHz基準クロックのRMSジッタ上限が 0.5 ps（500フェムト秒）以下と極めて厳格であり、特性インピーダンス 85 Ω/100 Ω 整合と精密終端抵抗による反射吸収が通信エラー防止の要となります。","両側のグラウンドガードトレースとステッチングビアでクロック差動対を完全包囲し、隣接する3.3 V大電流電源線やNANDデータ線からのクロストークを遮断します。"],"formula":{"expression":"f_REFCLK = 100.000 MHz (HCSL差動) ／ 許容ジッタ < 0.5 ps RMS（PCIe Gen4 16 GT/s規格）","description":"2兆分の1秒以下の狂いしか許されない超精密基準クロック配線を、50 Ω終端で完璧に受け止める"},"nextGenInnovation":"省電力モード（L1.2サブステート）時にはCLKREQ#信号でカメラ側100 MHzクロック供給を自動一時停止させ、待機消費電力と発熱を劇的に削減します。","specs":[{"label":"クロック規格","value":"PCIe Gen4 100 MHz 差動HCSL（SSCG拡散スペクトラム対応）"},{"label":"終端ネットワーク","value":"49.9 Ω ±0.1% 薄膜精密終端抵抗 ×2 ＋ 0201 AC結合MLCC ×2"},{"label":"許容ジッタ","value":"< 0.5 ps RMS（PCI-SIG PCIe 4.0 CEM仕様準拠）"},{"label":"シールド構造","value":"両側GNDガードライン ＋ 接地ステッチングビア遮蔽"}],"diagramType":"cfe_pcie_refclk_diff_term"},{"id":"cfe-vcore-ldo-buck-rails","order":66,"swatchColor":"#ea580c","groupKey":"電圧を3種類へ精密仕分けする静音フィルタ_C66_コントローラ頭","assembledPos":[11.6,-4.4,-0.82],"explodeOffset":[78,-8,-42],"integratedExplodeOffset":[78,-8,-42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C66. マルチレール Point-of-Load 同期降圧電源フィルタバンク（0.85 V / 1.2 V / 1.8 V）","subtitle":"Multi-Rail Core 0.85V / NAND 1.8V / VCCQ 1.2V Point-of-Load Synchronous Buck Filter Bank","category":"電圧を3種類へ精密仕分けする静音フィルタ C66 — コントローラ頭脳・メモリ・NANDそれぞれへ最適な超クリーン電圧を分配！","plainAnalogy":"カードへ届く3.3 Vの電気は、PMIC（C17）で「頭脳コア用の0.85 V」「高速I/O用の1.2 V」「3D NAND用の1.8 V」の3種類へ変換されます。でも変換した直後の電気には細かい波（リプル）が残っているため、この超小型セラミックコンデンサ＆フェライトビーズのπ型フィルタ群で鏡のように滑らかに整えてから各チップへ届けます！","summary":"オンカードPMIC（C17）の各同期降圧出力（VCORE 0.85 V / VCCQ 1.2 V / VIO 1.8 V）の直近に配置される、多系統Point-of-Load（PoL）低ESLセラミックMLCC・高周波フェライトビーズ・厚銅アイランドによる電源フィルタバンク。","opticsAndPhysics":["7 nm / 12 nm微細プロセスのコントローラコアはわずか 0.85 V で動作するため、負荷急変時（アイドル→1,800 MB/s連続書込の遷移）の過渡電圧ドロップ（±30 mV以内）を抑えるため、極低ESL（等価直列インダクタンス）の0201/0402 MLCCを複数並列に配置しています。","1.2 V Toggle 5.0 NAND I/OレールとアナログSerDes PHYレールを高周波フェライトビーズで分離し、NANDの同時スイッチング雑音がPCIe Gen4信号へ混入するのを防ぎます。"],"formula":{"expression":"3.3 V入力 → PoL独立3レール（VCORE 0.85 V / VCCQ 1.2 V / VIO 1.8 V・リプル < 15 mVpp）","description":"3種類の超低電圧電源を互いに干渉させず鏡のように安定化することで、極限の高速書込を支える"},"nextGenInnovation":"微細化が進む最新コントローラ世代ほど低電圧・高電流化するため、ミリ単位の基板空間へ多段PoLフィルタを凝縮するPDN設計が信頼性の鍵を握ります。","specs":[{"label":"生成電源レール","value":"VCORE (0.85 V) / NAND VCCQ (1.2 V) / 周辺VIO (1.8 V)"},{"label":"フィルタ構成","value":"0201/0402 低ESL X5R/X7R MLCC群 ＋ 高周波フェライトπフィルタ"},{"label":"電源リプル","value":"< 15 mVpp（フルロード1,800 MB/s転送時）"},{"label":"銅箔配線","value":"低抵抗 2 oz 厚銅ローカル電源アイランド直結"}],"diagramType":"cfe_vcore_ldo_buck_rails"},{"id":"cfe-nand-ce-rb-mux","order":67,"swatchColor":"#0ea5e9","groupKey":"16枚の記憶チップを隙間なく回す交通管制官_C67_書込み待ちの","assembledPos":[8.2,3.8,0.72],"explodeOffset":[74,24,34],"integratedExplodeOffset":[74,24,34],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C67. 16ダイ並列 チップイネーブル（CE#）＆ Ready/Busy（R/B#）インターリーブ調停マトリクス","subtitle":"16-Die Chip-Enable (CE#) & Ready/Busy (R/B#) Parallel Interleave Arbiter Matrix","category":"16枚の記憶チップを隙間なく回す交通管制官 C67 — 書込み待ちの時間をゼロにする16並列バトンリレー制御！","plainAnalogy":"NANDメモリ1枚あたりの書き込みには約0.5ミリ秒の「処理中（Busy）」時間がかかります。そのまま待つと8K動画が詰まってしまうため、この交通管制マトリクスが表裏16枚のNANDダイの状態（Ready/Busy）を瞬時に監視し、手が空いたダイへ次々とデータを流し込むことで1秒1,700 MBの爆速持続書込を実現します！","summary":"16ダイ積層3D NAND（16DP：C12/C13/C50）それぞれのチップ選択信号（CE0#〜CE15#）と処理状態信号（R/B#）をリアルタイム監視し、マルチプレーン＆ダイ・インターリーブ書込みをスケジュールする並列調停マトリクス配線およびオンダイ調停回路。","opticsAndPhysics":["ダイ0がプログラム動作（tPROG ≈ 400〜600 μs）に入った瞬間にCE#を切り替えてダイ1〜ダイ15へ連続データ転送を行う「ダイ・インターリーブ」により、NAND固有の書込みレイテンシを完全に隠蔽します。","R/B#オープンドレイン監視線の高速プルアップとピーク電流分散スケジューリング（同時書込ダイ数の動的制御）により、3.3 V電源の瞬間大電流スパイクによる電圧降下も抑え込みます。"],"formula":{"expression":"実効持続書込帯域 = (16ダイ並列 × マルチプレーン) / t_PROG ≥ 1,700 MB/s（VPG800余裕クリア！）","description":"16枚の記憶チップをバトンリレー式に休まず稼働させることで、待ち時間ゼロのシネマ連続収録を達成する"},"nextGenInnovation":"VPG800（最低800 MB/s連続書込保証）をあらゆる空き容量・発熱条件下で達成するための、コントローラ並列スケジューリングの中核です。","specs":[{"label":"管理ダイ数","value":"最大 16ダイ独立制御（CE0#〜CE15# ＋ R/B# 並列監視）"},{"label":"並列最適化","value":"ダイ・インターリーブ ＋ 4プレーン同時プログラム制御"},{"label":"電源平準化","value":"ピーク書込電流の時間分散（スタッガード・プログラム制御）"},{"label":"性能貢献","value":"書込み待ち時間 tPROG の完全隠蔽とVPG800安定維持"}],"diagramType":"cfe_nand_ce_rb_mux"},{"id":"cfe-thermal-paste-underfill","order":68,"swatchColor":"#f472b6","groupKey":"基板裏の純銅コインとステンレス板をつなぐ熱の架け橋_C68_ミク","assembledPos":[-6.2,-9,-1.62],"explodeOffset":[-48,-28,-58],"integratedExplodeOffset":[-48,-28,-58],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C68. 裏面アルミナ微粒子充填 導電エラストマー・サーマルギャップフィラー層","subtitle":"Controller-to-Backplate Conductive Elastomer Thermal Gap Filler & Alumina Micro-Sphere Layer","category":"基板裏の純銅コインとステンレス板をつなぐ熱の架け橋 C68 — ミクロの空気のすき間を埋めて背面からも一気に放熱！","plainAnalogy":"コントローラ直下の基板を貫通した純銅サーマルコイン（C63）の熱を、裏面のステンレス放熱板（C02）へ確実に受け渡すための「やわらかい熱伝導クッション」です！アルミナ（酸化アルミニウム）の極小セラミック球をびっしり練り込んだ特殊シリコーンが、ミクロの空気の隙間を完璧に埋めて背面放熱を最大化します。","summary":"基板埋込純銅サーマルコイン（C63）の裏面とステンレス放熱バックプレート（C02）間の微小クリアランス（約 0.15〜0.25 mm）を低熱抵抗で密着架橋する、高充填アルミナ微粒子シリコーン・サーマルギャップフィラー層。","opticsAndPhysics":["空気の熱伝導率はわずか 0.026 W/m·K しかなく、0.1 mmの隙間があるだけで裏面放熱ルートが機能しなくなります。高熱伝導（6〜8 W/m·K）の柔軟ギャップフィラーで密着充填することで界面熱抵抗を劇的に低減します。","高い柔軟性（低ショア硬度）により、TOUGH規格の150 N曲げ荷重や7.5 m落下衝撃が加わった際にも背面金属板からの衝撃応力を吸収し、コントローラBGAはんだ部への直接伝達を防ぎます。"],"formula":{"expression":"R_TIM = t / (k_TIM · A)   （k_TIM ≈ 7 W/m·K ≒ 空気の約270倍の熱伝導で背面放熱を開通！）","description":"空気の約270倍熱を通すやわらかいセラミック微粒子クッションが、放熱と耐衝撃緩衝を同時に叶える"},"nextGenInnovation":"表面（C25/C26）と裏面（C63/C68）の両面サンドイッチ放熱構造を完成させ、極小CFexpress Type Aカードの熱容量限界を押し広げます。","specs":[{"label":"材料組成","value":"高充填アルミナ（Al₂O₃）セラミック微粒子 ＋ 柔軟シリコーンマトリクス"},{"label":"熱伝導率","value":"約 6.0 〜 8.0 W/m·K（空気層比 約270倍）"},{"label":"配置位置","value":"裏面純銅サーマルコイン（C63）⇔ SUS放熱バックプレート（C02）間"},{"label":"副次効果","value":"落下・曲げ荷重に対する衝撃緩衝クッション＆絶縁保護"}],"diagramType":"cfe_thermal_paste_underfill"},{"id":"cfe-card-detect-pullup-ins","order":69,"swatchColor":"#22c55e","groupKey":"奥までカチッと入った_を確認する安全ゲート_C69_半挿しでのデ","assembledPos":[1.5,-20.8,0.72],"explodeOffset":[16,-74,42],"integratedExplodeOffset":[16,-74,42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C69. ホットプラグ挿入検出（INS# ピン12）デバウンスRC回路 ＆ パワーグッド監視IC","subtitle":"Hot-Plug Card-Detect (INS# Pin 12) Debounce RC Network & Power-Good Sequencing Supervisor","category":"「奥までカチッと入った！」を確認する安全ゲート C69 — 半挿しでのデータ破損や電源ショートを完全防止する見張り番","plainAnalogy":"CFexpressの21本の金端子のうち、真ん中の12番ピン（INS#）だけ少し奥に引っ込んでいます。カードが奥までしっかり刺さって12番ピンが触れた瞬間、このデバウンス回路が「チャタリング（微細な接触ブレ）」を除去し、パワーグッド監視ICが「よし完全装着！3.3 V電源を滑らかにONせよ！」と安全ゴーサインを出します！","summary":"奥まった最短ピンである挿入検出端子（INS# Pin 12）の接触バウンスを除去するRCデバウンス回路と、3.3 V主電源の安定確立（Power-Good）およびPCIe PERST#リセット解除を厳密に順序制御するSOT-353スーパーバイザIC。","opticsAndPhysics":["カードの活線挿抜（ホットプラグ）時にピンが微細に跳ねるチャタリング現象（数ms）をRC時定数フィルタで除去し、誤った電源断続やNAND書込途中の半端な起動を防ぎます。","3.3 V供給電圧が規定しきい値（約 2.95 V）を下回った瞬間には、パワーグッド監視ICがマイクロ秒単位で警告割り込みを発行し、PLPタンタルコンデンサ（C19）による緊急データ退避シーケンスを即座に起動させます。"],"formula":{"expression":"GND/3.3V先行接触 → INS#最後接触 → RCデバウンス（τ ≈ 1 ms） → 電源PG確立 → PERST#解除","description":"厳密な電源シーケンス制御が、撮影現場でのスピーディなカード交換でもデータ破損ゼロを保証する"},"nextGenInnovation":"PLPホールドアップ回路（C19）と直結連携することで、万一録画中に誤ってスロット蓋を開けても直前までの映像ファイルを安全にクローズ保護します。","specs":[{"label":"検出対象","value":"ピン12 INS#（最短ラストメイク挿入検出端子）"},{"label":"監視IC","value":"超小型SOT-353 電源電圧スーパーバイザ（精度 ±1.0%）"},{"label":"デバウンス回路","value":"100 kΩプルアップ抵抗 ＋ C0G RCデバウンスフィルタ"},{"label":"保護連携","value":"eFuse（C40）ソフトスタート許可 ＆ PLP緊急退避トリガ連動"}],"diagramType":"cfe_card_detect_pullup_ins"},{"id":"cfe-raid-xor-parity-engine","order":70,"swatchColor":"#8b5cf6","groupKey":"1チップ丸ごと故障しても8K映像を復元する_カード内RAID_C","assembledPos":[-9.6,-6.2,1.32],"explodeOffset":[-82,4,54],"integratedExplodeOffset":[-82,4,54],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C70. オンダイ NANDダイ間 XOR RAIDパリティ保護 ＆ 予備ブロック自動復旧エンジン","subtitle":"On-Die Internal NAND Die-Level XOR RAID Parity & Bad-Block Spare-Pool Recovery Engine","category":"1チップ丸ごと故障しても8K映像を復元する「カード内RAID」C70 — 企業サーバー級のパリティ保護を親指サイズに凝縮！","plainAnalogy":"大切な結婚式の瞬間や8K映画のワンテイクを記録中、もし16枚あるNANDチップの1ブロックが突然寿命で壊れたら大変です！そこでプロ用CFexpressコントローラは、複数のNANDダイにまたがって「足し算パリティ（XOR RAID）」を自動生成し、万一1つのダイやページが読めなくなっても残りのデータから元の8Kフレームを100%無傷で計算復元するんです！","summary":"コントローラSoC内部に実装されたハードウェアXORパリティ演算エンジン（ダイ間RAID-5相当のRAIN：Redundant Array of Independent NAND）および、工場・運用時の不良ブロックを即座に差し替えるオーバープロビジョニング予備ブロック管理プール。","opticsAndPhysics":["通常の4K LDPC誤り訂正（C10）で訂正しきれないページ単位・ワード線ショート・ダイ単位の壊滅的エラーが発生しても、他ダイ群のデータとXORパリティストライプを排他的論理和演算（D_lost = P_XOR ⊕ D₁ ⊕ D₂ …）することで、ビット誤りゼロで瞬時に完全復旧します。","全容量の数%〜十数%を隠し予備領域（オーバープロビジョニング）として常時確保し、劣化兆候のあるブロックを裏側でシームレスに新ブロックへ代替マッピングします。"],"formula":{"expression":"P_XOR = D₀ ⊕ D₁ ⊕ D₂ ⊕ … ⊕ Dₙ   （任意の1ダイ故障時も残余データとXOR演算で100%復元！）","description":"LDPC誤り訂正すら超える最終防衛網「オンカードRAIN/XOR RAID」が、絶対に失敗できないプロの収録を守り抜く"},"nextGenInnovation":"エンタープライズデータセンター用NVMe SSDのRAIN（Redundant Array of Independent NAND）信頼性アーキテクチャを、20×28 mm極小シネマカードへ統合した最高峰のデータ保護技術です。","specs":[{"label":"保護方式","value":"ハードウェア高速XOR演算 ダイ／プレーン横断型 RAIN（RAID-5相当）"},{"label":"救済範囲","value":"LDPC訂正限界超えのページ破損・ワード線断線・単一ダイ障害"},{"label":"予備領域","value":"ダイナミック・バッドブロック自動代替＆オーバープロビジョニングプール"},{"label":"信頼性指標","value":"UBER（訂正不能ビット誤り率）< 10⁻¹⁷ プロシネマ基準達成"}],"diagramType":"cfe_raid_xor_parity_engine"},{"id":"cfe-hard-gold-ni-barrier","order":71,"swatchColor":"#facc15","groupKey":"金端子の_見えない3層サンドイッチ_C71_1万回こすっても削れ","assembledPos":[-4.5,-24.4,0.05],"explodeOffset":[-26,-92,42],"integratedExplodeOffset":[-26,-92,42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C71. コバルト硬化金メッキ＋ニッケル拡散防止下地層（30 μin Au / 150 μin Ni 断面構造）","subtitle":"30 μin Cobalt-Hardened Gold Plating & 150 μin Nickel Diffusion Barrier Cross-Section","category":"金端子の「見えない3層サンドイッチ」C71 — 1万回こすっても削れず、銅のサビが上がってこない秘密の壁","plainAnalogy":"純粋な金（24金）はじつは爪で傷がつくほど柔らかいんです。もし銅の端子にそのまま純金を塗ると、すぐ削れるうえに下の銅原子がジワジワしみ出して黒くサビてしまいます！そこで間に「ニッケルの防波堤」を挟み、さらに表面にコバルトをわずかに混ぜて硬く鍛えた「コバルト硬質金」を着せることで、1万回抜き差ししてもピッカピカを保つんです！","summary":"CFexpressの21ピンエッジ端子（C05）を顕微鏡レベルで断面解剖した3層金属皮膜構造。銅箔下地の上に約3.8 μm（150 μin）の電解ニッケル拡散バリア層を挟み、最表面に約0.76 μm（30 μin）のコバルト硬化硬質金メッキと極薄封孔処理（ポアシーラー）を積層しています。","opticsAndPhysics":["ニッケル下地層は「銅と金の相互拡散（カーケンダル効果）」を完全に遮断する防壁であり、高温環境（72℃連続録画）でも端子表面への酸化銅析出・接触抵抗上昇を防ぎます。","金メッキに約0.2〜0.3%のコバルトを共析させることで、ビッカース／ヌープ硬度を軟質金の約2倍（130〜200 HK）へ引き上げ、カメラ側りん青銅バネ（C64）による10,000回以上の摺動摩耗に耐えます。","表面の目に見えない微細ピンホール（ナノ孔）を極薄の有機ポアシーラーで塞ぐことで、海辺の潮風や指の汗による腐食をシャットアウトします。"],"formula":{"expression":"Cu銅箔 → Ni防壁 3.8 μm (150 μin) → Co硬化Au 0.76 μm (30 μin)（硬度 130〜200 HK）","description":"3層の金属をミクロン単位で精密積層することで、低抵抗・耐腐食・1万回摩耗耐久を同時に達成"},"nextGenInnovation":"CFexpress 4.0（16 GT/s）では表皮深さが約0.7 μmまで浅くなるため、ニッケル厚と金厚のバランスを高周波損失（スキンスキン効果）まで考慮して最適化しています。","specs":[{"label":"最表面メッキ","value":"コバルト硬化硬質金 0.76 μm（30 μin・硬度 130〜200 HK）"},{"label":"中間拡散防壁","value":"低応力電解ニッケル 3.0〜5.0 μm（銅原子のしみ出し遮断）"},{"label":"防食処理","value":"ナノピンホール封孔処理（耐塩害・耐汗・耐硫化ガス）"},{"label":"接触抵抗","value":"< 30 mΩ（10,000回挿抜試験後も安定導通）"}],"diagramType":"cfe_hard_gold_ni_barrier"},{"id":"cfe-ac-cap-antipad-void","order":72,"swatchColor":"#06b6d4","groupKey":"160億Hzの波を跳ね返らせない_床の抜き穴_C72_コンデンサ","assembledPos":[-2,-18.5,0.24],"explodeOffset":[-64,-92,18],"integratedExplodeOffset":[-64,-92,18],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C72. ACカップリング直下 基準GND「アンチパッド抜き穴（リファレンス・ボイド）」構造","subtitle":"PCIe Gen4/5 AC-Coupling Capacitor Reference-Plane Anti-Pad Void Cutout (2-Layer Deep)","category":"160億Hzの波を跳ね返らせない「床の抜き穴」C72 — コンデンサの真下だけ銅ベタをくり抜いて電気の段差を消すプロ技","plainAnalogy":"高速道路（幅の細い85 Ω配線）の途中に、急に幅の広い駐車場（コンデンサのハンダパッド）があると、毎秒160億回の電気の波がドーンとぶつかって跳ね返ってしまいます！そこでエンジニアは、そのパッドの真下にある2層目の銅板に「長方形の抜き穴（アンチパッド）」をわざと彫り込み、電気のたまりすぎを打ち消して滑らかな高速道路へ戻しているんです！","summary":"PCIe Gen4差動レーン上の0201 ACカップリングコンデンサ（C20）のハンダパッド直下において、内層L2・L3の基準グラウンド銅箔を精密に長方形くり抜き（リファレンス・ボイド）する高周波インピーダンス補償構造です。","opticsAndPhysics":["0201コンデンサの実装パッドは微細な差動配線幅（約75〜90 μm）より数倍広いため、直下のGND層との間に余分な寄生容量（C_pad）が生じ、局所インピーダンスが85 Ωから約55〜65 Ωへ急落して強い信号反射（リターンロス悪化）を引き起こします。","TIやPCI-SIGの最新Gen4/Gen5設計ガイドラインに基づき、パッド直下のL2（および必要に応じてL3）グラウンド層に精密寸法のアンチパッド抜き穴を設けることで、対地容量を削減し、TDR（時間領域反射測定）波形を85 Ω±5%のフラット直線へ整えます。","プラス側とマイナス側の抜き穴を完全対称に設計し、周囲をリターン電流バイパスビアで囲むことで、モード変換ノイズ（Scd21）の発生も最小化しています。"],"formula":{"expression":"Z₀ = √(L / C)   （パッド直下のGND抜き穴で余剰Cを削減 → 局所インピーダンスを 85 Ω へピタリ復帰！）","description":"あえて内層の銅箔に窓を開ける逆転の発想で、16 GT/sの超高速信号の跳ね返りを根絶する基板マジック"},"nextGenInnovation":"2025〜2026年のPCIe Gen4/5高密度基板では、0201からさらに極小な01005コンデンサ＋3D電磁界シミュレータ最適化楕円ボイド形状の導入が標準化しています。","specs":[{"label":"ボイド対象","value":"PCIe Gen4 TX/RX ACカップリング0201パッド直下（L2〜L3層）"},{"label":"補償効果","value":"インピーダンス段差（60 Ω落ち込み）を 85 Ω±5% へ平坦化"},{"label":"高周波改善","value":"8 GHz帯リターンロス（Sdd11）約 6〜10 dB 改善"},{"label":"設計基準","value":"PCI-SIG PCIe 4.0/5.0 SI設計ガイドライン準拠"}],"diagramType":"cfe_ac_cap_antipad_void"},{"id":"cfe-glass-weave-rotated","order":73,"swatchColor":"#10b981","groupKey":"基板の_織り目_によるズレを防ぐ斜め走り_C73_ガラス繊維と樹","assembledPos":[-3,-14,-0.18],"explodeOffset":[-102,-56,-24],"integratedExplodeOffset":[-102,-56,-24],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C73. 低誘電スプレッドEガラス繊維クロス＆10°斜めルーティング（グラスウィーブ対策）","subtitle":"Spread-Glass 1067/1080 Low-Dk Core & 10° Diagonal Routing for Glass-Weave Skew Mitigation","category":"基板の「織り目」によるズレを防ぐ斜め走り C73 — ガラス繊維と樹脂の速度差を10度の斜め配線で均等化！","plainAnalogy":"プリント基板の中身は、ガラスの糸を縦横に編んだ「布（ガラスクロス）」を樹脂で固めた板です。ところが電気はガラス糸の上だと遅く、樹脂のすき間だと速く進むクセがあります！もし2本ペアの高速配線が布目に真っすぐ沿うと、片方だけ遅刻してデータが壊れるため、高級な平織りガラス布を使ったうえで配線をわざと「10度斜め」にジグザグ走らせ、2本を同時ゴールさせているんです！","summary":"8層HDI基板（C07）の絶縁コアを構成する低誘電・低損失スプレッドEガラス繊維クロス（1067 / 1080平織り＋低Dk樹脂）と、繊維の織り目に対して約10°傾けて配線するグラスウィーブ・スキュー（繊維目ズレ）対策構造です。","opticsAndPhysics":["通常のEガラス繊維は比誘電率 Dk ≈ 6.0、周囲のエポキシ樹脂は Dk ≈ 3.0 と約2倍も差があるため、PCIe Gen4（1ビットわずか62.5ピコ秒）では数センチ走るだけで差動ペアのP線とN線に深刻な到着時間差（Intra-Pair Skew）が生まれます。","ガラス糸の束を平たく押し広げた「開繊（スプレッド）ガラスクロス（1067等）」と低損失樹脂（Megtron系等）を採用し、さらに差動配線を織り目に対し約10°傾斜ジグザグ配置することで、P線・N線双方が通過するガラスと樹脂の比率を100%均等化します。","結果として高周波の位相ズレによる差動→コモンモード変換（EMI放射増加）とアイパターンの閉塞を根本から防ぎます。"],"formula":{"expression":"伝搬速度 v = c / √Dk   （ガラス Dk≈6 vs 樹脂 Dk≈3 → 開繊クロス＋10°斜め配線でペア間ズレ Δt < 1 ps！）","description":"顕微鏡でしか見えない基板の「布の織り目」まで計算し尽くす、16 GT/s時代の超精密物理設計"},"nextGenInnovation":"2025〜2026年の次世代PCIe Gen4/5カード向け超薄基板では、開繊ガラスをさらに進化させた低Dkガラス（NEガラス／Lガラス）や非織布系極低損失プリプレグが普及しています。","specs":[{"label":"ガラスクロス","value":"開繊（フラットスプレッド）1067 / 1080 低Dkガラス布"},{"label":"配線角度対策","value":"ガラス繊維軸に対し約 10° 斜めジグザグルーティング"},{"label":"誘電正接 Df","value":"超低損失材 Df ≈ 0.002〜0.005（8 GHz帯の減衰を最小化）"},{"label":"スキュー抑制","value":"差動ペア内スキュー < 1.0 ps（16 GT/sアイ開口維持）"}],"diagramType":"cfe_glass_weave_rotated"},{"id":"cfe-perimeter-via-fence","order":74,"swatchColor":"#eab308","groupKey":"基板のフチをぐるりと囲む黄金の電波柵_C74_8層のスキマから逃","assembledPos":[0,0.6,0],"explodeOffset":[106,-54,16],"integratedExplodeOffset":[106,-54,16],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C74. 基板外周 1/20波長「GNDステッチング・ビアフェンス（電波の柵）」＆ティアドロップ補強","subtitle":"Perimeter λ/20 Electromagnetic Picket-Fence Stitching Vias & Mechanical Teardrop Pad Fillets","category":"基板のフチをぐるりと囲む黄金の電波柵 C74 — 8層のスキマから逃げる高周波ノイズを細かな銅の柱で完全包囲！","plainAnalogy":"8層基板の側面（フチ）はサンドイッチのように層と層の間が開いているので、そのままでは160億Hzのノイズが横からピッと漏れ出してしまいます！そこで基板のフチ全体へ、電波の波長の20分の1よりも細かい間隔でズラリと金色の縦穴（ビア）を打って「電波の柵（ビアフェンス）」を作り、さらに配線と穴のつなぎ目を涙型（ティアドロップ）に太らせて折れにくくしているんです！","summary":"8層HDI基板の全周エッジおよびPCIe差動対の両脇を約0.8〜1.0 mm間隔で貫通連結するグラウンド・ステッチング・ビアフェンス（マイクロ波キャビティ遮蔽柵）と、配線接続部の機械的応力を逃がすティアドロップ（涙滴状）銅箔補強構造です。","opticsAndPhysics":["基板内部の平行な電源層とGND層は「平行平板導波管」として振る舞い、カード側面からGHz帯の不要電磁波（EMI）を放射します。波長λの1/20以下（16 GHz高調波で約0.9 mm以下）の間隔で外周をGNDビアで縫い合わせることで、側面放射を劇的に封じ込めます。","すべての微細ビアと銅配線の付け根を滑らかな涙滴状（ティアドロップ）に広げた形状にすることで、TOUGH 150 N曲げ試験や−12℃⇔+72℃の熱膨張収縮サイクルでも、極細配線がビアの付け根から断線（クラック）する事故を徹底防止します。","外周の露出金リングはシェル導通スプリングクリップ（C35）の確実な受け座としても機能します。"],"formula":{"expression":"ビア間隔 p ≤ λ_eff / 20 ≈ 0.9 mm（16 GHz高調波封じ込め）＋ ティアドロップ応力集中緩和","description":"基板そのものの内部に「見えない金属の檻」と「断線しない付け根」を同時構築するプロ基板設計"},"nextGenInnovation":"CFexpress 4.0ではカメラ内蔵のWi-Fi 6E（6 GHz帯）やGNSS（1.5 GHz帯）のすぐ隣でPCIe Gen4が動くため、外周ビアフェンスによる徹底したエッジ遮蔽が必須条件となっています。","specs":[{"label":"ビアピッチ","value":"外周 0.8〜1.0 mm 間隔（λ/20 電磁遮蔽ルール準拠）"},{"label":"遮蔽効果","value":"基板エッジからの高周波共振・平行平板放射を 15〜25 dB 抑制"},{"label":"機械補強","value":"全マイクロビア接合部にティアドロップ（涙滴）銅箔フィレット"},{"label":"耐久寄与","value":"TOUGH 150 N 曲げ＆熱衝撃サイクルでの配線破断ゼロ化"}],"diagramType":"cfe_perimeter_via_fence"},{"id":"cfe-die-backside-dbs-film","order":75,"swatchColor":"#d97706","groupKey":"髪の毛より薄いチップを割らずに16枚積む秘密_C75_サランラッ","assembledPos":[0,12.6,0.92],"explodeOffset":[-114,58,-18],"integratedExplodeOffset":[-114,58,-18],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C75. 30 μm極薄NANDダイ裏面「DBS反り防止補強フィルム」＆ステルスダイシング保護縁","subtitle":"25–30 μm Ultra-Thin NAND Die Backside Support (DBS) Film & Stealth-Dicing Stress-Relief Edge","category":"髪の毛より薄いチップを割らずに16枚積む秘密 C75 — サランラップ級の薄さに削ったシリコンの裏に貼る魔法の背骨シート","plainAnalogy":"薄さわずか2.8 mmの切手サイズカードに2テラバイトもの容量を詰め込むため、中の3D NANDシリコンチップは1枚たった0.03ミリ（髪の毛の半分以下！）まで削り薄められます。そのままではポテトチップスみたいに丸まってすぐパリンと割れてしまうので、チップの裏側へ特殊な補強フィルムを貼り、さらに切断面をレーザーで傷ゼロに切る（ステルスダイシング）ことで16段積み上げても割れない強さを生むんです！","summary":"16ダイ積層パッケージ（16DP：C50）を実現するため、25〜30 μmまで超薄化研磨（DBG：Dicing Before Grinding）された各3D NANDシリコンダイの裏面へ密着ラミネートされる反り防止補強フィルム（DBS / DAF複合層）およびレーザー・ステルスダイシング無欠陥エッジ構造です。","opticsAndPhysics":["従来の回転ダイヤモンドブレード切断ではダイ外周に数μmの微細な欠け（マイクロチッピング）が残り、7.5 m落下や150 N曲げ時の破壊起点になります。ウェハ内部へレーザー焦点を結ぶ「ステルスダイシング（SDBG）」により、表面チッピングゼロの極めて高い抗折強度を実現します。","シリコンと熱膨張係数が整合した極薄ポリイミド／シリカ充填補強フィルム（約5〜10 μm）をダイ裏面へ密着させることで、30 μm厚ダイの反り（ワーページ）を平坦化し、16段オフセット積層時の位置ズレとクラックを防ぎます。","薄膜化により垂直方向の熱抵抗も下がるため、16層目の最上段ダイの熱もパッケージ基板側へスムーズに逃げやすくなります。"],"formula":{"expression":"ダイ厚 t_Si ≈ 25〜30 μm × 16段 ＋ DAF/DBS 10 μm × 16段 ≈ 合計 0.64 mm（極薄1.0 mm BGAに収容！）","description":"髪の毛の半分の薄さまで削ったシリコンを無傷で16階建てにする、日本発の世界最高峰ウェハ薄化・実装技術"},"nextGenInnovation":"2025〜2026年の2 TB〜4 TB超大容量CFexpress Type A実現に向け、20 μm級超極薄ダイ＋レーザーアニーリング応力緩和技術の量産導入が進んでいます。","specs":[{"label":"シリコンダイ厚","value":"約 25 〜 30 μm（DBG先ダイシング超薄化研磨プロセス）"},{"label":"切断工法","value":"レーザー・ステルスダイシング（チッピング欠け極小・高抗折強度）"},{"label":"裏面補強材","value":"低応力高熱伝導 DBS / DAF 複合ポリマーシート（5〜10 μm）"},{"label":"積層実績","value":"1パッケージ内に最大 16ダイ（16DP）を総厚約 1.0 mm で封止"}],"diagramType":"cfe_die_backside_dbs_film"},{"id":"cfe-enepig-wirebond-pad","order":76,"swatchColor":"#cbd5e1","groupKey":"極細金線もハンダも最強にくっつく白金メッキ_C76_ニッケルと金","assembledPos":[8.5,12.6,0.85],"explodeOffset":[-116,16,46],"integratedExplodeOffset":[-116,16,46],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C76. パッケージ基板 ENEPIG（無電解Ni-Pd-Au）3層表面処理＆ブラックパッド防止層","subtitle":"ENEPIG (Electroless Nickel / Electroless Palladium / Immersion Gold) Universal Pad Finish","category":"極細金線もハンダも最強にくっつく白金メッキ C76 — ニッケルと金の間に「パラジウム」を挟んで落下割れをゼロに！","plainAnalogy":"NANDチップと基板をつなぐ髪の毛より細い金ワイヤー（C51）やハンダボールは、着地するパッドの表面が少しでもモロいと落とした瞬間にプチッと剥がれてしまいます。従来の「ニッケル＋金（ENIG）」はまれにニッケルが腐食する「ブラックパッド」という弱点がありました。そこで間に貴金属の「パラジウム（Pd）」を薄く挟んだ3層構造（ENEPIG）にすることで、金ワイヤーもハンダも鉄壁の強度でくっつくんです！","summary":"3D NANDパッケージおよびコントローラ用ABF/BT基板（C49）のワイヤーボンディング端子・BGAランド双方へ施される、無電解ニッケル（Ni）／無電解パラジウム（Pd）／置換金（Au）の3層ユニバーサル表面処理（ENEPIG）です。","opticsAndPhysics":["従来のENIG（無電解Ni/置換Au）では、金メッキ液が下地ニッケルを過剰腐食して脆いリン濃化層（ブラックパッド）を作るリスクがありました。間に厚さ0.05〜0.15 μmの純パラジウム（Pd）層を挟むことでニッケル腐食を100%防ぎます。","パラジウム層が金ワイヤー（Au）および銅ワイヤー（PdコートCu）双方の超音波熱圧着で均一な金属間化合物を形成し、16段多段ワイヤーの接合信頼性を飛躍的に高めます。","BGAはんだ側でも脆い金属間化合物の過剰成長を抑えるため、Sony TOUGHの7.5 mコンクリート落下衝撃テストでも界面剥離ゼロを支えます。"],"formula":{"expression":"Cuパッド → Ni (3〜5 μm) → Pdパラジウム防壁 (0.08 μm) → Au (0.05 μm)（ブラックパッド発生率 0%）","description":"貴金属パラジウムの極薄中間層が、ワイヤーボンディングと鉛フリーBGAはんだの両方を最強強度へ引き上げる"},"nextGenInnovation":"2025〜2026年の高密度BGA（0.35〜0.4 mmピッチ）では、薄Pd＋還元金（EPIG / Thin-ENEPIG）によりさらなる高周波表皮損失低減とコスト最適化が進んでいます。","specs":[{"label":"表面処理規格","value":"IPC-4556 準拠 ENEPIG（無電解Ni / 無電解Pd / 置換Au）"},{"label":"パラジウム厚","value":"約 0.05 〜 0.15 μm（ニッケル腐食・ブラックパッド完全阻止）"},{"label":"両立対応","value":"Au / Pd-Cu ワイヤーボンディング ＆ SAC305 BGAリフロー両対応"},{"label":"信頼性効果","value":"落下衝撃・熱サイクル後のBGAクラック寿命を大幅に延長"}],"diagramType":"cfe_enepig_wirebond_pad"},{"id":"cfe-bga-solder-mask-dam","order":77,"swatchColor":"#22c55e","groupKey":"極小ハンダ粒どうしのショートを防ぐ緑の堤防_C77_わずか0_0","assembledPos":[-6.2,-9,0.52],"explodeOffset":[-112,-26,-52],"integratedExplodeOffset":[-112,-26,-52],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C77. 微細0.4 mmピッチBGA NSMD銅ランド＆はんだブリッジ防止ソルダーマスクダム","subtitle":"0.4 mm Fine-Pitch BGA Non-Solder-Mask-Defined (NSMD) Copper Pads & Solder-Mask Dam Grid","category":"極小ハンダ粒どうしのショートを防ぐ緑の堤防 C77 — わずか0.07 mmの緑の壁で数百個のハンダボールを完璧に仕切る！","plainAnalogy":"コントローラやNANDチップの裏には、ゴマ粒より小さなハンダボールが0.4ミリ間隔で何百個もびっしり並んでいます。工場の高温オーブンでハンダを溶かしたとき、隣同士がくっついてショートしたら即アウト！そこで銅の丸い島（NSMDパッド）の周りを、幅たった0.07ミリの緑色の堤防（ソルダーマスクダム）で1個ずつ囲み、溶けたハンダが丸くキレイに固まるように仕切っているんです！","summary":"0.4 mmファインピッチBGA実装部において、銅箔外径をエッチング精度で厳密規定するNSMD（Non-Solder-Mask-Defined）パッドと、隣接パッド間を幅60〜75 μmの絶縁樹脂壁で仕切るソルダーマスクダム（SMD堤防）構造です。","opticsAndPhysics":["NSMD構造ではソルダーレジスト開口径を銅ランドより一回り大きく取るため、溶融したSAC305ハンダが銅パッドの上面だけでなく側面（エッジ）までぐるりと包み込み、強固な「はんだフィレット」を形成して落下・熱疲労耐性を大幅に高めます。","パッドとパッドのわずかな隙間に残された幅60〜75 μmのソルダーマスクダム（緑の堤防）が、リフロー溶融時のハンダ流出・隣接ピン間のブリッジ短絡（ショート）を物理的に阻止します。","アンダーフィル樹脂（C28）を流し込む際の毛細管流路（ギャップ均一性）を整える役割も担っています。"],"formula":{"expression":"BGAピッチ 0.40 mm ＝ NSMD銅ランド φ0.22 mm ＋ 開口クリアランス ＋ ダム堤防幅 0.07 mm","description":"髪の毛1本ほどの極細の緑の堤防が、数百ピンが密集する高速BGAのショート不良と落下割れを同時に防ぐ"},"nextGenInnovation":"レーザー直接描画（LDI：Laser Direct Imaging）露光技術の進化により、位置ズレ±10 μm以下で極細ソルダーマスクダムを安定量産できるようになっています。","specs":[{"label":"パッド方式","value":"NSMD（非ソルダーマスク定義・側面包み込み高強度ランド）"},{"label":"ダム堤防幅","value":"60 〜 75 μm（LDIレーザー直接露光による高精度形成）"},{"label":"対応ピッチ","value":"0.40 mm 〜 0.50 mm 超高密度BGA（コントローラ・NAND）"},{"label":"品質効果","value":"リフローはんだブリッジ短絡ゼロ ＋ 落下疲労寿命向上"}],"diagramType":"cfe_bga_solder_mask_dam"},{"id":"cfe-macaroni-channel-core","order":78,"swatchColor":"#38bdf8","groupKey":"3D_NAND縦穴の中身は_マカロニ_だった_C78_中身を空洞","assembledPos":[-4,14.2,0.36],"explodeOffset":[-32,96,68],"integratedExplodeOffset":[-32,96,68],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C78. マカロニ型ポリシリコン中空チャネル＆中心SiO₂酸化膜フィラー（3D NAND縦穴の芯）","subtitle":"Macaroni-Body Ultra-Thin Hollow Poly-Si Vertical Channel & Central SiO₂ Core Filler","category":"3D NAND縦穴の中身は「マカロニ」だった！ C78 — 中身を空洞にして薄いストロー状にすることで電子が迷わず高速ダッシュ","plainAnalogy":"3D NANDの縦穴メモリ柱（C15）を輪切りにすると、なんとパスタの「マカロニ」みたいに真ん中がくり抜かれた極薄のシリコンの筒（厚さわずか数ナノメートル！）になっていて、芯にはガラス（酸化膜）が詰まっています！もし中までぎっしりシリコンを詰めると結晶の粒のスキマ（欠陥）が増えて電子が引っかかるため、わざと極薄ストロー（マカロニ）にして電気の流れをスーッと安定させているんです！","summary":"3D NANDメモリストリングの垂直チャネル孔（直径約70〜100 nm）内部に形成される「マカロニボディ構造」。厚さ約6〜10 nmの極薄ポリシリコン円筒チャネルと、その中心空洞を満たす高純度SiO₂（二酸化ケイ素）コアフィラーで構成されます。","opticsAndPhysics":["垂直孔内に成膜したポリシリコンは多結晶であり、結晶粒界（グレインバウンダリ）にトラップ欠陥が存在します。チャネルを中実円柱にすると粒界欠陥の総数が増えてランダムテレグラフノイズ（RTN）やしきい値電圧ばらつきが悪化します。","極薄の中空パイプ状（マカロニ構造）にして芯を絶縁性のSiO₂フィラーで埋めることで、空乏層幅がゲート電界で完全制御（完全空乏化）され、粒界トラップの影響を激減させながら300層以上の長いストリングでも高いオン電流（読出電流）を確保できます。","レーザーアニール等による結晶粒大径化プロセスと組み合わせ、読出速度と低温〜高温での特性安定性を高めています。"],"formula":{"expression":"中空マカロニ管厚 t_poly ≈ 6〜10 nm ＋ 中心SiO₂芯（完全空乏化によりRTNノイズとVthばらつきを激減！）","description":"日本の研究者（旧東芝・キオクシア等）が3D NANDを世界標準へ押し上げた象徴的ナノ構造「マカロニチャネル」"},"nextGenInnovation":"2025〜2026年の300〜400層世代では、極薄ポリシリコンの結晶粒をさらに大きく整える金属誘起結晶化や極薄単結晶化チャネル研究が加速しています。","specs":[{"label":"チャネル形状","value":"マカロニ型中空円筒ポリシリコン（膜厚 約 6〜10 nm）"},{"label":"中心フィラー","value":"高純度SiO₂（二酸化ケイ素）絶縁コア充填"},{"label":"電気的利点","value":"完全空乏化による粒界ノイズ（RTN）低減＆高いゲート制御性"},{"label":"適用世代","value":"BiCS8（218層）〜 BiCS10（332層）・Samsung V9/V10 全世代"}],"diagramType":"cfe_macaroni_channel_core"},{"id":"cfe-inter-deck-channel-joint","order":79,"swatchColor":"#f97316","groupKey":"300階超の超高層メモリを2_3段つなぐ_中継フロア_C79_縦","assembledPos":[0,15.2,1.18],"explodeOffset":[0,102,42],"integratedExplodeOffset":[0,102,42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C79. マルチデック（2〜3段）縦穴ジョイント＆IDB（Inter-Deck-Body）高速消去接合部","subtitle":"Dual/Triple-Deck String-Stacking Inter-Deck Channel Connector & P+ IDB Erase Structure","category":"300階超の超高層メモリを2〜3段つなぐ「中継フロア」C79 — 縦穴を段ごとに彫ってピタッとドッキングする神業接合","plainAnalogy":"300階建てを超える超高層3D NANDに、屋上から地下まで一気に1本の細いストロー穴を掘るのは物理的に無理（途中で細くなったり曲がったりします）！そこでまず1〜150階（下段デック）を掘って作り、次に151〜332階（上段デック）を上に重ねてナノメートル精度で「パチッ」とドッキング！さらに2025〜2026年の最新研究では、この継ぎ目にプラスの電気（正孔）を直接送り込むIDB消去リングを組み込んでデータ消去まで爆速化する技術が進んでいます！","summary":"218層〜400層超の超多層3D NANDで必須となるマルチデック（2段／3段ストリングスタッキング）の階層間チャネル接合プラグ（N+ポリシリコン・インターデックコネクタ）と、2025〜2026年次世代のP+ Inter-Deck-Body（IDB）正孔直接供給消去構造です。","opticsAndPhysics":["200層を超えると単一デックでのエッチング深さが10 μmを超え穴径テーパーが大きくなるため、下段デックと上段デック（300〜400層級では3段）に分けて加工し、継ぎ目のラッパ状N+チャネルコネクタで数nm以内の位置合わせ精度で電気接続します。","従来の3D NANDはストリングの上下端からGIDL電流で正孔（ホール）を供給して消去するため、積層数が増えるほど真ん中まで正孔が届きにくく消去が遅くなりました。","2025〜2026年に注目されるIDB構造はデック間の継ぎ目にP+シリコン正孔供給源を配置し、長大な300〜400層ストリングの中央からも瞬時に正孔を注入して消去速度を一定に保ちます。"],"formula":{"expression":"下段デック（〜166層）＋ N+ジョイント／P+ IDB継ぎ目 ＋ 上段デック（〜166層）＝ 332層超ストリング！","description":"超高層ビルを2〜3ブロックに分けて建て、ナノ精度で直結するマルチデック接合が2TB極小カードの容量を生む"},"nextGenInnovation":"SK hynix 321層はトリプル（3段）スタッキングを採用し、Kioxia/Sandisk BiCS10（332層）やSamsung V10（400層超）もデック接合最適化＋クライオエッチングでさらなる高層化を実現しています。","specs":[{"label":"積層方式","value":"デュアル（2段）／トリプル（3段）ストリングスタッキング"},{"label":"接合構造","value":"N+ポリシリコン・チャネルコネクタ ＋ 上下ダミー保護層"},{"label":"合わせ精度","value":"上下デック縦穴オーバーレイ誤差 < 5 nm 級超精密整列"},{"label":"次世代消去","value":"2025–2026 IDB（Inter-Deck-Body）中央正孔注入高速消去技術"}],"diagramType":"cfe_inter_deck_channel_joint"},{"id":"cfe-cryo-harc-etch-pillar","order":80,"swatchColor":"#06b6d4","groupKey":"氷点下70_で彫る_まっすぐな超深井戸_C80_幅80nm・深さ","assembledPos":[4.5,14.2,1.22],"explodeOffset":[34,96,68],"integratedExplodeOffset":[34,96,68],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C80. 極低温（−70℃）クライオ・プラズマ深穴エッチング構造（アスペクト比100:1超縦穴）","subtitle":"2025–2026 Cryogenic (-60°C to -70°C) High-Aspect-Ratio Contact (HARC >100:1) Etch Structure","category":"氷点下70℃で彫る「まっすぐな超深井戸」C80 — 幅80nm・深さ10μmの針の穴を一切曲げず一気に貫く2026年の大革命","plainAnalogy":"332〜400層もの3D NANDに縦穴を彫るのは、たとえるなら「直径10センチの細さで高さ10メートルの井戸を、1ミリも曲げずにズドンと垂直に掘る」ような途方もない難しさ！普通の温度だと途中で穴が曲がったり詰まったりしますが、2025〜2026年に実用化された「極低温クライオエッチング（−60℃〜−70℃）」は、ウェハをキンキンに冷やしながら特殊なフッ化水素プラズマを当て、従来より2〜3倍速くビシッと真っすぐな縦穴を彫り抜くんです！","summary":"Samsung V10（400層超）や次世代3D NAND量産で2025〜2026年に本格導入が進む、極低温（−60℃〜−70℃）クライオ・プラズマによる超高アスペクト比（HARC > 100:1、径70〜100 nm・深さ10 μm超）垂直チャネル孔構造です。","opticsAndPhysics":["従来の常温フッ素炭素系プラズマでは、深さが増すにつれて穴の奥へ反応ガスが届かず、壁面が樽状に膨らむ（ボーイング）や曲がり（ツイスティング）が発生して歩留まりが急落しました。","東京エレクトロン（TEL）やLam Researchが開発した−60〜−70℃クライオエッチングでは、極低温のシリコン表面にフッ化水素（HF）分子が均一吸着して超高速にエッチング反応が進み、エッチレート2〜3倍向上・CO₂ガス排出大幅削減・垂直プロファイル均一化を同時達成します。","縦穴の直径が最上層から最下層まで均一に揃うことで、全332〜400層のメモリセルの書込／消去特性がピタリと一致し、CFexpressカードの長寿命・低エラー率へ直結します。"],"formula":{"expression":"アスペクト比 AR = 深さ (>10,000 nm) / 直径 (80 nm) > 125:1  （−70℃クライオで垂直壁＆2〜3×高速加工！）","description":"マイナス70℃の極寒プラズマが、400層時代の「縦穴がまっすぐ掘れない壁」を突破した2026年の製造ブレイクスルー"},"nextGenInnovation":"2025〜2026年にSamsung V10（400層クラス）をはじめ世界の最先端NANDファブが順次クライオ・チャネルホールエッチングへ移行し、次世代大容量CFexpressの基盤となっています。","specs":[{"label":"ウェハ温度","value":"−60 ℃ 〜 −70 ℃ 極低温チャック冷却クライオエッチング"},{"label":"縦穴アスペクト比","value":"100:1 〜 125:1 超（幅 70〜100 nm × 深さ 10 μm 級）"},{"label":"形状精度","value":"ボーイング・テーパー・曲がり（Twisting）を極限抑制"},{"label":"環境＆生産性","value":"加工速度 2〜3 倍向上 ＋ 温室効果ガス排出を大幅削減"}],"diagramType":"cfe_cryo_harc_etch_pillar"},{"id":"cfe-barrierless-moly-wl","order":81,"swatchColor":"#94a3b8","groupKey":"タングステンを超える新金属ワード線_C81_じゃまな下地膜_Ti","assembledPos":[-6.2,14.5,1.15],"explodeOffset":[-68,94,34],"integratedExplodeOffset":[-68,94,34],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C81. 2026年次世代「バリアレス・モリブデン（Mo）ワード線」＆サブ30 nm Zピッチ積層","subtitle":"2026 Barrierless ALD Molybdenum (Mo) Wordline Metallization for Sub-30 nm Z-Pitch 3D NAND","category":"タングステンを超える新金属ワード線 C81 — じゃまな下地膜（TiN）を無くして薄型・超低抵抗を叶える銀青色の切り札！","plainAnalogy":"これまでの3D NANDの水平配線（ワード線）はタングステン（W）で作られていましたが、タングステンは製造中に周りのガラスを溶かすガスを使うため、内側に分厚い「保護のり（TiNバリア膜）」を塗る必要がありました。でも332〜400層になると、その保護のりの厚みすら邪魔！そこで2026年に大本命となったのが「モリブデン（Mo）」。保護のり無し（バリアレス）で直接びっしり詰められて電気抵抗も3〜4割下がるため、高層化と爆速読み書きを同時に叶えるんです！","summary":"300〜400層超・Zピッチ30 nm未満の2026年次世代3D NANDにおいて、従来のタングステン（W）＋窒化チタン（TiN）バリア膜を置き換える「バリアレス・モリブデン（Mo）原子層堆積（ALD）ワード線」構造です。","opticsAndPhysics":["従来のタングステン（WF₆ガス成膜）ではフッ素による絶縁膜腐食と密着不足を防ぐため、電気抵抗の高いTiNバリアライナーを上下両面へ敷く必要があり、ワード線が薄くなるほど高抵抗なTiNの割合が増えてRC遅延が激増していました。","2026年1月のimec信頼性実証およびSamsung V10 / SK hynix / Kioxiaの次世代ロードマップで導入が進むバリアレスMoは、高い熱安定性と低拡散性によりTiNバリアが不要となり、実効ワード線抵抗を約30〜40%削減します。","ワード線RC遅延の劇的短縮により、332〜400層という超多層でもページ読出時間（tR ≈ 40 μs級）とプログラム精度を高水準に維持できます。"],"formula":{"expression":"TiNバリア撤廃 ＋ Mo比抵抗低減 → ワード線抵抗 R_WL 約 −30〜40% ／ 垂直Zピッチ < 30 nm 達成！","description":"「保護のり不要の新金属モリブデン」が、332〜400層超高層NANDのスピード低下と高さ限界を一気に打ち破る"},"nextGenInnovation":"2026年のimec研究ではH₂ポストアニール処理したバリアレスMoワード線の高いTDDB絶縁破壊信頼性が実証され、400層〜1,000層ロードマップの基幹材料となっています。","specs":[{"label":"ワード線材料","value":"高純度バリアレス・モリブデン（Mo・ALD原子層成膜）"},{"label":"撤廃ライナー","value":"従来の高抵抗 TiN バリア／グルー層を完全省略"},{"label":"電気的改善","value":"ワード線抵抗 約 30〜40% 低減（RC遅延＆発熱削減）"},{"label":"垂直ピッチ","value":"サブ 30 nm Zピッチ（332層〜400層超の高密度積層対応）"}],"diagramType":"cfe_barrierless_moly_wl"},{"id":"cfe-wordline-airgap-iso","order":82,"swatchColor":"#38bdf8","groupKey":"階と階の間に_空気のすき間_を作る魔法_C82_ガラスより電気を","assembledPos":[6.2,14.5,1.15],"explodeOffset":[68,94,34],"integratedExplodeOffset":[68,94,34],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C82. ワード線間「エアギャップ（ナノ空気層）」絶縁＆セル間干渉（Z-Interference）遮断構造","subtitle":"Inter-Wordline Nanoscale Air-Gap Dielectric Isolation (k ≈ 1.0) Suppressing Z-Interference","category":"階と階の間に「空気のすき間」を作る魔法 C82 — ガラスより電気を通さない最強絶縁体「空気」で上下の混線をストップ！","plainAnalogy":"マンションの天井と床が紙みたいに薄くなると、上の階の足音が下の階へガンガン響いてしまいますよね。300階建て以上の3D NANDでも、上のワード線へ書き込む電気の影響が下の階へ漏れる「Z干渉（セル間干渉）」が大問題！そこで階と階の間のガラスを一部くり抜いて「ナノサイズの空気のポケット（エアギャップ）」を閉じ込めます。空気はガラスの約4分の1しか電気の響きを通さない最強の防音壁なんです！","summary":"隣接する上下ワード線層間に従来のSiO₂（比誘電率 k ≈ 3.9）の代わりにナノメートルの空洞（エアギャップ：k ≈ 1.0）をピンチオフ封止形成することで、ワード線間寄生容量とZ方向セル間干渉を大幅低減する次世代絶縁構造です。","opticsAndPhysics":["垂直Zピッチが30 nm以下に縮小すると、上下ワード線間の静電容量（C_WL-WL）が急増し、隣り合う層の書き込み電界や電荷拡散が被害セルのしきい値電圧（Vth）を狂わせる「Z-Interference」を引き起こします。","層間酸化膜の一部を選択エッチングで後退させ、非コンフォーマルCVD酸化膜でスリット入口だけを塞ぐ（ピンチオフ）ことで、比誘電率 k ≈ 1.0 の極低誘電エアギャップ空間をワード線間に構築します。","これによりワード線間結合容量を40%以上削減し、TLC（8値）やQLC（16値）の狭い電圧マージンでも読み間違いを防ぎます。"],"formula":{"expression":"比誘電率 k_SiO2 (3.9) → k_AirGap (1.0)   （上下ワード線間容量 −40%超・Z干渉を劇的低減！）","description":"何もない「空気のスキマ」こそが自然界最強の低誘電絶縁体——ナノ空洞で332〜400層の混線を防ぐ究極構造"},"nextGenInnovation":"バリアレス・モリブデン（C81）による「R（抵抗）削減」と、エアギャップによる「C（容量）削減」の合わせ技で、2026年以降の超多層NANDのRC遅延壁を突破します。","specs":[{"label":"絶縁媒体","value":"ピンチオフ封止ナノ・エアギャップ空洞（比誘電率 k ≈ 1.0）"},{"label":"寄生容量削減","value":"上下ワード線間カップリング容量 約 40% 以上低減"},{"label":"信頼性効果","value":"上下隣接セルZ干渉（Z-Interference）およびプログラムディスターブ抑制"},{"label":"相乗技術","value":"Mo低抵抗ワード線（C81）との併用でRC時定数を抜本改善"}],"diagramType":"cfe_wordline_airgap_iso"},{"id":"cfe-slit-trench-csl-wall","order":83,"swatchColor":"#64748b","groupKey":"332層の中に金属を流し込む_秘密の施工溝_C83_金属ワード線","assembledPos":[-4.2,11.4,1.15],"explodeOffset":[-36,98,-26],"integratedExplodeOffset":[-36,98,-26],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C83. スリットトレンチ（Gate-Line Slit）＆共通ソース線（CSL）タングステン導電壁","subtitle":"3D NAND Deep Gate-Line Slit Trench (RMG Replacement Path) & Common Source Line (CSL) Wall","category":"332層の中に金属を流し込む「秘密の施工溝」C83 — 金属ワード線を作ったあと、そのまま電流の帰り道（壁）へ変身！","plainAnalogy":"最初から金属とガラスを332層積むと縦穴が硬すぎて彫れません。そこで最初は彫りやすい「仮の層（犠牲膜）」を積んで縦穴を彫り、あとからブロックの間に深い溝（スリットトレンチ）をズバッと切ります！その溝から薬液を入れて仮の層だけを溶かし出し、空いたスキマへ金属を流し込んでワード線を作るんです（置換メタルゲート工法）。そして最後に溝の中を絶縁膜とタングステンで埋めて、電流の帰り道（共通ソース線）として再利用する超かしこい一石二鳥構造です！","summary":"3D NANDブロックを区切る深溝「スリットトレンチ（Gate-Line Slit）」。置換メタルゲート（RMG）工程で犠牲窒化膜のウェット除去とMo/W金属ゲート充填の通路として機能した後、側壁酸化膜ライナーと中央タングステン（W）共通ソース線（CSL）壁として完成します。","opticsAndPhysics":["数μm〜10 μm超の深いスリットトレンチの側壁には均一なSiO₂絶縁スペーサーが形成され、中央を走る共通ソース線（CSL）金属壁と332層のワード線との間の高電圧ショート（20 Vプログラム時）を完全に防止します。","トレンチ底面でアレイ共通ソース（ACS）領域へ直接接続することで、何万本ものメモリ縦穴から流れ出る読出電流を極低抵抗で一括回収し、ソース線ノイズ（ソース線バウンス）を防ぎます。","最新の深溝加工では、チャネル孔エッチング時の残留帯電による「スリット傾き（CSL Tilting）」を防ぐ帯電除去制御が高歩留まりの鍵になっています。"],"formula":{"expression":"①スリット開口 → ②犠牲SiN除去 → ③Mo/Wゲート充填（RMG） → ④側壁酸化膜＋W充填CSL共通ソース壁","description":"332層もの金属ゲートを内部へ流し込む「工事用トンネル」を、そのまま大電流の帰り道へ転用する驚異の半導体工法"},"nextGenInnovation":"CBA（CMOS directly Bonded to Array）世代では、スリットトレンチ配置の最適化と背面ソース線接続により、チップ面積をさらに削りビット密度37 Gb/mm²超へ貢献しています。","specs":[{"label":"プロセス役割","value":"RMG（置換メタルゲート）犠牲膜除去＆金属ゲート充填通路"},{"label":"完成後機能","value":"低抵抗タングステン（W）共通ソース線（CSL）導電壁"},{"label":"絶縁保護","value":"側壁SiO₂スペーサーライナー（20 Vワード線耐圧絶縁）"},{"label":"電気効果","value":"並列読出時のソース線電圧浮き上がり（バウンス）を低減"}],"diagramType":"cfe_slit_trench_csl_wall"},{"id":"cfe-op-sgd-select-gates","order":84,"swatchColor":"#2563eb","groupKey":"ムダな仕切りを消して面積15_節約_C84_332連メモリの入口","assembledPos":[4.2,11.4,1.15],"explodeOffset":[36,98,-26],"integratedExplodeOffset":[36,98,-26],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C84. BiCS10独自「オンピッチ・ドレイン選択ゲート（OP-SGD）」＆GIDLブロック消去ゲート","subtitle":"Kioxia/Sandisk BiCS8–10 On-Pitch Select Gate Drain (OP-SGD) & GIDL Erase Transistor Deck","category":"ムダな仕切りを消して面積15%節約！C84 — 332連メモリの入口スイッチを極限圧縮し、一斉消去まで司る門番ゲート","plainAnalogy":"縦に332個の部屋が並ぶメモリストリングの「屋上の入口ドア」がドレイン選択ゲート（SGD）、「地下の出口ドア」がソース選択ゲート（SGS）です。昔はこの入口ドア同士を分けるために、データを入れられない「ムダな空き柱（ダミーストリング）」をたくさん挟んでいました。キオクシア／サンディスクのBiCS8〜BiCS10は、この空き柱を丸ごと無くせる「オンピッチSGD（OP-SGD）」を発明し、チップ面積をなんと15%も節約したんです！","summary":"各垂直NANDストリングの上端に配置され目的のストリングのみをビット線へ接続する「オンピッチ・ドレイン選択ゲート（OP-SGD）」と、上下端に配置されバンド間トンネル現象（GIDL）で正孔を生成してブロック一括消去を行う消去用選択ゲート群です。","opticsAndPhysics":["従来のサブブロック分割では選択ゲートを絶縁分離するためのスリット直下に「ダミーメモリ柱」が必要でしたが、BiCS8〜BiCS10のOP-SGD（On-Pitch Select Gate Drain）構造ではセルピッチ通りに選択ゲートを微細分離し、ダミー柱を撤廃して有効セルアレイ面積を約15%削減しました。","ブロック消去時には上下のGIDL専用ゲートへ高電圧を印加し、ドレイン／ソース端で発生するゲート誘起ドレインリーク（GIDL）により大量の正孔（ホール）をマカロニチャネルへ送り込み、Si₃N₄捕獲層から電子を一斉に引き抜いて全セルを「1（消去状態）」へ戻します。","CBA（ウェハ貼り合わせ）とOP-SGDの相乗効果により、2026年のBiCS10（332層）はBiCS8比で最大59〜60%ものビット密度向上を達成しています。"],"formula":{"expression":"OP-SGD（ダミー柱撤廃 → アレイ面積 −15%）＋ 上下両端GIDL正孔注入（全332層を一括高速消去！）","description":"「階数を増やすだけ」でなく「ムダな柱を消す」発想で世界最高の記録密度を叩き出したBiCS10の核心構造"},"nextGenInnovation":"2026年7〜8月発表のBiCS10（332層・最大37 Gb/mm²超）では、OP-SGDとCBA・Toggle 6.0の組み合わせにより、極小Type Aカードでのさらなる大容量化・低消費電力化を切り開いています。","specs":[{"label":"選択ゲート革新","value":"BiCS8–10 独自 OP-SGD（オンピッチ・ドレイン選択ゲート）"},{"label":"高密度効果","value":"分離用ダミーストリング廃止により有効アレイ面積 約 15% 削減"},{"label":"消去メカニズム","value":"上下両端 GIDL（ゲート誘起ドレインリーク）正孔注入一括消去"},{"label":"採用世代","value":"Kioxia / Sandisk BiCS8（218層）〜 BiCS10（332層・2026年）"}],"diagramType":"cfe_op_sgd_select_gates"},{"id":"cfe-dummy-edge-wordlines","order":85,"swatchColor":"#f59e0b","groupKey":"あえて写真データを入れない_緩衝フロア_C85_高電圧ゲートのす","assembledPos":[-8.5,12.6,1.12],"explodeOffset":[-92,84,-38],"integratedExplodeOffset":[-92,84,-38],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C85. 上下端部ダミーワード線（Dummy WL）＆電界緩和ショックアブソーバ層","subtitle":"Top/Bottom & Inter-Deck Edge Dummy Wordlines (Dummy WL) Fringe-Field Buffer Stack","category":"あえて写真データを入れない「緩衝フロア」C85 — 高電圧ゲートのすぐ隣にクッション層を置いて端っこのデータ破損を防ぐ！","plainAnalogy":"332階建ての超高層メモリでも、じつはすべての階に写真や動画を入れるわけではありません！屋上（SGD）や地下（SGS）、それに2段重ねの継ぎ目（C79）のすぐ隣は強い電気の嵐（高電圧の端っこ電界）が吹き荒れる危険地帯。そこでエンジニアは上下の数フロアをあえて「空き部屋クッション（ダミーワード線）」にして優しい中間電圧を掛け、本物の写真データの階を電界ダメージから優しく守っているんです！","summary":"垂直NANDストリングの上端（SGD直下）・下端（SGS直上）・およびデック接合部（C79）の前後へ意図的に数層配置される非データ格納用「ダミーワード線（Dummy WL）」電界緩和バッファ層です。","opticsAndPhysics":["消去時のGIDLゲート近傍や、プログラム時の高電圧（約20 V）と選択ゲート電圧（0〜4 V）の境界では急峻な電位段差（フリンジ電界）が生じ、ホットキャリア注入による誤書込み（Edge Program Disturb）が発生しやすくなります。","境界に2〜4層のダミーワード線を設け、段階的な中間バイアス電圧（例：20 V → 10 V → 5 V → 0 V）を階段状に印加することで、電界集中をなだらかに緩和します。","これが「物理積層数（例：332層や218層）」と「実効データ層数（例：316層等）」に数層〜十数層の差がある理由であり、見えないところでプロ撮影データの長期保存信頼性を支えています。"],"formula":{"expression":"実効データ層 ＋ 上下／デック間ダミーWL（4〜12層）＝ 物理積層数（電界勾配を階段緩和し誤書込を防止！）","description":"電車の連結クッションのように高電圧の衝撃を吸収する「あえて使わない層」が、写真の1ビットも壊さない"},"nextGenInnovation":"300〜400層級のマルチデック時代では、デック継ぎ目（C79）にも最適なダミーWL電圧シーケンスを割り当てることで、全332層にわたる均一なデータ保持寿命を達成しています。","specs":[{"label":"配置箇所","value":"ストリング上端（SGD隣）・下端（SGS隣）・デック接合部前後"},{"label":"層数目安","value":"各境界 2〜4 層（合計 6〜12 層を保護バッファ専用確保）"},{"label":"電気機能","value":"段階的バイアス印加によるフリンジ電界・ホットキャリア抑制"},{"label":"信頼性効果","value":"端部セルのプログラムディスターブ＆データ保持劣化を根本防止"}],"diagramType":"cfe_dummy_edge_wordlines"},{"id":"cfe-multiplane-6plane-mpir","order":86,"swatchColor":"#0ea5e9","groupKey":"1枚のチップを6つの独立倉庫に分割_C86_1つのシリコンから同","assembledPos":[0,12.6,1.32],"explodeOffset":[0,96,96],"integratedExplodeOffset":[0,96,96],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C86. 2026年最新 4〜6プレーン独立並列読出（MPIR）＆BiCS10 332層ダイフロアプラン","subtitle":"2026 4/6-Plane Multi-Plane Independent Read (MPIR) & BiCS10 332-Layer Silicon Die Floorplan","category":"1枚のチップを6つの独立倉庫に分割！C86 — 1つのシリコンから同時に6か所のデータをバラバラ読み書きする並列魔法","plainAnalogy":"昔のメモリーチップは、1枚のチップ全体が「レジが1台だけの巨大スーパー」だったので、1人ずつしか会計できませんでした。2025〜2026年の最新3D NAND（Micron G9の6プレーンやKioxia BiCS8/10の4プレーンCBA）は、たった1枚のシリコンダイの中を「4〜6つの独立したお店（プレーン）」に分割し、それぞれに専用レジ（ページバッファ）を設置！だから1枚のチップから同時に6か所の写真やメタデータをバラバラに並列読み出しできるんです！","summary":"1 Tb級の単一3D NANDシリコンダイ内部を4〜6個の独立アレイ区画（Plane 0〜5）へ分割し、各プレーン直下のCBA CMOS領域に独立した行デコーダと16 KBページバッファを備える「マルチプレーン独立読出（MPIR）」フロアプラン構造です。","opticsAndPhysics":["従来のマルチプレーン動作は「全プレーンで同じページ番号」という厳しい制約がありましたが、最新の独立プレーン読出（MPIR：Multi-Plane Independent Read）では各プレーンが完全にバラバラのアドレスを非同期並列に読み出せます。","CFexpress 4.0では動画記録中にファイルシステム（exFATディレクトリ・メタデータ）の細かなランダム読出と巨大RAWフレームのシーケンシャル書込が同時発生するため、プレーン並列度の拡大がVPG800/1600の安定維持とランダムIOPS倍増に直結します。","2026年7〜8月発表のBiCS10（332層）ではフロアプラン最適化とCBA直結により、BiCS8比＋59〜60%（QLCで37 Gb/mm²超）という世界最高密度を達成しています。"],"formula":{"expression":"1ダイ内 6プレーン独立稼働（MPIR）× 16ダイ積層 ＝ チップ全体で最大 96 並列アクセス空間！","description":"1枚のシリコンを独立並列化する2026年フロアプラン革命が、親指サイズのカードにサーバー級並列処理をもたらす"},"nextGenInnovation":"2026年のMicron G9（276層・6プレーン・3.6 GT/s）やKioxia/Sandisk BiCS10（332層・CBA・4.8 Gb/s）が牽引する、次世代CFexpress 4.0/5.0カードの中核シリコン設計です。","specs":[{"label":"ダイ内分割","value":"4プレーン（BiCS8/10 CBA）〜 6プレーン（Micron G9 独立並列）"},{"label":"最新並列機能","value":"MPIR（Multi-Plane Independent Read：非同期独立アドレス読出）"},{"label":"2026年密度","value":"BiCS10（332層）：BiCS8比 ＋59%（TLC）／＞37 Gb/mm²（QLC）"},{"label":"ページ構成","value":"各プレーン専用 16 KB ページバッファ＆独立デコーダ直下実装"}],"diagramType":"cfe_multiplane_6plane_mpir"},{"id":"cfe-wafer-seal-ring-guard","order":87,"swatchColor":"#d97706","groupKey":"ミクロのチップを囲む_お堀と城壁_C87_工場で切り出した瞬間の","assembledPos":[0,12.6,1.02],"explodeOffset":[92,84,-38],"integratedExplodeOffset":[92,84,-38],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C87. シリコンダイ最外周「クラックストッパー・シールリング」＆耐湿パッシベーション枠","subtitle":"Silicon Die Perimeter Multi-Layer Cu/W Crack-Stopper Guard & Hermetic Moisture Seal Ring","category":"ミクロのチップを囲む「お堀と城壁」C87 — 工場で切り出した瞬間の微細なヒビと湿気をチップのフチで食い止める！","plainAnalogy":"大きな円盤（300 mmシリコンウェハ）から何千枚ものチップを切り分けるとき、切り口からは目に見えないミクロのヒビが中へ向かって走ろうとします。もし回路に届いたらそのチップは即死！そこで実は、すべてのNANDチップやコントローラチップのフチには、金属の配線層を全階つなげた「頑丈なお堀と城壁（シールリング）」がぐるっと1周築かれていて、ヒビも湿気もそこでピタッと食い止めているんです！","summary":"NANDおよびコントローラ用シリコンダイの最外周（スクライブライン内側）を全周包囲する、多層BEOL金属壁（銅／タングステン連続トレンチ壁）と窒化シリコン（SiN）／ポリイミド保護膜からなるクラックストッパー＆耐湿シールリング構造です。","opticsAndPhysics":["ウェハ切断（ダイシング）やTOUGH 7.5 m落下時の衝撃応力がダイ端面から内側へ亀裂進展しようとした際、連続した延性金属壁（二重のクラックストッパーリング）が亀裂エネルギーを吸収・偏向して内部の332層セルアレイや7 nmトランジスタを保護します。","同時に、層間絶縁膜（Low-kポーラス酸化膜など）は側面から水分やナトリウムイオンを吸い込みやすい弱点がありますが、隙間ゼロの金属トレンチ壁が横方向からの湿気侵入を原子レベルで完全遮断します。","接地電位へ接続することでチップ端面からの静電気侵入を逃がすガードリングとしても働きます。"],"formula":{"expression":"ダイ切断縁 → ポリイミド保護 → 二重Cu/W連続金属シール壁（亀裂進展＆横方向吸湿を100%ブロック！）","description":"数ミクロン幅の「シリコン城壁」が、工場切断から過酷な熱帯ジャングル撮影まで半導体チップの命を守り抜く"},"nextGenInnovation":"CBAウェハ貼り合わせ（BiCS8/10）では、上ウェハ（アレイ）と下ウェハ（CMOS）の接合界面自体にも専用のCu-Cu外周シールリングを設けて剥離と吸湿を二重防御しています。","specs":[{"label":"構造形式","value":"全BEOL層貫通型 二重金属トレンチ壁（Cu / W 連続シールリング）"},{"label":"機械防御","value":"ダイシング亀裂・熱応力剥離の内部進展を端面で完全阻止"},{"label":"環境防御","value":"横方向からの水分・アルカリイオン拡散遮断（耐湿信頼性）"},{"label":"保護上膜","value":"プラズマSiNパッシベーション ＋ 緩衝ポリイミド保護コート"}],"diagramType":"cfe_wafer_seal_ring_guard"},{"id":"cfe-toggle6-sca-bus","order":88,"swatchColor":"#06b6d4","groupKey":"命令専用のVIPレーンを新設_C88_毎秒48億ビットの超高速デ","assembledPos":[3.5,3.6,0.85],"explodeOffset":[108,48,52],"integratedExplodeOffset":[108,48,52],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C88. 2026年最新 Toggle DDR 6.0（4.8 Gb/s）＆SCA（コマンド・アドレス分離）高速プロトコル回路","subtitle":"2026 Toggle DDR 6.0 / ONFI 6.0 (4.8 Gb/s) & Separate Command Address (SCA) Bus Architecture","category":"命令専用のVIPレーンを新設！C88 — 毎秒48億ビットの超高速データ輸送を邪魔しない2026年の次世代NAND通信革命","plainAnalogy":"これまでのNANDチップの道路（DQ線）は、大きな荷物トラック（写真・動画データ）も、注文書を運ぶバイク（コマンド・アドレス）も「ぜんぶ同じ車線」を順番待ちで走っていました。だからスピードを上げても注文待ちの渋滞が起きていたんです！2026年登場の「Toggle DDR 6.0＋SCA（コマンド・アドレス分離）」は、注文書専用のVIPレーンを別に新設！データ車線は毎秒4.8ギガビットで休みなく全開爆走できるようになったんです！","summary":"2026年1月制定のONFI 6.0および2026年7〜8月発表のKioxia/Sandisk BiCS10で実用化された、ピンあたり最大4.8 Gb/s（4,800 MT/s）の次世代Toggle DDR 6.0インターフェースと、コマンド・アドレスをデータ線（DQ[7:0]）から独立分離するSCA（Separate Command Address）プロトコル回路です。","opticsAndPhysics":["従来のNANDバスではコマンド・アドレス（低速・非同期）とデータ（高速・DDR同期）が同一のDQ[7:0]線を時分割共有していたため、高速化してもランダムアクセスや小ファイル混在時のバス実効効率が50〜70%程度へ頭打ちになっていました。","SCAプロトコルは専用のコマンド／アドレス信号線へ命令発行をオフロードすることで、データ線上で前ページのデータ転送を行っている最中に次ページのコマンド・アドレスを同時先行発行でき、バス利用率を劇的に引き上げます。","ピンあたり4.8 Gb/s（8ビット幅で1チャネル実効4.8 GB/s！）の超広帯域により、少ないチャネル数・少ない発熱でCFexpress 4.0（2 GB/s）さらには将来のCFexpress 5.0（PCIe Gen5・4 GB/s）まで軽々と飽和させます。"],"formula":{"expression":"Toggle DDR 6.0 = 4.8 Gb/s/pin（BiCS8比 ＋33%）＋ SCA命令分離（データと命令の衝突待ちゼロ！）","description":"「道路の制限速度アップ（4.8 Gb/s）」と「命令専用レーン新設（SCA）」のW革命が2026年のNANDを別次元へ！"},"nextGenInnovation":"2026年夏にKioxiaとSandiskがBiCS10（332層TLC/QLC）で4.8 Gb/s＋SCAを公式発表し、次世代の超高速・低発熱プロシネマカードへの搭載が現実化しています。","specs":[{"label":"対応規格","value":"Toggle DDR 6.0 / ONFI 6.0（2026年1月最終仕様公開）"},{"label":"最大ピン速度","value":"4.8 Gb/s（4,800 MT/s・従来3.6 Gb/s比 ＋33%高速化）"},{"label":"プロトコル革新","value":"SCA（Separate Command Address：命令／アドレス独立専用線）"},{"label":"実効効果","value":"ランダム処理＆8K記録中のメタデータ混在時でもバス渋滞ゼロ"}],"diagramType":"cfe_toggle6_sca_bus"},{"id":"cfe-pi-ltt-vccql-io","order":89,"swatchColor":"#10b981","groupKey":"4_8_Gb_sなのに出力電力34_カット_C89_信号の振れ幅","assembledPos":[10.2,4.2,0.85],"explodeOffset":[114,24,14],"integratedExplodeOffset":[114,24,14],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C89. ONFI 6.0 / BiCS10「PI-LTT（電源分離・低タップ終端）」＆VccQL超省電力I/Oドライバ","subtitle":"ONFI 6.0 / BiCS10 Power-Isolated Low-Tapped Termination (PI-LTT) & VccQL Ultra-Low-Power I/O","category":"4.8 Gb/sなのに出力電力34%カット！C89 — 信号の振れ幅を賢く抑えて超高速と「熱くならない」を両立する2026年回路","plainAnalogy":"毎秒48億回も電気をON/OFFすると、普通は切手サイズのカードがチンチンに熱くなってしまいます。そこで2026年のONFI 6.0とBiCS10が採用したのが「PI-LTT（電源分離・低タップ終端）」。高い電圧まで毎回フルスイングして電気をムダ遣いするのではなく、I/O出力専用の超低電圧電源（VccQL）を分離して小さな振れ幅でキレ良く信号を送ることで、なんとデータ出力時の消費電力を一気に34%もカットしたんです！","summary":"ONFI 6.0（2026年1月）およびBiCS10（2026年7月）で標準化された最新省電力インターフェース技術「PI-LTT（Power-Isolated Low-Tapped Termination）」。分離された低電圧I/Oレール（VccQL）と低タップ終端ドライバにより高速通信のダイナミック消費電力を激減させます。","opticsAndPhysics":["高速CMOS信号線の消費電力は電圧振幅の2乗と周波数に比例（P ∝ C·V²·f）するため、4.8 Gb/s化に伴う発熱増加がCFexpress Type Aのような極小カードでは最大の壁でした。","PI-LTTは、従来の1.2 V VCCQ電源から出力段の終端基準を独立分離した低電圧VccQLレールで駆動するLow-Tapped Termination（低タップ終端）を採用し、データ入力時−10%・データ出力時−34%もの大幅な省電力化を達成します。","発熱が減ることでサーマルスロットリングまでの余裕時間が伸び、ファンレスの小型ミラーレスカメラ（α7 IV / FX3 / FX5等）での長時間4K/8K撮影とバッテリー持ち向上に直結します。"],"formula":{"expression":"P_IO ∝ C · ΔV² · f   （PI-LTT ＋ VccQL分離駆動 → 入力電力 −10% ／ 出力電力 −34% 削減！）","description":"「速くするほど熱くなる」という物理の壁を、分離低電圧終端ドライバで鮮やかに突破した2026年の省エネ技術"},"nextGenInnovation":"ONFI 6.0では旧来のレガシーI/O（SDR/NV-DDR2/3）を廃止し、NV-LPDDR4（LTT）とこのPI-LTT（VccQL）へ完全集約されたことで、今後のCFexpress次世代カードの標準I/Oとなります。","specs":[{"label":"規格名称","value":"ONFI 6.0 / BiCS10 PI-LTT（Power-Isolated Low-Tapped Termination）"},{"label":"省電力性能","value":"データ入力 −10% ／ データ出力 −34% 消費電力削減（公称値）"},{"label":"専用電源","value":"分離型低電圧 I/O 電源レール VccQL 採用"},{"label":"カメラ恩恵","value":"8K/X-OCN録画時のカード温度上昇抑制＆カメラバッテリー延命"}],"diagramType":"cfe_pi_ltt_vccql_io"},{"id":"cfe-zq-240ohm-odt-cal","order":90,"swatchColor":"#3b82f6","groupKey":"温度が変わっても電気の基準が狂わない_精密ものさし_C90_雪山","assembledPos":[11.4,-1.8,0.72],"explodeOffset":[108,-2,54],"integratedExplodeOffset":[108,-2,54],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C90. 0.1%高精度 240 Ω外部ZQキャリブレーション抵抗＆オンダイ終端（ODT）自動整合回路","subtitle":"±0.1% 240 Ω External ZQ Calibration Reference Resistors & On-Die Termination (ODT) Ladder","category":"温度が変わっても電気の基準が狂わない「精密ものさし」C90 — 雪山でも真夏でも信号の跳ね返りを自動校正！","plainAnalogy":"NANDチップの中の電気抵抗は、雪山（−12℃）と真夏の8K録画（+72℃）で大きく値がズレてしまい、そのままでは超高速信号が跳ね返ってエラーになります！そこで基板の上に、温度が変わってもビクともしない「誤差0.1%の超精密240 Ω抵抗（ZQ抵抗）」を黄金のものさしとして実装！チップが起動時や温度変化のたびにこの240 Ωと見比べて、自分の抵抗値を自動でピタッと微調整（ZQキャリブレーション）するんです！","summary":"ONFI 4.0〜6.0 / Toggle DDR 5.0〜6.0の高速NANDインターフェースで必須となる、外部±0.1%・240 Ω低温度係数薄膜リファレンス抵抗（R_ZQ）と、NAND／コントローラ内蔵のバイナリ加重オンダイ終端（ODT）＆駆動抵抗（Ron）自動校正回路です。","opticsAndPhysics":["半導体チップ内部のCMOSトランジスタによる出力ドライバ抵抗（Ron：35/37.5/50 Ω）やオンダイ終端抵抗（ODT：50/75/100/150 Ω）は、製造ばらつき・電源電圧変動・動作温度変化（PVT変動）で±20%以上ドリフトします。","ZQピンに外付けされた高精度240 Ω（±0.1%・TCR ±25 ppm/℃）の基準抵抗と内部コンパレータを比較し、2進重み付け並列トランジスタ群（抵抗ラダー）のON/OFFを自動切替することで、常に±2%以内の精密インピーダンス整合を維持します。","16ダイ積層（16DP）では選択ダイと非選択ダイでODTを切り替える「マトリクスODT（Non-Target ODT）」により、分岐スタブからの多重反射まで吸収します。"],"formula":{"expression":"外部基準 R_ZQ = 240.0 Ω ±0.1% → 内部ドライバ Ron = R_ZQ / 6 (40 Ω) ＆ ODT = R_ZQ / 4 (60 Ω) 自動ロック！","description":"たった1粒の極小精密抵抗が「絶対の基準ものさし」となり、−12℃〜+72℃の全域で4.8 Gb/s通信を完璧に整える"},"nextGenInnovation":"ONFI 6.0（2026年）のPI-LTT（VccQL）でもZQキャリブレーションが完全統合され、極低電圧・超高速I/Oのインピーダンス精度を保証する生命線となっています。","specs":[{"label":"外部基準抵抗","value":"240 Ω ±0.1% 極小0201薄膜精密抵抗（超低温度係数 ±25 ppm/℃）"},{"label":"校正対象","value":"出力インピーダンス（Ron）＆ オンダイ終端（Target / Non-Target ODT）"},{"label":"校正タイミング","value":"電源投入時（ZQCL）＋ 温度ドリフト検知時の定期再校正（ZQCS）"},{"label":"対応規格","value":"ONFI 5.1 / 6.0 ＆ Toggle DDR 5.0 / 6.0 必須キャリブレーション"}],"diagramType":"cfe_zq_240ohm_odt_cal"},{"id":"cfe-dcc-vrefq-eye-trainer","order":91,"swatchColor":"#facc15","groupKey":"1ビット_208兆分の1秒_のど真ん中を狙い撃つ照準器_C91_","assembledPos":[7.4,2.2,0.85],"explodeOffset":[114,44,-22],"integratedExplodeOffset":[114,44,-22],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C91. 4.8 Gb/s デューティ比自動補正（DCC / WDCA）＆ピン別VrefQアイパターン最適化エンジン","subtitle":"Duty Cycle Correction (DCC / WDCA) & Per-Pin VrefQ Read/Write Eye-Diagram Training Engine","category":"1ビット「208兆分の1秒」のど真ん中を狙い撃つ照準器 C91 — 波形のゆがみをピコ秒単位で直す自動チューナー！","plainAnalogy":"Toggle 6.0（4.8 Gb/s）では、1個の「0」や「1」の信号が通り過ぎる時間はたったの208ピコ秒（光ですら6センチしか進めない一瞬！）。ほんの少し「上がり」と「下がり」のバランスが崩れるだけで、データの目（アイパターン）が潰れて読めなくなります！そこでこの自動チューナーが起動直後にテスト信号を流し、8本のピン1本ずつに最適な判定電圧（VrefQ）とタイミング（DCC/WDCA）を自動で合わせ込んで、ど真ん中を百発百中で射抜くんです！","summary":"ONFI 5.1〜6.0 / Toggle 5.0〜6.0高速転送を支えるオンダイ自動キャリブレーション回路群。クロックの50:50対称性を保つDCC（読出デューティ補正）・WDCA（書込デューティ調整）、およびデータピン毎の最適しきい値電圧を自動探索するPer-Pin VrefQトレーニングエンジンです。","opticsAndPhysics":["ダブルデータレート（DDR）転送ではクロック（DQS / RE）の立ち上がりと立ち下がりの両エッジでデータを読み取るため、デューティ比が50%からわずか数%ズレただけで偶数ビットと奇数ビットの有効窓（アイ幅）が不均等に狭まります。","DCC / WDCA回路はピコ秒分解能の可変遅延ラインでデューティ歪み（DCD）を50.0%へ精密復元し、さらにリード／ライトDQトレーニングでDQS位相を各DQピンのアイパターン中心へ揃えます。","さらにPer-Pin VrefQ DACが8本のデータ線それぞれに対してミリボルト単位で最適な「0/1の境目電圧」を個別設定し、基板の微小な非対称性までソフト的に完全吸収します。"],"formula":{"expression":"1 UI = 1 / 4.8 GHz ≈ 208 ps   （DCC 50%補正 ＋ Per-Pin VrefQ ＋ DQS位相整列 → 最大アイ開口確保！）","description":"工場の個体差も温度変化も、チップ自身がピコ秒・ミリボルト精度で自己調律する現代半導体の知性"},"nextGenInnovation":"ONFI 5.1〜6.0ではUnmatched DQS対応とPer-Pin VrefQ・WDCA・受信側DFE等化器が統合され、将来の5.6 GT/s〜6.4 GT/s世代を見据えた自己適応型インターフェースへ進化しています。","specs":[{"label":"時間軸補正","value":"読出DCC（Duty Cycle Correction）＆ 書込WDCA（ピコ秒精度）"},{"label":"電圧軸補正","value":"Per-Pin VrefQ DAC（DQ0〜DQ7 ピン別最適しきい値自動設定）"},{"label":"トレーニング","value":"起動時 Read/Write DQ トレーニング（アイ中心自動ロック）"},{"label":"単位時間UI","value":"312 ps（3.2 Gb/s）〜 208 ps（4.8 Gb/s Toggle 6.0）"}],"diagramType":"cfe_dcc_vrefq_eye_trainer"},{"id":"cfe-vpg5-precond-engine","order":92,"swatchColor":"#22c55e","groupKey":"プロが撮影前に_フルフォーマット_する科学的理由_C92_毎秒8","assembledPos":[-6.2,-5.2,1.32],"explodeOffset":[-108,22,74],"integratedExplodeOffset":[-108,22,74],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C92. CFA VPG Profile 5.0（VPG800 / VPG1600）＆プリコンディショニング（TRIM / Full Format）制御器","subtitle":"CFA VPG Profile 5.0 (VPG800 / VPG1600) Preconditioning, NVMe Deallocate (TRIM) & Sanitize Engine","category":"プロが撮影前に「フルフォーマット」する科学的理由 C92 — 毎秒800〜1,600 MBの映画録画を1コマも落とさない事前お掃除エンジン！","plainAnalogy":"カメラの「クイックフォーマット」は本の目次を消すだけで、中のページには古いゴミデータがびっしり残ったまま。その状態で8K映画を撮り始めると、書きながら掃除（消去）する羽目になり速度がガクッと落ちます！2025〜2026年の新規格「VPG Profile 5.0（VPG800 / VPG1600）」は、NVMeのDeallocate（TRIM）やフルフォーマットによる「プリコンディショニング（事前全ブロック更地化）」を公式に組み込み、撮影開始から終了まで1秒800〜1,600 MBを1コマも落とさず保証するんです！","summary":"CompactFlash Association（CFA）が2025年2月に策定し2026年に本格普及した動画保証規格「VPG Profile 5.0（VPG800：最低800 MB/s、VPG1600：最低1,600 MB/s）」を支える、NVMe Format / Dataset Management（TRIM / Deallocate）/ Sanitizeプリコンディショニング制御エンジンです。","opticsAndPhysics":["NANDフラッシュは「上書き」ができず必ず「ブロック単位の事前消去」が必要なため、使用済みブロックが断片化したまま高ビットレート動画を書き込むと、バックグラウンドのガベージコレクション（GC）が割り込んで一瞬だけ速度が急落（コマ落ち原因）します。","VPG Profile 5.0対応カードとカメラ（ソニーα／FX／BURANO等）がフルフォーマット（NVMe Format / Sanitize / Deallocate）を実行すると、コントローラは全物理ブロックの不要マッピングを即座に破棄し、クリーンな消去済みブロックプールへプリコンディションします。","これにより2025〜2026年の最新プロカード（Nextorage NX-A2PRO VPG800 / NX-B2PRO+ VPG1600、ProGrade Iridium、Angelbird AV PRO v4等）は80%以上埋まった状態でも1,300〜1,600 MB/s超の驚異的な持続書込を維持します。"],"formula":{"expression":"VPG Profile 5.0 ＝ Preconditioning（全ブロック更地化）＋ 最低持続保証 800 MB/s (Type A) / 1,600 MB/s (Type B)","description":"カメラ側の「フルフォーマット（初期化）」とカード内TRIM制御がタッグを組み、8K/12K X-OCN収録のコマ落ちを完全撲滅"},"nextGenInnovation":"2025年末〜2026年にNextorage NX-A2PRO（世界初VPG800 Type A）やNX-B2PRO+（世界初VPG1600＋VPG400両対応Type B）が相次ぎ誕生し、VPG Profile 5.0時代が本格幕開けしました。","specs":[{"label":"CFA最新規格","value":"VPG Profile 5.0（2025年2月策定・2026年本格商用化）"},{"label":"保証速度階級","value":"VPG800（最低 800 MB/s）／ VPG1600（最低 1,600 MB/s）"},{"label":"必須連携機能","value":"NVMe Format / Deallocate (TRIM) / Sanitize プリコンディショニング"},{"label":"実写メリット","value":"8K RAW / Sony X-OCN LT / 12K シネマの長時間無ドロップ収録"}],"diagramType":"cfe_vpg5_precond_engine"},{"id":"cfe-nvme24-pqc-puf-root","order":93,"swatchColor":"#f59e0b","groupKey":"量子コンピュータでも破れない_チップ固有の指紋_C93_偽造不能","assembledPos":[-9.2,-10.8,1.28],"explodeOffset":[-116,-24,58],"integratedExplodeOffset":[-116,-24,58],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C93. NVMe 2.4（2026年8月）耐量子暗号（PQC）＆シリコン指紋PUFルートオブトラスト","subtitle":"NVMe 2.4 (Aug 2026) Post-Quantum Cryptography (ML-DSA) & Silicon PUF Hardware Root-of-Trust","category":"量子コンピュータでも破れない「チップ固有の指紋」C93 — 偽造不能のシリコン指紋と耐量子署名で報道・映画の原本を守る！","plainAnalogy":"生成AIによるフェイク写真や将来の量子コンピュータによる暗号解読が心配される2026年。「この写真・映像は本物のカメラと本物のカードで撮られた原本だ！」と証明するには、コピーできない秘密鍵が必要です。最新チップは、製造時に偶然生まれる原子レベルの電気のクセを「シリコンの指紋（PUF）」として秘密鍵にし、さらに2026年8月公開のNVMe 2.4規格で採用された「耐量子暗号（PQC）」と組み合わせることで、未来の量子コンピュータでも絶対に偽造できない鉄壁の金庫を作るんです！","summary":"2026年8月公開の「NVMe 2.4」仕様で追加された耐量子暗号（Post-Quantum Cryptography：ML-DSA等）およびNVMe 2.1のKey Per I/Oに対応し、チップ固有の物理複製困難関数（PUF）をハードウェア・ルートオブトラストとする次世代セキュリティ・エンクレーブです。","opticsAndPhysics":["PUF（Physical Unclonable Function）は、電源投入直後の極小SRAMセルが持つ原子数個分のトランジスタしきい値ばらつき（0になるか1になるかのランダム性）から、世界に1つだけの暗号ルート鍵を毎回その場で生成します。不揮発メモリに鍵を保存しないため、チップを薬品で削って顕微鏡で覗いても鍵は盗めません。","2026年8月4日に公開された最新仕様「NVMe 2.4」は、将来の量子コンピュータ攻撃（Shorのアルゴリズム等）に耐える格子ベース耐量子暗号（PQC：ML-DSA電子署名等）をサポートし、ファームウェア改ざん防止と長期アーカイブ保護を強化しています。","カメラ本体のC2PA真正性証明（Content Credentials）やTCG Opal 2.0自己暗号化と連動し、報道・映画撮影の原本データ保護へ発展しています。"],"formula":{"expression":"シリコン原子ゆらぎ（PUF指紋）→ 非保存ルート鍵 ＋ NVMe 2.4 耐量子暗号（ML-DSA / PQC）＆ AES-256-XTS","description":"「鍵を記憶せずチップの指紋から毎回生み出すPUF」×「2026年NVMe 2.4耐量子暗号」が映像の未来を守る"},"nextGenInnovation":"2026年8月のNVMe 2.4規格化と並行して、Caliptra準拠の耐量子ルートオブトラストおよびハードウェアPUF IPの次世代コントローラ搭載が急速に進んでいます。","specs":[{"label":"最新準拠規格","value":"NVM Express 2.4（2026年8月公開：耐量子暗号PQC対応）"},{"label":"ハードウェア鍵","value":"SRAM-PUF 物理複製困難関数（チップ固有シリコン指紋・非保存鍵）"},{"label":"耐量子署名","value":"NIST標準 ML-DSA（格子ベース耐量子ファームウェア署名検証）"},{"label":"映像用途連携","value":"C2PAコンテンツ来歴証明・TCG Opal / Key Per I/O 原本保護"}],"diagramType":"cfe_nvme24_pqc_puf_root"},{"id":"cfe-pcie-l12-pm-fsm","order":94,"swatchColor":"#06b6d4","groupKey":"撮っていない瞬間に消費電力を800分の1へ_C94_バッテリーを","assembledPos":[6.8,-14.8,-0.78],"explodeOffset":[108,-28,-54],"integratedExplodeOffset":[108,-28,-54],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C94. PCIe ASPM L1.2 超省電力ステートマシン＆NVMe PS0〜PS4 動的電力制御ロジック","subtitle":"PCIe ASPM L1.2 Substate & NVMe PS0–PS4 Autonomous Power State Transition (APST) FSM","category":"撮っていない瞬間に消費電力を800分の1へ！C94 — バッテリーを守り、カメラを冷やす超高速「居眠り＆目覚め」頭脳","plainAnalogy":"CFexpress 4.0は全速力で8K動画を書くとき約4ワットもの電気を使いますが、もしシャッターを切っていない待ち時間までずっと4ワット使い続けたら、カメラのバッテリーは30分で空っぽになりボディもアツアツになってしまいます！そこでこの省電力頭脳が、書き込みが終わった数ミリ秒後に「よし休憩！」と自動で居眠りモード（PS4 / L1.2：0.005ワット未満＝800分の1！）へ入り、シャッターを半押しした瞬間に1000分の1秒でパッと全開覚醒するんです！","summary":"PCI Express Active State Power Management（ASPM L1.2サブステート）とNVMe規格の5段階電源ステート（PS0〜PS4）および自律遷移（APST）をミリ秒・マイクロ秒単位で切り替えるオンチップ電力管理ステートマシンです。","opticsAndPhysics":["撮影連写中のPS0（フル性能：約3.0〜4.5 W）から、書込終了後のアイドル状態を検知すると自動でPS1→PS2→PS3→PS4（ディープスリープ）へ降格遷移します。","最深省電力のPCIe L1.2サブステートでは、`CLKREQ#`ピン（C42）を解放してカメラ側の100 MHz基準クロック発振自体を止め、カード内部のPCIe SerDes PHY・PLL・コモンモード保持回路の電源まで遮断して消費電力を 2〜5 mW 以下へ抑え込みます。","次のシャッター半押しや再生操作を検知すると数十〜数百マイクロ秒で電源・クロック・PCIeリンクを瞬時復帰させるため、撮影者は省電力移行を一切感じません。"],"formula":{"expression":"PS0（8K全開 ≈ 4.0 W） ⇄ PS4 + PCIe L1.2（待機 < 0.005 W：約 1/800 省電力・μs級高速復帰！）","description":"カメラのバッテリー寿命とボディ冷却の影の立役者——秒間1,800 MBの怪物を待機時は蛍の光ほどに眠らせる"},"nextGenInnovation":"CFA CFexpress 4.0仕様ではバッテリー駆動カメラ向けに厳格な低消費電力ターゲットが定められており、TSMC 6/7 nm低リークプロセスとL1.2最適化が標準となっています。","specs":[{"label":"NVMe電源状態","value":"PS0（最大4.5 W）〜 PS4（ディープスリープ < 5 mW）APST自律遷移"},{"label":"PCIe省電力","value":"ASPM L0s / L1.1 / L1.2 サブステート（CLKREQ#完全連動）"},{"label":"復帰レイテンシ","value":"約 100 μs 〜 数 ms（シャッター半押しで体感ゼロ復帰）"},{"label":"撮影効果","value":"NP-FZ100バッテリー持続延長 ＆ アイドル時の自然冷却促進"}],"diagramType":"cfe_pcie_l12_pm_fsm"},{"id":"cfe-hctm-thermal-fsm","order":95,"swatchColor":"#f43f5e","groupKey":"ガクッと速度を落とさない_なめらか温度ブレーキ_C95_カメラと","assembledPos":[-2.4,-3.5,0.95],"explodeOffset":[-98,-68,54],"integratedExplodeOffset":[-98,-68,54],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C95. NVMe HCTM（ホスト協調サーマル制御）＆多段階18ステップ適応クロック調整エンジン","subtitle":"NVMe Host Controlled Thermal Management (HCTM) & 18-Stage Smooth Adaptive DVFS Throttling","category":"ガクッと速度を落とさない「なめらか温度ブレーキ」C95 — カメラと相談しながら細かくペース配分して8K録画を完走！","plainAnalogy":"昔の高速カードは限界温度（70℃）になった瞬間、急ブレーキをガツンと踏んで速度が1,700 MB/sから200 MB/sへ暴落し、動画録画がブチッと止まってしまいました！最新のNVMe HCTM＋多段階適応スロットリングは、カメラ（BIONZ XR）と温度の目安（TMT1/TMT2）を相談しながら、18段階もの細かなステップで「ほんの少しずつ」スピードと発熱を整えるため、VPG800の最低保証スピードを切らずに長時間8K録画を完走できるんです！","summary":"NVMe規格の「ホスト協調サーマル管理（HCTM：Host Controlled Thermal Management）」および、コントローラ動作周波数・NAND同時プログラム数を最大18段階で微細調整するスムース・サーマルスロットリング制御エンジンです。","opticsAndPhysics":["カメラ側（ホスト）がNVMe Set Featuresコマンドで「第1警戒温度 TMT1（例：65℃）」と「第2警戒温度 TMT2（例：72℃）」を柔軟に設定でき、カメラ筐体の温度設計（冷却ファン有無や夏場ロケ設定）に合わせた最適な熱協調が可能です。","従来の2〜3段階の荒いスロットリングでは速度が鋸歯状に乱高下してバッファ溢れを招きましたが、18ステップ級の細かなDVFS（動的電圧・周波数スケーリング）＋書込スロット挿入制御により、発熱と放熱が釣り合う最高持続速度へピタリと安定収束します。","オンダイ温度センサー（C24）の毎ミリ秒サンプリングと連動し、NANDの70℃超データ保持劣化を防ぎながら録画継続性を最大化します。"],"formula":{"expression":"T < TMT1（全開 1,700 MB/s） → TMT1 ≤ T < TMT2（18段階微細調整 ≥ VPG800維持） → T ≥ TMT2（保護動作）","description":"急ブレーキではなく「プロドライバーの繊細なアクセルワーク」で、熱暴走と録画停止の両方を同時に防ぐ"},"nextGenInnovation":"2025〜2026年のプロ用PCIe Gen4コントローラでは、18段階適応スロットリングとカメラ本体側サーマル設定（「自動電源OFF温度：高」等）の連携が当たり前になっています。","specs":[{"label":"協調プロトコル","value":"NVMe HCTM（ホスト指定 TMT1 / TMT2 デュアル温度しきい値）"},{"label":"制御粒度","value":"最大 18段階スムースDVFS ＆ 並列NANDスロット動的調整"},{"label":"動画保護","value":"急激な速度崖（クリフ）を回避し VPG400/VPG800 下限を死守"},{"label":"温度監視周期","value":"デジタル温度センサー（C24）によるミリ秒級リアルタイム閉ループ"}],"diagramType":"cfe_hctm_thermal_fsm"},{"id":"cfe-vth-read-retry-tracker","order":96,"swatchColor":"#3b82f6","groupKey":"薄れた文字を角度を変えて読み解く_名探偵のルーペ_C96_電子が","assembledPos":[3.6,10.6,1.18],"explodeOffset":[98,72,62],"integratedExplodeOffset":[98,72,62],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C96. NANDしきい値電圧（Vth）分布自動追従＆ソフト判定LDPCリード・リトライ回路","subtitle":"Dynamic TLC/QLC Threshold-Voltage (Vth) Valley-Tracking & Soft-Decision LDPC Read-Retry Engine","category":"薄れた文字を角度を変えて読み解く「名探偵のルーペ」C96 — 電子が少し抜けてズレた電圧の谷間をミリボルト単位で自動追跡！","plainAnalogy":"TLC方式の3D NANDは、1つの部屋に「電子の量8段階（8つの山）」を記憶しています。でも真夏の暑さや長年の保管で電子がほんの少し抜けると、8つの山が少し左へズレてしまい、いつもの境目では読み違えが起きます！そんな時、この名探偵エンジンが境目の電圧をミリボルト単位で左右に動かして「本当の谷間（Vthバレー）」を探し出し、「どれくらい確信があるか（ソフト判定LLR）」を4K LDPCへ渡して写真を100%無傷で救い出すんです！","summary":"温度変化・書換劣化（P/Eサイクル）・長期放置（リテンション）によってドリフトしたTLC（8値）／QLC（16値）セルのしきい値電圧（Vth）分布の最適谷間を自動探索し、ソフト判定LDPC復号用対数尤度比（LLR）を生成するリード・リトライ制御エンジンです。","opticsAndPhysics":["通常の高速読出（ハード判定：各境界1回計測）で4K LDPCの訂正上限を超えた場合、コントローラは即座に「リード・リトライ（Read Retry）」を発動し、最適シフト電圧テーブルで再読出を行います。","さらに境界付近の複数電圧で段階サンプリングを行う「ソフト判定（Soft-Decision Read）」により、各ビットが「ほぼ確実に1」「微妙に0寄り」といった信頼度情報（LLR）を算出し、ハード判定の2〜3倍の誤り訂正能力を引き出します。","温度クロス（高温で書き込み→低温で読み出す「クロス温度効果」）によるVthシフトも、温度センサー（C24）連動の動的トラッキングで自動補償します。"],"formula":{"expression":"ハード判定失敗 → Vth谷間ミリボルト探索（Read Retry）→ ソフト判定LLR生成 → 4K LDPC訂正能力 2〜3×向上！","description":"「0か1かの二択」ではなく「確率の濃淡（ソフト情報）」まで読み取ることで、数年放置した思い出の写真も確実に復元"},"nextGenInnovation":"2025〜2026年のコントローラでは、過去の読出履歴から最適なシフト電圧を1発で当てる軽量機械学習／履歴キャッシュ型Vthトラッキングにより、リトライ遅延すら極小化しています。","specs":[{"label":"対象セル分布","value":"3D TLC（8レベル・7境界）／ QLC（16レベル・15境界）Vth分布"},{"label":"探索分解能","value":"数 mV 〜 数十 mV ステップの動的バレー・トラッキング"},{"label":"LDPC連携","value":"複数回微細読出による高精度ソフト判定 LLR（対数尤度比）生成"},{"label":"補償現象","value":"高温⇔低温クロス温度シフト・長期電荷漏れ・書換劣化を自動救済"}],"diagramType":"cfe_vth_read_retry_tracker"},{"id":"cfe-ldpc-data-scrambler","order":97,"swatchColor":"#a855f7","groupKey":"真っ黒や真っ白の写真も_きれいに混ぜて_安全保存_C97_0や1","assembledPos":[-6.2,-10.4,1.32],"explodeOffset":[-74,-42,76],"integratedExplodeOffset":[-74,-42,76],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C97. ハードウェア・データスクランブラ（疑似乱数撹拌器）＆セル間パターン干渉防止エンジン","subtitle":"Hardware LFSR Pseudo-Random Data Scrambler & Worst-Case Cell-Pattern Interference Eliminator","category":"真っ黒や真っ白の写真も「きれいに混ぜて」安全保存！C97 — 0や1が連続する危険パターンを自動で50:50に撹拌するミキサー","plainAnalogy":"もしレンズキャップを付けた真っ黒な画面や、真っ青な空を撮ると、データの中身は「00000000…」や「11111111…」と同じ数字ばかりズラッと並びます。実はNANDフラッシュは同じ数字が隣同士に固まると電気の偏りで誤作動（パターン干渉）しやすいんです！そこで書き込む直前に、この高速ミキサー（データスクランブラ）がページ番号ごとの秘密のサイコロで0と1をちょうど50:50にシャッフルして保存し、読むときに一瞬で元に戻しているんです！","summary":"3D NANDへ書き込む直前の全データストリームに対し、物理ページアドレスを初期シードとする高速LFSR（線形帰還シフトレジスタ）疑似乱数系列を排他的論理和（XOR）してビット分布を完全均等化するハードウェア・データスクランブラです。","opticsAndPhysics":["「0」と「1」の偏りや特定周期パターン（例：未圧縮RAWの暗部フレームやフォーマット直後のゼロ埋め領域）がそのまま書き込まれると、隣接セル間の電界結合（プログラムディスターブ・Z干渉）や読出時のビット線同時スイッチング電流スパイクが最悪値に達します。","ハードウェア・スクランブラがナノ秒の遅延もなく全16 KBページを擬似白色雑音化（0と1の出現確率50%、TLCの8電圧レベルすべてが均等12.5%ずつ出現！）することで、あらゆる撮影シーンでセル干渉と消費電流を統計的最適値へ平準化します。","物理ページアドレスごとに異なるシードを使うため、全く同じ静止画を連続記録しても隣接ワード線間で同じビットパターンが縦に揃う現象（ワード線間相関）を完全に断ち切ります。"],"formula":{"expression":"D_NAND = D_raw ⊕ LFSR(PageAddr)   （全TLC 8状態が均等 12.5% 出現 → 読出時に同じXORで100%無損失復元！）","description":"カメラの映像を一切変質させず、NANDチップが最も壊れにくく快適に働ける「50:50の黄金バランス」へ自動撹拌"},"nextGenInnovation":"スクランブリングはAES-256暗号化や4K LDPC符号化パイプラインと1クロック単位で直列統合され、スループット低下ゼロで全書込みページを常時保護しています。","specs":[{"label":"演算方式","value":"物理ページアドレス連動シード型 高速ハードウェアLFSR-XOR撹拌"},{"label":"均等化効果","value":"TLC 8値（各12.5%）の完全バランス化＆最悪干渉パターン根絶"},{"label":"副次効果","value":"ビット線同時スイッチングノイズ（SSN）および電源リプル低減"},{"label":"処理遅延","value":"インライン数ナノ秒（1,800 MB/s転送へのオーバーヘッド実質ゼロ）"}],"diagramType":"cfe_ldpc_data_scrambler"},{"id":"cfe-pmic-ovp-uvlo-guard","order":98,"swatchColor":"#ef4444","groupKey":"異常な電気から7_nm頭脳を瞬時に守る_電圧の関所_C98_高す","assembledPos":[7.2,-11.4,-0.86],"explodeOffset":[74,-62,-58],"integratedExplodeOffset":[74,-62,-58],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C98. PMIC内蔵 OVP（過電圧）／UVLO（低電圧ロックアウト）／OCP三重保護コンパレータ","subtitle":"PMIC Precision Bandgap Reference & OVP / UVLO / OCP Triple-Window Protection Comparator","category":"異常な電気から7 nm頭脳を瞬時に守る「電圧の関所」C98 — 高すぎても低すぎても100万分の1秒で安全遮断＆緊急退避！","plainAnalogy":"安い粗悪カードリーダーからうっかり4.5 Vの高い電気が流れ込んだら、3.3 V用の繊細な7 nmチップは一瞬で焼き切れてしまいます。逆にカメラのバッテリーが切れて電圧が2.9 Vへガクッと落ちたまま書き込みを続けると、ファイルが半分壊れてしまいます！そこでPMICの入口に「上は3.63 V、下は2.97 V」の厳密な関所（ウィンドウコンパレータ）を置き、少しでも枠を外れた瞬間に100万分の1秒で遮断＆PLP緊急退避を発動させるんです！","summary":"温度に依存しない高精度バンドギャップ基準電圧源（約1.2 V・精度±1%）と、3.3 V入力電源および内部各レールを常時監視する過電圧保護（OVP）・低電圧ロックアウト（UVLO）・過電流保護（OCP）の三重ウィンドウコンパレータ回路です。","opticsAndPhysics":["過電圧保護（OVP：約3.63〜3.8 V超）が異常サージを検知すると、マイクロ秒未満で入力ロードスイッチ（eFuse：C40）を強制オープンしてコントローラや16層NANDのゲート酸化膜破壊を阻止します。","低電圧ロックアウト（UVLO：約2.95〜2.97 V未満）が電池切れや活線抜去を検知した瞬間に、ただ電源を切るのではなく即座に「PLP緊急退避割り込み（PLI#）」をコントローラへ送り、ホールドコンデンサ（C19）の蓄電エネルギーだけで仕掛かり中のFTL目次とキャッシュデータを安全に書き込み完了させます。","過電流保護（OCP）とサーマルシャットダウン（TSD）により、万一の内部短絡時でもカメラ本体側スロットの3.3 V電源を道連れ故障させません。"],"formula":{"expression":"安全動作窓：2.97 V (UVLO) < V_IN (3.30 V) < 3.63 V (OVP)   （窓逸脱を < 1 μs 検知 → 遮断／PLP退避！）","description":"「高すぎる電気」も「低すぎる電気」も見逃さない3重の関所が、大切なデータと高価なカメラ本体の両方を守る"},"nextGenInnovation":"最新世代PMICではバンドギャップ基準＋高速ADCテレメトリにより、過去の異常電圧イベント回数までS.M.A.R.T.ログへ記録して故障予兆診断に役立てています。","specs":[{"label":"過電圧遮断 OVP","value":"3.63 〜 3.80 V 超でマイクロ秒級入力FET強制遮断"},{"label":"低電圧監視 UVLO","value":"2.95 〜 2.97 V 未満で即座にPLP緊急データ退避トリガ発行"},{"label":"基準電圧源","value":"温度補償型バンドギャップリファレンス（精度 ±1.0%・−40〜+125℃）"},{"label":"過電流保護 OCP","value":"ハードウェア電流制限＆短絡時カメラ側スロット保護"}],"diagramType":"cfe_pmic_ovp_uvlo_guard"},{"id":"cfe-usb4-mrwg3-bridge-if","order":99,"swatchColor":"#64748b","groupKey":"撮った1_9_TBを2_3倍速でPCへ運ぶ_極太トンネル_C99","assembledPos":[0,28.95,0],"explodeOffset":[0,62,-84],"integratedExplodeOffset":[0,62,-84],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C99. USB4 40 Gbpsリーダー（Sony MRW-G3等）PCIeトンネリング直結＆放熱フィン接触部","subtitle":"USB4 40 Gbps Card Reader (Sony MRW-G3) Native PCIe Tunneling Bridge & CNC Thermal Clamp Dock","category":"撮った1.9 TBを2.3倍速でPCへ運ぶ「極太トンネル」C99 — USB4でPCIe信号をそのまま通し、金属フィンで冷やしながら爆速転送！","plainAnalogy":"せっかくCFexpress 4.0（毎秒1,800 MB）で撮っても、古いUSB 10 Gbpsリーダーだと半分以下のスピードしか出ず、1.9 TBのデータコピーに何十分もかかってしまいます！2025年登場のソニー「MRW-G3」など最新USB4（40 Gbps）リーダーは、PCIe Gen4の信号を翻訳せずにそのままUSB4ケーブル内へ「直通トンネル（PCIeトンネリング）」で通し、しかもアルミ製放熱フィンでカードの金属鎧（C01/C02）を挟み冷やしながら、1,800 MB/s全開で一瞬コピーを叶えるんです！","summary":"CFexpress 4.0 Type A（Sony CEA-G1920T / CEA-G960T等）の最大1,800 MB/s読出性能を100%引き出す、Sony MRW-G3等に代表されるUSB4（40 Gbps）対応カードリーダーのネイティブPCIeトンネリング結合およびCNCアルミ放熱フィンドック接触インターフェースです。","opticsAndPhysics":["従来のUSB 3.2 Gen2（10 Gbps・実効約900 MB/s）リーダーはUSBプロトコル変換がボトルネックになっていましたが、USB4 40 Gbps（ASMedia ASM2464PD等）はPCIe Gen4パケットをネイティブにトンネリング伝送することで、CFexpress 2.0比約2.3倍の実効転送を実現します。","1,920 GB（約2 TB）を1,800 MB/sで連続オフロードするとカードは数ワットの発熱を約18分間継続するため、リーダー側の大型CNCアルミ放熱フィン筐体とカード上下の金属アーマー（C01/C02）を熱結合させる放熱設計が不可欠です。","USB4経由でNVMeネイティブコマンドがそのままPCへ届くため、Sony「Media Scan Utility」によるS.M.A.R.T.寿命診断や最新ファームウェア更新も高速に行えます。"],"formula":{"expression":"CFexpress 4.0 (PCIe Gen4 ×1: 1,800 MB/s) ⇄ USB4 40 Gbps ネイティブPCIeトンネリング（従来比 2.3×高速転送！）","description":"撮影現場のオフロード待ち時間を半分以下に短縮する、2025〜2026年CFexpress 4.0ワークフローの決定打"},"nextGenInnovation":"2025年発売のSony MRW-G3（CFexpress 4.0 Type A専用・USB 40 Gbps）をはじめ、ProGrade・Nextorage・Angelbirdからも冷却フィン一体型USB4リーダーが出揃い、Type Aでも1.9 TB超の即座バックアップが標準化しました。","specs":[{"label":"代表対応機器","value":"Sony MRW-G3（USB 40 Gbps CFexpress 4.0 Type A専用リーダー）"},{"label":"伝送アーキテクチャ","value":"USB4 / Thunderbolt 4 ネイティブ PCIe Gen4 トンネリング直結"},{"label":"オフロード速度","value":"最大 約 1,800 MB/s（CFexpress 2.0 リーダー比 約 2.3 倍高速）"},{"label":"熱結合機能","value":"CNCアルミ放熱フィン接触により 1.9 TB連続読出でも速度低下ゼロ"}],"diagramType":"cfe_usb4_mrwg3_bridge_if"},{"id":"cfe-xray-magnetic-uv-shield","order":100,"swatchColor":"#38bdf8","groupKey":"地球上のあらゆる過酷ロケを生き抜く_6重バリア_C100_空港X","assembledPos":[0,1.3,1.88],"explodeOffset":[-42,-30,96],"integratedExplodeOffset":[-42,-30,96],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C100. 耐X線（ISO7816-1）・耐磁気・耐静電・耐UV 6重環境プロテクト多層バリア構造","subtitle":"6-Fold Environmental Protection Stack (ISO7816-1 X-Ray / Magnetic / UV / ESD / IP57 / Thermal Shock)","category":"地球上のあらゆる過酷ロケを生き抜く「6重バリア」C100 — 空港X線も強力磁石も砂漠の紫外線もはね返す究極の総仕上げ！","plainAnalogy":"海外ロケの空港X線検査、ジンバルやスピーカーの強力な磁石、真夏の炎天下の強烈な紫外線（UV）、冬場のバチッという静電気……撮影現場にはメモリーカードの天敵がいっぱい！でもCFexpress TOUGHカードは、磁気の影響を一切受けないシリコン窒化膜メモリ（C56）、UVを完全に遮る真っ黒な一体成型樹脂（C03）、静電気と電磁波を逃がす金属鎧（C01/C02/C35）、そしてX線ノイズすら修復する4K LDPC＋XOR RAID（C10/C70）という「6重のバリア」で大切な作品を守り抜くんです！","summary":"CFexpress 4.0 TOUGHカード（C01〜C99）のすべての物理・半導体・回路防御技術が統合されて実現する、耐X線（ISO 7816-1準拠）・耐磁気・耐静電（IEC 61000-4-2）・耐UV（紫外線）・防水防塵（IP57）・耐温度衝撃（−12〜+72℃）の6重環境プロテクト多層構造です。","opticsAndPhysics":["耐磁気：ハードディスクや磁気テープと異なり、3D NANDのチャージトラップ層（Si₃N₄）は磁性体ではなく静電ポテンシャル井戸に電子を閉じ込めるため、強力なネオジム磁石を近づけても記録データは原理的に1ビットも消えません。","耐X線＆耐UV：空港手荷物検査レベルのX線（ISO 7816-1準拠：0.1 Gy）では酸化膜障壁を越える電子脱出は極めて少なく、万一の微量ビット反転も4K LDPC（C10）＋ダイ間XOR RAID（C70）で100%無傷復元します。さらにカーボン配合不透明モノコック樹脂と金属シェルが、セルの電子を叩き出す紫外線（UV）を完全遮光します。","耐静電＆耐水防塵：外周IP57封止（C04）・プラズマ撥水膜（C46）・金属ファラデーシールド（C35）・±15 kV TVSダイオード（C21）の多層連携により、極地から砂漠・豪雨まであらゆる撮影環境でプロ品質の記録信頼性を完結させます。"],"formula":{"expression":"防水防塵(IP57) ＋ 耐衝撃(150N/7.5m) ＋ 耐X線(ISO7816-1) ＋ 耐磁気 ＋ 耐UV ＋ 耐静電(±15kV) ＝ 6重完全防御！","description":"100個もの極微細パーツと2026年最先端半導体の結晶が、親指サイズの1枚に「絶対に壊れない安心」を宿らせる"},"nextGenInnovation":"2025〜2026年のプロ用CFexpress 4.0 TOUGH規格（Sony CEA-G1920T等）では、この6重環境耐性に加え、Media Scan Utilityによる事前寿命予知＋データ復旧ソフト（Memory Card File Rescue）まで含めたトータル信頼性エコシステムが完成しています。","specs":[{"label":"耐X線・耐UV","value":"ISO 7816-1 準拠（空港X線対応）＋ 不透明金属／黒樹脂完全遮UV"},{"label":"耐磁気特性","value":"非磁性 Charge-Trap Si₃N₄ 記憶方式（強磁界環境でもデータ無影響）"},{"label":"耐静電・耐環境","value":"±15 kV ESD保護 ＋ IP57防水防塵 ＋ −12 ℃〜+72 ℃動作保証"},{"label":"総合データ保護","value":"6重物理バリア × 4K LDPC（C10）× ダイ間XOR RAID（C70）"}],"diagramType":"cfe_xray_magnetic_uv_shield"},{"id":"cfe-besonos-tunnel-oxide","order":101,"swatchColor":"#facc15","groupKey":"量子トンネルの_一方通行自動ドア_C101_書き込むときだけ通し","assembledPos":[-4.2,11.4,0.52],"explodeOffset":[-94,92,34],"integratedExplodeOffset":[-94,92,34],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C101. BE-SONOS バンドギャップ設計トンネル酸化膜（O1/N1/O2 量子障壁）","subtitle":"Bandgap-Engineered SONOS (O1/N1/O2) Quantum Tunneling Barrier (~5.1 nm Total)","category":"量子トンネルの「一方通行自動ドア」 C101 — 書き込むときだけ通し、普段は電子を10年逃がさない3層ナノ障壁！","plainAnalogy":"フラッシュメモリに写真を保存するには、電子を壁の向こうへ押し込む（書き込む）必要がありますが、壁が薄すぎると保存した電子が勝手に漏れて写真が消えてしまいます。そこで生まれた魔法の壁が「O1（酸化膜）／N1（窒化膜）／O2（酸化膜）」の3枚サンドイッチ（合計わずか約5 nm＝髪の毛の1万5000分の1）！書き込む強い電圧をかけた瞬間だけ量子力学のトンネル効果でスーッと電子を通し、普段の電圧ゼロでは分厚い防波堤になって10年間データ漏れ（SILC）をピタッと止める「究極の一方通行自動ドア」なんです！","summary":"シリコンチャネルと電荷捕獲層（Si3N4）の間に設けられた、SiO2（O1: 約1.3 nm）／Si3N4（N1: 約2.0 nm）／SiO2（O2: 約1.8 nm）の3層バンドギャップ設計トンネル絶縁膜です。低電界時の直接トンネリング漏洩と高電界時の高速ファウラー・ノルドハイム（FN）書込・正孔消去を両立します。","opticsAndPhysics":["単層のSiO2トンネル膜では書込・消去を繰り返すと膜内に欠陥が生まれ、低電圧でも電子が抜けるストレス誘起リーク電流（SILC）がデータ保持寿命を縮めます。","BE-SONOS構造ではバンドギャップの広いO1/O2（9.0 eV）で狭いN1（5.3 eV）を挟むことで、電界ゼロ時は実効障壁厚が厚く見えてリークを桁違いに遮断しつつ、消去・書込時の強電界では障壁が急激に傾いて三角障壁となり高速トンネル注入を実現します。","2026年発表のシミュレーション研究では、SiO2/Al2O3/SiO2 積層トンネル工学により10年保持後のしきい値電圧窓（Vth Window）を 0.78 V から 4.18 V へ劇的に改善するアプローチも実証されています。"],"formula":{"expression":"J_FN = A · E_ox² · exp(−B / E_ox),   B ∝ (m*)^(1/2) · Φ_B^(3/2)","description":"ファウラー・ノルドハイム（FN）量子トンネル電流式。電界 E_ox と障壁高さ Φ_B のバランスを3層O1/N1/O2で精密制御する。"},"nextGenInnovation":"2025〜2026年の332〜400層級3D NANDでは、円筒形マカロニチャネル内壁へ原子層堆積（ALD）でサブオングストローム精度のO1/N1/O2を均一成膜し、1万回以上の書換ストレス後も85℃高温データ保持を支えています。","specs":[{"label":"積層構造","value":"O1(SiO2 ~1.3nm) / N1(Si3N4 ~2.0nm) / O2(SiO2 ~1.8nm)"},{"label":"総物理膜厚","value":"約 5.0〜5.5 nm（原子 約20層分）"},{"label":"主要機能","value":"高速FN書込・正孔消去 ＆ SILC低電界リーク遮断"},{"label":"次世代研究（2026）","value":"SiO2/Al2O3/SiO2 工学で10年保持Vth窓 4.18 V 実証"}],"diagramType":"cfe_besonos_tunnel_oxide"},{"id":"cfe-highk-al2o3-blocking","order":102,"swatchColor":"#0284c7","groupKey":"金属ゲートへの逆流を断つサファイア防壁_C102_電気の抜け道を","assembledPos":[-1.4,13.8,0.58],"explodeOffset":[-68,108,42],"integratedExplodeOffset":[-68,108,42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C102. 高誘電率 Al2O3 / LaAlOx ブロッキング絶縁膜＆ゲート逆注入防止壁","subtitle":"High-k Al2O3 / Lanthanum-Doped LaAlOx Blocking Oxide & Back-Tunneling Barrier","category":"金属ゲートへの逆流を断つサファイア防壁 C102 — 電気の抜け道を塞ぎ、記憶のコントラストを最大化する高誘電率の盾！","plainAnalogy":"3D NANDのメモリセルを消去するとき、強い逆電圧をかけて電子を追い出します。ところが外側の金属配線（ワード線）との間にある仕切り壁が弱いと、せっかく消去しているのに金属側から別の電子がドバドバ逆流（バックトンネリング）して消去が止まってしまいます！そこで使われるのがサファイアと同じ成分「酸化アルミニウム（Al2O3）」に微量ランタンを混ぜた高誘電率バリア。電気を通さず電界だけを効率よく伝えるため、逆流をピタリと止めてデータを深くクッキリ消去・保存できるんです！","summary":"電荷捕獲層（Si3N4）と金属ワード線（Mo/W）の間に配置される高誘電率（High-k）ブロッキング絶縁膜です。消去時のゲートからの電子逆注入（Gate Injection / Erase Saturation）を抑制し、書込・消去電圧の低減と高温データ保持を両立します。","opticsAndPhysics":["従来のSiO2（比誘電率 κ ≈ 3.9）に比べ、Al2O3（κ ≈ 9）や微量ランタン添加LaAlOxは高い誘電率と広いバンドギャップ（〜8.7 eV）を兼ね備え、実効酸化膜厚（EOT）を薄く保ちながら物理膜厚を厚くできます。","消去動作時に金属ワード線から電子がブロッキング膜を突き抜けて窒化膜へ逆流すると「消去飽和（Erase Saturation）」が起きますが、2026年研究のAl2O3＋2 nm HfO2キャップやLaドープAl2O3は伝導帯オフセットを高め、最大9.5 V級の広いメモリ窓を実証しています。","332〜400層級のサブ30 nm Zピッチでは、ブロッキング膜を1 nmでも薄くしつつ高電界耐圧を維持することが積層高さ抑制の生命線です。"],"formula":{"expression":"EOT = t_phys × (κ_SiO2 / κ_high-k)   (κ_SiO2 = 3.9,  κ_Al2O3 ≈ 9.0)","description":"高誘電率（High-k）材料により、同じ電気的結合力（EOT）でも物理厚みを2倍以上に厚くして逆流トンネル電流を指数関数的に遮断。"},"nextGenInnovation":"2026年10月公開の最新研究では、Al2O3への微量ランタン（La）ドープ＋900℃アニールによりバンドギャップを犠牲にせずκ値を高め、85〜120℃環境下での高温電荷保持と低リーク特性を飛躍的に改善する技術が報告されています。","specs":[{"label":"採用材料","value":"ALD Al2O3 / LaAlOx / HfO2 キャップ積層"},{"label":"比誘電率（κ）","value":"約 9〜14（SiO2比 2.3〜3.5倍）"},{"label":"主要効果","value":"消去時ゲート電子逆流阻止 ＆ 動作電圧低減"},{"label":"記憶窓実績（2026）","value":"最大 9.5 V 級（10^4 回書換耐性）"}],"diagramType":"cfe_highk_al2o3_blocking"},{"id":"cfe-si3n4-trap-energy-wells","order":103,"swatchColor":"#9333ea","groupKey":"電子が住み着く_原子のくぼみ_C103_0_87_eVの深いポケ","assembledPos":[2.2,14.5,0.54],"explodeOffset":[-40,118,36],"integratedExplodeOffset":[-40,118,36],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C103. アモルファス Si3N4 電荷捕獲欠陥（0.87 eV 量子トラップ井戸）＆横方向拡散抑制","subtitle":"Amorphous Si3N4 Localized Electron/Hole Trap Wells (0.87 eV) & Lateral Migration Cut","category":"電子が住み着く「原子のくぼみ」 C103 — 0.87 eVの深いポケットに電子を閉じ込め、隣の階への脱走を防ぐ！","plainAnalogy":"昔のメモリ（フローティングゲート）は電気を通す金属のバケツに電子を入れていたので、壁に1か所でも小さな穴が空くと電子が全部流れ出してデータが消えました。今の3D NANDが使う「窒化シリコン（Si3N4）」は電気を通さない絶縁体の中に、原子レベルの小さなくぼみ（トラップ）が無数に散らばった「卵パック」のような構造！1個ずつ別々のくぼみ（深さ0.87 eV）に電子を閉じ込めるので、どこか1か所傷んでも他の電子は逃げません。さらに上下の階へ電子がジワジワ横移動するのも溝でブロックしています！","summary":"3D NANDで実際に「0と1」の情報を記憶するアモルファス窒化シリコン（a-Si3N4）電荷捕獲層（CTL）の微視的欠陥準位構造です。電子・正孔を絶縁体内の局在欠陥（トラップ）へ捕獲し、上下セル間の横方向電荷移動（Lateral Charge Migration）を抑えます。","opticsAndPhysics":["2026年8月のARCNLおよびIEEE研究により、3D NANDのa-Si3N4捕獲層内のトラップ密度はガウス分布を示し、深さ約 0.87 eV にピーク密度 4.3×10^18 cm^-3·eV^-1 が存在することが円筒座標BITE法で定量解明されています。","高温（85〜125℃）環境では浅いトラップ（0.6〜0.75 eV）からプール・フレンケル（Poole-Frenkel）放出やトラップ・バンド間トンネリング（TB）で電荷が脱出しやすく、さらに連続したSi3N4膜を伝って上下の隣接ワード線へ逃げる「横方向電荷移動」が300層超での最大の保持劣化要因です。","最新世代ではSi3N4の組成比（Si/N比）制御による深いトラップ準位の最適化と、セル間の窒化膜分断（Charge Trap Cut）により、TLC/QLCの狭いしきい値間隔を長期間守り抜きます。"],"formula":{"expression":"τ_emit = τ_0 · exp(E_T / (k_B · T)),   Peak N_T ≈ 4.3×10^18 cm^-3·eV^-1 @ 0.87 eV","description":"トラップ深さ E_T が深いほど熱放出時間 τ_emit が指数関数的に延び、高温撮影後も写真が消えにくくなる（2026年実測モデル）。"},"nextGenInnovation":"2026年の第一原理DFT計算と非放射多フォノン理論により、原子結合欠陥（Kセンター等）の捕獲断面積を設計し、ISPP書込効率と10年データ保持を同時に最適化する材料設計が実用化されています。","specs":[{"label":"記憶媒体","value":"アモルファス窒化シリコン（a-Si3N4）膜厚 4〜6 nm"},{"label":"トラップ準位ピーク","value":"約 0.87 eV / 4.3×10^18 cm^-3·eV^-1（2026実測）"},{"label":"主な劣化機構","value":"Poole-Frenkel熱放出 ＆ 上下セル間横方向電荷移動"},{"label":"対策構造","value":"Si/N組成深準位化 ＋ セル間CTN分断（Cut）"}],"diagramType":"cfe_si3n4_trap_energy_wells"},{"id":"cfe-ispp-step-pulse-verify","order":104,"swatchColor":"#f97316","groupKey":"電子を1粒単位で正確に注ぐ_階段パルス_C104_少しずつ電圧を","assembledPos":[-7.4,8.6,0.46],"explodeOffset":[-108,72,16],"integratedExplodeOffset":[-108,72,16],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C104. 適応型ステップ昇圧書込（A-ISPP）＆セルフブースト非選択セル書込禁止","subtitle":"Adaptive Incremental Step Pulse Programming (A-ISPP) & Self-Boosted Program Inhibit","category":"電子を1粒単位で正確に注ぐ「階段パルス」 C104 — 少しずつ電圧を上げて測り直し、隣りのセルにはバリアを張る！","plainAnalogy":"TLC（8段階）やQLC（16段階）のメモリセルにデータを書き込むのは、目盛り付きの小さな試験管に電子をピタリの高さまで注ぐ精密作業です。一気にドバッと高い電圧をかけると溢れて隣の値と混ざってしまいます。そこで「ちょっと電圧をかけて（例：15 V）→高さを確認（ベリファイ）→足りなければ0.3 Vだけ上げてまた確認…」という階段作戦（ISPP）を繰り返します！さらに同じ横並びの「書き換えたくないセル」は、内部を8 Vにプカプカ浮かせる「セルフブースト保護バリア」で誤書込を防ぐんです！","summary":"3D NANDの多値（TLC 8状態／QLC 16状態）しきい値電圧（Vth）分布を極限までシャープに揃える「ステップ昇圧書込＋ベリファイ（ISPP）」と、同一ワード線上の非選択ストリングを保護する「セルフブースト書込禁止（Program Inhibit）」回路機構です。","opticsAndPhysics":["ISPPでは開始電圧 V_start（約14〜16 V）からステップ幅 ΔV_ISPP（約0.2〜0.5 V）ずつ階段状に昇圧パルスを印加し、1パルスごとに目標Vthに到達したセルをビット線電圧（Vdd）でロック（書込完了）します。","非選択ストリングは選択ゲート（SGD）を閉じてチャネルを電気的に浮遊（フローティング）状態にし、ワード線のVpass（約8〜10 V）との容量結合でチャネル電位を約7〜8 Vへ自動昇圧（Self-Boosting）することで、ゲート-チャネル間電界を弱めて誤書込（Program Disturb）を防ぎます。","2026年発表の適応型A-ISPP＋ISPE方式では、低い目標値では細かく、高い目標値では素早くステップ幅を可変制御し、Vth分布のばらつき（ΔVth）を従来比約38〜60%も狭める成果が示されています。"],"formula":{"expression":"V_pgm(n) = V_start + (n − 1) · ΔV_ISPP,   V_ch,boost ≈ C_ox/(C_ox + C_dep) · V_pass","description":"理想ISPP勾配（ΔVth / ΔV_ISPP ≈ 1）を維持しつつ、非選択チャネルを容量結合で自動昇圧して誤書込を完全防止。"},"nextGenInnovation":"2025〜2026年の次世代QLC/TLC 3D NANDでは、ベリファイ回数を間引くNV-APPやニューラルネットワーク最適化パルス波形により、書込速度（tPROG）を高速化しながらVPG800/1600の安定持続書込を支えています。","specs":[{"label":"書込パルス範囲","value":"V_pgm ≈ 14 V → 25 V（ΔV_ISPP: 0.2〜0.5 V）"},{"label":"非選択保護機構","value":"Local Self-Boosting（チャネル自動昇圧 ~8 V）"},{"label":"A-ISPP改善効果","value":"Vthばらつき最大 38〜60% 縮小 / 保持 +43%"},{"label":"対応セル方式","value":"pSLC（2値）/ TLC（8値）/ QLC（16値）"}],"diagramType":"cfe_ispp_step_pulse_verify"},{"id":"cfe-wafer-backside-stress-sin","order":105,"swatchColor":"#0ea5e9","groupKey":"332層積んで反り返るウェハを裏から真っ直ぐに_C105_最大1","assembledPos":[-4.6,15.6,-0.45],"explodeOffset":[-82,114,-8],"integratedExplodeOffset":[-82,114,-8],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C105. 332〜400層ウェハ反り矯正・裏面高応力PVD SiN/SiON応力補償膜","subtitle":"3D NAND Backside High-Stress PVD SiN/SiON Wafer Bow & Warpage Compensation Film","category":"332層積んで反り返るウェハを裏から真っ直ぐに！ C105 — 最大1800 MPaの力で鏡のように平らへ戻す「背骨のコルセット」","plainAnalogy":"紙の片面だけに何十回も分厚い絵の具を塗ると、紙がクルッと弓なりに反り返ってしまいますよね。332〜400層もの金属とガラスを片面に積み上げる2026年の3D NANDウェハも、何もしないとポテトチップスのように大きく反ってしまい、レーザー露光もウェハ貼り合わせ（CBA）もズレて失敗します！そこでウェハの「裏側」にわざと強い押し返す力（400〜1800 MPaの圧縮応力）を持つ窒化シリコン膜をスパッタ成膜し、反りを1ミクロン単位でピシッと真っ直ぐ矯正しているんです！","summary":"300〜400層超の超高層3D NAND製造工程で発生する巨大なウェハ反り（Bow / Warpage）を裏面側から相殺するため、反応性スパッタ（PVD）で成膜される応力可変SiN / SiON補償膜です。","opticsAndPhysics":["332層以上の多層ONON/OPOP積層と金属置換（RMG）はウェハ表面へ数百MPa〜GPa級の残留応力を生み、直径300 mmウェハが最大1000 μm（1 mm！）近くも反るため、リソグラフィの焦点ズレやCBAハイブリッド接合の位置ずれを引き起こします。","2026年8月に大手3D NANDメーカーで量産認定が報じられた高応力PVD SiN/SiON膜は、同一膜厚のまま圧縮応力を 400〜1800 MPa（>1.2 GPa）の範囲で精密調整でき、従来のPECVD法より2〜3倍高い反り矯正効率を実現します。","非対称な鞍型（サドル型）反りに対しては、ウェハ裏面の局所的な成膜厚プロファイル制御や裏面トレンチ構造を併用し、CBAウェハ貼り合わせ前の平坦度を極限まで整えます。"],"formula":{"expression":"σ_f = (E_s · t_s²) / (6 · (1 − ν_s) · t_f · R)   [Stoneyの式]","description":"ストーニー（Stoney）の公式。表面積層膜が作る曲率半径 R を、裏面補償膜の応力 σ_f と膜厚 t_f で正確にゼロへ打ち消す。"},"nextGenInnovation":"2026年の400層級3D NANDおよびCBAウェハ間接合では、裏面高応力PVD SiN膜を犠牲層として工程ごとに貼り替え・ウェット除去する高度なストレスエンジニアリングが歩留まりを左右する核心技術となっています。","specs":[{"label":"補償膜材料","value":"反応性スパッタ PVD SiN / SiON（犠牲応力膜）"},{"label":"圧縮応力レンジ","value":"400〜1,800 MPa（>1.2 GPa チューナブル）"},{"label":"反り矯正能力","value":"最大 1,000 μm 級ウェハ反り補正（PECVD比 2〜3倍）"},{"label":"主な貢献工程","value":"サブ30 nm露光オーバーレイ ＆ CBAハイブリッド接合"}],"diagramType":"cfe_wafer_backside_stress_sin"},{"id":"cfe-sicn-cmp-sub2nm-dishing","order":106,"swatchColor":"#d97706","groupKey":"原子0_5_nmの鏡面が触れた瞬間ピタッと融合_C106_銅の凹","assembledPos":[0.5,16.4,-0.32],"explodeOffset":[-48,124,-18],"integratedExplodeOffset":[-48,124,-18],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C106. CBAハイブリッド接合 SiCN誘電体界面＆サブ2 nm超精密CMPディッシング制御","subtitle":"SiCN Hydrophilic Dielectric Interface & Sub-2 nm Cu CMP Dishing Hybrid Bonding","category":"原子0.5 nmの鏡面が触れた瞬間ピタッと融合！ C106 — 銅の凹みを2 nm未満に抑え込むハイブリッド接合の芸術","plainAnalogy":"BiCS10のメモリ側ウェハと回路側ウェハを貼り合わせる「ハイブリッド接合」には、接着剤もハンダも一切使いません！2枚のウェハ表面を「地球全体を磨いても凹凸がビー玉1個分以下」というレベル（粗さ0.5 nm未満）まで化学機械研磨（CMP）で鏡面磨きし、プラズマで水になじむ手（Si-OH基）を生やして重ねると、常温で分子同士がスッと吸い付いて結合！その後250℃以下で温めると、2 nm未満だけわざと引っ込めておいた銅パッド同士が熱膨張してピタッと一体化するんです！","summary":"Kioxia/Sandisk BiCS8/BiCS10のCBA構造を支える、炭窒化シリコン（SiCN）誘電体どうしの常温自発接合と、サブ2 nm精度の化学機械研磨（CMP）による銅パッド・ディッシング（凹み）制御界面です。","opticsAndPhysics":["従来のSiO2接合膜に代わり採用が進むSiCN（炭窒化シリコン）は、高い結合エネルギー・銅拡散バリア性・ボイド抑止力を併せ持ち、250℃以下の低温アニールでの強固なハイブリッド接合を可能にします。","CMP研磨後に銅パッドが周囲のSiCNより凹みすぎる（ディッシング過大）と銅同士が触れずオープン不良になり、飛び出しすぎる（プロトルージョン）とSiCNがくっつかずボイドが発生します。2025〜2026年の先端プロセスではディッシングを 2 nm 未満、SiCN粗さを 0.5 nm RMS 未満、段差傾き（ロールオフ）を 1 nm/μm 未満へ管理します。","2025年のASMEレビュー論文で紹介されたソニーの超微細CMP技術では、0.4 μmピッチ（銅パッド径0.2 μm）でのボイドレスCu-Cu接合まで実証されており、3D NANDの高密度CBA化を牽引しています。"],"formula":{"expression":"Δh_Cu = α_Cu · L_Cu · ΔT ≥ d_dishing   (d_dishing < 2 nm,  Ra_SiCN < 0.5 nm)","description":"アニール時の銅の熱膨張量 Δh_Cu がCMPディッシング量 d_dishing を正確に埋めて隙間ゼロのCu-Cu金属拡散結合を完成させる。"},"nextGenInnovation":"2026年7月公開の最新研究では、プラズマ活性化による表面Si-OH基密度制御が接合波（Bond Wave）速度とウェハ歪みを決めるメカニズムが解明され、サブミクロン級の歩留まりがさらに向上しています。","specs":[{"label":"接合誘電体膜","value":"SiCN（高結合強度・Cu拡散防止・ボイド抑制）"},{"label":"CMP平坦精度","value":"SiCN粗さ < 0.5 nm RMS / Cuディッシング < 2 nm"},{"label":"接合プロセス","value":"N2/O2プラズマ親水化 → 常温自発接合 → <250℃アニール"},{"label":"先端ピッチ実証","value":"0.4〜1.4 μm ピッチ（ソニー 0.4 μm 実証）"}],"diagramType":"cfe_sicn_cmp_sub2nm_dishing"},{"id":"cfe-stealth-dicing-mod-layer","order":107,"swatchColor":"#ef4444","groupKey":"表面無傷で中だけ切る_透視レーザー_C107_25_mの紙より薄","assembledPos":[-9.2,12.2,-0.58],"explodeOffset":[-114,48,-14],"integratedExplodeOffset":[-114,48,-14],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C107. 25 μm極薄NANDウェハ「ステルスダイシング」近赤外1117 nm内部改質層（MOD）","subtitle":"25 μm Thin-Wafer Stealth Dicing (1117 nm NIR Subsurface Modified Layer)","category":"表面無傷で中だけ切る「透視レーザー」 C107 — 25 μmの紙より薄いチップを欠けゼロで切り分ける近赤外魔法！","plainAnalogy":"1枚のCFexpressカードに16枚ものNANDチップを重ねるため、チップの厚みはコピー用紙の3分の1以下（約25〜30 μm）まで極限に薄く削ります。こんな超極薄ガラス板を普通のダイヤモンドカッター（ノコギリ）で切ると、端がボロボロに欠けて（チッピング）割れてしまいます！そこで使うのが「ステルスダイシング」。シリコンを透明に通り抜ける波長1117 nmの赤外線レーザーを「内部の1点だけ」に集光して見えないミシン目（改質層）を作り、テープを横に軽く引っ張るだけでパキッと鏡のように綺麗に割るんです！","summary":"25〜30 μm厚の超極薄3D NANDウェハを無塵・無水・チッピングゼロで個片化する、近赤外パルスレーザー（約1064〜1117 nm）による内部改質層（MOD Layer）形成＆テープエキスパンド分離構造です。","opticsAndPhysics":["単結晶シリコンのバンドギャップは 1.12 eV（吸収端波長 約1107 nm）であるため、波長約1117 nmの近赤外パルスレーザーはシリコン表面をほとんど透過し、レンズで絞った内部焦点だけで多光子吸収・自由キャリア吸収を起こして局所溶融・再凝固による改質層（MOD層）を形成します。","表面を削るブレードダイシングやレーザーアブレーションと異なり、デブリ（切りくず）や熱変質（リキャスト）が回路面に一切飛ばず、スクライブライン（切り代）幅を極小化して1ウェハあたりのチップ取得数を増やせます。","2025〜2026年の半導体シンギュレーション研究では、1 W級の超低平均出力・ナノ秒／フェムト秒マルチスキャン制御により、内部マイクロクラックの進展深さをミクロン精度で揃え、16段スタック時の極薄ダイ抗折強度を飛躍的に高めています。"],"formula":{"expression":"λ_cutoff = h·c / E_g ≈ 1240 / 1.12 eV ≈ 1107 nm   (Stealth Laser λ ≈ 1117 nm)","description":"シリコンのバンドギャップよりわずかに低い光子エネルギーを選ぶことで、表面透過と焦点内部限定の多光子吸収を両立。"},"nextGenInnovation":"2025〜2026年の先端積層NAND工場では、裏面研削（DBG: Dicing Before Grinding）や極薄DAF（Dicing Die Attach Film）とステルスダイシングを統合し、25 μm極薄チップの欠け・割れ不良を極限まで排除しています。","specs":[{"label":"レーザー波長","value":"近赤外 約 1064〜1117 nm（Si透過ウィンドウ）"},{"label":"対象ウェハ厚","value":"25〜30 μm 級 極薄積層3D NANDダイ"},{"label":"分離メカニズム","value":"内部焦点MOD改質層＋マイクロクラック → テープ拡張分離"},{"label":"最大利点","value":"ドライ加工・デブリゼロ・チッピング極小・狭切り代"}],"diagramType":"cfe_stealth_dicing_mod_layer"},{"id":"cfe-fenand-hzo-igzo-2026","order":108,"swatchColor":"#d946ef","groupKey":"未来のCFexpress_5_0_6_0を変える2026年大発見","assembledPos":[3.2,17.8,0.62],"explodeOffset":[-16,126,10],"integratedExplodeOffset":[-16,126,10],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C108. 2026年次世代フロンティア：強誘電体 HZO（Hf0.5Zr0.5O2）＋a-IGZO酸化物チャネル FeNANDセル","subtitle":"2026 Frontier: Ferroelectric Hf0.5Zr0.5O2 (HZO) + a-IGZO Oxide-Channel 3D FeNAND","category":"未来のCFexpress 5.0/6.0を変える2026年大発見！ C108 — 電子を壁越しに飛ばさず「電気の磁石」を反転させる次世代FeNAND！","plainAnalogy":"今の3D NANDは「電子を強い電圧で壁の向こうへ無理やり押し込む」ため、書き込むたびに壁が少しずつ傷み、25 Vもの高電圧も必要です。そこで2026年にimecや東京大学・各社が猛スピードで開発しているのが「強誘電体メモリ（FeNAND）」！ハフニウムとジルコニウムの特殊結晶（HZO）は、小さな電圧をかけるだけで内部の電気のプラス・マイナス（分極）がクルッと反転してそのまま記憶します。電子を壁に叩きつけないので寿命が圧倒的に長く、消去速度も理論上最大1万倍速い次世代フラッシュの大本命なんです！","summary":"2026年6月にimecが3D積層実証を発表し、2026年10月のarXiv総説でも3D NANDの次世代本命と位置づけられた、直方晶強誘電体ハフニウム・ジルコニウム酸化物（HZO: Hf0.5Zr0.5O2）とアモルファス酸化物半導体チャネル（a-IGZO）を組み合わせた次世代3D FeNANDセル構造です。","opticsAndPhysics":["従来のポリシリコンチャネルは粒界欠陥による電流ばらつきと高電圧（~25 V）が必要でしたが、アモルファスIGZO（InGaZnO）酸化物半導体チャネルは低温成膜（バックエンド互換）が可能でオフ電流が極めて小さく、強誘電体HZOの分極反転と組み合わせることで低電圧・高速動作を実現します。","2026年9〜11月の最新デバイス論文では、HZOとAl2O3/SiO2/HfO2界面層の最適化により QLC多値記録に十分な 11 V〜17.8 V もの巨大なメモリ窓（Memory Window）と10年データ保持・ΔVth ≤ 0.1 Vの耐ディスターブ特性が実証されています。","さらに強誘電体セルとシリコンピラー消去を組み合わせた構造では、従来のGIDL消去に対して約1 μs（最大10,000倍高速）の消去ポテンシャルも報告されており、将来の超高層500〜1,000層時代の突破口として注目されています。"],"formula":{"expression":"MW = 2 · E_c · t_FE   (HZO: Hf_0.5 Zr_0.5 O_2,  2026実証 MW = 11〜17.8 V)","description":"強誘電体膜の抗電界 E_c と膜厚 t_FE、および界面誘電体層の電荷結合設計によりQLC対応の広大なメモリ窓を形成。"},"nextGenInnovation":"2026年6月のimecプレス発表および2026年10月arXiv「The future of 3D NAND flash technology」で実証加速中のFe-VNANDは、2028〜2030年代の超大容量・超低消費電力CFexpressカードへ繋がる最先端研究ロードマップの頂点です。","specs":[{"label":"強誘電体材料","value":"直方晶 Hf0.5Zr0.5O2（HZO）薄膜"},{"label":"チャネル半導体","value":"アモルファス酸化物半導体 a-IGZO（低温成膜・超低リーク）"},{"label":"2026実証メモリ窓","value":"11 V〜17.8 V（QLC 16値記録に対応可能）"},{"label":"理論ポテンシャル","value":"低電圧書換・超高耐久・高速分極反転消去"}],"diagramType":"cfe_fenand_hzo_igzo_2026"},{"id":"cfe-sac305-imc-cu6sn5-cu3sn","order":109,"swatchColor":"#94a3b8","groupKey":"ハンダと銅の境目に生まれる_ホタテ貝の結晶_C109_強すぎても","assembledPos":[5.6,10.2,-0.62],"explodeOffset":[38,116,-24],"integratedExplodeOffset":[38,116,-24],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C109. BGAはんだ接合界面 Cu6Sn5 / Cu3Sn 金属間化合物（IMC）＆カーケンダルボイド抑止層","subtitle":"SAC305 Solder Joint Scalloped η-Cu6Sn5 / Planar ε-Cu3Sn IMC & Kirkendall Void Guard","category":"ハンダと銅の境目に生まれる「ホタテ貝の結晶」 C109 — 強すぎても弱すぎてもダメな1ミクロンの金属接着剤！","plainAnalogy":"チップと基板をくっつける鉛フリーはんだ（SAC305：スズ・銀・銅）は、溶けて銅パッドに触れた瞬間に化学反応を起こし、境目に「ホタテ貝が並んだような結晶の壁（Cu6Sn5）」を作ります。この結晶（IMC）があるおかげでハンダは強固にくっつくのですが、8K撮影の熱で長年温められ続けると結晶が分厚く脆くなり、下に「カーケンダルボイド」というミクロの空洞（虫食い穴）ができて衝撃でパキッと折れてしまいます！だから理想的な1〜3 μm厚の結晶に抑える冷却制御とNiバリアがTOUGH耐久の隠れた主役なんです！","summary":"BGAはんだボール（SAC305: Sn-3.0Ag-0.5Cu）と銅パッドの接合界面に生成される、ホタテ貝状の η-Cu6Sn5 相および平板状の ε-Cu3Sn 相からなる金属間化合物（IMC）層と、熱エージング時のカーケンダル空孔（Kirkendall Voids）抑止構造です。","opticsAndPhysics":["2026年材料解析論文のナノインデンテーション実測によると、弾性率は Cu6Sn5 が 125 GPa、Cu3Sn が 136 GPa、Ni3Sn4 が 142 GPa と軟らかいβ-Snはんだ母材よりはるかに硬く脆いため、IMC厚さが厚くなりすぎると落下衝撃（7.5 m落下）時のせん断応力がIMC界面に集中してへき開破壊を起こします。","リフロー後の高温使用中に銅原子がスズ側へ拡散し続けると、Cu3Sn層と銅パッドの界面に原子拡散速度差による微細空孔「カーケンダルボイド」が連なり、接合破壊靭性が急低下します。","パッド側にニッケル（Ni）拡散バリア層を設けて (Cu,Ni)6Sn5 相へ改質しつつリフロー冷却速度を精密制御することで、Cu3Sn成長とカーケンダルボイドを劇的に抑え込みます。"],"formula":{"expression":"x_IMC(t) = x_0 + k · t^n · exp(−Q / (R · T))   (n ≈ 0.36–0.41)","description":"IMC厚さは時間の約0.4乗とアレニウス熱拡散則で成長するため、低温動作とNiバリアによる拡散活性化エネルギー制御が長寿命の鍵。"},"nextGenInnovation":"2025〜2026年の先端パッケージ研究では、機械学習によるSEM断面IMC自動解析に加え、低温リフローで基板反りを減らすSn-Bi系ナノ粒子強化はんだや微量Ni/Ag添加によるIMC微細化が進展しています。","specs":[{"label":"はんだ合金","value":"SAC305（Sn-3.0%Ag-0.5%Cu 鉛フリー）"},{"label":"界面金属間化合物","value":"η-Cu6Sn5（125 GPa）/ ε-Cu3Sn（136 GPa）/ (Cu,Ni)6Sn5"},{"label":"適正IMC膜厚","value":"リフロー直後 1〜3 μm（過成長・空孔を防止）"},{"label":"破壊抑止機構","value":"Ni拡散バリアによるカーケンダルボイド＆粒界亀裂防止"}],"diagramType":"cfe_sac305_imc_cu6sn5_cu3sn"},{"id":"cfe-cu-pillar-ubm-trilayer","order":110,"swatchColor":"#ea580c","groupKey":"6nmコントローラを支える極細_銅の柱_C110_激しい電流の押","assembledPos":[7.4,7.6,-0.52],"explodeOffset":[72,108,-32],"integratedExplodeOffset":[72,108,-32],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C110. フリップチップ極細銅ピラー＆3層UBM（Ti密着／Cu種膜／Ni拡散障壁）構造","subtitle":"Flip-Chip 60 μm Copper Pillar Bump & Ti/Cu/Ni Trilayer Under-Bump Metallization (UBM)","category":"6nmコントローラを支える極細「銅の柱」 C110 — 激しい電流の押し合い（エレクトロマイグレーション）を跳ね返す3層台座！","plainAnalogy":"コントローラチップの裏側には何百本もの配線を繋ぐ端子がびっしり並んでいますが、普通の丸いハンダ玉（C4バンプ）は溶けると横に潰れて隣とくっつきやすく、しかも電流が入口に集中して原子を吹き飛ばす「エレクトロマイグレーション」で痩せ細ってしまいます。そこで最新チップは、溶けない頑丈な「銅の柱（Cuピラー）」をずらりと立て、先端だけに薄いハンダ帽子をかぶせます！根元の「チタン（糊）＋銅（種）＋ニッケル（壁）」の3層台座（UBM）が熱と大電流から接合を守り抜くんです！","summary":"6nm/7nmコントローラダイをABFパッケージ基板へ高密度フリップチップ接続する、銅ピラー（Cu Pillar）バンプと、Ti（密着）／Cu（シード）／Ni（拡散バリア）の3層アンダーバンプメタライゼーション（UBM）構造です。","opticsAndPhysics":["従来の丸型はんだバンプはリフロー時に横へ広がるため微細ピッチ化に限界がありますが、高さ約40〜62 μmの電解めっき銅ピラーはリフロー中も溶融せず柱形状を保つため、狭ピッチ化とスタンドオフ確保を同時に実現します。","大電流が薄いチップ配線からバンプへ曲がり込む「電流集中（Current Crowding）」箇所では電子風力による原子移動（エレクトロマイグレーション）でパンケーキ状ボイドが発生しますが、厚い銅ピラーが電流密度を均一に分散し寿命（MTTF）を大幅に延ばします。","根元のTi/Cu/Ni 3層UBMは、チップのパッシベーション膜との強固な密着（Ti）、電解めっき通電層（Cu）、そしてスズと銅の過剰反応を防ぐ障壁（Ni 約3〜4 μm）の3役を分担します。"],"formula":{"expression":"MTTF = A · J^(−n) · exp(E_a / (k_B · T))   [Blackの式：エレクトロマイグレーション寿命]","description":"電流密度 J を銅ピラーで均一低減し、温度 T を下げることでフリップチップ接合寿命 MTTF が飛躍的に延びる。"},"nextGenInnovation":"2025〜2026年の先端パッケージでは、Cuピラーの微細化（ピッチ35〜50 μm）と熱圧着接合（TCB）やMR-MUF一括封止を組み合わせ、モバイル・カメラ用小型コントローラの熱疲労耐性を極限まで高めています。","specs":[{"label":"バンプ構造","value":"Cuピラー（高 40〜62 μm）＋ Ni（~4 μm）＋ SACはんだキャップ"},{"label":"UBM 3層構成","value":"Ti（密着層）／ Cu（シード層）／ Ni（拡散バリア）"},{"label":"物理的メリット","value":"電流集中緩和・エレクトロマイグレーション耐性向上・狭ピッチ対応"},{"label":"適用箇所","value":"6nm/7nm PCIe 4.0 コントローラダイ ↔ ABF基板"}],"diagramType":"cfe_cu_pillar_ubm_trilayer"},{"id":"cfe-pdcu-wirebond-fab-imc","order":111,"swatchColor":"#f59e0b","groupKey":"パラジウムの鎧をまとった極細銅ワイヤ_C111_金より電気を通し","assembledPos":[8.6,13.4,-0.42],"explodeOffset":[104,92,-38],"integratedExplodeOffset":[104,92,-38],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C111. パラジウム被覆銅（PdCu）ワイヤボンド＆フリーエアボール（FAB）Cu-Al-Pd耐腐食接合","subtitle":"Palladium-Coated Copper (PdCu) Wirebond, Free-Air-Ball (FAB) & Cu-Al-Pd IMC","category":"パラジウムの鎧をまとった極細銅ワイヤ C111 — 金より電気を通し、塩素や熱のサビも跳ね返す20 μmの神経線！","plainAnalogy":"昔はNANDチップと基板を繋ぐ極細ワイヤはすべて「純金（Au）」でした。でも純金は高価なうえ、実は「銅」のほうが電気も熱も約25%よく通して強度も高いんです！ただし裸の銅はすぐサビて塩素イオンで腐食する弱点がありました。そこで生まれたのが、髪の毛の4分の1ほどの極細銅線の周りに貴金属パラジウム（Pd）をナノレベルでコーティングした「PdCuワイヤ」！放電で先端を丸い玉（FAB）にして超音波圧着すると、パラジウムが接合部に溶け込んでサビも空洞も防ぐ最強の神経線になるんです！","summary":"16段積層NANDダイのアルミパッドとパッケージ基板を接続する、パラジウム被覆銅（PdCu / PCC）極細ボンディングワイヤ（径約18〜23 μm）と、電気トーチ放電（EFO）で形成されるフリーエアボール（FAB）および耐腐食Cu-Al-Pd金属間化合物接合です。","opticsAndPhysics":["銅（抵抗率 1.72×10^-8 Ω·m、熱伝導率 400 W/m·K）は金（2.2×10^-8 Ω·m、320 W/m·K）より低抵抗・高放熱かつ高剛性（ヤング率 130 GPa vs 60 GPa）なため、16段スタックの長いワイヤループでも樹脂封止時のワイヤ流れ（Wire Sweep）を大幅に抑えられます。","純金ワイヤは高温放置（HTSL）時にAu-Al IMCが速く成長してカーケンダルボイドを起こしやすいのに対し、PdCuワイヤではCu-Al IMC成長速度が格段に遅く、さらに分散したパラジウムがCu-Al-Pd三元IMCを形成して塩素イオン（Cl-）による湿熱（HAST）腐食を強力にブロックします。","先端のフリーエアボール（FAB）はフォーミングガス（N2+5%H2）雰囲気下で酸化を防ぎながら柱状晶・微細亜結晶へ凝固させ、下の3D NAND回路にダメージ（クレータリング）を与えない絶妙な超音波エネルギーで接合されます。"],"formula":{"expression":"R_wire = ρ · L / (π · r²),   ρ_Cu = 1.72×10^-8 Ω·m < ρ_Au = 2.20×10^-8 Ω·m","description":"PdCuワイヤは純金より約22%低抵抗・約25%高熱伝導で、4.8 Gb/s高速Toggle信号の電圧降下と発熱を低減。"},"nextGenInnovation":"最新の16段積層NANDパッケージでは、PdCuワイヤに加えてイオン捕捉剤（イオントラッパー）配合の低ハロゲンEMC封止樹脂と組み合わせることで、過酷な高温高湿環境（85℃/85%RH HAST）でも極めて高い長期信頼性を達成しています。","specs":[{"label":"ワイヤ材質・線径","value":"Pd被覆銅（PdCu / PCC）径 約 18〜23 μm"},{"label":"電気・熱特性","value":"抵抗率 1.72 μΩ·cm / 熱伝導 400 W/m·K（金より優位）"},{"label":"接合界面相","value":"薄層 Cu-Al-Pd 三元IMC（Cl-腐食・空孔を抑止）"},{"label":"活性化エネルギー","value":"PdCu ボールボンド E_aa ≈ 0.85 eV（HTSL 4800h+ 耐久）"}],"diagramType":"cfe_pdcu_wirebond_fab_imc"},{"id":"cfe-fow-film-over-wire-stack","order":112,"swatchColor":"#38bdf8","groupKey":"下のワイヤを潰さず包み込む_魔法のクッション糊_C112_16枚","assembledPos":[9.4,15.8,-0.25],"explodeOffset":[126,66,-26],"integratedExplodeOffset":[126,66,-26],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C112. 16段極薄NAND積層用「フィルムオーバーワイヤ（FOW）」埋込接着フィルム","subtitle":"2026 Film-Over-Wire (FOW) Non-Conductive Encapsulating Die Attach Film (<10–35 μm)","category":"下のワイヤを潰さず包み込む「魔法のクッション糊」 C112 — 16枚の極薄シリコンを傾き・気泡ゼロで重ねる極意！","plainAnalogy":"25 μmの超極薄NANDチップを16枚も縦に重ねるとき、下のチップから出ている極細ワイヤの上にそのまま次のチップを載せたら、ワイヤが押し潰れてショートしてしまいます！昔はわざわざ間にダミーのスペーサー板を挟んで厚くなっていましたが、今の切り札が「フィルムオーバーワイヤ（FOW）」。上段チップの裏にあらかじめ貼った絶縁フィルムが、熱と圧力でハチミツのように柔らかく溶けて下のワイヤをふわっと隙間なく包み込み、そのままカチッと固まるから、薄くて頑丈な16段タワーが実現できるんです！","summary":"16段以上の多段積層3D NANDパッケージで、下段ダイのボンディングワイヤループを空隙（ボイド）なく埋め込みながら上段ダイを水平に搭載するための、熱可塑・熱硬化ハイブリッド型絶縁接着フィルム（FOW: Film-Over-Wire）です。","opticsAndPhysics":["液状ペースト接着剤は厚みがばらついてダイが傾いたり端からはみ出したり（ブリード）しますが、フィルム型のDAF/FOWは全面がミクロン精度で均一なボンドライン厚（BLT）を保証します。","FOWフィルムはダイボンディング温度（約100〜130℃）で一時的に低粘度化して下段ワイヤのループ周辺へ気泡（ボイド）を残さず回り込み、ワイヤを押し倒すことなく絶縁保護した後、ポストキュア加熱で架橋硬化して強固な機械支持層となります。","2026年10月の市場・技術レポートによれば、積層段数の増加に伴い10 μm未満の超極薄DAFやダイシングテープ一体型DDAF（レゾナック・日東電工・リンテック・LG化学・ヘンケル等）が16DP超大容量NANDの必須材料となっています。"],"formula":{"expression":"H_pkg = N_die · (t_Si + t_FOW) + t_sub + t_mold   (N=16, t_Si≈25μm, t_FOW≈10–35μm)","description":"スペーサー用ダミーシリコンを排除し、FOW厚と極薄25 μmダイ厚の最小化で1.2 mm以下の超薄BGAパッケージへ16枚収容。"},"nextGenInnovation":"2026年はLG化学・日東電工・レゾナック・住友ベークライトなどが高熱伝導・低反り・10 μm未満極薄FOW/DDAF生産ラインを大幅増強しており、1.92 TB〜4 TB超の小型CFexpress Type Aカード実現の影の立役者です。","specs":[{"label":"フィルム方式","value":"FOW（Film-Over-Wire）非導電性エポキシ接着フィルム"},{"label":"フィルム膜厚","value":"標準 15〜35 μm（超薄DAF層は <10 μm 級）"},{"label":"主要機能","value":"下段ワイヤ無損傷埋込・ボイドレス封止・ダイ傾斜防止"},{"label":"代表材料メーカー","value":"日東電工・レゾナック・リンテック・LG化学・Henkel"}],"diagramType":"cfe_fow_film_over_wire_stack"},{"id":"cfe-ula-silica-emc-filler","order":113,"swatchColor":"#64748b","groupKey":"チップを包む黒い鎧は_88_が超高純度ガラスの玉_C113_樹脂","assembledPos":[10.2,6.2,-0.74],"explodeOffset":[132,34,-42],"integratedExplodeOffset":[132,34,-42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C113. 超低アルファ線（ULA）球状溶融シリカ88 wt%充填EMC封止樹脂＆ソフトエラー抑止","subtitle":"Ultra-Low-Alpha (ULA) 88 wt% Spherical Fused-Silica Epoxy Molding Compound","category":"チップを包む黒い鎧は「88%が超高純度ガラスの玉」 C113 — 樹脂自身の放射線によるデータ化けまで防ぐ究極の封止材！","plainAnalogy":"チップを包む真っ黒なプラスチック（EMC）は、実は単なるプラスチックではありません！中身の実に85〜90%は、目に見えないほど小さな「ツルツルの丸いガラスの玉（球状溶融シリカ）」がギッシリ詰まっています。なぜ？プラスチックだけだと熱で大きく伸び縮みしてシリコンチップを引きちぎってしまうから！さらに天然の砂にはごく微量のウランやトリウムが含まれていて、出すアルファ線がメモリの0と1を書き換える（ソフトエラー）ため、放射線をほぼゼロ（ULAグレード）まで精製した超高純度ガラス玉を使っているんです！","summary":"コントローラや3D NANDパッケージを封止するエポキシモールド樹脂（EMC）内部に85〜90 wt%の高密度で配合される、超低アルファ線（ULA: <0.002 cph/cm²）球状溶融シリカ（SiO2）フィラーマトリクスです。","opticsAndPhysics":["純エポキシ樹脂の熱膨張係数（CTE ≈ 60 ppm/°C）はシリコン（2.6 ppm/°C）の20倍以上もありますが、低膨張の球状溶融シリカ（0.5 ppm/°C）を85〜90 wt%まで最密充填することで、EMC全体のCTEを 7〜9 ppm/°C まで引き下げて熱サイクル時のパッケージ反り・ワイヤ断線を防ぎます。","微粒子の角が尖っていると16段積層ワイヤを傷つけるため、火炎溶融法で真球状に加工し、大・中・小の粒度分布を最適化して超狭い隙間にもボイドなく流動充填させます。","天然シリカ中のppbレベルのウラン（U）・トリウム（Th）が崩壊して放つアルファ粒子は、シリコン内で大量の電子正孔対を生み出してSRAMキャッシュやロジックのビット反転（SER: ソフトエラー）を引き起こすため、超低アルファ線（ULA: <0.001〜0.002 counts/hr/cm²）精製シリカが不可欠です。"],"formula":{"expression":"CTE_EMC ≈ (1 − φ) · CTE_resin + φ · CTE_SiO2   (φ ≈ 0.85–0.90 wt% → 7–9 ppm/°C)","description":"真球状シリカの高充填により、流動性を保ちながら熱膨張係数をシリコン＆ABF基板へ精密整合させる。"},"nextGenInnovation":"2025〜2026年の超薄型・高発熱パッケージでは、球状シリカに加えてアルミナ（Al2O3）や窒化ホウ素（BN）をハイブリッド配合した高熱伝導・超低アルファEMCや、PdCuワイヤ腐食を防ぐイオントラッパー添加樹脂が標準化しています。","specs":[{"label":"フィラー配合率","value":"球状溶融シリカ（SiO2）約 85〜90 wt%"},{"label":"アルファ線放出率","value":"ULAグレード < 0.001〜0.002 cph/cm²"},{"label":"熱膨張係数（CTE）","value":"約 7〜9 ppm/°C（シリコン・基板と精密整合）"},{"label":"添加機能剤","value":"カーボンブラック遮光剤 ＋ ハロゲン捕捉イオントラッパー"}],"diagramType":"cfe_ula_silica_emc_filler"},{"id":"cfe-wafer-11n-cz-monocrystal","order":114,"swatchColor":"#38bdf8","groupKey":"1000億個の原子に不純物1個以下_C114_すべての超微細チッ","assembledPos":[1.8,12.2,-0.78],"explodeOffset":[18,122,-62],"integratedExplodeOffset":[18,122,-62],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C114. 11N超高純度（99.999999999%）CZ単結晶シリコンインゴット＆{100}格子面方位","subtitle":"11N Electronic-Grade (99.999999999%) Czochralski {100} Monocrystalline Silicon Wafer","category":"1000億個の原子に不純物1個以下！ C114 — すべての超微細チップの土台となる「11N単結晶シリコン」","plainAnalogy":"332層NANDも6nmコントローラも、すべてのスタート地点は「砂（石英）」から作られるシリコンウェハです。ただし普通の砂では不純物だらけで電気がデタラメに流れてしまいます。そこでトクヤマや信越化学・SUMCOなどの世界トップメーカーが、塩素ガス化学精製（シーメンス法）で純度99.999999999%（ナインが11個＝11N！）まで磨き上げ、1420℃で溶かして1本の継ぎ目ない巨大結晶（インゴット）へ引き上げます。原子1000億個の中に不純物が1個もない究極の結晶板が、1.92 TBの記憶を支える大地なんです！","summary":"CFexpressカード内部の全半導体ダイ（3D NANDおよび6nm/7nmコントローラ）の基盤となる、純度11N（99.999999999%）電子級ポリシリコンからチョクラルスキー（CZ）法で引き上げられた直径300 mm・{100}面方位単結晶シリコンウェハです。","opticsAndPhysics":["シーメンス法でトリクロロシランガスを精製・析出させた11N級ポリシリコンを石英るつぼ内で溶融し、種結晶を回転させながらゆっくり引き上げるCZ法で転位（結晶のズレ）ゼロの単結晶インゴットを育成します。","ダイヤモンドワイヤ切断・両面鏡面研磨（CMP）を経て、表面原子配列が最もMOSFET界面準位密度（D_it）を低く抑えられる結晶面「{100}面」を切り出します。","2026年のグローバル半導体エコシステム分析でも、先端300 mmウェハ供給の50〜60%以上を日本の信越化学工業・SUMCOが担い、最先端ロジック向けにはさらに欠陥ゼロのエピタキシャル単結晶層を表面に成長させています。"],"formula":{"expression":"Purity = 11N = 99.999999999%   (不純物濃度 < 10^-11 ＝ 原子1000億個中 1個未満)","description":"サブ7 nmトランジスタや332層NANDチャネルのしきい値ばらつきを防ぐための地球上で最も純粋な工業材料。"},"nextGenInnovation":"2025〜2026年は、3D NANDの400層超積層ストレスに耐える高酸素析出ゲッタリング制御ウェハと、2nm GAA・裏面給電（BSPDN）対応の超高平坦エピタキシャル300 mmウェハが最先端工場の基盤を支えています。","specs":[{"label":"化学純度","value":"11N（99.999999999%：シーメンス法電子級）"},{"label":"結晶育成・面方位","value":"チョクラルスキー（CZ）無転位単結晶 / {100}面"},{"label":"格子定数（Si）","value":"a = 0.5431 nm（ダイヤモンド立方晶）"},{"label":"ウェハ規格","value":"直径 300 mm → 加工後 25〜30 μm へ極薄研削"}],"diagramType":"cfe_wafer_11n_cz_monocrystal"},{"id":"cfe-hvlp2-copper-skin-depth","order":115,"swatchColor":"#ea580c","groupKey":"16_GT_sの電気は銅の_皮0_6_m_しか通らない_C115","assembledPos":[10.8,1.4,0.22],"explodeOffset":[134,4,-14],"integratedExplodeOffset":[134,4,-14],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C115. 超平滑HVLP2銅箔（Rz < 2.0 μm）＆表皮効果（Skin Effect）シランカップリング密着層","subtitle":"HVLP / HVLP2 Ultra-Smooth Copper Foil (Rz < 2.0 μm) & Silane Adhesion Coupling","category":"16 GT/sの電気は銅の「皮0.6 μm」しか通らない！ C115 — 鏡のようにツルツルの超平滑HVLP2銅箔と分子の糊！","plainAnalogy":"PCIe Gen4/5のような超高速の電気信号（8〜16 GHz以上）には「表皮効果」という不思議な性質があり、銅線の中身を通らず表面わずか0.5〜0.7 μmの「薄皮」だけを走ります！普通の銅箔は樹脂にくっつきやすいように表面が山谷5〜8 μmもデコボコしているので、電気信号は険しい山道を延々と遠回りしてヘトヘトに弱ってしまいます。そこで登場したのが鏡のように平らな「HVLP2超平滑銅箔（凹凸2 μm未満）」！ツルツルでも剥がれないよう分子レベルの糊（シランカップリング剤）で接着し、高速信号のロスを劇的に減らすんです！","summary":"PCIe Gen4/Gen5/Gen6高速差動配線の導体損失を最小化するため、表面粗さ Rz を 2.0 μm 未満（最先端では 0.5〜1.0 μm）へ極限平滑化した超低粗度電解銅箔（HVLP / HVLP2）と、化学結合で樹脂密着を確保するシランカップリング界面です。","opticsAndPhysics":["銅の表皮深さ δ は 8 GHz（PCIe 4.0ナイキスト）で約 0.73 μm、16 GHz（PCIe 5.0）で約 0.52 μm、32 GHz（PCIe 6.0）で約 0.37 μm まで浅くなります。","2026年の高速PCB設計実測（AtlasPCB / NextPCB）によると、標準ED銅箔（Rz 5〜8 μm）は表皮深さの10〜20倍もの凹凸を持ち、Hammerstad-Jensen／Hurayモデルで導体抵抗が2倍以上に増大しますが、HVLP2銅箔（Rz < 2 μm）へ切り替えることで導体損失を15〜25%以上削減できます。","粗さを減らすと機械的アンカー効果が減り引き剥がし強度（ピール強度）が低下するため、粗化しない酸化代替処理と有機シランカップリング剤による化学架橋で基板剥離（デラミネーション）を防ぎます。"],"formula":{"expression":"δ = √(2 / (ω · μ · σ)) ≈ 66 / √f(MHz) [μm]   (@8 GHz → δ ≈ 0.73 μm)","description":"周波数が高いほど電流が銅箔表面の極薄層 δ に集中するため、表面粗さ Rz を δ に近づけるHVLP2化が決定的に効く。"},"nextGenInnovation":"2026年のPCIe 5.0/6.0および224G AI基板では、Rz < 0.5〜1.0 μmのHVLP4級銅箔と低粗度無電解銅めっきビア壁の組み合わせが、信号到達距離を延ばす最重要マテリアルとなっています。","specs":[{"label":"銅箔グレード","value":"HVLP / HVLP2（Rz < 2.0 μm、最先端HVLP4 < 1.0 μm）"},{"label":"表皮深さ δ","value":"0.73 μm (@8 GHz) / 0.52 μm (@16 GHz)"},{"label":"導体損失低減","value":"標準ED銅箔（Rz 5–8 μm）比 15〜25% 低減"},{"label":"界面密着処理","value":"非粗化酸化代替処理 ＋ シランカップリング分子結合"}],"diagramType":"cfe_hvlp2_copper_skin_depth"},{"id":"cfe-megtron7-ultralow-df-resin","order":116,"swatchColor":"#10b981","groupKey":"電気信号が熱に変わって消えるのを防ぐ極上絶縁体_C116_一般基","assembledPos":[10.6,-3.4,-0.18],"explodeOffset":[132,-28,-24],"integratedExplodeOffset":[132,-28,-24],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C116. 超低誘電正接（Df ≤ 0.002）Megtron 7/8 級高周波樹脂＆Tガラス補強プリプレグ","subtitle":"Ultra-Low-Loss Hydrocarbon Resin (Df ≤ 0.002 @ 10–28 GHz) & Low-Dk T-Glass Prepreg","category":"電気信号が熱に変わって消えるのを防ぐ極上絶縁体 C116 — 一般基板の10分の1しかロスしないMegtron 7/8級レジン！","plainAnalogy":"電子レンジで食べ物が温まるのは、電波が水分子を揺らして熱に変えてしまうからです。実は普通の緑色の基板（FR-4）でも、PCIe Gen4/5の超高速電波が走ると基板のプラスチック分子が揺れて信号エネルギーが熱としてどんどん消えてしまいます（誘電損失）！そこでハイエンド高速カードや次世代基板では、分子が電波で揺れにくい特別な超低損失ポリマー（パナソニック Megtron 6/7/8 級）＋低誘電Tガラス繊維を使い、信号をキンキンにクリアなままコントローラまで届けるんです！","summary":"16〜32 GT/sのマルチGHz差動信号における誘電体損失（Dielectric Loss）を劇的に抑える、超低誘電正接（Df = 0.001〜0.004）炭化水素／PPE系高周波樹脂と低Dkガラスクロス補強プリプレグ層です。","opticsAndPhysics":["誘電損失 α_d は周波数 f と誘電正接 tanδ（Df）および √Dk に比例するため、一般FR-4（Df ≈ 0.020）では高周波ほど指数関数的にアイパターンが閉じてしまいます。","2026年の高速PCB材料梯子では、PCIe Gen4/5量産主力のMegtron 6（R-5775: Df 0.004）、PCIe Gen5/6・112G向けのMegtron 7（R-5785: Df 0.002、Tガラス補強）、さらに224G/次世代向けのMegtron 8（Df 0.0008）・Megtron 9（Df 0.0005, Dk 2.9）へと劇的な低損失化が進んでいます。","高耐熱（Tg > 180℃）・低吸湿・耐CAF（導電性陽極フィラメント）性を兼ね備えることで、CFexpress Type A TOUGHの −12℃〜+72℃ 動作とIP57環境下でも特性インピーダンス（85 Ω ±5%）を安定維持します。"],"formula":{"expression":"α_d ≈ 2.3 · f(GHz) · √Dk · Df   [dB/inch]","description":"誘電損失 α_d は誘電正接 Df に直接比例。FR-4（0.02）からMegtron 7（0.002）へ変えると誘電損失が約1/10になる。"},"nextGenInnovation":"2026年の次世代PCIe Gen6（64 GT/s PAM4）およびCFexpress次世代規格では、ノイズマージンが9.5 dB厳しくなるため、Df ≤ 0.002 級の超低損失積層材と ±5% 厳格インピーダンス管理が必須インフラになっています。","specs":[{"label":"代表高速樹脂群","value":"Megtron 6 (Df 0.004) / Megtron 7 (Df 0.002) / 8 (0.0008)"},{"label":"比誘電率（Dk）","value":"2.9〜3.4（低Dk Tガラス・NEガラス補強）"},{"label":"インピーダンス精度","value":"差動 85 Ω ±5%（TDR 100% 全数検証基準）"},{"label":"信頼性特性","value":"高Tg（>180℃）・低吸湿・耐CAFマイグレーション"}],"diagramType":"cfe_megtron7_ultralow_df_resin"},{"id":"cfe-uv-laser-50um-microvia","order":117,"swatchColor":"#eab308","groupKey":"紫外線レーザーで開ける50_mの垂直エレベーター_C117_髪の","assembledPos":[9.4,-9.8,-0.12],"explodeOffset":[124,-60,-18],"integratedExplodeOffset":[124,-60,-18],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C117. UVレーザー穿孔 50 μm 銅充填スタックドマイクロビア＆無電解シードめっき壁","subtitle":"UV-Laser 50 μm Copper-Filled Stacked Microvias (±10–15 μm Optical Registration)","category":"紫外線レーザーで開ける50 μmの垂直エレベーター C117 — 髪の毛より細い銅の縦穴を±10 μm精度で積み上げる！","plainAnalogy":"8層もある超薄型HDI基板の1階から8階まで普通のドリルで穴を開けると、太すぎて狭いBGAチップの足元に収まらないうえ、使わない余分な穴の尻尾（スタブ）が電波を反射して邪魔をします。そこで紫外線（UV）レーザー光線で、髪の毛より細い直径50 μmの極小穴を1層ずつピンポイントで開け、中を純銅めっきでギュッと隙間なく詰めて垂直に積み上げます（スタックドマイクロビア）！余分な尻尾ゼロ・反射ゼロで高速信号を階層ワープさせる「ナノ・エレベーター」なんです！","summary":"狭ピッチ0.4 mm BGA（コントローラ・NAND）直下からの高密度ファンアウトとスタブゼロ層間遷移を実現する、UVレーザー（Nd:YAG / エキシマ）加工による直径50〜75 μm銅充填スタックドマイクロビア構造です。","opticsAndPhysics":["従来のCO2レーザー（波長9.4 μm）では75〜100 μm径が限界でしたが、波長355 nmのUVレーザー加工により直径50 μm級の真円マイクロビアを樹脂・極薄銅箔ごと高精度に穿孔できます。","2026年の先端HDI基準（NextPCB）では、50 μmスタックドマイクロビアの層間アライメント精度は ±10〜15 μm（光学位置補正）に達し、ビア内部をボイドなく電解銅充填（Cu-Filled Via）することで「ビア・イン・パッド（VIPPO）」実装と放熱性を両立します。","不要な貫通残余長（スタブ）が物理的に存在しないため、16〜32 GHz帯での1/4波長共振ノッチ（S21の急峻な落ち込み）を完全に排除し、アイパターン開口を最大化します。"],"formula":{"expression":"f_notch = c / (4 · L_stub · √Dk)   (Microvia: L_stub = 0 → 共振ノッチ完全消滅)","description":"スタックドマイクロビアは信号終端層で物理的に止まるため、スタブ長 L_stub = 0 となり高周波反射ノッチを根絶する。"},"nextGenInnovation":"2026年の最先端高周波HDIでは、ビア内壁の表皮効果ロスまで減らすため、低粗度無電解銅シード（ECD）化学めっきとボイドレス・パルス電解充填プロセスが採用されています。","specs":[{"label":"ビア孔径・加工法","value":"φ 50〜75 μm / UVレーザー（355 nm Nd:YAG）穿孔"},{"label":"層間位置精度","value":"光学アライメント ±10〜15 μm（スタックド多段）"},{"label":"内部構造","value":"ボイドレス電解銅完全充填（VIPPO パッド直下対応）"},{"label":"電気的利点","value":"スタブ長 0 mm（高周波共振ゼロ）・低インダクタンス"}],"diagramType":"cfe_uv_laser_50um_microvia"},{"id":"cfe-mlcc-batio3-soft-term","order":118,"swatchColor":"#d97706","groupKey":"150Nの曲げに耐える_ゴム入りコンデンサ_C118_中身は数百","assembledPos":[8.2,-15.4,0.62],"explodeOffset":[106,-86,14],"integratedExplodeOffset":[106,-86,14],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C118. MLCC内部 BaTiO3強誘電ナノ粒子多層電極＆樹脂ソフトターミネーション耐屈曲構造","subtitle":"MLCC BaTiO3 Nanograin Stack & Flex-Crack-Proof Conductive-Resin Soft Termination","category":"150Nの曲げに耐える「ゴム入りコンデンサ」 C118 — 中身は数百層のチタン酸バリウムとニッケルのミルフィーユ！","plainAnalogy":"基板にたくさん並ぶゴマ粒ほどのセラミックコンデンサ（MLCC）。顕微鏡で割ってみると、中は「チタン酸バリウム（BaTiO3）」という陶器と極薄ニッケル金属板が数百枚も交互に重なった超精巧なミルフィーユです！陶器なので硬くて割れやすく、カードがちょっと曲がっただけでパキッと割れてショートする弱点がありました。そこでTOUGH高信頼モデルでは、両端の金属電極の中に「柔らかい導電性樹脂（ゴムクッション層）」を挟み込み（ソフトターミネーション）、基板がたわんでも陶器本体を絶対に割らせないんです！","summary":"電源デカップリングおよびPLPエネルギー保持を担う積層セラミックコンデンサ（MLCC）の内部BaTiO3強誘電体ナノ粒子・交互Ni内部電極構造と、基板屈曲クラックを防ぐ導電性樹脂ソフトターミネーション電極です。","opticsAndPhysics":["Class 2（X5R/X7R）MLCCは強誘電体ペロブスカイト結晶 BaTiO3（比誘電率 数千）をサブミクロン厚で数百層積層して小型大容量を実現しますが、直流電圧をかけると分極ドメインが固定され実効容量が低下する「DCバイアス特性」があるため、設計時には定格電圧ディレーティング（50%以下運用等）が不可欠です。","通常のCu/Ni/Sn硬質端子は基板曲げ応力をそのまま脆いセラミック素体へ伝えて斜めクラック→内部電極ショートを起こします。","銅・銀エポキシ系「導電性樹脂層」をCu下地とNiめっきの間に挟んだソフトターミネーション（村田・TDK・SEMCO等）は、基板たわみ耐性を約4 mm → 7 mm以上へ約2倍化し、−55℃〜+125℃の3,000回熱衝撃サイクルでもセラミック素体クラックを完全に防ぎます。"],"formula":{"expression":"C = ε_0 · ε_r(V_DC, T) · (N − 1) · A / d   (積層数 N: 数百層,  誘電体厚 d < 1 μm)","description":"積層数 N を増やし BaTiO3 誘電体厚 d を1 μm未満へ極薄化することで、0.4×0.2 mm極小サイズでも大容量を達成。"},"nextGenInnovation":"2025〜2026年の最新世代（村田 0.4×0.2 mm 100 nF級、SEMCO 2,000G衝撃1万回耐性Cu-エポキシ端子等）は、小型CFexpressカードの高密度化とTOUGH 150N曲げ／7.5 m落下耐性の両立を支えています。","specs":[{"label":"内部構造","value":"BaTiO3 強誘電セラミック ＜1 μm × 数百層 Ni交互電極"},{"label":"端子緩衝層","value":"Ag/Cu含有導電性エポキシ樹脂ソフトターミネーション"},{"label":"耐屈曲・熱衝撃","value":"基板たわみ 7 mm+ / 熱衝撃 3,000サイクル（−55〜125℃）"},{"label":"設計注意点","value":"Class 2（X5R/X7R）DCバイアス容量低下を見込んだ余裕設計"}],"diagramType":"cfe_mlcc_batio3_soft_term"},{"id":"cfe-atcut-quartz-shear-cavity","order":119,"swatchColor":"#facc15","groupKey":"35度15分_の魔法の角度で切った水晶板_C119_12_でも_","assembledPos":[9.4,-12.2,0.72],"explodeOffset":[126,-42,32],"integratedExplodeOffset":[126,-42,32],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C119. ATカット水晶片（35°15′切断）厚みすべり圧電振動子＆窒素気密封止セラミックキャビティ","subtitle":"35°15′ AT-Cut Quartz Thickness-Shear Piezo Resonator in Hermetic N2 Ceramic Cavity","category":"「35度15分」の魔法の角度で切った水晶板 C119 — −12℃でも+72℃でも狂わない超精密メトロノーム！","plainAnalogy":"カード内部のクロック発振器の金属フタを開けると、中には小さな透明な「人工水晶の板」が片持ちでフワッと浮いています。水晶に電気を流すとブルブル震える性質（圧電効果）を使って1秒間に2500万〜4000万回も正確に拍子を刻むのですが、普通の水晶は暑くなったり寒くなったりすると拍子がズレます。そこで結晶の軸から「ちょうど35度15分」という魔法の角度（ATカット）で斜めにスライス！すると温度が変わっても震える速さがほとんど変わらない（誤差±20 ppm）最強のメトロノームになるんです！","summary":"コントローラ内部PLLおよびシステムタイミングの基準となる、人工水晶結晶からZ軸に対し35°15′の角度で切り出された「ATカット厚みすべり振動子（Thickness-Shear Mode）」と、不活性窒素ガスを気密封止したセラミックパッケージ空洞です。","opticsAndPhysics":["ATカット水晶片は温度に対する周波数変化が25℃付近を変曲点とする穏やかな3次曲線（Cubic Curve）を描くため、−12℃〜+72℃のカメラ動作温度全域で ±15〜30 ppm という驚異的な周波数安定度を無補正で保てます。","両面に蒸着された極薄金（Au）励振電極へ交流電圧を印加すると、水晶片の上面と下面が逆向きに水平スライドする「厚みすべり振動」を起こし、共振周波数 f は水晶板の厚み t に厳密に反比例（周波数定数 K ≈ 1.661 MHz·mm → 40 MHzでは厚みわずか約41.5 μm！）します。","振動子チップはセラミック空洞の片端だけを柔らかい導電性シリコーン接着剤で支持し、金属リッドをシーム溶接して高純度N2ガスまたは真空で気密封止することで、落下衝撃（7.5 m）や湿度による周波数ドリフト（エージング）を防ぎます。"],"formula":{"expression":"f_0 = K_AT / t   (K_AT ≈ 1.661 MHz·mm → 40 MHz時 水晶片厚 t ≈ 41.5 μm)","description":"厚みすべり共振周波数は水晶の厚み t で決まり、高いQ値（数万〜10万）により低位相ノイズ・超低ジッタークロックを生成。"},"nextGenInnovation":"2025〜2026年の超高速PCIe Gen4/Gen5機器では、超小型1.6×1.2 mm気密ATカット水晶や、耐衝撃性に優れたシリコンMEMS発振器（ジッター ≤ 0.15 ps RMS）への進化が進んでいます。","specs":[{"label":"水晶切断方位","value":"ATカット（結晶Z軸より 35°15′ 傾斜切断）"},{"label":"振動モード・厚み","value":"厚みすべり（Thickness-Shear）/ 厚み約 40〜65 μm"},{"label":"周波数温度安定度","value":"±15〜30 ppm（−12℃〜+72℃ 3次温度特性）"},{"label":"封止構造","value":"セラミックキャビティ ＋ Kovar金属リッドN2気密シーム溶接"}],"diagramType":"cfe_atcut_quartz_shear_cavity"},{"id":"cfe-tvs-snapback-esd-junction","order":120,"swatchColor":"#e11d48","groupKey":"0_5ナノ秒で静電気を逃がす_超速避雷針_C120_16_GT_","assembledPos":[8.8,-18.2,0.68],"explodeOffset":[112,-10,46],"integratedExplodeOffset":[112,-10,46],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C120. 超低容量（0.2 pF）ディープスナップバックTVSダイオード PNPNサイリスタ微細接合","subtitle":"0.2 pF Ultra-Low-Capacitance Deep-Snapback TVS ESD Diode (PNPN Micro-Junction)","category":"0.5ナノ秒で静電気を逃がす「超速避雷針」 C120 — 16 GT/sの邪魔をしない0.2 pF極小容量＆スナップバック放電！","plainAnalogy":"冬の乾燥した日にCFexpressカードをポケットから取り出すと、指先から1万5千ボルトもの静電気（ESD）が21本の金ピンにバチッと飛びます！普通の保護部品を高速データ線に付けると、部品自身の電気を溜める力（寄生容量）がブレーキになって16 GT/s信号がボヤけてしまいます。そこで使うのが「0.2 pF超低容量ディープスナップバックTVS」！普段は存在しないかのように透明で信号を通し、静電気が来た瞬間だけ0.5ナノ秒以内に内部電圧をガクンと落として大電流を地面（GND）へ一気に逃がす超速避雷針なんです！","summary":"PCIe Gen4（16 GT/s）超高速差動レーン直近に配置され、静電気放電（IEC 61000-4-2 ±15 kV気中／±8 kV接触）から6nmコントローラSerDes入力段を守る、超低接合容量（~0.2 pF）ディープスナップバック型PNPNサイリスタ微細構造です。","opticsAndPhysics":["通常のツェナーダイオードは保護動作中に電圧が上がり続けるため微細な6nmゲート酸化膜（耐圧数V）を破壊してしまいますが、PNPN寄生サイリスタ構造を持つ「ディープスナップバックTVS」は、トリガ電圧（V_trig ≈ 5〜6 V）を超えた瞬間に正帰還で導通し、クランプ電圧を低い保持電圧（V_hold ≈ 1.5〜2.5 V）へ急降下（Snapback）させます。","動的抵抗 R_dyn を 0.2〜0.4 Ω 級まで抑えることで、数十アンペアのESDサージ電流（8/20 μs・TLPピーク）が流れてもSerDesピン電圧を安全域内に完璧にクランプします。","差動線路のインピーダンス（85 Ω）を乱さないよう接合面積を極小化し、ピン間容量を 0.15〜0.25 pF 以下へ抑えて16 GT/sアイパターンの劣化をゼロに近づけています。"],"formula":{"expression":"V_clamp = V_hold + I_ESD · R_dyn   (C_j ≤ 0.2 pF,  R_dyn ≈ 0.3 Ω,  t_resp < 0.5 ns)","description":"スナップバックによる低い保持電圧 V_hold と超低動的抵抗 R_dyn により、大サージ電流時でも6nmチップの耐圧以下に抑え込む。"},"nextGenInnovation":"PCIe Gen4/5やUSB4 40 Gbpsリーダー（MRW-G3）向け最新ESD保護素子では、スルーレイアウト（フロー・スルー配線）対応の0.15 pF極小パッケージにより、保護素子実装による挿入損失を0.1 dB未満へ抑えています。","specs":[{"label":"保護接合構造","value":"PNPNディープスナップバック型シリコン微小サイリスタ"},{"label":"寄生接合容量","value":"0.15〜0.25 pF（16 GT/s 85 Ω 差動透過）"},{"label":"ESD耐量・応答","value":"IEC 61000-4-2 ±15 kV（気中）/ 応答 < 0.5 ns"},{"label":"動的抵抗 R_dyn","value":"約 0.2〜0.4 Ω（6nm SerDes入力ゲート保護）"}],"diagramType":"cfe_tvs_snapback_esd_junction"},{"id":"cfe-pcie-tx-ffe-3tap-driver","order":121,"swatchColor":"#2563eb","groupKey":"遠くで丸くなる波形をあらかじめ_トゲ状_に強調送信_C121_1","assembledPos":[2.4,-14.8,0.64],"explodeOffset":[74,-102,26],"integratedExplodeOffset":[74,-102,26],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C121. PCIe Gen4/5 送信側 3タップFFEプリエンファシス回路＆差動CML出力ドライバ","subtitle":"PCIe Gen4/5 TX 3-Tap Feed-Forward Equalizer (FFE) & Differential CML Output Driver","category":"遠くで丸くなる波形をあらかじめ「トゲ状」に強調送信！ C121 — 16 GT/sを鮮明に届ける3タップ先読みドライバ！","plainAnalogy":"広いトンネルの向こうへ声を届けると、高い音ほど壁に吸収されてモゴモゴに聞き取りにくくなりますよね。PCIe Gen4（16 GT/s）の電気信号も、基板や21ピンコネクタを通るあいだに高い周波数が削れて四角い波形が丸く潰れてしまいます。そこで送信側（TX）は「今のビット」に「1つ前のビット（プリカーソル）」と「1つ後のビット（ポストカーソル）」の引き算をあらかじめ混ぜ（3タップFFE）、変化する瞬間だけ電圧をキュッと尖らせて送り出すことで、相手に届くころにちょうど綺麗な四角に戻るよう逆算しているんです！","summary":"PCIe 4.0（16 GT/s）および次世代PCIe 5.0（32 GT/s）送信側物理層（TX PHY）の中核となる、3タップ（Pre-cursor C-1 / Main C0 / Post-cursor C+1）フィードフォワード等化器（FFE）と電流モードロジック（CML）差動出力ドライバです。","opticsAndPhysics":["高速チャネルはローパスフィルタとして働くため、連続する同符号（0000や1111）は振幅が大きく残り、反転ビット（0101）は大きく減衰して符号間干渉（ISI）を引き起こします。","TX 3タップFFEは11種類のプリセット（P0〜P10）からプリカーソル（前ビット補償）とデエンファシス／ポストカーソル（後ビット補償）の電流重みをデジタル設定し、低周波成分を抑えて高周波遷移エッジを相対強調します。","リンク起動時のLTSSM等化フェーズ（Phase 2/3）では、カメラ側受信機が「もう少しポストカーソルを強くして！」とリクエストを返し、最適な3タップ係数を自動収束させます。"],"formula":{"expression":"y[n] = c_(−1)·x[n+1] + c_0·x[n] + c_(+1)·x[n−1]   (|c_(−1)| + |c_0| + |c_(+1)| = 1)","description":"送信FIRフィルタ（3タップFFE）の基本式。前後ビットの重み付け加算でチャネル高周波減衰を事前に打ち消す。"},"nextGenInnovation":"2026年のPCIe 5.0（32 GT/s）およびPCIe 6.0（64 GT/s PAM4）コントローラでは、微細な6nm/4nmプロセス上でDACベース精密プリセット制御と低消費電力SST（Source-Series-Terminated）電圧モードドライバ化が進んでいます。","specs":[{"label":"等化方式","value":"3タップTX FFE（Pre C-1 / Main C0 / Post C+1）"},{"label":"プリセット数","value":"PCIe 4.0/5.0 標準 11プリセット（P0〜P10）"},{"label":"出力インピーダンス","value":"差動 85 Ω（オンチップ終端自動キャリブレーション）"},{"label":"対応レート","value":"16 GT/s（Gen4）/ 32 GT/s（Gen5）NRZ"}],"diagramType":"cfe_pcie_tx_ffe_3tap_driver"},{"id":"cfe-pcie-rx-ctle-dfe-eq","order":122,"swatchColor":"#06b6d4","groupKey":"潰れて閉じた信号の_目_をパッと開くデジタル顕微鏡_C122_高","assembledPos":[-0.8,-15.6,0.66],"explodeOffset":[42,-112,34],"integratedExplodeOffset":[42,-112,34],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C122. PCIe Gen4/5 受信側 2次CTLE線形等化＋多タップDFE判定帰還等化器","subtitle":"PCIe Gen4/5 RX 2nd-Order CTLE Linear Equalizer & Multi-Tap DFE Slicer","category":"潰れて閉じた信号の「目」をパッと開くデジタル顕微鏡 C122 — 高周波ブースト（CTLE）＋残響引き算（DFE）の2段技！","plainAnalogy":"カメラ本体から長い基板やコネクタを通ってカードに届いた16 GT/s信号は、ノイズや減衰で「0か1か全く読めないグチャグチャの波（閉じたアイパターン）」になっています！これを見事に復元するのが受信側（RX）の2段階コンビ技。まずアナログの「CTLE」が弱った高周波だけをキュッと持ち上げ、次にデジタルの「DFE」が「さっき受信した1ビットの残響（エコー）が今これだけ邪魔しているはず」とリアルタイムで引き算！するとノイズを増やさずに信号の「目（アイ）」がクッキリ大きく開くんです！","summary":"チャネル損失（PCIe 4.0最大 −28 dB @ 8 GHz、PCIe 5.0最大 −36 dB @ 16 GHz）で完全に閉じた受信アイパターンを開口させる、アナログ連続時間線形等化器（CTLE）＋可変利得増幅器（VGA）＋非線形判定帰還等化器（DFE）の適応受信エンジンです。","opticsAndPhysics":["CTLE（Continuous-Time Linear Equalizer）はソース縮退RC回路で高周波域（ナイキスト周波数付近）を選択的にブーストし、PCB導体損失と誘電損失による右下がり周波数特性を平坦化します。","CTLEだけでブーストしすぎると高周波ノイズやクロストークまで一緒に増幅してしまいますが、DFE（Decision Feedback Equalizer）は「すでに0/1と判定済みの過去ビット」をフィードバックして後続ビットへの符号間干渉（ポストカーソルISI）をノイズ増幅ゼロで直接差し引きます。","2026年2月のMDPI PCIe 5.0エンドツーエンド論文では、2次CTLE＋3タップDFEのビット単位適応収束（IBIS-AMI）により、パッケージ不連続やビア反射がある過酷なチャネルでも安定してビット誤り率 BER < 10^-12 を達成する動作が検証されています。"],"formula":{"expression":"v_eq[n] = v_CTLE[n] − Σ_(k=1..N) h_k · d̂[n−k]   (Gen4: 2-tap / Gen5: 3-tap DFE)","description":"CTLE出力から過去判定ビット d̂[n−k] の残響重み h_k を減算することで、ノイズを増やさずアイ高・アイ幅を劇的拡大。"},"nextGenInnovation":"PCIe 4.0以降で必須化された「レーンマージニング（Lane Margining at Receiver）」機能により、カメラや工場検査機から稼働中のカード受信アイ開口（電圧mV・時間ps）をリアルタイムに内部診断できます。","specs":[{"label":"線形等化段","value":"2次アナログCTLE ＋ 自動利得制御（VGA）"},{"label":"非線形等化段","value":"2〜3タップ適応DFE（ノイズ増幅ゼロでISI消去）"},{"label":"補償損失バジェット","value":"最大 −28 dB (@8 GHz Gen4) / −36 dB (@16 GHz Gen5)"},{"label":"診断機能","value":"オンチップ・レーンマージニング（稼働中アイ開口計測）"}],"diagramType":"cfe_pcie_rx_ctle_dfe_eq"},{"id":"cfe-serdes-lctank-pll-cdr","order":123,"swatchColor":"#fbbf24","groupKey":"62_5ピコ秒の_ど真ん中_を狙い撃つ超精密オートフォーカス時計","assembledPos":[-4.2,-16.2,0.62],"explodeOffset":[8,-116,22],"integratedExplodeOffset":[8,-116,22],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C123. SerDes オンチップ螺旋LCタンクPLL発振器＆位相補間器（PI）クロックデータ復元（CDR）","subtitle":"On-Chip Spiral LC-Tank PLL VCO & Phase-Interpolator (PI) Clock-Data Recovery (CDR)","category":"62.5ピコ秒の「ど真ん中」を狙い撃つ超精密オートフォーカス時計 C123 — チップ上の黄金コイルと位相補間CDR！","plainAnalogy":"PCIe Gen4は1秒間に160億回も0と1が切り替わるため、1ビット分の長さはわずか「62.5ピコ秒（光でさえ約1.8 cmしか進めない一瞬）」！しかもデータ線には別個のクロック線が添えられておらず、届いたデータの波そのものからタイミングを自力で読み取らなければなりません。そこでコントローラ上の極小「黄金うずまきコイル（LCタンクPLL）」が超低揺らぎの基準リズムを作り、位相補間器（PI-CDR）が62.5ピコ秒を64分割する精度で「波のど真ん中」へ自動ピント合わせし続けるんです！","summary":"100 MHzの基準クロックを8 GHz/16 GHzへ逓倍するオンチップ螺旋インダクタ型LCタンクPLLと、受信データ遷移エッジから最適サンプリング位相をピコ秒単位で追尾する位相補間器ベース・クロックデータ復元回路（PI-CDR）です。","opticsAndPhysics":["リング発振器は位相ノイズ（ランダムジッター）が大きく16〜32 GT/s規格（基準ジッター ≤ 0.15〜0.5 ps RMS）を満たせないため、コントローラダイ最上層の厚銅配線に八角形・螺旋状のオンチップ・インダクタ（L）とバラクタ容量（C）を作り込んだLCタンクVCOを採用します。","受信側CDRはアレキサンダー（Bang-Bang）位相検出器でデータの立ち上がり・立ち下がりエッジとクロックの早遅を毎ビット監視し、デジタルループフィルタ経由で64ステップ位相補間器（1ステップ ≈ 1 ps！）を回してサンプリング点を常にアイの最大開口中心へロックします。","カメラ本体とカード間でわずかなクロック周波数差（SSCスペクトラム拡散変調最大 −5,000 ppm等）があっても、CDRとSKPオーダーセット補償バッファが同期外れを完全に防ぎます。"],"formula":{"expression":"f_VCO = 1 / (2π · √(L · C_var)),   1 UI (16 GT/s) = 62.5 ps → PI分解能 ≈ 0.98 ps","description":"螺旋LCタンクの高Q共振でジッターをフェムト秒域へ抑え、位相補間器で1ビット（62.5 ps）を約1 ps刻みで精密追尾。"},"nextGenInnovation":"2025〜2026年の6nm/4nm SerDesマクロでは、完全デジタルPLL（ADPLL）とインダクタ磁気結合を抑える差動8の字（Figure-8）コイル構造により、チップ面積とジッターを同時に削減しています。","specs":[{"label":"発振器構造","value":"最上層厚銅 螺旋LCタンクVCO（8 GHz / 16 GHz）"},{"label":"1ビット時間幅（UI）","value":"62.5 ps（PCIe 4.0）/ 31.25 ps（PCIe 5.0）"},{"label":"CDR位相分解能","value":"64ステップ位相補間器（約 1 ps 刻み自動追尾）"},{"label":"ジッター目標","value":"≤ 0.15〜0.5 ps RMS（SSC拡散クロック完全追従）"}],"diagramType":"cfe_serdes_lctank_pll_cdr"},{"id":"cfe-pcie-ltssm-128b130b-mac","order":124,"swatchColor":"#3b82f6","groupKey":"カード挿入から数ミリ秒で16_GT_sを開通する_管制塔_C12","assembledPos":[-7.4,-15.4,0.64],"explodeOffset":[-26,-112,42],"integratedExplodeOffset":[-26,-112,42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C124. PCIe 128b/130b 高効率ブロック符号化（損失1.54%）＆LTSSMリンク等化トレーニングFSM","subtitle":"PCIe 128b/130b Block Encoding (98.46% Efficiency) & LTSSM Equalization State Machine","category":"カード挿入から数ミリ秒で16 GT/sを開通する「管制塔」 C124 — 無駄わずか1.54%の128b/130b符号化＆自動リンク交渉！","plainAnalogy":"昔の高速通信（PCIe 2.0やSATA）は、0や1が連続して迷子にならないよう8ビットごとに2ビットの目印を足す「8b/10b方式」だったので、速度の20%も目印だけで無駄にしていました！今のCFexpress 4.0（PCIe 4.0）は「128ビットごとにたった2ビットの目印」だけで済む128b/130b方式を採用し、実効効率を98.46%へ爆上げ！さらにカードをカメラに挿した瞬間、LTSSM管制塔が「相手を確認（Detect）→挨拶（Polling）→速度交渉と波形調整（Equalization）→全開運転（L0）」をわずか数ミリ秒で完了させるんです！","summary":"PCIe Gen3/4/5物理層ロジカルサブブロックで動作する、オーバーヘッドわずか1.538%の128b/130bブロック符号化・スクランブラおよび、リンク確立・速度ネゴシエーション・エラー復帰を司るLTSSM（Link Training and Status State Machine）です。","opticsAndPhysics":["128b/130b符号化では2ビットのシンクヘッダ（`10`=データブロック、`01`=オーダーセット）＋128ビットのスクランブル済データを130ビット単位で伝送し、8b/10b（効率80%）比で実効帯域効率を 128/130 ≈ 98.46% へ引き上げます。","カード電源投入後、LTSSMはまず2.5 GT/s（Gen1）で安全にリンクを確立し、Detect → Polling → Configuration → L0 を経て、Recovery.Equalization Phase 0〜3 でカメラ側ホストとTX FFE／RX CTLE・DFE係数を相互調整して16 GT/s（Gen4）へステップアップします。","さらにクレジットベースフロー制御（UpdateFC DLLP）とLCRC（32ビット巡回冗長検査）＋リトライバッファにより、万一ノイズで1パケット化けてもハードウェア層で即自動再送し、8K録画のコマ落ちを完全に防ぎます。"],"formula":{"expression":"η_128b/130b = 128 / 130 ≈ 98.46%   (16 GT/s × 128/130 ÷ 8 ≈ 1.969 GB/s per Lane)","description":"128b/130b高効率符号化により、PCIe 4.0 ×1レーン（16 GT/s）から実効約1.97 GB/s（実測1800 MB/s超）を引き出す。"},"nextGenInnovation":"2026年にエンタープライズ出荷が始まったPCIe 6.0（64 GT/s）では、PAM4変調と固定長256バイトFLITモード＋軽量FECへ進化しており、将来世代のCFexpress規格にもこの論理アーキテクチャが継承されます。","specs":[{"label":"ブロック符号化","value":"128b/130b（オーバーヘッド 1.538% / 効率 98.46%）"},{"label":"リンク訓練FSM","value":"LTSSM（Detect → Polling → Config → EQ Ph0–3 → L0）"},{"label":"エラー保護","value":"TLP 32bit LCRC ＋ ハードウェア自動再送リトライバッファ"},{"label":"帯域実効値","value":"PCIe 4.0 ×1: 約 1.969 GB/s（実測 R:1800 / W:1700 MB/s）"}],"diagramType":"cfe_pcie_ltssm_128b130b_mac"},{"id":"cfe-6nm-finfet-6t-sram-cell","order":125,"swatchColor":"#7c3aed","groupKey":"6ナノメートルの立体スイッチ_1クロック作業机_C125_発熱を","assembledPos":[-8.4,-10.8,0.58],"explodeOffset":[-58,-104,18],"integratedExplodeOffset":[-58,-104,18],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C125. 6nm FinFET / 次世代GAA 3次元ナノシート・トランジスタ＆コントローラ内蔵6T SRAMセル","subtitle":"6nm FinFET / Next-Gen 2nm GAA Nanosheet Transistors & On-Die 6T SRAM Bitcell","category":"6ナノメートルの立体スイッチ＆1クロック作業机 C125 — 発熱を半分に抑えながら8K動画をさばくコントローラの細胞！","plainAnalogy":"CFexpress 4.0カードは指先サイズなのに秒速1800 MBものデータを処理するため、昔のコントローラではチンチンに熱くなって止まってしまいます。そこで最新コントローラ（Phison E27T/E28やSilicon Motion SM2508級の6nm世代）では、電気の通り道を背びれのように立てて3方向からゲートで挟み込む立体スイッチ（FinFET、さらに2026年先端では4面全部を包むGAAナノシート）を採用！さらにチップの中に「6個のトランジスタで1ビットを1クロックで出し入れする超高速作業机（6T SRAM）」を数MBも内蔵しているんです！","summary":"2025〜2026年の低消費電力CFexpress 4.0 / PCIe 5.0 SSDコントローラを構成する6nmクラスFinFET（および次世代2nm GAAゲートオールアラウンド・ナノシート）微細トランジスタと、オンダイL1キャッシュ・FTLワーク用6T SRAMビットセル配列です。","opticsAndPhysics":["従来の平面プレーナMOSFETでは微細化するとスイッチOFF時にも漏れ電流（短チャネル効果）が止まりませんが、シリコンチャネルを垂直フィン（FinFET）または積層水平シート（GAA Nanosheet）にしてゲートで3面〜4面全周から静電制御することで、低い電源電圧（0.65〜0.75 V）でも鋭いON/OFFスイッチングと劇的な省電力化を実現します。","コントローラ内蔵SRAMは1ビットあたり6個のトランジスタ（クロスカップル・インバータ4個＋アクセストランジスタ2個：6Tセル）で構成され、DRAMのようなリフレッシュ不要でわずか1クロック（<1 ns）で読み書きできます。","このオンダイSRAMがブートコード、LDPC復号バッファ、書込アグリゲーション、およびDRAMレス／HMB運用時のホットFTLマップキャッシュとして働き、α7 IV等の連写バッファ開放速度を極限まで引き上げます。"],"formula":{"expression":"P_dyn = α · C_load · V_dd² · f   (6nm微細化で C_load ＆ V_dd を低減 → 電力は V_dd² で激減)","description":"消費電力は電源電圧 V_dd の2乗に比例するため、6nm FinFET/GAAによる低電圧動作がカード発熱低減に直結。"},"nextGenInnovation":"2026年は6nm世代SSDコントローラ（Phison E28 / SM2508等）が本格普及し、さらにロジック最先端では2nm GAAナノシート＋裏面給電（BSPDN: PowerVia / Super Power Rail）への移行が加速しています。","specs":[{"label":"プロセスノード","value":"6nm / 7nm FinFET（次世代ロードマップ 4nm → 2nm GAA）"},{"label":"内蔵メモリ細胞","value":"6T SRAMビットセル（単一クロック・リフレッシュ不要）"},{"label":"コア電源電圧","value":"約 0.65〜0.75 V（V_dd² 則による超低発熱動作）"},{"label":"主な用途","value":"ARM/RISC-Vコア・LDPCバッファ・ホットFTLマップキャッシュ"}],"diagramType":"cfe_6nm_finfet_6t_sram_cell"},{"id":"cfe-ldpc-soft-llr-cgllr","order":126,"swatchColor":"#10b981","groupKey":"0らしさ・1らしさ_を確率推理する2026年最新ECC_C126","assembledPos":[3.2,-10.8,-0.58],"explodeOffset":[56,-106,-46],"integratedExplodeOffset":[56,-106,-46],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C126. 2026年次世代 分類段階化ソフト判定LDPC（CGLLR）＆対数尤度比（LLR）確率復号エンジン","subtitle":"2026 CGLLR Graded Soft-Decision LDPC & Log-Likelihood Ratio (LLR) Iterative Decoder","category":"「0らしさ・1らしさ」を確率推理する2026年最新ECC！ C126 — 25 mV刻みで何度も読み直し、限界劣化データも完全救出！","plainAnalogy":"ハード判定の誤り訂正は、ボヤけた文字を見て「たぶん0！」と1回で決めつけるので間違いが増えるとギブアップします。ところが最新コントローラの「ソフト判定LDPC」は探偵のよう！同じメモリセルを電圧を25 mVずつズラしながら何度も読み直し、「このビットは99%確実に1」「このビットは境界ギリギリで55%くらい0かも…」という確信度スコア（対数尤度比：LLR）を全ビットに採点します！さらに2026年10月発表の最新手法（CGLLR）はスコアの段階分けを賢く最適化し、推理の繰り返し回数を26.3%も短縮したんです！","summary":"3D TLC/QLC NANDの極限劣化・高温リテンション後でもビット誤りを訂正する、複数しきい値ソフトリードから対数尤度比（LLR: Log-Likelihood Ratio）を生成し、タナーグラフ上の確率伝搬（Belief Propagation / Min-Sum）で反復復号する最新LDPCハードウェアエンジンです。","opticsAndPhysics":["通常リード時は高速な1回読み出しのハード判定（Hard-Decision）LDPCで低遅延処理し、劣化により失敗した場合のみ基準電圧 Vref を ±25 mV 等で多段階シフトするソフトリード（Soft-Decision）へ自動移行します。","各ビットには LLR = ln[ P(bit=0|y) / P(bit=1|y) ] の確信度が付与され、チェックノードとバリアブルノード間でメッセージをやり取りする反復復号により、従来のBCH符号より桁違いに高い生ビット誤り率（RBER > 10^-2 級）を訂正できます。","2026年10月公開の最新研究「CGLLR（Classification-based Graded LLR Quantization）」では、ハードウェア量子化によるLLR解像度劣化をk-means分類ベースの段階量子化で解決し、復号平均反復回数を 26.3% 削減する革新的成果が報告されています。"],"formula":{"expression":"LLR(y) = ln( P(x = 0 | y) / P(x = 1 | y) )   (2026 CGLLR: 反復回数 −26.3%)","description":"絶対値が大きいほど確信度が高く、0に近いほど境界上の曖昧ビット。ソフト情報により確率推理の精度を飛躍的に高める。"},"nextGenInnovation":"2026年は書換回数（PEC）の増加に合わせてLLR参照テーブル自体をオンザフライ自動更新する動的LDPC（DyLDPC）やAI機械学習LLR推定が実装され、高層3D NANDの寿命末期でも8K撮影の信頼性を守り抜きます。","specs":[{"label":"復号アルゴリズム","value":"2段階 Hard → Soft-Decision LDPC（Min-Sum / BP反復）"},{"label":"ソフトリード刻み","value":"複数Vrefシフト（約 25 mV ステップ境界サンプリング）"},{"label":"2026年最新手法","value":"CGLLR（k-means段階LLR量子化：反復回数 −26.3%）"},{"label":"訂正能力目標","value":"UBER < 10^-16（写真・映像データ破損率を天文学的低水準へ）"}],"diagramType":"cfe_ldpc_soft_llr_cgllr"},{"id":"cfe-nvme-e2e-crc32c-dif","order":127,"swatchColor":"#14b8a6","groupKey":"入り口から出口まで_1ビットの化け_も許さない封印シール_C12","assembledPos":[-9.6,-7.2,0.56],"explodeOffset":[-92,-88,22],"integratedExplodeOffset":[-92,-88,22],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C127. エンドツーエンド（E2E）データパス保護・T10 DIF CRC-32C＆内部SRAM ECCパリティ網","subtitle":"End-to-End (E2E) Data-Path Protection (CRC-32C / T10 DIF) & Internal SRAM ECC Mesh","category":"入り口から出口まで「1ビットの化け」も許さない封印シール C127 — PCIe・SRAM・NAND全区間をCRCとECCで連続監視！","plainAnalogy":"どれだけNANDメモリ本体に強力な誤り訂正（LDPC）があっても、その手前の「PCIeの入口」や「コントローラ内部の作業机（SRAM）」で宇宙線やノイズによってデータが1ビットだけ化けてしまったら、壊れたデータのまま丁寧に保存されてしまいます！そこでプロ用カードは、カメラから届いた瞬間にデータへ「封印シール（CRC-32C検査コード）」を貼り、内部SRAMの1バイトごとにECCパリティを付け、NANDに書き込む直前まで全チェックポイントで封印が破れていないか確認し続ける「全区間完全警備（E2E）」を敷いているんです！","summary":"カメラホストからPCIeインターフェースで受信したデータが、コントローラ内部バス・SRAMバッファ・DRAM・暗号化エンジンを経てNANDフラッシュへ格納されるまでの全経路でサイレントデータ破損（SDC）を防止するエンドツーエンド（E2E）データパス保護機構です。","opticsAndPhysics":["PCIeリンク層（LCRC）を通過した直後にコントローラ入口でセクタ単位（512B/4KB）のCRC-32C／T10 DIF保護情報（Guard Tag + Application Tag + Reference Tag）を生成・付加し、内部のあらゆるデータ移動後にハードウェア検証を行います。","コントローラ内部のSRAMバッファ・DMA FIFO・外付けDRAMキャッシュにも1ビット自動訂正・2ビット検知（SECDED）のECCまたはパリティ保護を実装し、宇宙線中性子や電源スパイクによるサイレントビット反転を完全に遮断します。","NAND格納時にはデータ本体とCRC保護タグを一緒にLDPC符号化するため、数年後に読み出した際も「本当にカメラが送った元のデータか」をビット単位で100%証明できます。"],"formula":{"expression":"CRC-32C(M) = M(x) · x^32 mod G_Castagnoli(x),   保護区間 = Host ↔ SRAM ↔ AES ↔ NAND","description":"Castagnoli多項式CRC-32CとSRAM SECDED ECCを直列連鎖させ、データ経路上の単一障害点（サイレント破損）をゼロ化。"},"nextGenInnovation":"NVMe 2.1〜2.4世代では64ビット拡張保護情報（64b Guard PI / CRC-64）への拡張も規定され、放送・映画制作現場での大容量8K RAWワークフローのデータ完全性をエンドツーエンドで保証します。","specs":[{"label":"保護範囲","value":"PCIe PHY → 内部DMA/SRAM → DRAM → AES → LDPC → NAND"},{"label":"検査符号","value":"T10 DIF / CRC-32C（次世代 NVMe 64-bit Guard PI対応）"},{"label":"内部メモリ保護","value":"SRAM / DRAM SECDED ECC（1bit訂正・2bit検知）"},{"label":"防止対象","value":"サイレントデータ破損（SDC）・アドレス取り違え（Misdirected Write）"}],"diagramType":"cfe_nvme_e2e_crc32c_dif"},{"id":"cfe-nvme-fdp-reclaim-units","order":128,"swatchColor":"#f97316","groupKey":"寿命の違うデータを別_の倉庫へスマート仕分け_C128_2026","assembledPos":[-10.4,-2.4,0.54],"explodeOffset":[-116,-60,14],"integratedExplodeOffset":[-116,-60,14],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C128. 2026年 NVMe 柔軟データ配置（FDP: TP4146）リクレームユニット＆書込増幅（WAF ≈ 1.03）削減","subtitle":"2026 NVMe Flexible Data Placement (FDP / TP4146) Reclaim Units & WAF Minimization","category":"寿命の違うデータを別々の倉庫へスマート仕分け！ C128 — 2026年NVMe FDP規格で無駄な書き直し（WAF）を激減！","plainAnalogy":"撮影中のカードには「ずっと残す8K本編動画」「すぐ消すプレビュー用プロキシ」「何度も書き換えるファイル一覧（メタデータ）」という寿命がバラバラのデータが同時に届きます。これらを同じ物理ブロックにごちゃ混ぜで保存すると、後で不要データだけ消して引っ越しさせる大掃除（ガベージコレクション）が頻発し、速度がガタ落ちして寿命も縮みます！そこで2026年に本格普及したNVMe FDP技術は、ホストのヒントに従って「寿命ごとの専用倉庫（リクレームユニット）」へ綺麗に仕分け！無駄な書き直し（WAF）をほぼゼロ（1.03）へ近づけるんです！","summary":"NVMe仕様TP4146で標準化され2025〜2026年に商用展開が加速した、ホストが配置ハンドル（Placement Handle）を指定して寿命の異なるデータを物理的に独立したNANDブロック群「リクレームユニット（Reclaim Unit）」へ分離配置する柔軟データ配置（FDP）アーキテクチャです。","opticsAndPhysics":["従来のZNS（Zoned Namespaces）はホスト側に厳格なシーケンシャル書込制約と複雑なガベージコレクション管理を強いましたが、FDPは既存のランダムブロックI/O互換を保ったまま「配置ヒント」だけで物理分離を達成します。","2026年10月のarXiv論文およびUSENIX FAST \'26・Meta CacheLibの実測評価では、FDPの適用により書込増幅係数（WAF: Write Amplification Factor）を従来の 1.22〜2.5 級から理想値（1.0）に肉薄する 1.03 まで削減し、高容量使用率下でのQoS遅延と持続書込速度を劇的に改善しています。","カメラ撮影においては、連続ストリームの8K RAW映像、スチル連写、exFATメタデータ、音声トラックを別々のリクレームユニットへ隔離することで、VPG800/1600の最低保証速度低下を根源から防ぎます。"],"formula":{"expression":"WAF = (NAND物理書込総量) / (ホスト論理書込総量)   (理想値 = 1.00,  FDP実測 ≈ 1.03)","description":"WAFが1.0に近いほど無駄なガベージコレクション移動がなく、最高速の持続書込とカード長寿命を同時達成。"},"nextGenInnovation":"2026年10月の最新研究（FAST \'26 / arXiv 2610.02676）によりLinuxカーネルNVMe I/O PassthruでのFDP運用が成熟し、データセンターから次世代シネマカメラ・CFexpressワークフローへと波及が始まっています。","specs":[{"label":"準拠規格","value":"NVM Express TP4146 Flexible Data Placement（FDP）"},{"label":"物理分離単位","value":"リクレームユニット（Reclaim Unit: RU）× 複数ハンドル"},{"label":"WAF削減実測（2026）","value":"Non-FDP 1.22 → FDP 1.03（高利用率ほど劇的効果）"},{"label":"互換性","value":"標準ブロックI/O完全互換（ZNSの制約なしに導入可能）"}],"diagramType":"cfe_nvme_fdp_reclaim_units"},{"id":"cfe-superblock-interleave-mux","order":129,"swatchColor":"#0ea5e9","groupKey":"16車線のノンストップ料金所_C129_書き込み待ちのチップを飛","assembledPos":[-10.8,3.2,0.48],"explodeOffset":[-124,-22,6],"integratedExplodeOffset":[-124,-22,6],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C129. マルチチャネル・マルチダイ・インターリーブ＆スーパーブロック（Superpage）並列ストライピング","subtitle":"Multi-Channel / Multi-Die Interleaving & Superblock / Superpage Parallel Striping","category":"16車線のノンストップ料金所！ C129 — 書き込み待ちのチップを飛ばして次々流し込む超並列スーパーブロック！","plainAnalogy":"1枚のNANDチップにデータを書き込む作業自体は実はそこまで速くありません（1ページあたり数百マイクロ秒の待ち時間があります）。それなのになぜCFexpress 4.0は秒速1700 MBもの爆速で8K動画を書き込めるのでしょう？秘密は「スーパーブロック＆ダイ・インターリーブ」という16車線ノンストップ作戦！1番目のチップが書込作業をしている待ち時間の裏で、すぐ2番・3番・4番…のチップと別チャネルへ次々データを流し込み、全チップを1枚の超巨大ページ（スーパーページ）として一斉稼働させているんです！","summary":"コントローラ配下の複数NANDチャネル（4〜8ch）と、各チャネル上の複数積層ダイ（CEインターリーブ）および各ダイ内の複数プレーン（4〜6 Plane）を論理的に束ね、単一の超巨大「スーパーブロック／スーパーページ」として並列ストライピング書込するアーキテクチャです。","opticsAndPhysics":["NANDセルの物理書込時間 tPROG（TLCで約 300〜600 μs）の間、そのダイはビジー状態になりますが、同一チャネル上の別ダイへコマンドとデータ転送を重ねる「ダイ・インターリーブ」により、Toggle DDRバスの空き時間をほぼゼロに埋めます。","同じオフセットを持つブロックを全チャネル・全ダイ・全プレーン横断で束ねて「スーパーブロック」を構成し、1回の書込で数十MB規模の「スーパーページ」を同時ストライピングすることで、1ダイあたりの速度の十数倍のカード実効帯域を実現します。","さらにスーパーブロック内の1ブロック分をXORパリティ専用に割り当てることで、将来どこかのダイに回復不能ブロックが生じてもRAID的に自動復旧する安全網を兼ねます。"],"formula":{"expression":"BW_eff = min( N_ch · BW_Toggle,  N_die · N_plane · (PageSize / tPROG) )","description":"チャネル数 N_ch・積層ダイ数 N_die・プレーン数 N_plane の掛け算並列度により、低速なセル書込時間 tPROG を完全に隠蔽。"},"nextGenInnovation":"2026年の1.92 TB大容量CFexpress Type A（CEA-G1920T等）が低容量版より高速・高持続なのは、内部のインターリーブ可能ダイ数と4〜6プレーン並列度がコントローラの4〜8チャネルを完全飽和させられるためです。","specs":[{"label":"並列階層構造","value":"Channel（4–8）× Die Interleave（2–4）× Plane（4–6）"},{"label":"論理単位","value":"Superblock（横断ブロック群）/ Superpage（一斉書込単位）"},{"label":"RAID連携","value":"スーパーブロック内XORパリティによるダイ故障冗長保護"},{"label":"効果","value":"tPROG待ち時間を完全隠蔽し持続 1,700 MB/s 級を実現"}],"diagramType":"cfe_superblock_interleave_mux"},{"id":"cfe-mopa-laser-oxide-pvd-coat","order":130,"swatchColor":"#64748b","groupKey":"金属を1ミクロンも削らず_光の干渉_で黒く描く_C130_サビず","assembledPos":[6.4,9.2,-1.68],"explodeOffset":[84,72,-96],"integratedExplodeOffset":[84,72,-96],"edgeOpacity":0.22,"standaloneOnly":true,"title":"C130. 外装MOPA 1064 nmファイバーレーザー無切削黒色酸化発色＆耐摩耗PVDマイクロ結晶層","subtitle":"1064 nm MOPA Fiber-Laser Non-Ablative Oxide Annealing & Wear-Resistant PVD Armor","category":"金属を1ミクロンも削らず「光の干渉」で黒く描く！ C130 — サビず消えないナノ秒レーザー酸化発色＆PVD外装！","plainAnalogy":"Sony CEA-G1920T TOUGHの裏面ステンレスに描かれたクッキリ真っ黒な「SONY」ロゴやVPG800マーク、シリアル番号。実はインク印刷でもなければ、金属を彫って削ったわけでもありません！インクは擦れると消え、彫るとサビや水漏れの原因になります。そこで使うのが「MOPAナノ秒ファイバーレーザーの無切削アニーリング」！金属表面をごく一瞬だけ高温にして深さわずか100 nmの極薄酸化クロム膜を育て、シャボン玉と同じ「光の干渉」の仕組みで真っ黒に発色させるから、ツルツル無傷で永遠に消えずサビないんです！","summary":"ステンレス鋼製バックプレート（C02）の型番・VPG800ロゴ・2Dデータマトリクス印字に用いられる、波長1064 nm MOPAパルスファイバーレーザーによる無切削熱酸化アニーリング発色層（約50〜150 nm）と、外装表面の耐摩耗PVDマイクロ結晶保護層です。","opticsAndPhysics":["通常の彫刻レーザー（アブレーション）は金属表面を溶融気化させて溝を掘るため、ステンレスの耐食性不動態皮膜（Cr2O3）が破壊され、汗や海風で赤錆が発生しやすくなります。","MOPA（Master Oscillator Power Amplifier）レーザーはパルス幅を数ナノ秒〜数百ナノ秒へ精密制御し、金属を蒸発させず融点直下へ局所加熱（レーザーアニーリング）することで、表面を完全平坦なまま深さ約50〜150 nmの緻密な黒色酸化クロム・鉄複合皮膜（Cr2O3/Fe3O4）を成長させます。","光学薄膜干渉と表面微細酸化結晶の光吸収により高いコントラスト（高視認バーコード／DataMatrix）を得ながら、耐食性・IP57防水シール性・1万回抜き差し耐摩耗性を一切損ないません。"],"formula":{"expression":"2 · n_ox · d_ox · cos(θ) = (m + 1/2) · λ   (d_ox ≈ 80–150 nm 薄膜干渉＋光吸収黒化)","description":"ナノ秒MOPAパルス熱制御で酸化膜厚 d_ox を制御し、非破壊・無凹凸のまま永久的な高コントラスト黒色マーキングを形成。"},"nextGenInnovation":"2025〜2026年のプロ用カメラメディア外装では、MOPAレーザー非破壊アニーリングとPVD（物理気相成長）窒化チタン・DLC系耐摩耗コーティングを組み合わせ、過酷な報道・野生動物撮影現場でも10年間判読可能な製品トレーサビリティを実現しています。","specs":[{"label":"レーザー光源","value":"1064 nm MOPA パルスファイバーレーザー（パルス幅可変）"},{"label":"発色メカニズム","value":"無切削アニーリング酸化皮膜（Cr2O3/Fe3O4 厚 ~100 nm）"},{"label":"表面粗さ変化","value":"ほぼゼロ（非削溝・不動態皮膜維持で高耐食）"},{"label":"表面保護層","value":"ヘアラインSUS ＋ 高硬度耐摩耗PVDマイクロ結晶層"}],"diagramType":"cfe_mopa_laser_oxide_pvd_coat"}]'),i={unitId:e,version:a,nameJa:l,nameEn:s,declaredPartCount:130,parts:t};export{n as declaredPartCount,i as default,s as nameEn,l as nameJa,t as parts,e as unitId,a as version};
